declare
  v_uid    uuid := (select auth.uid());
  v_inv    uuid;
  v_r      crm.conversion_reservas%rowtype;
  v_lead   crm.leads%rowtype;
  v_est    jsonb;
  v_clave  text;
  v_motivo text := nullif(pg_catalog.btrim(p_motivo), '');
  v_previo text;
begin
  -- F2.b [D-5] (Codex E2 #12): una reserva SELLADA (punto de no retorno) cuyo edge murió ANTES de crear la cuenta de Auth
  -- deja a la persona «en conversión» para siempre (persona_en_conversion: sellada y sin convertir): nadie puede darle un
  -- lead, tomarla, reabrirla ni convertirla. Gerencia la ABANDONA con motivo: solo si NADA externo existe (claim en
  -- `reclamado`: sin cuenta de acceso ni ficha) y la ejecución ya no está viva (reserva o lease vencidos): se borran la
  -- reserva y el claim (bitácora en audit_log por sus triggers) y queda una nota en el lead. Con cuenta o ficha creadas
  -- el camino es RETOMAR (crm.retomar_conversion_gerencia_fn); consumada (perfil enlazado) no hay nada que abandonar.
  -- Orden de candados: persona → lead → reserva → claim (el de la conversión en cooperativa y del sellado).
  if not private.es_gerencia_crm_activa() then
    raise exception 'Solo Gerencia abandona una conversión' using errcode = '42501';
  end if;
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Abandonar requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  if not coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false) then
    raise exception 'Identidad unificada apagada' using errcode = 'P0409';
  end if;
  if p_lead_id is null then
    raise exception 'El lead es obligatorio' using errcode = '22023';
  end if;
  if v_motivo is null or pg_catalog.length(v_motivo) < 5 or pg_catalog.length(v_motivo) > 300 then
    raise exception 'El motivo es obligatorio (entre 5 y 300 caracteres)' using errcode = '22023';
  end if;
  select r.inversionista_id into v_inv from crm.conversion_reservas r where r.lead_id = p_lead_id;
  if v_inv is null then
    raise exception 'Este lead no tiene una reserva por persona' using errcode = 'P0002';
  end if;
  -- Orden de candados (Codex v5 #3): persona → lead → reserva → claim, el de la conversión en cooperativa y del sellado
  -- (lead antes que reserva); las revalidaciones van después de cada candado.
  perform 1 from crm.inversionistas i where i.id = v_inv for update;
  select * into v_lead from crm.leads l where l.id = p_lead_id for update;
  if not found then
    raise exception 'Lead no encontrado' using errcode = 'P0002';
  end if;
  select * into v_r from crm.conversion_reservas r where r.lead_id = p_lead_id for update;
  -- Revalidación tras los candados (auditor v1 #3): la reserva pudo borrarse (doble clic) o cambiar de persona mientras se esperaba.
  if not found then
    raise exception 'Este lead ya no tiene una reserva por persona' using errcode = 'P0002';
  end if;
  if v_r.inversionista_id is distinct from v_inv then
    raise exception 'La reserva cambió de persona mientras se bloqueaba; vuelve a intentarlo' using errcode = '40001';
  end if;
  if v_r.efectos_iniciados_en is null then
    raise exception 'La reserva no está sellada: caduca sola a los pocos minutos, no hay nada que abandonar' using errcode = 'P0409';
  end if;
  if v_lead.etapa = 'convertido' then
    raise exception 'El lead ya está convertido: la conversión se consumó, no se abandona' using errcode = 'P0409';
  end if;
  v_clave := 'auth_persona:' || v_inv::text;
  select i.resultado into v_est from crm.multiempresa_idempotencia i where i.clave = v_clave for update;
  if v_est is null and v_r.claim_id is not null then
    raise exception 'La reserva apunta a un claim que ya no existe (anomalía de datos): revisar antes de abandonar' using errcode = 'P0409';
  end if;
  if v_est is not null then
    if (v_est->>'lead_id')::uuid is distinct from p_lead_id or v_r.claim_id is distinct from (v_est->>'claim_id')::uuid then
      raise exception 'La reserva y el claim de esta persona no corresponden a este lead' using errcode = 'P0409';
    end if;
    if v_est->>'estado' = 'enlazado' then
      raise exception 'La conversión ya se consumó (ficha enlazada): no se abandona' using errcode = 'P0409';
    end if;
    if v_est->>'estado' in ('auth_creado', 'perfil_creado') then
      raise exception 'Ya existe la cuenta de acceso (o la ficha) de esta persona: retoma la conversión en vez de abandonarla'
        using errcode = 'P0409', hint = 'crm.retomar_conversion_gerencia_fn(p_lead_id)';
    end if;
    if v_est->>'estado' <> 'reclamado' then
      raise exception 'Estado de saga desconocido (%): revisar antes de abandonar', v_est->>'estado' using errcode = 'P0409';
    end if;
  end if;
  -- Nunca expulsa a una ejecución viva (Codex E2 #10): abandonar es destructivo, así que exige los DOS plazos vencidos
  -- (el tope de la reserva Y el lease del claim; sin lease escrito se trata como vivo). Codex v3 #2: un reintento del dueño
  -- renueva el lease diez minutos aunque el tope original haya pasado; con «uno u otro» se le borraba el claim en vuelo.
  if v_est is not null and v_est->>'lease_hasta' is null then
    raise exception 'El claim de esta conversión no tiene lease (anomalía de datos): revisar antes de abandonar' using errcode = 'P0409';
  end if;
  if v_r.vence_absoluto_en > pg_catalog.now()
     or (v_est is not null and (v_est->>'lease_hasta')::timestamptz > pg_catalog.now()) then
    raise exception 'La conversión sigue viva (reserva o claim vigentes): espera a que venzan los dos antes de abandonarla' using errcode = 'P0409';
  end if;
  -- Auditor v1 #1 (ALTO): el edge crea el usuario de Auth ANTES de registrar el paso (createUser con app_metadata.claim_id
  -- → registrar_auth). Si murió entre medias, el claim sigue en «reclamado» pero la cuenta EXISTE con la marca de este claim;
  -- borrar el claim la dejaría huérfana para siempre (el reintento la adopta por la marca). Con la marca viva: retomar.
  if v_r.claim_id is not null and exists (select 1 from auth.users u where u.raw_app_meta_data->>'claim_id' = v_r.claim_id::text) then
    raise exception 'Ya existe la cuenta de acceso creada por esta conversión (aún sin registrar en la saga): retoma la conversión en vez de abandonarla'
      using errcode = 'P0409', hint = 'crm.retomar_conversion_gerencia_fn(p_lead_id)';
  end if;
  delete from crm.multiempresa_idempotencia where clave = v_clave;
  delete from crm.conversion_reservas where lead_id = p_lead_id;
  -- Nota administrativa en el lead (no es contacto). La válvula es PREVISIÓN (hoy ningún trigger de crm.actividades veta una
  -- «nota» ni mira la válvula; trg_gestion_lead_serializada exige creado_por = auth.uid(), lead activo y rol, que se cumplen).
  if v_lead.activo then
    v_previo := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true), 'off');
    perform pg_catalog.set_config('crm.op_privilegiada', 'on', true);
    insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por)
    values (p_lead_id, 'nota', 'Conversión abandonada por Gerencia: ' || v_motivo,
            pg_catalog.jsonb_build_object('evento', 'conversion_abandonada', 'inversionista_id', v_inv, 'claim_id', v_r.claim_id,
              'estado_previo', coalesce(v_est->>'estado', 'sin_claim'), 'reservado_por', v_r.reservado_por,
              'sellada_en', v_r.efectos_iniciados_en, 'motivo', v_motivo),
            v_uid);
    perform pg_catalog.set_config('crm.op_privilegiada', v_previo, true);
  end if;
  return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'inversionista_id', v_inv, 'claim_id', v_r.claim_id,
    'estado_previo', coalesce(v_est->>'estado', 'sin_claim'), 'abandonada_por', v_uid, 'abandonada_en', pg_catalog.now());
end;

declare
  v_actor uuid := (select auth.uid());
  v_producto crm.productos_inversion%rowtype;
  v_version crm.producto_versiones%rowtype;
begin
  if private.rol_crm(v_actor) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia puede administrar productos de inversión'
      using errcode = '42501';
  end if;
  perform private.validar_cabecera_version_producto(
    p_nombre, p_descripcion, p_vigente_desde, p_vigente_hasta
  );

  select p.* into v_producto
  from crm.productos_inversion p
  where p.id = (
    select v.producto_id from crm.producto_versiones v
    where v.id = p_version_id
  )
  for update;
  if not found then
    raise exception 'Versión no encontrada' using errcode = 'P0002';
  end if;

  select * into v_version
  from crm.producto_versiones v
  where v.id = p_version_id
  for update;

  if v_producto.es_legacy or v_producto.estado <> 'activo'
     or v_version.estado <> 'borrador' then
    raise exception 'Solo puede editarse un borrador de producto activo'
      using errcode = '23514';
  end if;
  if p_expected_revision is distinct from v_version.revision then
    raise exception 'El borrador cambió; recarga antes de guardar'
      using errcode = '40001';
  end if;

  update crm.producto_condiciones
     set activa = false,
         retirada_por = v_actor,
         retirada_en = now()
   where version_id = p_version_id
     and activa;

  perform private.insertar_condiciones_producto(
    p_version_id, p_condiciones, v_actor
  );

  update crm.producto_versiones
     set nombre = btrim(p_nombre),
         descripcion = nullif(btrim(p_descripcion), ''),
         vigente_desde = p_vigente_desde,
         vigente_hasta = p_vigente_hasta,
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now()
   where id = p_version_id;

  update crm.productos_inversion
     set revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now()
   where id = v_producto.id;

  return jsonb_build_object(
    'producto_id', v_producto.id,
    'producto_revision', v_producto.revision + 1,
    'version_id', p_version_id,
    'version_revision', v_version.revision + 1,
    'numero_version', v_version.numero_version,
    'estado', 'borrador'
  );
end;

begin
  if private.rol_crm((select auth.uid())) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia puede configurar la capacidad de los analistas'
      using errcode='42501';
  end if;
  if not coalesce(
    private.rol_crm(p_analista_id) in ('vendedor','supervisor'),
    false
  ) then
    raise exception 'Analista activo no encontrado' using errcode='P0002';
  end if;
  return query
  select * from private.actualizar_capacidad_leads_objetivo_implementacion(
    p_analista_id,p_capacidad_leads_objetivo
  );
end;

declare
  v_domicilio text;
  v_actualizado boolean;
begin
  if private.rol_crm((select auth.uid())) is distinct from 'gerencia' then
    raise insufficient_privilege using
      message = 'Solo Gerencia puede corregir clientes fuera de cartera';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object'
     or not p_patch ? 'domicilio'
     or jsonb_typeof(p_patch->'domicilio') <> 'string' then
    raise exception 'El domicilio legal del cliente es obligatorio'
      using errcode = '22023';
  end if;

  v_domicilio := crm.normalizar_domicilio_legal(p_patch->>'domicilio');

  v_actualizado := crm.actualizar_cliente_gerencia(
    p_cliente_id,
    p_patch - 'domicilio'
  );
  if not v_actualizado then return false; end if;

  update public.perfiles
     set domicilio = v_domicilio
   where id = p_cliente_id
     and rol = 'cliente';
  if not found then
    raise exception 'Cliente no encontrado' using errcode = 'P0002';
  end if;
  return true;
end;

declare
  v_cliente_id      uuid;
  v_cliente_cuenta  uuid;
  v_moneda_actual   text;
  v_moneda_cuenta   text;
  v_moneda_nueva    text;
  v_tiene_cuenta    boolean;
begin
  if p_contrato is null or jsonb_typeof(p_contrato) <> 'object' then
    raise exception using errcode = '22023', message = 'Faltan los datos del contrato';
  end if;

  select
    ct.cliente_id,
    cb.cliente_id,
    ct.moneda,
    cb.moneda,
    ccp.contrato_id is not null
  into
    v_cliente_id,
    v_cliente_cuenta,
    v_moneda_actual,
    v_moneda_cuenta,
    v_tiene_cuenta
  from public.contratos ct
  left join crm.contrato_cuentas_pago ccp on ccp.contrato_id = ct.id
  left join crm.cuentas_bancarias cb on cb.id = ccp.cuenta_bancaria_id
  where ct.id = p_id;

  if not found or not (select private.puede_registrar_ventas()) then
    raise exception using errcode = '42501', message = 'Contrato no encontrado o fuera de tu cartera';
  end if;

  if v_tiene_cuenta then
    if v_cliente_id is distinct from v_cliente_cuenta
       or v_moneda_actual is distinct from v_moneda_cuenta then
      raise exception using
        errcode = 'P0001',
        message = 'El contrato tiene una cuenta de pago con moneda inconsistente; requiere conciliacion';
    end if;
    v_moneda_nueva := upper(btrim(coalesce(p_contrato->>'moneda', v_moneda_actual)));
    if v_moneda_nueva is distinct from v_moneda_cuenta then
      raise exception using
        errcode = '22023',
        message = 'La moneda de un contrato con cuenta de pago fijada no se puede cambiar desde Corregir';
    end if;
  end if;

  -- public.actualizar_contrato conserva la ventana de 5 h, la autoria/cartera
  -- y la regeneracion segura del cronograma como segunda linea de defensa.
  perform public.actualizar_contrato(p_id, p_contrato, p_cronograma);
end;

declare
  v_actor_id uuid := (select auth.uid());
  v_pdf jsonb;
begin
  if v_actor_id is null then
    raise insufficient_privilege using message = 'Sesión no válida';
  end if;
  if private.contrato_en_eliminacion(p_id) then
    raise exception 'El contrato está en proceso de eliminación'
      using errcode = '55000';
  end if;

  perform set_config(
    'crm.contrato_pdf_revision_autorizada', p_id::text, true
  );
  begin
    -- Esta RPC conserva la autorización autoritativa vigente: para el vendedor,
    -- autor + cartera + menos de 5 horas; para roles administrativos, sus gates.
    perform crm.actualizar_contrato_con_cuenta(
      p_id, p_contrato, p_cronograma
    );
  exception when others then
    perform set_config('crm.contrato_pdf_revision_autorizada', '', true);
    raise;
  end;
  perform set_config('crm.contrato_pdf_revision_autorizada', '', true);

  v_pdf := private.crear_revision_contrato_pdf_base(p_id, v_actor_id);
  return jsonb_build_object('id', p_id, 'ok', true, 'pdf', v_pdf);
end;

declare
  v_resultado jsonb;
  v_condicion_resultante uuid;
begin
  if not (select private.puede_registrar_ventas()) then
    raise insufficient_privilege using message = 'No autorizado para gestionar contratos desde el CRM';
  end if;
  if p_producto_condicion_id is null then
    raise exception 'Selecciona un producto de inversión'
      using errcode = '22023';
  end if;
  perform pg_catalog.set_config(
    'crm.producto_condicion_id', p_producto_condicion_id::text, true
  );
  perform crm.actualizar_contrato_con_cuenta(
    p_id, p_contrato, p_cronograma
  );
  perform pg_catalog.set_config('crm.producto_condicion_id', '', true);
  select c.producto_condicion_id into v_condicion_resultante
  from public.contratos c
  where c.id = p_id;
  if not found then
    raise exception 'Contrato no encontrado' using errcode = 'P0002';
  end if;
  v_resultado := jsonb_build_object('id', p_id, 'ok', true)
    || private.metadata_condicion_producto(v_condicion_resultante);
  return v_resultado;
exception when others then
  perform pg_catalog.set_config('crm.producto_condicion_id', '', true);
  raise;
end;

declare
  v_resultado jsonb;
  v_condicion_resultante uuid;
begin
  if not (select private.puede_registrar_ventas()) then
    raise insufficient_privilege using message = 'No autorizado para gestionar contratos desde el CRM';
  end if;
  if p_producto_condicion_id is null then
    raise exception 'Selecciona un producto de inversión'
      using errcode = '22023';
  end if;
  perform pg_catalog.set_config(
    'crm.producto_condicion_id', p_producto_condicion_id::text, true
  );
  v_resultado := public.actualizar_contrato(p_id, p_contrato, p_cronograma);
  perform pg_catalog.set_config('crm.producto_condicion_id', '', true);
  select c.producto_condicion_id into v_condicion_resultante
  from public.contratos c
  where c.id = p_id;
  if not found then
    raise exception 'Contrato no encontrado' using errcode = 'P0002';
  end if;
  return v_resultado
    || private.metadata_condicion_producto(v_condicion_resultante);
exception when others then
  perform pg_catalog.set_config('crm.producto_condicion_id', '', true);
  raise;
end;

declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_supervisor_anterior uuid;
  v_version timestamptz;
  v_evento_objetivo uuid;
begin
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message = 'Solo Gerencia puede organizar la jerarquia CRM';
  end if;
  if p_version_equipo is null or p_idempotencia is null then
    raise exception 'Version e idempotencia requeridas';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0)
  );

  select e.rol_crm, e.supervisor_id, e.actualizado_en
    into v_rol, v_supervisor_anterior, v_version
  from crm.equipo e where e.perfil_id = p_perfil_id
  for update;
  if not found then
    raise exception 'Membresia CRM no encontrada';
  end if;
  select ue.objetivo_id into v_evento_objetivo
  from crm.usuario_eventos ue
  where ue.actor_id = v_actor
    and ue.accion = 'jerarquia_actualizada'
    and ue.idempotencia = p_idempotencia;
  if found then
    if v_evento_objetivo is distinct from p_perfil_id then
      raise exception 'La idempotencia ya fue usada para otro usuario';
    end if;
    return pg_catalog.jsonb_build_object(
      'perfil_id', p_perfil_id,
      'supervisor_id', v_supervisor_anterior,
      'version_equipo', v_version, 'idempotente', true
    );
  end if;
  if v_version is distinct from p_version_equipo then
    raise exception using errcode = '40001', message = 'La jerarquia fue modificada por otra sesion';
  end if;

  perform private.validar_supervisor_usuario_crm(
    p_perfil_id, v_rol, p_supervisor_id
  );

  if v_supervisor_anterior is not distinct from p_supervisor_id then
    return pg_catalog.jsonb_build_object(
      'perfil_id', p_perfil_id, 'supervisor_id', p_supervisor_id,
      'version_equipo', v_version, 'idempotente', true
    );
  end if;

  update crm.equipo e
  set supervisor_id = p_supervisor_id
  where e.perfil_id = p_perfil_id;

  select e.actualizado_en into v_version
  from crm.equipo e where e.perfil_id = p_perfil_id;

  perform private.registrar_evento_usuario(
    'jerarquia_actualizada', p_perfil_id,
    pg_catalog.jsonb_build_object(
      'supervisor_anterior', v_supervisor_anterior,
      'supervisor_nuevo', p_supervisor_id
    ),
    p_idempotencia
  );

  return pg_catalog.jsonb_build_object(
    'perfil_id', p_perfil_id, 'supervisor_id', p_supervisor_id,
    'version_equipo', v_version, 'idempotente', false
  );
end;

declare
  v_actor_id uuid := (select auth.uid());
  v_resultado jsonb;
  v_pdf jsonb;
begin
  if v_actor_id is null then
    raise insufficient_privilege using message = 'Sesión no válida';
  end if;
  if private.contrato_en_eliminacion(p_id) then
    raise exception 'El contrato está en proceso de eliminación'
      using errcode = '55000';
  end if;

  perform set_config(
    'crm.contrato_pdf_revision_autorizada', p_id::text, true
  );
  begin
    v_resultado := public.actualizar_numero_contrato(
      p_id, p_numero, p_notas, p_categoria
    );
  exception when others then
    perform set_config('crm.contrato_pdf_revision_autorizada', '', true);
    raise;
  end;
  perform set_config('crm.contrato_pdf_revision_autorizada', '', true);

  v_pdf := private.crear_revision_contrato_pdf_base(p_id, v_actor_id);
  return coalesce(v_resultado, '{}'::jsonb)
    || jsonb_build_object('id', p_id, 'ok', true, 'pdf', v_pdf);
end;

declare
  v_actor uuid := (select auth.uid());
  v_tipo text := upper(pg_catalog.btrim(coalesce(p_tipo_documento, '')));
  v_documento text := upper(pg_catalog.btrim(coalesce(p_documento, '')));
  v_fila public.perfiles%rowtype;
  v_nueva_version timestamptz := pg_catalog.clock_timestamp();
begin
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message = 'Solo Gerencia puede editar usuarios CRM';
  end if;
  if p_idempotencia is null or p_version_perfil is null then
    raise exception 'Idempotencia y version de perfil requeridas';
  end if;

  perform private.validar_datos_usuario_crm(
    p_nombre_completo, v_tipo, v_documento,
    nullif(pg_catalog.btrim(p_telefono), ''),
    nullif(pg_catalog.btrim(p_whatsapp), ''),
    nullif(pg_catalog.btrim(p_cargo), '')
  );

  select p.* into v_fila
  from public.perfiles p
  where p.id = p_perfil_id
    and (
      p.rol in ('comercial', 'analista')
      or exists (select 1 from crm.equipo e where e.perfil_id = p.id)
    )
  for update;

  if not found then
    raise exception 'Usuario CRM no encontrado';
  end if;
  if exists (
    select 1 from crm.usuario_eventos ue
    where ue.actor_id = v_actor
      and ue.accion = 'perfil_actualizado'
      and ue.idempotencia = p_idempotencia
      and ue.objetivo_id = p_perfil_id
  ) then
    return pg_catalog.jsonb_build_object(
      'perfil_id', p_perfil_id,
      'version_perfil', v_fila.actualizado_en,
      'idempotente', true
    );
  elsif exists (
    select 1 from crm.usuario_eventos ue
    where ue.actor_id = v_actor
      and ue.accion = 'perfil_actualizado'
      and ue.idempotencia = p_idempotencia
  ) then
    raise exception 'La idempotencia ya fue usada para otro usuario';
  end if;
  if v_fila.actualizado_en is distinct from p_version_perfil then
    raise exception using errcode = '40001', message = 'El usuario fue modificado por otra sesion';
  end if;

  update public.perfiles p
  set nombre_completo = pg_catalog.btrim(p_nombre_completo),
      tipo_documento = v_tipo,
      dni = v_documento,
      telefono = nullif(pg_catalog.btrim(p_telefono), ''),
      whatsapp = nullif(pg_catalog.btrim(p_whatsapp), ''),
      cargo = nullif(pg_catalog.btrim(p_cargo), ''),
      actualizado_en = v_nueva_version
  where p.id = p_perfil_id;

  select p.actualizado_en into v_nueva_version
  from public.perfiles p where p.id = p_perfil_id;

  perform private.registrar_evento_usuario(
    'perfil_actualizado', p_perfil_id,
    pg_catalog.jsonb_build_object(
      'campos', pg_catalog.jsonb_build_array(
        'nombre_completo','tipo_documento','documento','telefono','whatsapp','cargo'
      )
    ),
    p_idempotencia
  );

  return pg_catalog.jsonb_build_object(
    'perfil_id', p_perfil_id, 'version_perfil', v_nueva_version,
    'idempotente', false
  );
end;

declare
  v_perfil_id uuid;
begin
  select a.perfil_id into v_perfil_id
  from crm.agenda_ics a
  where a.token = p_token;

  if not found or private.rol_crm(v_perfil_id) is null then
    return pg_catalog.jsonb_build_object(
      'autorizado', false,
      'tareas', '[]'::jsonb
    );
  end if;

  return private.agenda_ics_feed_implementacion(p_token, p_desde);
end;

begin
  if tg_op = 'UPDATE' then
    raise exception using errcode = '42501',
      message = 'El libro de reconocimientos es inmutable: no se edita';
  end if;
  if old.creado_en >= pg_catalog.now() - make_interval(days => 90) then
    raise exception using errcode = '42501',
      message = 'El libro de reconocimientos es inmutable: solo caduca a los 90 días';
  end if;
  return old;
end;

begin
  -- La fila es SIEMPRE del actor autenticado: la autoría no viaja del cliente.
  new.perfil_id := (select auth.uid());
  if new.perfil_id is null then
    raise exception using errcode = '42501', message = 'Acceso CRM revocado';
  end if;

  -- Defensa en profundidad (auditor #8): el gate de rol vive en la policy,
  -- pero una futura RPC definer que inserte aquí no debe poder saltárselo.
  if private.rol_crm(new.perfil_id) is distinct from 'supervisor' then
    raise exception using errcode = '42501',
      message = 'Solo un supervisor escribe en el libro de reconocimientos';
  end if;

  -- Nadie reconoce alertas ajenas: el uuid del alerta_id ES el del actor.
  -- (El CHECK de formato corre DESPUÉS de este BEFORE trigger — aquí solo se
  -- ata la identidad; lo malformado muere luego en el CHECK. auditor #5.)
  if new.alerta_id !~ ('[:]' || new.perfil_id::text || '$') then
    raise exception using errcode = '42501',
      message = 'Solo puedes reconocer alertas de tu propia campana';
  end if;

  -- Miembros sanos: ids cortos sin espacios, sin nulls (la cardinalidad ya
  -- la acota el CHECK). Un null dentro del array pasa cardinality y habría
  -- envenenado la comparación de «empeoró» en el front.
  if exists (
    select 1 from pg_catalog.unnest(new.miembros) as m
    where m is null or m collate "C" !~ '^[0-9A-Za-z_-]{1,64}$'
  ) then
    raise exception using errcode = '22023',
      message = 'La foto de miembros trae ids inválidos';
  end if;

  -- Posponer: futura y con tope de 7 DÍAS (decisión de Miguel 2026-08-23).
  -- clock_timestamp() y no now(): la lección de F3 — «futura» significa
  -- futura en la pared, no en el BEGIN de la transacción.
  if new.accion = 'posponer' then
    if new.hasta <= pg_catalog.clock_timestamp() then
      raise exception using errcode = '22023',
        message = 'La fecha de posposición debe ser futura';
    end if;
    if new.hasta > pg_catalog.clock_timestamp() + make_interval(days => 7) then
      raise exception using errcode = '22023',
        message = 'Posponer tiene un tope de 7 días';
    end if;
  end if;

  -- creado_en lo SELLA el servidor: el orden del libro no lo decide el
  -- cliente. clock_timestamp() y no now() (auditor #6): un POST batch de
  -- PostgREST mete varias filas en UNA transacción y con now() empatarían —
  -- «el último asiento manda» necesita un reloj que avance dentro del batch.
  new.creado_en := pg_catalog.clock_timestamp();
  return new;
end;

declare
  v_uid uuid := (select auth.uid());
  v_cap jsonb; v_tipo text; v_doc text; v_inv uuid; v_perfil uuid; v_activo boolean;
  v_claim uuid; v_loc record; v_r jsonb; v_hash_payload jsonb;
begin
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada: el alta con identidad no está activa' using errcode = 'P0409';
  end if;
  if v_uid is not null then
    v_cap := private.puede_alta_cliente();
    if coalesce((v_cap->>'ok')::boolean, false) is not true then
      raise exception 'No autorizado para crear clientes' using errcode = '42501';
    end if;
  end if;
  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Payload inválido' using errcode = '22023';
  end if;

  if p_paso = 'reclamar' then
    v_tipo := coalesce(nullif(pg_catalog.upper(pg_catalog.btrim(p_payload->>'tipo_documento')), ''), 'DNI');
    -- Misma normalización que el resolver (el lookup del perfil por documento la necesita igual).
    v_doc  := nullif(pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p_payload->>'documento', ''), '[^A-Za-z0-9]', '', 'g')), '');
    if v_doc is null then
      raise exception 'El documento es obligatorio para crear un cliente (identidad unificada)' using errcode = '22023';
    end if;
    -- F2.b (b5) [Codex N2]: jerarquía compartida ANTES del documento (asegurar_identidad_perfil la toma después;
    -- el offboarding la toma exclusiva): nunca documento/identidad -> jerarquía.
    perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0));
    perform private.identidad_bloquear_documento(v_tipo, v_doc);
    v_inv := private.inversionista_resolver(v_tipo, v_doc, true, 'alta_cliente');
    perform 1 from crm.inversionistas i where i.id = v_inv for update;
    -- Proyección canónica COMPLETA del alta (Codex E2 #10), sin documento (la identidad, uuid, ya lo aporta):
    v_hash_payload := pg_catalog.jsonb_build_object('v', 1, 'inv', v_inv,
      'correo', pg_catalog.lower(coalesce(p_payload->>'correo','')), 'nombre', coalesce(p_payload->>'nombre_completo',''),
      'apellidos', coalesce(p_payload->>'apellidos',''), 'nombres', coalesce(p_payload->>'nombres',''),
      'telefono', coalesce(p_payload->>'telefono',''), 'domicilio', coalesce(p_payload->'domicilio', 'null'::jsonb),
      'bancarios', coalesce(p_payload->'bancarios', 'null'::jsonb), 'asesor', coalesce(p_payload->>'asesor_id', ''));
    -- (El asesor DERIVADO del que llama no entra en la huella: otra sesión puede reanudar tras el lease.)
    -- 1) La SAGA manda antes que la existencia (Codex E2 #4): un enlace confirmado cuya respuesta se
    --    perdió se reanuda como 'enlazado' con su perfil_id, no como un rechazo.
    if exists (select 1 from crm.multiempresa_idempotencia i where i.clave = 'auth_persona:' || v_inv::text) then
      v_r := private.saga_auth_reclamar(v_inv, 'alta_cliente', v_hash_payload, null, p_payload->>'token');
      return v_r || pg_catalog.jsonb_build_object('asesor_id', coalesce(v_cap->>'asesor_id', p_payload->>'asesor_id'), 'via', coalesce(v_cap->>'via', 'service_role'));
    end if;
    -- 2) Persona ya cliente (identidad con perfil, o perfil suelto con el documento exacto creado con la
    --    bandera apagada, que se ENLAZA): resultado normal, NUNCA excepción (una excepción desharía el enlace).
    select i.perfil_id into v_perfil from crm.inversionistas i where i.id = v_inv;
    if v_perfil is null then
      select p.id into v_perfil from public.perfiles p
       where p.rol = 'cliente'
         and pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p.dni,''), '[^A-Za-z0-9]', '', 'g')) = v_doc
         and coalesce(nullif(pg_catalog.btrim(p.tipo_documento), ''), 'DNI') = v_tipo
       limit 1;
      if v_perfil is not null then
        perform private.asegurar_identidad_perfil(v_perfil, 'alta_cliente');
      end if;
    end if;
    if v_perfil is not null then
      select p.activo into v_activo from public.perfiles p where p.id = v_perfil;
      -- Un vendedor (vía crm) solo sabe que existe y si está activo: sin ids (anti-pesca, auditor b3 M3).
      if coalesce(v_cap->>'via', '') = 'crm' and coalesce(v_cap->>'asesor_id', '') <> '' then
        return pg_catalog.jsonb_build_object('estado', 'ya_existia', 'activo', coalesce(v_activo, false), 'reanudar', false);
      end if;
      return pg_catalog.jsonb_build_object('estado', 'ya_existia', 'perfil_id', v_perfil, 'activo', coalesce(v_activo, false),
        'inversionista_id', v_inv, 'reanudar', false);
    end if;
    -- 3) Claim nuevo.
    v_r := private.saga_auth_reclamar(v_inv, 'alta_cliente', v_hash_payload, null, p_payload->>'token');
    return v_r || pg_catalog.jsonb_build_object('asesor_id', coalesce(v_cap->>'asesor_id', p_payload->>'asesor_id'), 'via', coalesce(v_cap->>'via', 'service_role'));
  end if;

  v_claim := (p_payload->>'claim_id')::uuid;
  if v_claim is null then raise exception 'Falta claim_id' using errcode = '22023'; end if;

  if p_paso = 'registrar_auth' then
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'auth_creado', (p_payload->>'auth_user_id')::uuid, null, (p_payload->>'version')::integer);
  elsif p_paso = 'compensar_auth' then
    -- El edge borró el Auth (perfil rechazado por datos): el claim vuelve a 'reclamado'.
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'reclamado', null, null, (p_payload->>'version')::integer);
  elsif p_paso = 'perfil_creado' then
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'perfil_creado', null, (p_payload->>'perfil_id')::uuid, (p_payload->>'version')::integer);
  elsif p_paso = 'enlazar' then
    -- Sin lock del claim aquí: documento -> identidad -> perfil (asegurar) -> claim (avanzar).
    select * into v_loc from private.saga_auth_localizar(v_claim);
    if not found then raise exception 'Saga: claim inexistente' using errcode = 'P0002'; end if;
    if v_loc.estado->>'token_hash' is distinct from private.saga_token_hash(p_payload->>'token') then
      raise exception 'Saga: token inválido' using errcode = '42501';
    end if;
    v_perfil := coalesce((v_loc.estado->>'perfil_id')::uuid, (v_loc.estado->>'auth_user_id')::uuid);
    if v_perfil is null then raise exception 'Saga: sin perfil que enlazar' using errcode = 'P0409'; end if;
    if (p_payload->>'perfil_id') is not null and (p_payload->>'perfil_id')::uuid is distinct from v_perfil then
      raise exception 'Saga: el perfil a enlazar es el del claim, no el del payload' using errcode = 'P0409';
    end if;
    v_r := private.asegurar_identidad_perfil(v_perfil, 'alta_cliente');
    -- F2.b (b5) [E3-12]: comparación por la CANÓNICA (un enlace ya consumado se puede reintentar tras una fusión).
    if private.inversionista_canonica((v_r->>'inversionista_id')::uuid) is distinct from private.inversionista_canonica(v_loc.inversionista_id) then
      raise exception 'El perfil creado no corresponde a la persona reclamada' using errcode = 'P0409';
    end if;
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'enlazado', null, v_perfil, (p_payload->>'version')::integer) || v_r;
  end if;
  raise exception 'Paso desconocido: %', p_paso using errcode = '22023';
end;

declare
  v_uid    uuid := (select auth.uid());
  v_rol    text := private.rol_crm((select auth.uid()));
  v_lead   crm.leads%rowtype;
  v_motivo text := btrim(p_motivo);
  v_contratos uuid[];
  v_ajuste uuid;
begin
  if v_uid is null or v_rol is distinct from 'gerencia' then
    raise exception 'Solo gerencia anula cierres'
      using errcode = '42501';
  end if;

  -- El motivo es obligatorio a proposito: esto le quita merito a una persona y
  -- esa persona merece una razon escrita, no un registro de auditoria mudo.
  if v_motivo is null or v_motivo = '' then
    raise exception 'Escribe el motivo de la anulacion'
      using errcode = '22023';
  end if;
  if length(v_motivo) > 300 then
    raise exception 'El motivo admite como maximo 300 caracteres'
      using errcode = '22023';
  end if;

  select * into v_lead
  from crm.leads
  where id = p_lead_id
  for update;
  if not found then
    raise exception 'Lead no encontrado';
  end if;

  if exists (select 1 from crm.cierres_externos ce where ce.lead_id = p_lead_id) then
    raise exception 'Ese lead cerro en cooperativa: usa crm.anular_cierre_externo'
      using errcode = '22023';
  end if;

  if v_lead.etapa is distinct from 'convertido' then
    raise exception 'Ese lead no tiene ningun cierre que anular'
      using errcode = '22023';
  end if;

  if v_lead.convertido_en is null then
    raise exception 'Ese lead esta convertido pero sin fecha de conversion: no se puede saber que contratos trajo'
      using errcode = '22023';
  end if;

  if exists (select 1 from crm.cierres_avance_anulados ca where ca.lead_id = p_lead_id) then
    raise exception using
      errcode = 'P0409',
      message = 'Ese cierre ya estaba anulado';
  end if;

  -- Los contratos afectados se calculan ANTES de insertar la anulacion: despues,
  -- `contratos_afectados_por_anulacion` ya leeria la foto recien creada y daria
  -- lo mismo, pero el orden explicito evita depender de ese detalle.
  select coalesce(array_agg(x), '{}'::uuid[]) into v_contratos
  from private.contratos_afectados_por_anulacion(p_lead_id) x;

  insert into crm.cierres_avance_anulados (lead_id, motivo, anulado_por, acreditado_a)
  values (p_lead_id, v_motivo, v_uid,
          private.vendedor_acreditado_del_cierre(p_lead_id));

  -- Si el mes de ese cierre YA ESTA CERRADO, el mes no se reescribe: nace la
  -- deuda que el vendedor arrastrara al mes vivo hasta saldarla.
  v_ajuste := private.registrar_ajuste_si_mes_cerrado(p_lead_id, v_motivo, v_uid);

  insert into crm.actividades (
    lead_id, tipo, detalle, metadata, creado_por
  ) values (
    p_lead_id,
    'nota',
    'Gerencia anulo el cierre',
    jsonb_build_object(
      'accion', 'anulacion_cierre_avance',
      'motivo', v_motivo,
      'mes_cerrado', v_ajuste is not null,
      'anulado', jsonb_build_object(
        'vendedor_id', v_lead.vendedor_id,
        'contrato_id', v_lead.contrato_id)
    ),
    v_uid
  );

  return jsonb_build_object(
    'ok', true,
    'lead_id', p_lead_id,
    'contratos_afectados', to_jsonb(v_contratos),
    'afecta_cuota', array_length(v_contratos, 1) is not null,
    -- CLAVES NUEVAS. `mes_cerrado` le dice a gerencia que ese mes ya se pago y
    -- que por eso el descuento va al mes vivo en vez de moverle el pasado.
    'mes_cerrado', v_ajuste is not null,
    'ajuste_id', v_ajuste);
end;

declare
  v_uid    uuid := (select auth.uid());
  v_rol    text := private.rol_crm((select auth.uid()));
  v_cierre crm.cierres_externos%rowtype;
  v_motivo text := btrim(p_motivo);
  v_ajuste uuid;
begin
  if v_uid is null or v_rol is distinct from 'gerencia' then
    raise exception 'Solo gerencia anula cierres externos'
      using errcode = '42501';
  end if;

  -- El motivo es obligatorio a propósito: esto le quita dinero a una persona y
  -- esa persona merece una razón escrita, no un registro de auditoría mudo.
  if v_motivo is null or v_motivo = '' then
    raise exception 'Escribe el motivo de la anulacion'
      using errcode = '22023';
  end if;
  if length(v_motivo) > 300 then
    raise exception 'El motivo admite como maximo 300 caracteres'
      using errcode = '22023';
  end if;

  select * into v_cierre
  from crm.cierres_externos
  where id = p_cierre_id
  for update;
  if not found then
    raise exception 'Cierre externo no encontrado';
  end if;
  if v_cierre.anulado_en is not null then
    raise exception using
      errcode = 'P0409',
      message = 'Ese cierre ya estaba anulado',
      detail  = pg_catalog.format('cierre %s, anulado el %s', v_cierre.id, v_cierre.anulado_en);
  end if;

  perform set_config('crm.op_privilegiada', 'on', true);
  update crm.cierres_externos
     set anulado_en = now(),
         anulado_por = v_uid,
         motivo_anulacion = v_motivo
   where id = p_cierre_id;
  perform set_config('crm.op_privilegiada', 'off', true);

  -- Si el mes de ese cierre YA ESTA CERRADO, el mes no se reescribe: nace la
  -- deuda que el vendedor arrastrara al mes vivo.
  v_ajuste := private.registrar_ajuste_si_mes_cerrado(v_cierre.lead_id, v_motivo, v_uid);

  insert into crm.actividades (
    lead_id, tipo, detalle, metadata, creado_por
  ) values (
    v_cierre.lead_id,
    'nota',
    'Gerencia anulo el cierre externo',
    jsonb_build_object(
      'accion', 'anulacion_cierre_externo',
      'cierre_externo_id', p_cierre_id,
      'motivo', v_motivo,
      'mes_cerrado', v_ajuste is not null,
      'anulado', jsonb_build_object(
        'cooperativa', v_cierre.cooperativa,
        'monto', v_cierre.monto,
        'moneda', v_cierre.moneda,
        'numero_transaccion', v_cierre.numero_transaccion,
        'vendedor_id', v_cierre.vendedor_id)
    ),
    v_uid
  );

  return jsonb_build_object(
    'ok', true,
    'cierre_id', p_cierre_id,
    'lead_id', v_cierre.lead_id,
    'mes_cerrado', v_ajuste is not null,
    'ajuste_id', v_ajuste);
end;

declare
  v_actor uuid := (select auth.uid());
  v_producto crm.productos_inversion%rowtype;
begin
  if private.rol_crm(v_actor) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia puede archivar productos de inversión'
      using errcode = '42501';
  end if;

  select * into v_producto
  from crm.productos_inversion p
  where p.id = p_producto_id
  for update;
  if not found then
    raise exception 'Producto no encontrado' using errcode = 'P0002';
  end if;
  if v_producto.es_legacy then
    raise exception 'El producto histórico es interno'
      using errcode = '23514';
  end if;
  if v_producto.estado = 'archivado' then
    raise exception 'El producto ya está archivado'
      using errcode = '23514';
  end if;
  if p_expected_revision is distinct from v_producto.revision then
    raise exception 'El producto cambió; recarga antes de archivarlo'
      using errcode = '40001';
  end if;

  update crm.producto_versiones
     set estado = 'retirada',
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now(),
         retirada_por = v_actor,
         retirada_en = now()
   where producto_id = p_producto_id
     and estado in ('borrador', 'publicada');

  update crm.productos_inversion
     set estado = 'archivado',
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now(),
         archivado_por = v_actor,
         archivado_en = now()
   where id = p_producto_id;

  return jsonb_build_object(
    'producto_id', p_producto_id,
    'producto_revision', v_producto.revision + 1,
    'estado', 'archivado'
  );
end;

declare
  v_actor uuid := (select auth.uid());
  v_perfil_rol text;
  v_perfil_activo boolean;
  v_tiene_equipo boolean := false;
  v_rol_anterior text;
  v_supervisor uuid;
  v_activo boolean;
  v_version timestamptz;
  v_accion text;
  v_evento_objetivo uuid;
begin
  if not private.es_superadmin_portal_activo() then
    raise insufficient_privilege using message = 'Solo Superadmin puede asignar roles CRM';
  end if;
  if p_rol_crm not in ('vendedor','supervisor','gerencia','coordinador','directorio') then
    raise exception 'Rol CRM no permitido';
  end if;
  if p_idempotencia is null then
    raise exception 'Idempotencia requerida';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0)
  );

  select p.rol, p.activo into v_perfil_rol, v_perfil_activo
  from public.perfiles p where p.id = p_perfil_id
  for update;
  if not found or v_perfil_activo is not true then
    raise exception 'El perfil no existe o esta suspendido en Portal';
  end if;
  if v_perfil_rol = 'superadmin' and p_rol_crm <> 'gerencia' then
    raise exception 'Superadmin Portal solo puede recibir el rol CRM Gerencia';
  end if;

  select true, e.rol_crm, e.supervisor_id, e.activo, e.actualizado_en
    into v_tiene_equipo, v_rol_anterior, v_supervisor, v_activo, v_version
  from crm.equipo e where e.perfil_id = p_perfil_id
  for update;
  v_tiene_equipo := found;

  select ue.objetivo_id into v_evento_objetivo
  from crm.usuario_eventos ue
  where ue.actor_id = v_actor
    and ue.accion in ('rol_asignado','rol_cambiado')
    and ue.idempotencia = p_idempotencia
  limit 1;
  if found then
    if v_evento_objetivo is distinct from p_perfil_id then
      raise exception 'La idempotencia ya fue usada para otro usuario';
    end if;
    if not v_tiene_equipo then
      raise exception 'La operacion idempotente perdio su membresia';
    end if;
    return pg_catalog.jsonb_build_object(
      'perfil_id', p_perfil_id, 'rol_crm', v_rol_anterior,
      'activo_crm', v_activo, 'version_equipo', v_version,
      'idempotente', true
    );
  end if;

  if not v_tiene_equipo then
    if v_perfil_rol not in ('comercial', 'analista') then
      raise exception 'Solo un candidato CRM pendiente o Analista Portal puede recibir su primer rol';
    end if;
    if p_version_equipo is not null then
      raise exception using errcode = '40001', message = 'La membresia cambio antes de asignar el rol';
    end if;

    insert into crm.equipo (
      perfil_id, rol_crm, supervisor_id, activo,
      creado_por, creado_en, actualizado_en
    ) values (
      p_perfil_id, p_rol_crm, null, false,
      v_actor, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
    );
    v_accion := 'rol_asignado';
  else
    if p_version_equipo is null or v_version is distinct from p_version_equipo then
      raise exception using errcode = '40001', message = 'La membresia fue modificada por otra sesion';
    end if;
    if v_rol_anterior = p_rol_crm then
      return pg_catalog.jsonb_build_object(
        'perfil_id', p_perfil_id, 'rol_crm', v_rol_anterior,
        'activo_crm', v_activo, 'version_equipo', v_version,
        'idempotente', true
      );
    end if;

    if v_rol_anterior = 'gerencia' and v_activo is true
       and not exists (
         select 1 from crm.equipo e
         join public.perfiles p on p.id = e.perfil_id and p.activo is true
         where e.perfil_id <> p_perfil_id
           and e.rol_crm = 'gerencia' and e.activo is true
       ) then
      raise exception 'No se puede retirar el rol a la ultima Gerencia activa';
    end if;

    update crm.equipo e
    set rol_crm = p_rol_crm
    where e.perfil_id = p_perfil_id;
    v_accion := 'rol_cambiado';
  end if;

  select e.activo, e.actualizado_en into v_activo, v_version
  from crm.equipo e where e.perfil_id = p_perfil_id;

  perform private.registrar_evento_usuario(
    v_accion, p_perfil_id,
    pg_catalog.jsonb_build_object(
      'rol_anterior', v_rol_anterior,
      'rol_nuevo', p_rol_crm
    ),
    p_idempotencia
  );

  return pg_catalog.jsonb_build_object(
    'perfil_id', p_perfil_id, 'rol_crm', p_rol_crm,
    'activo_crm', v_activo, 'version_equipo', v_version,
    'idempotente', false
  );
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text;
  v_preguntas jsonb;
begin
  v_rol := private.rol_crm(v_uid);
  if v_uid is null or v_rol is null then
    raise exception 'No autorizado' using errcode = '42501';
  end if;

  if p_vista is null or not (p_vista = any(array[
    'hoy','alertas','conversiones','ranking-vendedores','reuniones','metas',
    'rendimiento','capital-cierres','pipeline','cartera','agenda','mi-cartera',
    'repartir','equipo','config','config-usuarios','config-productos',
    'config-metas','config-sla'
  ]::text[])) then
    raise exception 'Vista de ayuda no válida' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(s.pregunta order by s.relacionada desc, s.prioridad, s.clave), '[]'::jsonb)
  into v_preguntas
  from (
    select
      i.pregunta,
      p_vista = any(i.vistas) as relacionada,
      i.prioridad,
      i.clave
    from private.ayuda_intenciones i
    where i.estado = 'publicado'
    order by relacionada desc, i.prioridad, i.clave
    limit 6
  ) s;

  return jsonb_build_object('version', 1, 'preguntas', v_preguntas);
end;

declare
  v_id uuid;
  v_correo text := lower(pg_catalog.btrim(coalesce(p_correo, '')));
begin
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message = 'Solo Gerencia puede preparar altas CRM';
  end if;

  if v_correo !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'Correo invalido';
  end if;

  select p.id into v_id
  from public.perfiles p
  left join crm.equipo e on e.perfil_id = p.id
  where lower(p.correo) = v_correo
    and (p.rol in ('comercial', 'analista') or e.perfil_id is not null)
  limit 1;

  return v_id;
end;

declare
  v_actor uuid := (select auth.uid());
  v_producto crm.productos_inversion%rowtype;
begin
  if private.rol_crm(v_actor) is distinct from 'gerencia' then
    raise insufficient_privilege using
      message = 'Solo Gerencia puede cerrar la compatibilidad legacy';
  end if;

  if to_regprocedure(
       'public.productos_inversion_seleccion_fn(uuid)'
     ) is null
     or to_regprocedure(
       'public.crear_contrato_producto(uuid,jsonb,jsonb)'
     ) is null
     or to_regprocedure(
       'public.actualizar_contrato_producto(uuid,uuid,jsonb,jsonb)'
     ) is null
     or to_regprocedure(
       'public.actualizar_contrato_con_cuenta_producto(uuid,uuid,jsonb,jsonb)'
     ) is null then
    raise exception
      'La frontera catalogada del Portal todavía no está instalada'
      using errcode = '55000';
  end if;

  if not exists (
    select 1
    from crm.producto_condiciones c
    join crm.producto_versiones v on v.id = c.version_id
    join crm.productos_inversion p on p.id = v.producto_id
    where p.estado = 'activo'
      and not p.es_legacy
      and v.estado = 'publicada'
      and v.vigente_desde <= current_date
      and (v.vigente_hasta is null or v.vigente_hasta >= current_date)
      and c.activa
      and not c.es_legacy
  ) then
    raise exception
      'Publica al menos una condición de producto vigente antes de cerrar la compatibilidad legacy'
      using errcode = '23514';
  end if;

  select * into v_producto
  from crm.productos_inversion p
  where p.es_legacy
  for update;
  if not found then
    raise exception 'Configuración legacy no encontrada' using errcode = 'P0002';
  end if;
  if p_expected_revision is distinct from v_producto.revision then
    raise exception 'La compatibilidad cambió; recarga antes de cerrarla'
      using errcode = '40001';
  end if;
  if not v_producto.permite_altas_legacy then
    raise exception 'La compatibilidad legacy ya está cerrada y no se reactiva'
      using errcode = '23514';
  end if;

  update crm.productos_inversion
     set permite_altas_legacy = false,
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now()
   where id = v_producto.id;

  return jsonb_build_object(
    'compatibilidad_altas_legacy', false,
    'compatibilidad_revision', v_producto.revision + 1
  );
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm((select auth.uid()));
  v_tarea crm.tareas%rowtype;
  v_act_id uuid;
  v_sig_id uuid;
  v_retroceso text;
begin
  if v_uid is null
     or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_estado is null
     or p_estado not in ('completada', 'no_show', 'cancelada') then
    raise exception 'Estado de reunion invalido' using errcode = '22023';
  end if;
  if p_estado = 'completada'
     and (
       p_resultado_reunion is null
       or p_resultado_reunion not in (
         'interesado', 'seguimiento', 'propuesta',
         'inicia_registro', 'no_interesado'
       )
     ) then
    raise exception 'Registra el resultado comercial de la reunion'
      using errcode = '22023';
  end if;
  if p_estado = 'no_show' then
    p_motivo_no_realizada := 'cliente_no_asistio';
  elsif p_estado = 'cancelada'
        and (
          p_motivo_no_realizada is null
          or p_motivo_no_realizada not in (
            'cancelada_cliente', 'cancelada_empresa', 'otro'
          )
        ) then
    raise exception 'Registra el motivo de cancelacion'
      using errcode = '22023';
  end if;
  if p_estado = 'cancelada'
     and p_motivo_no_realizada = 'otro'
     and nullif(btrim(coalesce(p_detalle, '')), '') is null then
    raise exception 'Describe el otro motivo de cancelacion'
      using errcode = '22023';
  end if;

  perform 1
  from crm.leads
  where id = (
    select t.lead_id
    from crm.tareas t
    where t.id = p_tarea_id
      and t.tipo = 'reunion'
      and t.activo
      and t.estado = 'pendiente'
      and (
        v_rol = 'gerencia'
        or t.vendedor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
        or (
          t.vendedor_id is null
          and t.asignado_supervisor_id in (
            select private.vendedor_ids_visibles(v_uid)
          )
        )
      )
  )
  for no key update;

  select *
    into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id
    and t.tipo = 'reunion'
    and t.activo
    and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (
        select private.vendedor_ids_visibles(v_uid)
      )
      or (
        t.vendedor_id is null
        and t.asignado_supervisor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
      )
    )
  for update;
  if not found then
    raise exception 'Reunion no encontrada, cerrada o fuera de tu ambito';
  end if;

  if p_estado = 'completada' and v_tarea.lead_id is not null then
    insert into crm.actividades (
      lead_id, tipo, detalle, metadata, creado_por
    ) values (
      v_tarea.lead_id,
      'reunion_realizada',
      nullif(btrim(coalesce(p_detalle, '')), ''),
      jsonb_build_object(
        'modalidad', v_tarea.modalidad_reunion,
        'resultado_reunion', p_resultado_reunion,
        'tarea_id', v_tarea.id
      ),
      v_uid
    )
    returning id into v_act_id;
  elsif p_estado = 'no_show'
        and v_tarea.lead_id is not null
        and btrim(coalesce(p_detalle, '')) <> '' then
    insert into crm.actividades (
      lead_id, tipo, detalle, metadata, creado_por
    ) values (
      v_tarea.lead_id,
      'nota',
      btrim(p_detalle),
      jsonb_build_object(
        'evento', 'reunion_no_show',
        'tarea_id', v_tarea.id
      ),
      v_uid
    )
    returning id into v_act_id;
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas
     set estado = p_estado,
         resultado_actividad_id = v_act_id,
         resultado_reunion = case
           when p_estado = 'completada' then p_resultado_reunion
         end,
         motivo_no_realizada = case
           when p_estado in ('no_show', 'cancelada')
             then p_motivo_no_realizada
         end,
         detalle_cierre_reunion =
           nullif(btrim(coalesce(p_detalle, '')), '')
   where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  v_sig_id := private.crear_siguiente_tarea(
    v_tarea,
    p_siguiente,
    case when p_estado = 'no_show' then p_tarea_id else null end,
    v_uid
  );

  if p_estado = 'cancelada' and v_tarea.lead_id is not null then
    v_retroceso := private.retroceso_por_anular_reunion(
      v_tarea.lead_id, p_tarea_id, v_uid
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'tarea_id', p_tarea_id,
    'actividad_id', v_act_id,
    'siguiente_id', v_sig_id,
    'retroceso', v_retroceso
  );
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm(v_uid);
  v_tarea crm.tareas%rowtype;
  v_act_id uuid;
  v_act_cliente_id uuid;
  v_sig_id uuid;
  v_retroceso text;
  v_detalle text := nullif(btrim(coalesce(p_resultado_detalle, '')), '');
begin
  if v_uid is null or v_rol not in ('vendedor','supervisor','gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_estado is null or p_estado not in ('completada','no_show','cancelada') then
    raise exception 'Estado de cierre inválido' using errcode = '22023';
  end if;

  select * into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id and t.activo and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (select private.vendedor_ids_visibles(v_uid))
      or (t.vendedor_id is null and t.asignado_supervisor_id in (
        select private.vendedor_ids_visibles(v_uid)
      ))
    )
  for update;
  if not found then
    raise exception 'Tarea no encontrada, cerrada o fuera de tu ámbito';
  end if;

  if v_tarea.lead_id is not null then
    perform 1 from crm.leads l where l.id = v_tarea.lead_id for no key update;
  else
    perform 1 from public.perfiles p where p.id = v_tarea.perfil_id for share;
  end if;

  if p_resultado_tipo is not null and p_resultado_tipo not in (
    'llamada_realizada','llamada_no_contestada','whatsapp_enviado',
    'whatsapp_recibido','reunion_realizada','nota'
  ) then
    raise exception 'Tipo de resultado inválido' using errcode = '22023';
  end if;
  if v_tarea.tipo = 'llamada' and p_estado = 'completada'
     and p_resultado_tipo is null then
    raise exception 'Registra el resultado de la llamada (contestó / no contestó)'
      using errcode = '22023';
  end if;

  -- Clasificación de reuniones: mismo contrato cerrado que cerrar_reunion. La
  -- validación ocurre ANTES del INSERT del timeline para que ningún rechazo
  -- deje una actividad huérfana, aun si la RPC se invoca fuera del frontend.
  if v_tarea.tipo <> 'reunion' then
    if p_resultado_reunion is not null or p_motivo_no_realizada is not null then
      raise exception 'Resultado y motivo de reunión solo aplican a reuniones'
        using errcode = '22023';
    end if;
  else
    if p_resultado_reunion is not null and p_resultado_reunion not in (
      'interesado','seguimiento','propuesta','inicia_registro','no_interesado'
    ) then
      raise exception 'Resultado comercial de reunión inválido' using errcode = '22023';
    end if;

    if p_estado = 'completada' then
      -- Compatibilidad de despliegue: el bundle anterior todavía llama los
      -- cinco parámetros. Solo ese payload ausente degrada a sin_clasificar;
      -- el frontend nuevo siempre envía el valor capturado.
      p_resultado_reunion := coalesce(p_resultado_reunion, 'sin_clasificar');
      p_motivo_no_realizada := null;
    elsif p_estado = 'no_show' then
      p_resultado_reunion := null;
      p_motivo_no_realizada := 'cliente_no_asistio';
    elsif p_estado = 'cancelada' then
      p_resultado_reunion := null;
      if p_motivo_no_realizada is null then
        -- Misma ventana de compatibilidad para el bundle anterior: evita que
        -- una publicación escalonada bloquee la agenda, sin inventar uno de
        -- los motivos comerciales específicos.
        p_motivo_no_realizada := 'otro';
        v_detalle := coalesce(
          v_detalle,
          'Compatibilidad: motivo no estructurado por cliente anterior'
        );
      elsif p_motivo_no_realizada not in ('cancelada_cliente','cancelada_empresa','otro') then
        raise exception 'Registra el motivo de cancelación' using errcode = '22023';
      end if;
      if p_motivo_no_realizada = 'otro' and v_detalle is null then
        raise exception 'Describe el otro motivo de cancelación' using errcode = '22023';
      end if;
    end if;
  end if;

  if p_resultado_tipo is not null and v_tarea.lead_id is not null then
    insert into crm.actividades (lead_id, tipo, detalle, creado_por)
    values (v_tarea.lead_id, p_resultado_tipo, v_detalle, v_uid)
    returning id into v_act_id;
  elsif p_resultado_tipo is not null and v_tarea.perfil_id is not null then
    insert into crm.actividades_cliente (
      cliente_id, vendedor_id, tarea_id, tipo, detalle, creado_por
    ) values (
      v_tarea.perfil_id, v_tarea.vendedor_id, v_tarea.id, p_resultado_tipo,
      v_detalle, v_uid
    ) returning id into v_act_cliente_id;
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas set
    estado = p_estado,
    resultado_actividad_id = v_act_id,
    resultado_reunion = case
      when v_tarea.tipo = 'reunion' and p_estado = 'completada'
        then p_resultado_reunion else null end,
    motivo_no_realizada = case
      when v_tarea.tipo = 'reunion' and p_estado in ('no_show','cancelada')
        then p_motivo_no_realizada else null end,
    detalle_cierre_reunion = case
      when v_tarea.tipo = 'reunion' then v_detalle else null end
  where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  v_sig_id := private.crear_siguiente_tarea(
    v_tarea, p_siguiente,
    case when p_estado = 'no_show' then p_tarea_id else null end,
    v_uid
  );
  if p_estado = 'cancelada' and v_tarea.tipo = 'reunion'
     and v_tarea.lead_id is not null then
    v_retroceso := private.retroceso_por_anular_reunion(
      v_tarea.lead_id, p_tarea_id, v_uid
    );
  end if;

  return jsonb_build_object(
    'ok', true, 'tarea_id', p_tarea_id,
    'actividad_id', v_act_id,
    'actividad_cliente_id', v_act_cliente_id,
    'siguiente_id', v_sig_id, 'retroceso', v_retroceso
  );
end;

declare
  v_mes_actual date := date_trunc('month', now() at time zone 'America/Lima')::date;
  v_periodo    date;
  v_detalle    jsonb := '[]'::jsonb;
  v_fallo      jsonb := null;
  v_vueltas    integer := 0;
begin
  -- Gate explicito y ANTES de tocar nada, aunque `cerrar_periodo` tenga el suyo:
  -- quien llame a esto con una sesion tiene que recibir 42501 aqui, no a mitad
  -- del recorrido y con parte del trabajo hecho.
  if (select auth.uid()) is not null then
    raise exception 'El ciclo de cierre lo dispara el reloj, no una persona'
      using errcode = '42501',
            hint = 'Para cerrar un mes concreto a mano, gerencia usa crm.cerrar_periodo.';
  end if;

  loop
    v_periodo := private.cierre_mes_pendiente(v_mes_actual);
    -- Nada pendiente, o el pendiente todavia esta en su ventana de ajuste.
    exit when v_periodo is null;
    exit when now() < private.cierre_mes_ventana_desde(v_periodo);

    begin
      v_detalle := v_detalle || jsonb_build_array(crm.cerrar_periodo(v_periodo));
    exception when others then
      -- Lo sellado hasta aqui SOBREVIVE; solo revierte el mes que fallo.
      v_fallo := jsonb_build_object(
        'periodo', to_char(v_periodo, 'YYYY-MM'),
        'sqlstate', sqlstate,
        'mensaje', sqlerrm
      );
      exit;
    end;

    -- Cinturon: `cerrar_periodo` inserta en `periodos_cerrados`, asi que la
    -- siguiente vuelta ve un mes mas nuevo y el bucle avanza. Si alguna vez
    -- dejara de avanzar, mejor reventar que girar para siempre dentro de un cron.
    v_vueltas := v_vueltas + 1;
    if v_vueltas > 120 then
      raise exception 'El ciclo de cierre dio mas de 120 vueltas sin terminar: hay un mes que no avanza.';
    end if;
  end loop;

  return jsonb_build_object(
    'ok', v_fallo is null,
    'cerrados', jsonb_array_length(v_detalle),
    'detalle', v_detalle,
    'fallo', v_fallo
  );
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol_crm text := private.rol_crm(v_uid);
  v_cliente public.perfiles%rowtype;
  v_acceso_crudo boolean;
  v_acceso_crm boolean;
  v_banca_visible boolean;
  v_cuentas_bancarias_visibles boolean;
begin
  if v_uid is null or p_cliente_id is null then
    return;
  end if;

  select p.* into v_cliente
  from public.perfiles p
  where p.id = p_cliente_id and p.rol = 'cliente';
  if not found then
    return;
  end if;

  -- Espejo exacto de las vías históricas de SELECT crudo sobre perfiles. Esta
  -- rama conserva su semántica; la rama CRM agrega Supervisor/Analista sin
  -- volver a exponer la tabla compartida.
  v_acceso_crudo :=
    v_cliente.id = v_uid
    or (select public.es_gestor_cartera())
    or (
      (select private.es_analista_vigente())
      and (
        v_cliente.asesor_perfil_id = v_uid
        or (
          v_cliente.asesor_perfil_id is null
          and v_cliente.creado_por = v_uid
        )
      )
    )
    or v_rol_crm = 'gerencia';

  select exists (
    select 1
    from private.cliente_ids_visibles_crm() v
    where v.cliente_id = v_cliente.id
  ) into v_acceso_crm;

  if not coalesce(v_acceso_crudo, false)
     and not coalesce(v_acceso_crm, false) then
    return;
  end if;

  -- Quien ya podía leer la fila cruda conserva sus campos. Para el nuevo
  -- ámbito CRM, las capacidades existentes deciden; Directorio queda con
  -- identidad/contacto mínimo global, sin domicilio ni banca.
  -- La lectura de las casillas históricas y la lectura del ledger no son la
  -- misma capacidad: el acceso crudo conserva banca embebida aun en un cliente
  -- inactivo, mientras cuentas_bancarias_cliente_fn exige cliente activo.
  -- Publicar ambos bits evita que el navegador infiera uno a partir del otro.
  v_cuentas_bancarias_visibles := coalesce(
    private.puede_gestionar_cuentas_cliente(v_cliente.id), false
  );
  v_banca_visible := coalesce(v_acceso_crudo, false)
    or v_cuentas_bancarias_visibles;

  return query select
    v_cliente.id,
    v_cliente.nombre_completo,
    v_cliente.nombres,
    v_cliente.apellidos,
    v_cliente.tipo_documento,
    v_cliente.dni,
    v_cliente.correo,
    v_cliente.telefono,
    case when private.es_lector_global() then null else v_cliente.domicilio end,
    v_cliente.asesor_perfil_id,
    v_cliente.creado_por,
    v_cliente.creado_en,
    v_banca_visible,
    v_cuentas_bancarias_visibles,
    case when v_banca_visible then v_cliente.banco else null end,
    case when v_banca_visible then v_cliente.tipo_cuenta else null end,
    case when v_banca_visible then v_cliente.numero_cuenta else null end,
    case when v_banca_visible then v_cliente.cci else null end,
    case when v_banca_visible then v_cliente.titular_distinto else false end,
    case when v_banca_visible then v_cliente.beneficiario_nombre else null end,
    case when v_banca_visible then v_cliente.beneficiario_dni else null end,
    case when v_banca_visible then v_cliente.banco_usd else null end,
    case when v_banca_visible then v_cliente.tipo_cuenta_usd else null end,
    case when v_banca_visible then v_cliente.numero_cuenta_usd else null end,
    case when v_banca_visible then v_cliente.cci_usd else null end,
    case when v_banca_visible then v_cliente.titular_distinto_usd else false end,
    case when v_banca_visible then v_cliente.beneficiario_nombre_usd else null end,
    case when v_banca_visible then v_cliente.beneficiario_dni_usd else null end;
end;

declare v_n integer;
begin
  if (select auth.uid()) is not null then
    raise exception 'Solo el servicio consulta si un cliente es eliminable' using errcode = '42501';
  end if;
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada' using errcode = 'P0409';
  end if;
  if exists (select 1 from crm.inversionistas i where i.perfil_id = p_perfil_id and i.estado <> 'fusionado') then
    return pg_catalog.jsonb_build_object('eliminable', false, 'motivo', 'identidad',
      'mensaje', 'Este cliente está reconocido como persona (identidad unificada): desactívalo en vez de eliminarlo');
  end if;
  select count(*) into v_n from public.contratos c where c.cliente_id = p_perfil_id;
  if v_n > 0 then
    return pg_catalog.jsonb_build_object('eliminable', false, 'motivo', 'contratos', 'contratos', v_n,
      'mensaje', 'Este cliente tiene contratos: desactívalo en vez de eliminarlo');
  end if;
  return pg_catalog.jsonb_build_object('eliminable', true);
end;

declare
  v_uid uuid := (select auth.uid());
  v_domicilio text;
  v_actual text;
  v_filas int;
begin
  if v_uid is null then
    raise insufficient_privilege using message = 'Sesion no valida';
  end if;

  if not private.puede_gestionar_cuentas_cliente(p_cliente_id) then
    raise exception 'Cliente no encontrado o fuera de tu cartera'
      using errcode = '42501';
  end if;

  v_domicilio := crm.normalizar_domicilio_legal(p_domicilio);

  -- Techo a la espera del lock: mas vale un error claro que una pantalla
  -- colgada mientras otra transaccion larga retiene la fila.
  perform set_config('lock_timeout', '3s', true);

  -- `for no key update` y no `for update`: da la misma exclusion mutua entre
  -- dos escrituras concurrentes del domicilio y sigue conflictuando con el
  -- `for share` del alta de contrato, pero NO bloquea los inserts de tablas
  -- hijas con FK a este perfil (contratos, cuentas, leads).
  select nullif(btrim(coalesce(p.domicilio, '')), '')
  into v_actual
  from public.perfiles p
  where p.id = p_cliente_id
    and p.rol = 'cliente'
  for no key update;
  if not found then
    raise exception 'Cliente no encontrado o fuera de tu cartera'
      using errcode = '42501';
  end if;

  -- El permiso se comprueba OTRA VEZ, ya con la fila bloqueada: entre la
  -- primera comprobacion y el lock pudo esperarse a otra transaccion (una
  -- reasignacion de cartera, una baja) y la autorizacion de arriba estaria
  -- caducada. Mismo patron que private.crear_job_contrato_pdf_base.
  if not private.puede_gestionar_cuentas_cliente(p_cliente_id) then
    raise exception 'Cliente no encontrado o fuera de tu cartera'
      using errcode = '42501';
  end if;

  -- NO se devuelve el domicilio que ya estaba: el alcance incluye al supervisor
  -- del arbol, que por RLS no puede leer public.perfiles.domicilio
  -- (perfiles_analista_select exige asesor_perfil_id = auth.uid()). Devolverlo
  -- convertiria una funcion de ESCRITURA en una via de lectura de PII.
  if v_actual is not null then
    return jsonb_build_object('version', 1, 'accion', 'conservado');
  end if;

  update public.perfiles
  set domicilio = v_domicilio
  where id = p_cliente_id
    and rol = 'cliente';

  -- Sin esto, un UPDATE que toque 0 filas (RLS forzada, trigger, la fila
  -- cambiada bajo los pies) devolveria 'completado' y el vendedor veria
  -- «Domicilio legal registrado» sobre algo que no se guardo: seguiria
  -- bloqueado, y convencido de lo contrario.
  get diagnostics v_filas = row_count;
  if v_filas <> 1 then
    raise exception 'El domicilio legal no se pudo registrar (% filas afectadas)', v_filas
      using errcode = 'P0001';
  end if;

  -- Tampoco se devuelve en 'completado': es EXACTAMENTE el texto que envio
  -- quien llama, y devolverlo solo abriria la puerta a usar esta funcion como
  -- lectura disfrazada.
  return jsonb_build_object('version', 1, 'accion', 'completado');
end;

declare
  v_uid uuid := (select auth.uid());
  v_periodo_id uuid;
  v_revision integer := 0;
  v_publicada_en timestamptz;
  v_publicada_por uuid;
  v_publicada_por_nombre text;
  v_puede_editar boolean;
  v_ve_todo boolean;
  v_payload jsonb;
begin
  if v_uid is null
     or (private.rol_crm(v_uid) is null and not private.es_lector_global()) then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_periodo is null or p_periodo <> date_trunc('month',p_periodo)::date then
    raise exception 'El periodo debe ser el primer dia del mes' using errcode = '22023';
  end if;

  v_puede_editar := coalesce(private.rol_crm(v_uid) = 'gerencia', false);
  v_ve_todo := v_puede_editar or private.es_lector_global();

  select mp.id,mp.revision,mp.publicada_en,mp.publicada_por,p.nombre_completo
    into v_periodo_id,v_revision,v_publicada_en,v_publicada_por,v_publicada_por_nombre
  from crm.meta_periodos mp
  left join public.perfiles p on p.id=mp.publicada_por
  where mp.periodo=p_periodo
  order by mp.revision desc limit 1;
  v_revision := coalesce(v_revision,0);

  with dimensiones as (
    select * from (values
      ('nuevo'::text,'PEN'::text),('nuevo','USD'),
      ('renovacion','PEN'),('renovacion','USD'),
      ('upgrade','PEN'),('upgrade','USD')
    ) d(categoria,moneda)
  ), roster as (
    -- Misma fuente que usa la publicacion: lo que se ve aqui es exactamente lo
    -- que el servidor va a aceptar.
    -- Mismo coalesce que en los excluidos: nombre_completo es nullable y el
    -- contrato del front exige texto no vacio en un strictObject, asi que un
    -- nombre en blanco tumbaria la pantalla entera en vez de una fila.
    select r.vendedor_id,
           coalesce(nullif(pg_catalog.btrim(p.nombre_completo), ''),
                    '(sin nombre · ' || pg_catalog.left(r.vendedor_id::text, 8) || ')')
             as nombre_completo,
           r.supervisor_id,
           coalesce(nullif(pg_catalog.btrim(ps.nombre_completo), ''),
                    '(sin nombre · ' || pg_catalog.left(r.supervisor_id::text, 8) || ')')
             as supervisor_nombre
    from private.roster_metas_vendedores() r
    join public.perfiles p on p.id = r.vendedor_id
    join public.perfiles ps on ps.id = r.supervisor_id
    where private.es_lector_global()
       or r.vendedor_id in (select private.vendedor_ids_visibles(v_uid))
  )
  select jsonb_build_object(
    'version',1,
    'periodo',p_periodo,
    'revision',v_revision,
    'publicada_en',v_publicada_en,
    'publicada_por',v_publicada_por,
    'publicada_por_nombre',v_publicada_por_nombre,
    'puede_editar',v_puede_editar,
    -- Solo para quien gobierna el roster entero: a un supervisor no le
    -- corresponde enumerar analistas fuera de su subarbol.
    'sin_supervisor', case when v_ve_todo then coalesce((
      select jsonb_agg(jsonb_build_object(
               'vendedor_id',s.vendedor_id,'nombre',s.nombre,'motivo',s.motivo)
             order by s.nombre)
      from private.vendedores_sin_supervisor() s
    ),'[]'::jsonb) else '[]'::jsonb end,
    'vendedores',coalesce((
      select jsonb_agg(jsonb_build_object(
        'vendedor_id',r.vendedor_id,
        'nombre',r.nombre_completo,
        'supervisor_id',r.supervisor_id,
        'supervisor_nombre',r.supervisor_nombre,
        'conversion_objetivo',coalesce(mv.conversion_objetivo,0),
        'detalles',(
          select jsonb_agg(jsonb_build_object(
            'categoria',d.categoria,
            'moneda',d.moneda,
            'capital_objetivo',coalesce(md.capital_objetivo,0),
            'contratos_objetivo',coalesce(md.contratos_objetivo,0)
          ) order by array_position(array['nuevo','renovacion','upgrade'],d.categoria),d.moneda)
          from dimensiones d
          left join crm.metas_vendedor_detalle md
            on md.meta_vendedor_id=mv.id
           and md.categoria=d.categoria and md.moneda=d.moneda
        )
      ) order by r.supervisor_nombre,r.nombre_completo)
      from roster r
      left join crm.metas_vendedor mv
        on mv.meta_periodo_id=v_periodo_id and mv.vendedor_id=r.vendedor_id
    ),'[]'::jsonb)
  ) into v_payload;
  return v_payload;
end;

declare
  v_uid uuid := (select auth.uid());
  v_ultima_version integer;
  v_payload jsonb;
begin
  if v_uid is null
    or (private.rol_crm(v_uid) is null and not private.es_lector_global()) then
    raise exception 'No autorizado' using errcode='42501';
  end if;
  select max(version) into v_ultima_version from crm.sla_politicas;
  select jsonb_build_object(
    'version',1,
    'expected_version',v_ultima_version,
    'puede_editar',coalesce(private.rol_crm(v_uid)='gerencia',false),
    'politica',jsonb_build_object(
      'id',p.id,'version',p.version,'version_anterior_id',p.version_anterior_id,
      'vigente_desde',p.vigente_desde,'zona_horaria',p.zona_horaria,
      'tipo_reloj',p.tipo_reloj,
      'primera_gestion_minutos',p.primera_gestion_minutos,
      'primer_contacto_minutos',p.primer_contacto_minutos,
      'publicada_por',p.publicada_por,
      'publicada_por_nombre',(select perfil.nombre_completo
        from public.perfiles perfil where perfil.id=p.publicada_por),
      'publicada_en',p.publicada_en,
      'etapas',(select jsonb_agg(jsonb_build_object(
        'etapa',e.etapa,'maximo_minutos',e.maximo_minutos
      ) order by array_position(array['nuevo','contactado','reunion_agendada','propuesta_enviada'],e.etapa))
      from crm.sla_politica_etapas e where e.politica_id=p.id)
    )
  ) into v_payload
  from crm.sla_politicas p
  where p.id=private.sla_politica_vigente(statement_timestamp());
  return v_payload;
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text;
  v_limpia text := trim(coalesce(p_consulta, ''));
  v_normalizada text;
  v_tsquery tsquery;
  v_regla record;
  v_exacta record;
  v_ids bigint[];
  v_puntuaciones numeric[];
  v_claves text[];
  v_top numeric;
  v_segunda numeric;
  v_contenido jsonb;
  v_opciones jsonb;
  v_payload jsonb;
begin
  v_rol := private.rol_crm(v_uid);
  if v_uid is null or v_rol is null then
    raise exception 'No autorizado' using errcode = '42501';
  end if;

  if p_vista is null or not (p_vista = any(array[
    'hoy','alertas','conversiones','ranking-vendedores','reuniones','metas',
    'rendimiento','capital-cierres','pipeline','cartera','agenda','mi-cartera',
    'repartir','equipo','config','config-usuarios','config-productos',
    'config-metas','config-sla'
  ]::text[])) then
    raise exception 'Vista de ayuda no válida' using errcode = '22023';
  end if;

  if char_length(v_limpia) not between 2 and 240 then
    raise exception 'La consulta debe tener entre 2 y 240 caracteres'
      using errcode = '22023';
  end if;

  v_normalizada := private.normalizar_consulta_ayuda(v_limpia);
  if char_length(v_normalizada) < 2 then
    v_payload := jsonb_build_object(
      'version', 1,
      'tipo', 'sin_resultado',
      'consulta', v_limpia
    );
    perform private.registrar_consulta_ayuda(
      v_uid, p_vista, v_limpia, 'sin_resultado', null, null, null,
      'consulta_sin_terminos'
    );
    return v_payload;
  end if;

  -- Las ambigüedades editoriales conocidas se resuelven antes de buscar.
  select r.*
  into v_regla
  from private.ayuda_reglas_aclaracion r
  where r.activa
    and not exists (
      select 1
      from unnest(r.todos) as requerido(termino)
      where not private.consulta_contiene_termino_ayuda(
        v_normalizada,
        requerido.termino
      )
    )
    and exists (
      select 1
      from unnest(r.alguno) as disparador(termino)
      where private.consulta_contiene_termino_ayuda(
        v_normalizada,
        disparador.termino
      )
    )
    and not exists (
      select 1
      from unnest(r.ninguno) as objeto(termino)
      where private.consulta_contiene_termino_ayuda(
        v_normalizada,
        objeto.termino
      )
    )
  order by r.prioridad, r.clave
  limit 1;

  if found then
    v_payload := jsonb_build_object(
      'version', 1,
      'tipo', 'aclaracion',
      'aclaracion', jsonb_build_object(
        'titulo', v_regla.titulo,
        'detalle', v_regla.detalle,
        'opciones', v_regla.opciones
      )
    );
    perform private.registrar_consulta_ayuda(
      v_uid, p_vista, v_limpia, 'aclaracion', null, null, null,
      'regla:' || v_regla.clave
    );
    return v_payload;
  end if;

  -- Una frase editorial exacta es la única resolución que no necesita score.
  select i.id, i.clave, i.contenido
  into v_exacta
  from private.ayuda_expresiones e
  join private.ayuda_intenciones i on i.id = e.intencion_id
  where e.texto_normalizado = v_normalizada
    and i.estado = 'publicado'
  limit 1;

  if found then
    v_payload := jsonb_build_object(
      'version', 1,
      'tipo', 'respuesta',
      'respuesta', v_exacta.contenido
    );
    perform private.registrar_consulta_ayuda(
      v_uid, p_vista, v_limpia, 'respuesta', v_exacta.id, 1, null,
      'expresion_exacta:' || v_exacta.clave
    );
    return v_payload;
  end if;

  v_tsquery := websearch_to_tsquery('spanish'::regconfig, v_normalizada);

  with vocabularios as materialized (
    select
      e.intencion_id,
      string_agg(e.texto_normalizado, ' ' order by e.id) as texto
    from private.ayuda_expresiones e
    group by e.intencion_id
  ),
  expresiones_candidatas as (
    select
      i.id,
      i.clave,
      i.prioridad,
      greatest(
        extensions.similarity(e.texto_normalizado, v_normalizada),
        extensions.strict_word_similarity(e.texto_normalizado, v_normalizada),
        extensions.strict_word_similarity(v_normalizada, e.texto_normalizado)
      )::numeric as similitud,
      case
        when e.vector_busqueda @@ v_tsquery
        then ts_rank_cd(e.vector_busqueda, v_tsquery, 32)::numeric
        else 0::numeric
      end as rango_fts,
      e.peso
    from private.ayuda_expresiones e
    join private.ayuda_intenciones i on i.id = e.intencion_id
    join vocabularios v on v.intencion_id = i.id
    where i.estado = 'publicado'
      and private.cumple_grupos_ayuda(v_normalizada, i.grupos_obligatorios)
      and private.vocabulario_cubre_consulta_ayuda(
        v_normalizada,
        v.texto
      )
      and not exists (
        select 1
        from unnest(i.terminos_excluidos) as excluido(termino)
        where private.consulta_contiene_termino_ayuda(
          v_normalizada,
          excluido.termino
        )
      )
      and (
        e.vector_busqueda @@ v_tsquery
        or e.texto_normalizado operator(extensions.%) v_normalizada
      )
  ),
  puntuadas as (
    select
      c.id,
      c.clave,
      c.prioridad,
      least(
        1::numeric,
        0.82::numeric * c.similitud
        + 0.14::numeric * least(1::numeric, c.rango_fts * 8::numeric)
        + 0.04::numeric * c.peso
      ) as puntuacion
    from expresiones_candidatas c
  ),
  por_intencion as (
    select
      p.id,
      p.clave,
      min(p.prioridad) as prioridad,
      max(p.puntuacion) as puntuacion
    from puntuadas p
    group by p.id, p.clave
  ),
  primeras as (
    select p.*
    from por_intencion p
    order by p.puntuacion desc, p.prioridad, p.clave
    limit 3
  )
  select
    array_agg(p.id order by p.puntuacion desc, p.prioridad, p.clave),
    array_agg(p.puntuacion order by p.puntuacion desc, p.prioridad, p.clave),
    array_agg(p.clave order by p.puntuacion desc, p.prioridad, p.clave)
  into v_ids, v_puntuaciones, v_claves
  from primeras p;

  v_top := v_puntuaciones[1];
  v_segunda := v_puntuaciones[2];

  -- Umbral y margen son independientes: una opción fuerte pero empatada
  -- pregunta antes de actuar. La pantalla actual no modifica ninguno.
  if v_top >= 0.61
     and (v_segunda is null or v_top - v_segunda >= 0.12) then
    select i.contenido into v_contenido
    from private.ayuda_intenciones i
    where i.id = v_ids[1];

    v_payload := jsonb_build_object(
      'version', 1,
      'tipo', 'respuesta',
      'respuesta', v_contenido
    );
    perform private.registrar_consulta_ayuda(
      v_uid, p_vista, v_limpia, 'respuesta', v_ids[1], v_top, v_segunda,
      'ranking_con_margen:' || v_claves[1]
    );
    return v_payload;
  end if;

  if v_top >= 0.56
     and v_segunda >= 0.56
     and v_top - v_segunda < 0.12 then
    select jsonb_agg(
      jsonb_build_object(
        'etiqueta', i.pregunta,
        'detalle', i.contenido ->> 'resumen',
        'consulta', i.pregunta
      ) order by array_position(v_ids, i.id)
    )
    into v_opciones
    from private.ayuda_intenciones i
    where i.id = any(v_ids[1:2]);

    v_payload := jsonb_build_object(
      'version', 1,
      'tipo', 'aclaracion',
      'aclaracion', jsonb_build_object(
        'titulo', 'Encontré más de una posibilidad',
        'detalle', 'Elige la situación que se parece a lo que necesitas para no aplicar la guía equivocada.',
        'opciones', v_opciones
      )
    );
    perform private.registrar_consulta_ayuda(
      v_uid, p_vista, v_limpia, 'aclaracion', null, v_top, v_segunda,
      'ranking_sin_margen:' || coalesce(v_claves[1], '-') || ':' || coalesce(v_claves[2], '-')
    );
    return v_payload;
  end if;

  v_payload := jsonb_build_object(
    'version', 1,
    'tipo', 'sin_resultado',
    'consulta', v_limpia
  );
  perform private.registrar_consulta_ayuda(
    v_uid, p_vista, v_limpia, 'sin_resultado', null, v_top, v_segunda,
    case when v_top is null then 'sin_candidatos' else 'evidencia_insuficiente' end
  );
  return v_payload;
end;

declare
  v_eliminacion private.contrato_eliminaciones%rowtype;
  v_objetos integer;
  -- Claim que había al entrar (NULL bajo service_role): se restaura al salir, como en
  -- private.poder_eliminar_contrato_como.
  v_sub_anterior text := current_setting('request.jwt.claim.sub', true);
begin
  perform private.bloquear_fila_contrato_pdf(p_contrato_id);

  select * into v_eliminacion
  from private.contrato_eliminaciones e
  where e.contrato_id = p_contrato_id
    and e.token = p_token
    and e.solicitado_por = p_actor_id
  for update;
  if not found then
    raise exception 'La preparación de eliminación no existe o venció'
      using errcode = 'P0002';
  end if;
  v_objetos := jsonb_array_length(v_eliminacion.objetos);

  -- El DELETE queda auditado a nombre del actor que preparó la eliminación (ya validado
  -- arriba por token + solicitado_por), aunque quien llame sea service_role —la edge del
  -- botón «Eliminar contrato» de Gerencia—: public.log_audit_change lee auth.uid(), que en
  -- esta base resuelve request.jwt.claim.sub. Sin esto el rastro quedaba con usuario NULL
  -- (medido en producción el 05/09/2026). Local a la transacción y restaurado al salir.
  perform set_config('request.jwt.claim.sub', p_actor_id::text, true);
  perform set_config(
    'crm.contrato_pdf_eliminacion_autorizada', p_contrato_id::text, true
  );
  begin
    delete from private.contrato_pdfs p
    where p.contrato_id = p_contrato_id;
    delete from private.contrato_pdf_jobs j
    where j.contrato_id = p_contrato_id;
    delete from private.contrato_eliminaciones e
    where e.contrato_id = p_contrato_id;
    delete from public.contratos c
    where c.id = p_contrato_id;
    if not found then
      raise exception 'Contrato no encontrado' using errcode = 'P0002';
    end if;
  exception when others then
    perform set_config(
      'crm.contrato_pdf_eliminacion_autorizada', '', true
    );
    perform set_config('request.jwt.claim.sub', coalesce(v_sub_anterior, ''), true);
    raise;
  end;
  perform set_config('crm.contrato_pdf_eliminacion_autorizada', '', true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub_anterior, ''), true);

  return jsonb_build_object(
    'ok', true,
    'contrato_id', p_contrato_id,
    'objetos_eliminados', v_objetos
  );
end;

declare
  v_poder jsonb;
  v_eliminacion private.contrato_eliminaciones%rowtype;
  v_objetos jsonb;
begin
  perform private.bloquear_fila_contrato_pdf(p_contrato_id);
  v_poder := private.poder_eliminar_contrato_como(
    p_contrato_id, p_actor_id
  );
  if not coalesce((v_poder->>'admin')::boolean, false) then
    raise insufficient_privilege using
      message = 'Solo Admin o Superadmin puede eliminar contratos';
  end if;
  if coalesce((v_poder->>'tiene_pagos')::boolean, false)
     and not coalesce((v_poder->>'superadmin')::boolean, false) then
    raise insufficient_privilege using
      message = 'Este contrato tiene pagos; solo Superadmin puede eliminarlo';
  end if;

  select * into v_eliminacion
  from private.contrato_eliminaciones e
  where e.contrato_id = p_contrato_id
  for update;
  if found then
    return jsonb_build_object(
      'contrato_id', v_eliminacion.contrato_id,
      'token', v_eliminacion.token,
      'objetos', v_eliminacion.objetos
    );
  end if;

  if exists (
    select 1
    from private.contrato_pdf_jobs j
    where j.contrato_id = p_contrato_id
      and j.estado in ('procesando', 'subido_verificado')
      and j.lease_expira_en > statement_timestamp()
  ) then
    raise exception
      'El PDF se está generando; reintenta la eliminación en unos minutos'
      using errcode = '55000';
  end if;

  if exists (
    select 1
    from public.documentos d
    where d.contrato_id = p_contrato_id
      and (
        d.storage_path is null
        or d.storage_path <> btrim(d.storage_path)
        or length(d.storage_path) not between 5 and 1024
        or left(d.storage_path, length(p_contrato_id::text) + 1)
             <> p_contrato_id::text || '/'
        or strpos(d.storage_path, '..') > 0
        or strpos(d.storage_path, '//') > 0
        or strpos(d.storage_path, E'\\') > 0
        or d.storage_path ~ '[[:cntrl:]]'
      )
  ) then
    raise exception 'Un documento del contrato tiene una ruta Storage inválida'
      using errcode = '23514';
  end if;

  select coalesce(jsonb_agg(objeto order by objeto->>'bucket', objeto->>'path'), '[]'::jsonb)
  into v_objetos
  from (
    select distinct jsonb_build_object(
      'bucket', 'contratos-generados', 'path', x.storage_path
    ) as objeto
    from (
      select j.storage_path
      from private.contrato_pdf_jobs j
      where j.contrato_id = p_contrato_id
      union
      select p.storage_path
      from private.contrato_pdfs p
      where p.contrato_id = p_contrato_id
    ) x
    where x.storage_path is not null

    union

    select distinct jsonb_build_object(
      'bucket', 'documentos', 'path', d.storage_path
    ) as objeto
    from public.documentos d
    where d.contrato_id = p_contrato_id
      and d.storage_path is not null
      and btrim(d.storage_path) <> ''
  ) objetos;

  if jsonb_array_length(v_objetos) > 1000 then
    raise exception 'El contrato supera el límite seguro de archivos para borrar'
      using errcode = '54000';
  end if;

  insert into private.contrato_eliminaciones (
    contrato_id, solicitado_por, objetos
  ) values (
    p_contrato_id, p_actor_id, v_objetos
  ) returning * into v_eliminacion;

  return jsonb_build_object(
    'contrato_id', v_eliminacion.contrato_id,
    'token', v_eliminacion.token,
    'objetos', v_eliminacion.objetos
  );
end;

declare
  v_estado jsonb;
begin
  if not private.puede_leer_contrato_pdf(p_contrato_id) then
    raise insufficient_privilege using
