declare
  v_actor uuid := (select auth.uid());
  v_nombre text;
  v_rol_portal text;
  v_perfil_activo boolean;
  v_tiene_equipo boolean;
  v_rol_crm text;
  v_equipo_activo boolean;
  v_es_gerencia boolean := false;
  v_es_superadmin boolean := false;
  v_es_directorio boolean := false;
begin
  if v_actor is null then
    raise insufficient_privilege using message = 'Sesion CRM requerida';
  end if;

  select p.nombre_completo, p.rol, p.activo,
         e.perfil_id is not null, e.rol_crm, e.activo
    into v_nombre, v_rol_portal, v_perfil_activo,
         v_tiene_equipo, v_rol_crm, v_equipo_activo
  from public.perfiles p
  left join crm.equipo e on e.perfil_id = p.id
  where p.id = v_actor;

  if not found then
    return pg_catalog.jsonb_build_object(
      'estado', 'no_enrolado', 'perfil_id', v_actor,
      'puede_listar_usuarios', false,
      'puede_administrar_usuarios', false,
      'puede_organizar_jerarquia', false,
      'puede_administrar_roles', false,
      'puede_contratar', false
    );
  end if;

  if v_perfil_activo is not true
     or (v_tiene_equipo and (
       v_equipo_activo is not true
       or v_rol_crm not in ('vendedor','supervisor','gerencia','coordinador','directorio')
     )) then
    return pg_catalog.jsonb_build_object(
      'estado', 'revocado', 'perfil_id', v_actor,
      'puede_listar_usuarios', false,
      'puede_administrar_usuarios', false,
      'puede_organizar_jerarquia', false,
      'puede_administrar_roles', false,
      'puede_contratar', false
    );
  end if;

  v_es_gerencia := private.es_gerencia_crm_activa();
  v_es_superadmin := private.es_superadmin_portal_activo();
  v_es_directorio := private.es_directorio_crm_activo();

  if v_es_superadmin and not v_es_gerencia then
    return pg_catalog.jsonb_build_object(
      'estado', 'administrador_roles', 'perfil_id', v_actor,
      'rol_portal', v_rol_portal,
      'nombre_completo', v_nombre,
      'puede_listar_usuarios', true,
      'puede_administrar_usuarios', false,
      'puede_organizar_jerarquia', false,
      'puede_administrar_roles', true,
      'puede_contratar', false
    );
  end if;

  if v_tiene_equipo then
    return pg_catalog.jsonb_build_object(
      'estado', 'miembro', 'perfil_id', v_actor,
      'rol_crm', v_rol_crm, 'rol_portal', v_rol_portal,
      'nombre_completo', v_nombre,
      'puede_listar_usuarios',
        v_es_gerencia or v_es_superadmin or v_es_directorio,
      'puede_administrar_usuarios', v_es_gerencia,
      'puede_organizar_jerarquia', v_es_gerencia,
      'puede_administrar_roles', v_es_superadmin,
      'puede_contratar', private.puede_gestionar_contratos_crm()
    );
  end if;

  if v_rol_portal = 'directorio' then
    return pg_catalog.jsonb_build_object(
      'estado', 'global', 'perfil_id', v_actor,
      'rol_crm', 'directorio', 'rol_portal', v_rol_portal,
      'nombre_completo', v_nombre,
      'puede_listar_usuarios', v_es_superadmin or v_es_directorio,
      'puede_administrar_usuarios', false,
      'puede_organizar_jerarquia', false,
      'puede_administrar_roles', v_es_superadmin,
      'puede_contratar', false
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'estado', 'no_enrolado', 'perfil_id', v_actor,
    'puede_listar_usuarios', false,
    'puede_administrar_usuarios', false,
    'puede_organizar_jerarquia', false,
    'puede_administrar_roles', false,
    'puede_contratar', false
  );
end;

declare
  -- Espacios exoticos que SI ocupan sitio: se convierten en espacio normal.
  v_espacios constant text := U&'\00A0\2007\202F\3000\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\205F';
  -- Invisibles de ancho CERO y controles de direccion: no se normalizan, se
  -- RECHAZAN. Escritos con escapes Unicode a proposito — pegarlos literales
  -- volveria este fichero ilegible y no auditable.
  v_invisibles constant text :=
    U&'[\00AD\180E\200B\200C\200D\200E\200F\2028\2029\202A\202B\202C\202D\202E\2060\2061\2062\2063\2064\FEFF]';
  v_min constant int := 15;
  v_max constant int := 240;
  v_out text;
  v_plano text;
begin
  v_out := coalesce(p_domicilio, '');
  v_out := translate(v_out, v_espacios, repeat(' ', length(v_espacios)));
  v_out := btrim(regexp_replace(v_out, '\s+', ' ', 'g'));

  if v_out = '' then
    raise exception 'Completa el domicilio legal del cliente.'
      using errcode = '22023';
  end if;
  if v_out ~ v_invisibles then
    raise exception 'El domicilio legal contiene caracteres invisibles que no se imprimirian en el contrato.'
      using errcode = '22023';
  end if;
  -- length() sobre text cuenta CARACTERES, igual que el Array.from() del
  -- navegador.
  if length(v_out) not between v_min and v_max or v_out ~ '[[:cntrl:]]' then
    raise exception
      'El domicilio legal debe tener entre % y % caracteres válidos; escribe la calle, el número y el distrito.',
      v_min, v_max
      using errcode = '22023';
  end if;

  -- Al menos un digito. Los 19 domicilios reales de produccion lo cumplen sin
  -- excepcion, y es lo que separa una direccion de un relleno: `LIMA.`,
  -- `PENDIENTE`, `no tiene`, `Su casa` caen todos aqui.
  if v_out !~ '[0-9]' then
    raise exception
      'El domicilio legal necesita el número de la calle, el lote o la manzana.'
      using errcode = '22023';
  end if;

  -- Un unico caracter repetido: `.....`, `xxxxxxxxxxxxxxxx`, `----------------`.
  if length(regexp_replace(v_out, '[^[:alnum:]]', '', 'g')) > 0
     and (select count(distinct c) from regexp_split_to_table(
            regexp_replace(lower(v_out), '[^[:alnum:]]', '', 'g'), '') as t(c)) = 1 then
    raise exception 'El domicilio legal no puede ser un solo carácter repetido.'
      using errcode = '22023';
  end if;

  -- La direccion de la PROPIA Avance Corp. Se compara en plano (sin tildes, sin
  -- mayusculas, sin puntuacion) para que no la salve un acento o un «N.°».
  v_plano := lower(translate(v_out,
    'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'));
  v_plano := regexp_replace(v_plano, '[^a-z0-9 ]', '', 'g');
  v_plano := regexp_replace(v_plano, '\s+', ' ', 'g');
  if v_plano like '%republica de panama%' and v_plano like '%3635%' then
    raise exception
      'Esa es la dirección de Avance Corp, no la del cliente: el contrato dejaría a las dos partes domiciliadas en el mismo sitio.'
      using errcode = '22023';
  end if;

  return v_out;
end;

begin
  new.actualizado_por := (select auth.uid());
  new.actualizado_en := pg_catalog.now();
  return new;
end;

declare
  v_uid uuid := (select auth.uid());
  v_revision_actual integer;
  v_revision_nueva integer;
  v_anterior_id uuid;
  v_periodo_id uuid;
  v_total_roster integer;
  v_total_enviadas integer;
  v_item record;
  v_detalle record;
  v_vendedor_id uuid;
  v_supervisor_id uuid;
  v_meta_vendedor_id uuid;
  v_conversion numeric;
  v_capital numeric;
  v_contratos numeric;
  v_categoria text;
  v_moneda text;
begin
  if v_uid is null or private.rol_crm(v_uid) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia activa puede publicar metas comerciales'
      using errcode = '42501';
  end if;
  if p_periodo is null or p_periodo <> date_trunc('month', p_periodo)::date then
    raise exception 'El periodo debe ser el primer dia del mes' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected_revision debe ser cero o positivo' using errcode = '22023';
  end if;
  if p_metas is null or jsonb_typeof(p_metas) <> 'object' then
    raise exception 'Las metas deben ser un objeto por vendedor' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.meta_periodos'),
    (p_periodo - date '2000-01-01')::integer
  );
  -- La publicacion fotografía un roster completo. El lock evita que una alta,
  -- baja o reasignacion concurrente lo cambie entre la validacion y el INSERT.
  lock table crm.equipo in share mode;
  -- Antes esto era `lock table public.perfiles in share mode`, y eso congelaba
  -- las escrituras del PORTAL EN PRODUCCION —altas y ediciones de perfil— cada
  -- vez que Gerencia publicaba metas del CRM. El aislamiento que hace falta es
  -- solo sobre el flag `activo` de la gente del equipo comercial (21 filas),
  -- porque es lo que puede cambiar `private.rol_crm` a mitad de transaccion;
  -- nadie puede entrar al roster sin fila en crm.equipo, que ya esta bloqueada.
  perform 1 from public.perfiles p
  where p.id in (select e.perfil_id from crm.equipo e)
  for share;

  select mp.id, mp.revision into v_anterior_id, v_revision_actual
  from crm.meta_periodos mp where mp.periodo = p_periodo
  order by mp.revision desc limit 1;
  v_revision_actual := coalesce(v_revision_actual, 0);
  if p_expected_revision <> v_revision_actual then
    raise exception 'Conflicto de revision: esperada %, vigente %',
      p_expected_revision, v_revision_actual using errcode = '40001';
  end if;
  v_revision_nueva := v_revision_actual + 1;

  -- El conjunto exigido es EXACTAMENTE el que el editor ofrece. Un vendedor sin
  -- supervisor activo no cabe en crm.metas_vendedor (supervisor_id NOT NULL):
  -- antes se exigia su meta igual y eso hacia imposible publicar el mes entero.
  select count(*)::integer into v_total_roster from private.roster_metas_vendedores();
  select count(*)::integer into v_total_enviadas from jsonb_object_keys(p_metas);

  if v_total_roster = 0 then
    raise exception 'No hay analistas con supervisor activo a los que fijarles meta'
      using errcode = '22023';
  end if;

  -- Sin claves faltantes y con los totales iguales, tampoco puede sobrar
  -- ninguna: el conjunto enviado es el roster exacto.
  if v_total_enviadas <> v_total_roster
     or exists (
       select 1 from private.roster_metas_vendedores() r
       where not (p_metas ? r.vendedor_id::text)
     ) then
    raise exception
      'Debe enviarse exactamente una meta por analista del roster (esperadas %, recibidas %); recarga la pantalla',
      v_total_roster, v_total_enviadas using errcode = '22023';
  end if;

  insert into crm.meta_periodos (
    periodo, revision, revision_anterior_id, publicada_por
  ) values (p_periodo, v_revision_nueva, v_anterior_id, v_uid)
  returning id into v_periodo_id;

  -- Los mensajes de este bucle NO nombran al vendedor. Antes interpolaban su
  -- UUID, que viaja al cliente con el 22023 y de ahi a Sentry (el scrub de
  -- observabilidad limpia correos y tokens, no UUID). Nadie los necesita: el
  -- payload lo construye el propio front, asi que un fallo de formato es un
  -- bug del cliente, no un dato que Gerencia deba leer.
  for v_item in select key, value from jsonb_each(p_metas) loop
    begin v_vendedor_id := v_item.key::uuid;
    exception when invalid_text_representation then
      raise exception 'Identificador de vendedor invalido' using errcode = '22023';
    end;

    if jsonb_typeof(v_item.value) <> 'object'
       or not (v_item.value ?& array['conversion_objetivo','detalles'])
       or (v_item.value - array['conversion_objetivo','detalles']) <> '{}'::jsonb
       or jsonb_typeof(v_item.value->'conversion_objetivo') is distinct from 'number'
       or jsonb_typeof(v_item.value->'detalles') is distinct from 'array'
       or jsonb_array_length(v_item.value->'detalles') <> 6 then
      raise exception 'Formato de meta invalido en el payload enviado' using errcode = '22023';
    end if;
    v_conversion := (v_item.value->>'conversion_objetivo')::numeric;
    if v_conversion < 0 or v_conversion > 100 then
      raise exception 'Conversion fuera de rango en el payload enviado' using errcode = '22023';
    end if;

    select r.supervisor_id into v_supervisor_id
    from private.roster_metas_vendedores() r
    where r.vendedor_id = v_vendedor_id;
    if not found then
      raise exception 'Vendedor o supervisor fuera de jerarquia activa' using errcode = '23503';
    end if;

    insert into crm.metas_vendedor (
      meta_periodo_id, vendedor_id, supervisor_id, conversion_objetivo
    ) values (v_periodo_id, v_vendedor_id, v_supervisor_id, v_conversion)
    returning id into v_meta_vendedor_id;

    for v_detalle in select value from jsonb_array_elements(v_item.value->'detalles') loop
      if jsonb_typeof(v_detalle.value) <> 'object'
         or not (v_detalle.value ?& array['categoria','moneda','capital_objetivo','contratos_objetivo'])
         or (v_detalle.value - array['categoria','moneda','capital_objetivo','contratos_objetivo']) <> '{}'::jsonb
         or jsonb_typeof(v_detalle.value->'categoria') is distinct from 'string'
         or jsonb_typeof(v_detalle.value->'moneda') is distinct from 'string'
         or jsonb_typeof(v_detalle.value->'capital_objetivo') is distinct from 'number'
         or jsonb_typeof(v_detalle.value->'contratos_objetivo') is distinct from 'number' then
        raise exception 'Detalle de meta invalido en el payload enviado' using errcode = '22023';
      end if;
      v_categoria := v_detalle.value->>'categoria';
      v_moneda := v_detalle.value->>'moneda';
      v_capital := (v_detalle.value->>'capital_objetivo')::numeric;
      v_contratos := (v_detalle.value->>'contratos_objetivo')::numeric;
      if v_categoria not in ('nuevo','renovacion','upgrade')
         or v_moneda not in ('PEN','USD')
         or v_capital < 0 or v_capital > 100000000
         or v_contratos < 0 or v_contratos > 1000 or trunc(v_contratos) <> v_contratos then
        raise exception 'Detalle de meta fuera de rango en el payload enviado' using errcode = '22023';
      end if;
      begin
        insert into crm.metas_vendedor_detalle (
          meta_vendedor_id,categoria,moneda,capital_objetivo,contratos_objetivo
        ) values (v_meta_vendedor_id,v_categoria,v_moneda,v_capital,v_contratos::integer);
      exception when unique_violation then
        raise exception 'Categoria/moneda repetida en el payload enviado' using errcode = '22023';
      end;
    end loop;
  end loop;

  return query select mp.* from crm.meta_periodos mp where mp.id = v_periodo_id;
end;

declare
  v_uid uuid := (select auth.uid());
  v_actual integer; v_anterior uuid; v_ultimo timestamptz;
  v_tasa numeric; v_tope numeric; v_dias numeric; v_modo text; v_nota text;
  v_fila crm.politica_rentabilidad;
  v_desde timestamptz := clock_timestamp();
begin
  if v_uid is null or private.rol_crm(v_uid) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia activa publica la política de rentabilidad' using errcode = '42501';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception 'expected_version inválido' using errcode = '22023';
  end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object'
     or not (p_config ?& array['tasa_base_nueva', 'tope_tecnico', 'vigencia_solicitud_dias', 'modo'])
     or (p_config - array['tasa_base_nueva', 'tope_tecnico', 'vigencia_solicitud_dias', 'modo', 'nota']) <> '{}'::jsonb
     or jsonb_typeof(p_config -> 'tasa_base_nueva') is distinct from 'number'
     or jsonb_typeof(p_config -> 'tope_tecnico') is distinct from 'number'
     or jsonb_typeof(p_config -> 'vigencia_solicitud_dias') is distinct from 'number'
     or jsonb_typeof(p_config -> 'modo') is distinct from 'string'
     or (p_config ? 'nota' and jsonb_typeof(p_config -> 'nota') not in ('string', 'null')) then
    raise exception 'Formato de política inválido' using errcode = '22023';
  end if;
  v_tasa := (p_config ->> 'tasa_base_nueva')::numeric;
  v_tope := (p_config ->> 'tope_tecnico')::numeric;
  v_dias := (p_config ->> 'vigencia_solicitud_dias')::numeric;
  v_modo := p_config ->> 'modo';
  v_nota := nullif(btrim(p_config ->> 'nota'), '');
  if v_tasa <= 0 or v_tasa > 50 or v_tope <= 0 or v_tope > 50 or v_tope < v_tasa
     or trunc(v_dias) <> v_dias or v_dias < 1 or v_dias > 30 then
    raise exception 'Política fuera de rango (tasa 0-50, tope >= tasa y <= 50, vigencia 1-30 días)' using errcode = '22023';
  end if;
  if v_modo not in ('observacion', 'enforcement') then
    raise exception 'Modo inválido: observacion o enforcement' using errcode = '22023';
  end if;
  if v_modo = 'enforcement' then
    -- R1/R2: nada lee aún el modo enforcement; publicarlo prometería un bloqueo que no existe. Se habilita en R4.
    raise exception 'El modo enforcement todavía no está construido (llega en R4); publica en observacion' using errcode = '0A000';
  end if;
  if v_nota is not null and length(v_nota) > 500 then
    raise exception 'La nota no puede superar 500 caracteres' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('crm.politica_rentabilidad'), 1);
  select p.id, p.version, p.vigente_desde into v_anterior, v_actual, v_ultimo
  from crm.politica_rentabilidad p order by p.version desc limit 1;
  if p_expected_version <> v_actual then
    raise exception 'Conflicto de versión: esperada %, vigente %', p_expected_version, v_actual using errcode = '40001';
  end if;
  if v_desde <= v_ultimo then
    v_desde := v_ultimo + interval '1 millisecond';
  end if;
  insert into crm.politica_rentabilidad (version, version_anterior_id, vigente_desde, tasa_base_nueva, tope_tecnico,
                                         vigencia_solicitud_dias, modo, nota, publicada_por)
  values (v_actual + 1, v_anterior, v_desde, v_tasa, v_tope, v_dias::integer, v_modo, v_nota, v_uid)
  returning * into v_fila;
  return to_jsonb(v_fila) || jsonb_build_object('ok', true);
end;

declare
  v_uid uuid := (select auth.uid());
  v_actual integer;
  v_anterior uuid;
  v_ultimo_desde timestamptz;
  v_desde timestamptz := coalesce(p_vigente_desde,statement_timestamp());
  v_id uuid;
  v_gestion numeric;
  v_contacto numeric;
  v_regla record;
  v_etapa text;
  v_maximo numeric;
begin
  if v_uid is null or private.rol_crm(v_uid) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia activa puede publicar politicas SLA' using errcode='42501';
  end if;
  if p_expected_version is null or p_expected_version<1 then
    raise exception 'expected_version invalido' using errcode='22023';
  end if;
  if p_config is null or jsonb_typeof(p_config)<>'object'
    or not (p_config ?& array['zona_horaria','tipo_reloj','primera_gestion_minutos','primer_contacto_minutos','etapas'])
    or (p_config-array['zona_horaria','tipo_reloj','primera_gestion_minutos','primer_contacto_minutos','etapas'])<>'{}'::jsonb
    or jsonb_typeof(p_config->'zona_horaria') is distinct from 'string'
    or jsonb_typeof(p_config->'tipo_reloj') is distinct from 'string'
    or jsonb_typeof(p_config->'primera_gestion_minutos') is distinct from 'number'
    or jsonb_typeof(p_config->'primer_contacto_minutos') is distinct from 'number'
    or jsonb_typeof(p_config->'etapas') is distinct from 'array'
    or jsonb_array_length(p_config->'etapas')<>4 then
    raise exception 'Formato SLA invalido' using errcode='22023';
  end if;
  if p_config->>'zona_horaria'<>'America/Lima' or p_config->>'tipo_reloj'<>'corrido' then
    raise exception 'Solo America/Lima y reloj corrido' using errcode='22023';
  end if;
  v_gestion := (p_config->>'primera_gestion_minutos')::numeric;
  v_contacto := (p_config->>'primer_contacto_minutos')::numeric;
  if trunc(v_gestion)<>v_gestion or trunc(v_contacto)<>v_contacto
    or v_gestion<1 or v_gestion>43200
    or v_contacto<v_gestion or v_contacto>43200 then
    raise exception 'Plazos SLA fuera de rango' using errcode='22023';
  end if;
  if not isfinite(v_desde) or v_desde<statement_timestamp() then
    raise exception 'La vigencia debe iniciar ahora o en el futuro' using errcode='22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm.sla_politicas'),1);
  select p.id,p.version,p.vigente_desde into v_anterior,v_actual,v_ultimo_desde
  from crm.sla_politicas p order by p.version desc limit 1;
  if p_expected_version<>v_actual then
    raise exception 'Conflicto de version SLA: esperada %, vigente %',p_expected_version,v_actual
      using errcode='40001';
  end if;
  if v_desde<=v_ultimo_desde then
    raise exception 'La vigencia debe ser posterior a la ultima politica' using errcode='22023';
  end if;

  insert into crm.sla_politicas(
    version,version_anterior_id,vigente_desde,zona_horaria,tipo_reloj,
    primera_gestion_minutos,primer_contacto_minutos,publicada_por
  ) values (v_actual+1,v_anterior,v_desde,'America/Lima','corrido',
    v_gestion::integer,v_contacto::integer,v_uid) returning id into v_id;

  for v_regla in select value from jsonb_array_elements(p_config->'etapas') loop
    if jsonb_typeof(v_regla.value)<>'object'
      or not (v_regla.value ?& array['etapa','maximo_minutos'])
      or (v_regla.value-array['etapa','maximo_minutos'])<>'{}'::jsonb
      or jsonb_typeof(v_regla.value->'etapa') is distinct from 'string'
      or jsonb_typeof(v_regla.value->'maximo_minutos') is distinct from 'number' then
      raise exception 'Regla SLA invalida' using errcode='22023';
    end if;
    v_etapa:=v_regla.value->>'etapa'; v_maximo:=(v_regla.value->>'maximo_minutos')::numeric;
    if v_etapa not in ('nuevo','contactado','reunion_agendada','propuesta_enviada')
      or trunc(v_maximo)<>v_maximo or v_maximo<1 or v_maximo>43200 then
      raise exception 'Regla SLA fuera de rango' using errcode='22023';
    end if;
    begin
      insert into crm.sla_politica_etapas(politica_id,etapa,maximo_minutos)
      values(v_id,v_etapa,v_maximo::integer);
    exception when unique_violation then
      raise exception 'Etapa SLA repetida: %',v_etapa using errcode='22023';
    end;
  end loop;
  return query select p.* from crm.sla_politicas p where p.id=v_id;
end;

declare
  v_actor uuid := (select auth.uid());
  v_producto crm.productos_inversion%rowtype;
  v_version crm.producto_versiones%rowtype;
begin
  if private.rol_crm(v_actor) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia puede publicar productos de inversión'
      using errcode = '42501';
  end if;

  select p.* into v_producto
  from crm.productos_inversion p
  where p.id = (
    select v.producto_id from crm.producto_versiones v
    where v.id = p_version_id
  )
  for update;
  if not found then
    raise exception 'Versión no encontrada' using errcode = 'P0002';
  end if;

  select * into v_version
  from crm.producto_versiones v
  where v.id = p_version_id
  for update;

  if v_producto.es_legacy or v_producto.estado <> 'activo'
     or v_version.estado <> 'borrador' then
    raise exception 'Solo puede publicarse un borrador de producto activo'
      using errcode = '23514';
  end if;
  if p_expected_revision is distinct from v_version.revision then
    raise exception 'El borrador cambió; recarga antes de publicar'
      using errcode = '40001';
  end if;
  if v_version.vigente_desde > current_date
     or (v_version.vigente_hasta is not null
       and v_version.vigente_hasta < current_date) then
    raise exception 'La versión debe estar vigente el día de su publicación'
      using errcode = '23514';
  end if;
  if not exists (
    select 1 from crm.producto_condiciones c
    where c.version_id = p_version_id and c.activa and not c.es_legacy
  ) then
    raise exception 'La versión no tiene condiciones activas'
      using errcode = '23514';
  end if;

  update crm.producto_versiones
     set estado = 'retirada',
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now(),
         retirada_por = v_actor,
         retirada_en = now()
   where producto_id = v_producto.id
     and estado = 'publicada';

  update crm.producto_versiones
     set estado = 'publicada',
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now(),
         publicada_por = v_actor,
         publicada_en = now()
   where id = p_version_id;

  update crm.productos_inversion
     set revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now()
   where id = v_producto.id;

  return jsonb_build_object(
    'producto_id', v_producto.id,
    'producto_revision', v_producto.revision + 1,
    'version_id', p_version_id,
    'version_revision', v_version.revision + 1,
    'numero_version', v_version.numero_version,
    'estado', 'publicada'
  );
end;

declare
  v_fila crm.equipo%rowtype;
begin
  if length(btrim(coalesce(p_motivo, ''))) < 20 then
    raise exception 'Purgar una membresia exige un motivo escrito de al menos 20 caracteres.'
      using errcode = '22023';
  end if;

  select * into v_fila from crm.equipo where perfil_id = p_perfil_id;
  if not found then
    raise exception 'No hay membresia que purgar para %', p_perfil_id using errcode = 'P0002';
  end if;

  insert into private.membresias_purgadas (perfil_id, rol_crm, activo_al_purgar, motivo)
  values (v_fila.perfil_id, v_fila.rol_crm, v_fila.activo, btrim(p_motivo));

  perform set_config('crm.purgando_membresia', 'on', true);
  delete from crm.equipo where perfil_id = p_perfil_id;
  perform set_config('crm.purgando_membresia', '', true);
end;

declare
  v_uid     uuid := (select auth.uid());
  v_rol     text := private.rol_crm((select auth.uid()));
  v_lead    crm.leads%rowtype;
  v_bloqueo jsonb;
  v_v       jsonb;
  v_previo  text;
  v_inv     uuid;
  v_flag    boolean;
begin
  -- F2.b [D-15]: la puerta del botón «Reabrir» del CRM (analista, supervisor o Gerencia, sobre un lead de su ámbito).
  -- Sustituye el UPDATE directo de etapa que hacía el front, que con la identidad encendida cierra el trigger
  -- «reabrir solo por RPC» de D-13 (P0409): reabrir tiene que juzgar a la PERSONA y enlazar el lead, como tomar,
  -- rescatar y deshacer. Con la bandera apagada es EXACTAMENTE el UPDATE de hoy (mismos triggers, mismos índices).
  if v_uid is null or v_rol is null or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception 'Solo un analista, un supervisor o Gerencia reabre un lead' using errcode = '42501';
  end if;
  if p_lead_id is null then
    raise exception 'El lead es obligatorio' using errcode = '22023';
  end if;
  -- Ámbito ANTES de cualquier candado (auditor D-13 v4 M1): un lead ajeno o inexistente muere aquí sin sondear a nadie.
  -- Mismo predicado que la policy leads_update (el UPDATE que hacía el front).
  if not exists (select 1 from crm.leads l
                  where l.id = p_lead_id and l.activo = true
                    and (v_rol = 'gerencia'
                         or l.vendedor_id in (select private.vendedor_ids_visibles(v_uid))
                         or (l.vendedor_id is null and l.asignado_supervisor_id in (select private.vendedor_ids_visibles(v_uid))))) then
    raise exception 'Lead no encontrado o fuera de tu ambito' using errcode = 'P0002';
  end if;
  -- Codex v4 #2: READ COMMITTED SIEMPRE antes de leer la bandera (una foto REPEATABLE READ anterior al encendido seguiría
  -- viendo la bandera vieja aunque tome el candado). Codex v3 #4 / auditor v4 #6: la bandera se lee bajo el candado
  -- COMPARTIDO por bandera (el cambio de bandera toma el exclusivo en su trigger, D-5) y DESPUÉS del ámbito: una llamada
  -- que entró apagada termina apagada aunque espere por el lead, y viceversa; un lead ajeno no espera por nada.
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'La reapertura requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  v_flag := coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false);
  -- Candados de PERSONA antes de la fila (documento → persona → lead), como tomar/rescatar/deshacer (D-13); inertes con la bandera apagada.
  v_bloqueo := private.bloquear_personas_de_leads(array[p_lead_id], null);
  select * into v_lead
  from crm.leads l
  where l.id = p_lead_id and l.activo = true
    and (v_rol = 'gerencia'
         or l.vendedor_id in (select private.vendedor_ids_visibles(v_uid))
         or (l.vendedor_id is null and l.asignado_supervisor_id in (select private.vendedor_ids_visibles(v_uid))))
  for update;
  if not found then
    raise exception 'Lead no encontrado o fuera de tu ambito' using errcode = 'P0002';
  end if;
  if v_lead.etapa <> 'descartado' then
    raise exception 'Solo se puede reabrir un lead descartado (este está en «%»)', v_lead.etapa using errcode = 'P0409';
  end if;
  -- Gemela de rescatar/deshacer (b2/D-3): una persona vetada no se reabre (el propio lead, su persona, su puente o un
  -- suelto con el documento de una persona vetada). Inerte con la bandera apagada: el UPDATE de hoy tampoco lo mira.
  if private.persona_vetada(v_lead.id) then
    raise exception '%: no se puede reabrir', 'La persona tiene la restricción «No insistir»' using errcode = 'P0429';
  end if;
  if v_flag then
    -- La bandera debe seguir encendida tras los candados (Codex D-13 v4.3 [1]): apagada a medias, los candados fueron no-ops.
    if not coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false) then
      raise exception 'La identidad unificada se apagó durante la operación; vuelve a intentarlo' using errcode = '40001';
    end if;
    if not private.lead_dentro_de_bloqueo(v_lead.id, v_bloqueo) then
      raise exception 'El documento o la persona de este lead cambió mientras se bloqueaba; vuelve a intentarlo' using errcode = '40001';
    end if;
    -- El JUICIO único de reapertura (D-13): veto, otro lead de la persona, conversión en curso, ya cliente (activo o no).
    v_v := private.juicio_reapertura(v_lead.id, v_lead.telefono, null);
    if v_v->>'estado' = 'no_contactar' then
      raise exception '%: no se puede reabrir', 'La persona tiene la restricción «No insistir»' using errcode = 'P0429';
    end if;
    if v_v is not null then
      raise exception 'La persona ya es cliente o ya tiene su lead: no se puede reabrir'
        using errcode = 'P0409', detail = pg_catalog.jsonb_build_object('estado', 'ya_es_cliente', 'via', 'identidad', 'lead_id', v_lead.id)::text;
    end if;
  end if;
  -- El MISMO UPDATE que hacía el front (etapa → nuevo, sin motivo): los triggers de siempre (sello del descarte, actividad
  -- «cambio_etapa» atribuida a quien reabre, disponibilidad, SLA) y los índices de contacto VIVO (23505 si otro lead
  -- abierto ya tiene ese teléfono o DNI: el front lo traduce como hoy) deciden igual que antes. Bajo el GUC de reapertura
  -- para que el trigger «reabrir solo por RPC» (D-13) lo deje pasar con la bandera encendida.
  v_previo := coalesce(pg_catalog.current_setting('crm.reapertura_identidad', true), 'off');
  perform pg_catalog.set_config('crm.reapertura_identidad', 'on', true);
  update crm.leads set etapa = 'nuevo', motivo_descarte = null
   where id = p_lead_id and activo = true and etapa = 'descartado';
  if not found then
    raise exception 'El lead ya no está descartado (carrera)' using errcode = 'P0002';
  end if;
  perform pg_catalog.set_config('crm.reapertura_identidad', v_previo, true);
  -- Con la identidad encendida, el lead reabierto queda ENLAZADO a su persona (como al nacer), ya bloqueada FOR SHARE.
  if v_flag and v_lead.inversionista_id is null then
    v_inv := private.lead_persona_reabrir(p_lead_id);
    perform private.enlazar_lead_reabierto(p_lead_id, v_inv);
  end if;
  select * into v_lead from crm.leads where id = p_lead_id;
  return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'etapa', v_lead.etapa,
    'inversionista_id', v_lead.inversionista_id, 'enlazado', v_flag and v_lead.inversionista_id is not null,
    'reabierto_por', v_uid, 'reabierto_en', pg_catalog.statement_timestamp());
end;

declare
  v_uid uuid;
  v_inv crm.inversionistas%rowtype; v_tramo crm.inversionista_responsables%rowtype; v_nuevo_id uuid; v_ahora timestamptz; v_lead crm.leads%rowtype;
  v_rol_nuevo text; v_leads uuid[] := array[]::uuid[]; v_leads_movidos integer := 0; v_perfil_movido boolean := false; v_tenencia text := 'sin_cambios';  -- F2.b [D-2]
begin
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada' using errcode = 'P0409';
  end if;
  if not private.es_gerencia_crm_activa() then
    raise exception 'Solo Gerencia reasigna el responsable de relación' using errcode = '42501';
  end if;
  v_uid := (select auth.uid());
  if p_inversionista is null or p_nuevo_responsable is null then
    raise exception 'Faltan la persona o el nuevo responsable' using errcode = '22023';
  end if;
  perform private.motivo_sin_documento(p_motivo, (select pg_catalog.array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id = p_inversionista));
  -- jerarquía compartida (el offboarding la toma exclusiva) + Gerencia y destinatario revalidados bajo ella -> identidad FOR UPDATE
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0));
  if not private.es_gerencia_crm_activa() then
    raise exception 'Solo Gerencia reasigna el responsable de relación (membresía revalidada)' using errcode = '42501';
  end if;
  if not coalesce(private.rol_crm(p_nuevo_responsable) in ('vendedor', 'supervisor', 'gerencia'), false) then
    raise exception 'El nuevo responsable debe ser un miembro activo del equipo comercial (rol efectivo)' using errcode = '22023';
  end if;
  select * into v_inv from crm.inversionistas where id = p_inversionista for update;
  if not found then
    raise exception 'La persona no existe' using errcode = 'P0002';
  end if;
  if v_inv.estado = 'fusionado' then
    raise exception 'Esta identidad está fusionada: reasigna en su canónica %', private.inversionista_canonica(v_inv.id) using errcode = 'P0409';
  elsif v_inv.estado <> 'activo' then
    raise exception 'La persona no está activa (%): revisión de Gerencia', v_inv.estado using errcode = 'P0409';
  end if;
  -- F2.b [D-2] (Codex #12): el motivo se revalida contra los documentos BAJO el lock de la persona (la validación de
  -- arriba corre antes del lock y una corrección documental concurrente pudo cambiarlos).
  perform private.motivo_sin_documento(p_motivo, (select pg_catalog.array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id = p_inversionista));
  select * into v_tramo from crm.inversionista_responsables where inversionista_id = p_inversionista and hasta is null for update;
  if v_tramo.id is not null and v_tramo.responsable_id = p_nuevo_responsable then
    return pg_catalog.jsonb_build_object('ok', true, 'estado', 'sin_cambios', 'inversionista_id', p_inversionista, 'tramo_id', v_tramo.id);
  end if;
  -- F2.b [D-2]: capacidad operativa del nuevo responsable. Si puede tener cartera (vendedor/supervisor activo, rol
  -- efectivo), los leads VIVOS en tenencia operativa de la persona (enlace ∪ puente ∪ sueltos con su documento, D-13)
  -- pasan a su cartera y el perfil cliente de la persona también. Orden: persona (ya) → tramo (ya) → tareas
  -- pendientes → leads → perfil, como el veto (b2) y la fusión (b5). Con Gerencia como nuevo responsable no hay
  -- cartera que mover: solo el tramo (tenencia = 'sin_cambios').
  v_rol_nuevo := private.rol_crm(p_nuevo_responsable);
  if v_rol_nuevo in ('vendedor', 'supervisor') then
    select coalesce(pg_catalog.array_agg(s.id), array[]::uuid[]) into v_leads
    from (select l.id from crm.leads l
           where l.id in (select x from private.leads_de_personas(array[p_inversionista]) x)
             and l.activo = true
             and l.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
             and (l.vendedor_id is distinct from p_nuevo_responsable or l.asignado_supervisor_id is not null)
           order by l.id) s;
    -- (Codex N1/N4) tampoco se espera por una TAREA ni por el PERFIL: cerrar_tarea tiene la tarea y va tarea → lead/perfil;
    -- el Portal actualiza el perfil y su trigger va perfil → tareas. Con la persona y el tramo en la mano, todo lo demás
    -- se toma SIN esperar → 40001 y Gerencia reintenta.
    begin
      perform 1 from crm.tareas t
       where t.estado = 'pendiente'
         and (t.lead_id = any(v_leads) or (v_inv.perfil_id is not null and t.perfil_id = v_inv.perfil_id))
       order by t.id
       for update nowait;
      if v_inv.perfil_id is not null then
        perform 1 from public.perfiles p where p.id = v_inv.perfil_id for no key update nowait;
      end if;
    exception when lock_not_available then
      raise exception 'Otra sesión está trabajando una tarea o la ficha de la persona; vuelve a intentarlo'
        using errcode = '40001';
    end;
    -- (Codex #1) tareas → leads es el orden de b2/D-3 y de cerrar_tarea; derivar y repartir van lead → tareas (por el
    -- trigger de sincronización) bajo el mismo interlock compartido. Como la fusión (b5, E3-9): los leads se toman
    -- SIN esperar; si otra sesión tiene uno → 40001 y Gerencia reintenta.
    begin
      perform 1 from crm.leads l where l.id = any(v_leads) order by l.id for update nowait;
    exception when lock_not_available then
      raise exception 'Otra sesión está trabajando uno de los leads de la persona; vuelve a intentarlo'
        using errcode = '40001';
    end;
    v_tenencia := 'movida';
  end if;
  v_ahora := pg_catalog.clock_timestamp();
  perform pg_catalog.set_config('crm.op_privilegiada', 'on', true);
  if v_tramo.id is not null then
    update crm.inversionista_responsables set hasta = v_ahora where id = v_tramo.id;
  end if;
  insert into crm.inversionista_responsables (inversionista_id, responsable_id, desde, motivo, por)
  values (p_inversionista, p_nuevo_responsable, v_ahora, p_motivo, v_uid) returning id into v_nuevo_id;
  update crm.inversionistas set responsable_relacion_id = p_nuevo_responsable where id = p_inversionista;
  -- F2.b [D-2]: la cartera sigue al responsable (los triggers de leads llevan el ledger de asignaciones, la actividad
  -- «reasignacion», tenencia_desde y las tareas pendientes; el del perfil mueve las tareas de cliente y deja su actividad).
  if v_tenencia = 'movida' then
    if coalesce(pg_catalog.array_length(v_leads, 1), 0) > 0 then
      -- (auditor M2) se REVALIDA bajo los locks: sigue vivo, en etapa abierta y sigue siendo de la persona (un descarte o una
      -- conversión concurrentes solo bloquean el lead; la puerta del DNI de D-13 puede llevarse un suelto a otra persona).
      update crm.leads l
         set vendedor_id = p_nuevo_responsable,
             asignado_supervisor_id = null
       where l.id = any(v_leads)
         and l.activo = true
         and l.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
         and l.id in (select x from private.leads_de_personas(array[p_inversionista]) x);
      get diagnostics v_leads_movidos = row_count;
    end if;
    if v_inv.perfil_id is not null then
      update public.perfiles p
         set asesor_perfil_id = p_nuevo_responsable,
             actualizado_en = pg_catalog.clock_timestamp()
       where p.id = v_inv.perfil_id and p.rol = 'cliente' and p.activo is true
         and p.asesor_perfil_id is distinct from p_nuevo_responsable;
      v_perfil_movido := found;
    end if;
    -- (auditor N5) «movida» solo si algo se movió de verdad.
    if v_leads_movidos = 0 and not v_perfil_movido then
      v_tenencia := 'sin_cambios';
    end if;
  end if;
  select * into v_lead from crm.leads where inversionista_id = p_inversionista and activo = true order by id limit 1;
  if v_lead.id is not null then
    insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por)
    values (v_lead.id, 'nota', 'Responsable de relación reasignado (Gerencia)',
            pg_catalog.jsonb_build_object('evento', 'reasignacion_responsable', 'inversionista_id', p_inversionista,
                                          'anterior', v_tramo.responsable_id, 'nuevo', p_nuevo_responsable, 'tramo_id', v_nuevo_id),
            v_uid);
  end if;
  perform pg_catalog.set_config('crm.op_privilegiada', 'off', true);
  return pg_catalog.jsonb_build_object('ok', true, 'estado', 'reasignado', 'inversionista_id', p_inversionista,
    'tramo_anterior_id', v_tramo.id, 'tramo_nuevo_id', v_nuevo_id, 'responsable_anterior', v_tramo.responsable_id, 'responsable_nuevo', p_nuevo_responsable,
    'tenencia', pg_catalog.jsonb_build_object('estado', v_tenencia, 'leads_movidos', v_leads_movidos, 'perfil_movido', v_perfil_movido));  -- F2.b [D-2]
end;

declare
  v_tel text;
begin
  -- La fila es SIEMPRE del actor autenticado: la autoría no viaja del cliente.
  new.perfil_id := (select auth.uid());
  if new.perfil_id is null then
    raise exception using errcode = '42501', message = 'Acceso CRM revocado';
  end if;

  v_tel := private.normalizar_telefono(new.telefono);
  -- El regex además del null: normalizar_telefono casi nunca devuelve NULL
  -- (su rama else devuelve '+' || dígitos) — sin esto, un fijo o un número
  -- corto rebotaría con el 23514 críptico del CHECK en vez de este 22023
  -- (auditor-rls m5, 2026-08-18).
  if v_tel is null or v_tel !~ '^\+519[0-9]{8}$' then
    raise exception using errcode = '22023',
      message = 'El teléfono del recordatorio debe ser un celular peruano válido';
  end if;
  new.telefono := v_tel;
  new.dni := nullif(pg_catalog.btrim(coalesce(new.dni, '')), '');

  -- Un recordatorio nace (o se reprograma) hacia el futuro, con tope sano.
  -- clock_timestamp() y no now() (Codex R2, 2026-08-18): now() es tiempo de
  -- TRANSACCIÓN — un statement que esperó un lock validaría contra un reloj
  -- viejo y dejaría entrar una fecha ya pasada. «Futura» aquí significa
  -- futura en la pared, no en el BEGIN.
  if new.recordar_en <= pg_catalog.clock_timestamp() then
    raise exception using errcode = '22023',
      message = 'La fecha de revisión debe ser futura';
  end if;
  if new.recordar_en > pg_catalog.clock_timestamp() + make_interval(days => 365) then
    raise exception using errcode = '22023',
      message = 'La fecha de revisión no puede pasar de 365 días';
  end if;

  -- creado_en lo SELLA el servidor en INSERT (un cliente no nace su
  -- recordatorio en 1999 — auditor-rls m1) y se conserva en UPDATE.
  if tg_op = 'INSERT' then
    new.creado_en := pg_catalog.now();
  else
    new.creado_en := old.creado_en;
  end if;
  return new;
end;

declare
  v_actor uuid := (select auth.uid());
  v_correo text := lower(pg_catalog.btrim(coalesce(p_correo, '')));
  v_tipo text := upper(pg_catalog.btrim(coalesce(p_tipo_documento, '')));
  v_documento text := upper(pg_catalog.btrim(coalesce(p_documento, '')));
  v_auth_correo text;
  v_existente record;
  v_evento_objetivo uuid;
begin
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message = 'Solo Gerencia puede crear usuarios CRM';
  end if;
  if p_perfil_id is null or p_idempotencia is null then
    raise exception 'perfil_id e idempotencia son requeridos';
  end if;
  if v_correo !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or length(v_correo) > 254 then
    raise exception 'Correo invalido';
  end if;

  select ue.objetivo_id into v_evento_objetivo
  from crm.usuario_eventos ue
  where ue.actor_id = v_actor
    and ue.accion = 'candidato_creado'
    and ue.idempotencia = p_idempotencia;
  if found then
    if v_evento_objetivo is distinct from p_perfil_id then
      raise exception 'La idempotencia ya fue usada para otro usuario';
    end if;
    return pg_catalog.jsonb_build_object(
      'perfil_id', v_evento_objetivo, 'estado', 'pendiente_rol',
      'idempotente', true
    );
  end if;

  perform private.validar_datos_usuario_crm(
    p_nombre_completo, v_tipo, v_documento,
    nullif(pg_catalog.btrim(p_telefono), ''),
    nullif(pg_catalog.btrim(p_whatsapp), ''),
    nullif(pg_catalog.btrim(p_cargo), '')
  );

  select lower(u.email) into v_auth_correo
  from auth.users u where u.id = p_perfil_id;
  if not found or v_auth_correo is distinct from v_correo then
    raise exception 'La identidad Auth no coincide con el candidato';
  end if;

  select p.id, p.correo, p.rol, e.perfil_id is not null as tiene_equipo
    into v_existente
  from public.perfiles p
  left join crm.equipo e on e.perfil_id = p.id
  where p.id = p_perfil_id
  for update of p;

  if found then
    if lower(v_existente.correo) is distinct from v_correo
       or (v_existente.rol <> 'comercial' and not v_existente.tiene_equipo) then
      raise exception 'La identidad Auth ya pertenece a otro perfil Portal';
    end if;
  else
    insert into public.perfiles (
      id, nombre_completo, tipo_documento, dni, correo,
      telefono, whatsapp, cargo, rol, activo, debe_cambiar_password,
      creado_por, creado_en, actualizado_en
    ) values (
      p_perfil_id,
      pg_catalog.btrim(p_nombre_completo),
      v_tipo,
      v_documento,
      v_correo,
      nullif(pg_catalog.btrim(p_telefono), ''),
      nullif(pg_catalog.btrim(p_whatsapp), ''),
      nullif(pg_catalog.btrim(p_cargo), ''),
      'comercial', true, false,
      v_actor, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
    );
  end if;

  perform private.registrar_evento_usuario(
    'candidato_creado', p_perfil_id,
    pg_catalog.jsonb_build_object('estado', 'pendiente_rol'),
    p_idempotencia
  );

  return pg_catalog.jsonb_build_object(
    'perfil_id', p_perfil_id, 'estado', 'pendiente_rol',
    'idempotente', false
  );
end;

declare
  v_id uuid;
  v_datos jsonb;
begin
  if (select auth.uid()) is not null then
    raise exception 'Solo el importador (service_role) registra reingresos' using errcode = '42501';
  end if;
  -- Paridad apagada: superficie inerte mientras la identidad no esté activa (Codex E1).
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada: el reingreso no se registra' using errcode = 'P0409';
  end if;
  if p_lead_id is null or not exists (select 1 from crm.leads l where l.id = p_lead_id) then
    raise exception 'Lead inexistente' using errcode = 'P0002';
  end if;
  if p_origen is null or pg_catalog.length(pg_catalog.btrim(p_origen)) not between 1 and 40 then
    raise exception 'Origen inválido' using errcode = '22023';
  end if;
  -- Sin documento en claro en la actividad: solo datos comerciales del formulario.
  v_datos := (
    select coalesce(pg_catalog.jsonb_object_agg(e.key, e.value), '{}'::jsonb)
    from pg_catalog.jsonb_each(coalesce(p_datos, '{}'::jsonb)) e
    where e.key in ('nombre','telefono','telefono_alternativo','correo','capital','moneda','canal','distrito','interes','nota','fila')
  );
  insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por)
  values (
    p_lead_id, 'nota',
    'Reingreso por ' || pg_catalog.btrim(p_origen) || ': la persona volvió a dejar sus datos',
    pg_catalog.jsonb_build_object('evento', 'reingreso', 'origen', pg_catalog.btrim(p_origen), 'datos', v_datos),
    null)
  returning id into v_id;
  return pg_catalog.jsonb_build_object('ok', true, 'actividad_id', v_id);
end;

declare
  v_actor uuid := (select auth.uid());
  v_correo text := lower(pg_catalog.btrim(coalesce(p_correo, '')));
  v_tipo text := upper(pg_catalog.btrim(coalesce(p_tipo_documento, '')));
  v_documento text := upper(pg_catalog.btrim(coalesce(p_documento, '')));
  v_auth_correo text;
  v_origen_app text;
  v_perfil public.perfiles%rowtype;
  v_equipo crm.equipo%rowtype;
  v_perfil_nuevo boolean := false;
  v_eventos bigint;
  v_evento_otro_objetivo boolean;
  v_tiene_rol boolean;
  v_tiene_jerarquia boolean;
  v_tiene_activacion boolean;
  v_version timestamptz;
begin
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message =
      'Solo Gerencia puede completar altas de vendedores CRM';
  end if;
  if p_perfil_id is null or p_supervisor_id is null
     or p_idempotencia is null then
    raise exception 'Perfil, Supervisor e idempotencia son requeridos';
  end if;
  if v_correo !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
     or length(v_correo) > 254 then
    raise exception 'Correo invalido';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0)
  );
  -- La autoridad se revalida dentro del candado: un actor revocado mientras
  -- esperaba no puede continuar el alta con una decisión obsoleta.
  if not private.es_gerencia_crm_activa() then
    raise insufficient_privilege using message =
      'Solo Gerencia puede completar altas de vendedores CRM';
  end if;

  select
    pg_catalog.count(*),
    coalesce(
      pg_catalog.bool_or(ue.objetivo_id is distinct from p_perfil_id), false
    ),
    coalesce(pg_catalog.bool_or(ue.accion = 'rol_asignado'), false),
    coalesce(
      pg_catalog.bool_or(ue.accion = 'jerarquia_actualizada'), false
    ),
    coalesce(
      pg_catalog.bool_or(ue.accion = 'membresia_activada'), false
    )
    into v_eventos, v_evento_otro_objetivo, v_tiene_rol,
         v_tiene_jerarquia, v_tiene_activacion
  from crm.usuario_eventos ue
  where ue.actor_id = v_actor
    and ue.idempotencia = p_idempotencia;
  if v_eventos > 0 then
    if v_evento_otro_objetivo or not v_tiene_rol
       or not v_tiene_jerarquia or not v_tiene_activacion then
      raise exception 'La idempotencia ya fue usada por otra operacion';
    end if;

    select p.* into v_perfil
    from public.perfiles p where p.id = p_perfil_id;
    select lower(u.email), u.raw_app_meta_data->>'origen_app'
      into v_auth_correo, v_origen_app
    from auth.users u where u.id = p_perfil_id;
    select e.* into v_equipo
    from crm.equipo e where e.perfil_id = p_perfil_id;
    if not found
       or v_perfil.id is null
       or v_perfil.activo is not true
       or v_perfil.rol <> 'comercial'
       or lower(v_perfil.correo) is distinct from v_correo
       or upper(pg_catalog.btrim(v_perfil.tipo_documento)) is distinct from v_tipo
       or upper(pg_catalog.btrim(v_perfil.dni)) is distinct from v_documento
       or v_auth_correo is distinct from v_correo
       or v_origen_app is distinct from 'crm'
       or v_equipo.rol_crm <> 'vendedor'
       or v_equipo.activo is not true
       or v_equipo.supervisor_id is distinct from p_supervisor_id then
      raise exception 'La operacion idempotente perdio su membresia';
    end if;
    return pg_catalog.jsonb_build_object(
      'perfil_id', p_perfil_id, 'estado', 'activo',
      'rol_crm', 'vendedor', 'supervisor_id', p_supervisor_id,
      'activo_crm', true, 'version_equipo', v_equipo.actualizado_en,
      'idempotente', true
    );
  end if;

  perform private.validar_datos_usuario_crm(
    p_nombre_completo, v_tipo, v_documento,
    nullif(pg_catalog.btrim(p_telefono), ''),
    nullif(pg_catalog.btrim(p_whatsapp), ''),
    nullif(pg_catalog.btrim(p_cargo), '')
  );

  select lower(u.email), u.raw_app_meta_data->>'origen_app'
    into v_auth_correo, v_origen_app
  from auth.users u where u.id = p_perfil_id;
  if not found or v_auth_correo is distinct from v_correo then
    raise exception 'La identidad Auth no coincide con el vendedor';
  end if;

  select p.* into v_perfil
  from public.perfiles p
  where p.id = p_perfil_id
  for update;

  if found then
    if lower(v_perfil.correo) is distinct from v_correo then
      raise exception 'La identidad Auth ya pertenece a otro perfil Portal';
    end if;
    -- Una identidad compartida con el Portal conserva exactamente el flujo y
    -- credenciales previos. Esta frontera solo completa cuentas cuyo origen
    -- servidor y perfil prueban que nacieron exclusivamente en el CRM.
    if v_perfil.rol <> 'comercial' or v_origen_app is distinct from 'crm' then
      return pg_catalog.jsonb_build_object(
        'perfil_id', p_perfil_id, 'estado', 'candidato_existente',
        'idempotente', true
      );
    end if;
    if v_perfil.activo is not true then
      raise exception 'El perfil esta suspendido en Portal';
    end if;
    if upper(pg_catalog.btrim(v_perfil.tipo_documento)) is distinct from v_tipo
       or upper(pg_catalog.btrim(v_perfil.dni)) is distinct from v_documento then
      raise exception 'El documento no coincide con la identidad CRM existente';
    end if;
  else
    if v_origen_app is distinct from 'crm' then
      raise exception 'La identidad nueva no pertenece exclusivamente al CRM';
    end if;
    insert into public.perfiles (
      id, nombre_completo, tipo_documento, dni, correo,
      telefono, whatsapp, cargo, rol, activo, debe_cambiar_password,
      creado_por, creado_en, actualizado_en
    ) values (
      p_perfil_id,
      pg_catalog.btrim(p_nombre_completo),
      v_tipo,
      v_documento,
      v_correo,
      nullif(pg_catalog.btrim(p_telefono), ''),
      nullif(pg_catalog.btrim(p_whatsapp), ''),
      nullif(pg_catalog.btrim(p_cargo), ''),
      'comercial', true, false,
      v_actor, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
    );
    v_perfil_nuevo := true;
  end if;

  select e.* into v_equipo
  from crm.equipo e where e.perfil_id = p_perfil_id
  for update;
  if found then
    if v_equipo.rol_crm = 'vendedor'
       and v_equipo.activo is true
       and v_equipo.supervisor_id is not distinct from p_supervisor_id then
      return pg_catalog.jsonb_build_object(
        'perfil_id', p_perfil_id, 'estado', 'candidato_existente',
        'rol_crm', v_equipo.rol_crm,
        'supervisor_id', v_equipo.supervisor_id,
        'activo_crm', v_equipo.activo,
        'version_equipo', v_equipo.actualizado_en,
        'idempotente', true
      );
    end if;
    raise exception 'El usuario ya tiene una membresia CRM; usa sus controles de administracion';
  end if;

  perform private.validar_supervisor_usuario_crm(
    p_perfil_id, 'vendedor', p_supervisor_id
  );

  insert into crm.equipo (
    perfil_id, rol_crm, supervisor_id, activo,
    creado_por, creado_en, actualizado_en
  ) values (
    p_perfil_id, 'vendedor', p_supervisor_id, true,
    v_actor, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
  );

  select e.actualizado_en into v_version
  from crm.equipo e where e.perfil_id = p_perfil_id;

  if v_perfil_nuevo then
    perform private.registrar_evento_usuario(
      'candidato_creado', p_perfil_id,
      pg_catalog.jsonb_build_object('estado', 'activo'),
      p_idempotencia
    );
  end if;
  perform private.registrar_evento_usuario(
    'rol_asignado', p_perfil_id,
    pg_catalog.jsonb_build_object(
      'rol_anterior', null, 'rol_nuevo', 'vendedor'
    ),
    p_idempotencia
  );
  perform private.registrar_evento_usuario(
    'jerarquia_actualizada', p_perfil_id,
    pg_catalog.jsonb_build_object(
      'supervisor_anterior', null, 'supervisor_nuevo', p_supervisor_id
    ),
    p_idempotencia
  );
  perform private.registrar_evento_usuario(
    'membresia_activada', p_perfil_id,
    pg_catalog.jsonb_build_object('activo', true),
    p_idempotencia
  );

  return pg_catalog.jsonb_build_object(
    'perfil_id', p_perfil_id, 'estado', 'activo',
    'rol_crm', 'vendedor', 'supervisor_id', p_supervisor_id,
    'activo_crm', true, 'version_equipo', v_version,
    'idempotente', false
  );
end;

begin
  if not private.puede_operar_reparto_crm() then
    raise insufficient_privilege using message = 'Solo Coordinacion o Gerencia puede repartir leads';
  end if;
  if not private.es_destino_crm_activo(p_supervisor, array['supervisor']) then
    raise exception 'La bandeja destino no pertenece a un supervisor activo'
      using errcode = '22023';
  end if;
  return private.repartir_lead_implementacion(p_lead, p_supervisor);
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text := private.rol_crm((select auth.uid()));
  v_tarea crm.tareas%rowtype;
  v_nueva_id uuid := coalesce(p_nueva_id, gen_random_uuid());
begin
  if v_uid is null
     or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_vence_en is null
     or p_vence_en < timestamptz '2026-01-01 00:00Z'
     or p_vence_en >= timestamptz '2100-01-01 00:00Z' then
    raise exception 'Fecha de reunion invalida' using errcode = '22023';
  end if;

  perform 1
  from crm.leads
  where id = (
    select t.lead_id
    from crm.tareas t
    where t.id = p_tarea_id
      and t.tipo = 'reunion'
      and t.activo
      and t.estado = 'pendiente'
      and (
        v_rol = 'gerencia'
        or t.vendedor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
        or (
          t.vendedor_id is null
          and t.asignado_supervisor_id in (
            select private.vendedor_ids_visibles(v_uid)
          )
        )
      )
  )
  for no key update;

  select *
    into v_tarea
  from crm.tareas t
  where t.id = p_tarea_id
    and t.tipo = 'reunion'
    and t.activo
    and t.estado = 'pendiente'
    and (
      v_rol = 'gerencia'
      or t.vendedor_id in (
        select private.vendedor_ids_visibles(v_uid)
      )
      or (
        t.vendedor_id is null
        and t.asignado_supervisor_id in (
          select private.vendedor_ids_visibles(v_uid)
        )
      )
    )
  for update;
  if not found then
    raise exception 'Reunion no encontrada, cerrada o fuera de tu ambito';
  end if;
  if p_vence_en = v_tarea.vence_en then
    raise exception 'La nueva fecha debe ser distinta'
      using errcode = '22023';
  end if;

  perform set_config('crm.op_tarea', 'on', true);
  update crm.tareas
     set estado = 'reprogramada',
         motivo_no_realizada = 'reprogramada',
         detalle_cierre_reunion = 'Reprogramada a ' || p_vence_en::text
   where id = p_tarea_id;
  perform set_config('crm.op_tarea', 'off', true);

  insert into crm.tareas (
    id, lead_id, perfil_id, tipo, titulo, nota, vence_en, duracion_min,
    modalidad_reunion, ubicacion_reunion, enlace_reunion,
    reagendada_de, reprogramaciones, creado_por
  ) values (
    v_nueva_id,
    v_tarea.lead_id,
    v_tarea.perfil_id,
    'reunion',
    v_tarea.titulo,
    v_tarea.nota,
    p_vence_en,
    v_tarea.duracion_min,
    v_tarea.modalidad_reunion,
    v_tarea.ubicacion_reunion,
    v_tarea.enlace_reunion,
    v_tarea.id,
    v_tarea.reprogramaciones + 1,
    v_uid
  );

  return jsonb_build_object(
    'ok', true,
    'tarea_anterior_id', p_tarea_id,
    'tarea_nueva_id', v_nueva_id,
    'reprogramaciones', v_tarea.reprogramaciones + 1
  );
end;

declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_destinos_validos uuid[];
  v_total_episodios integer;
  v_total_destinos integer;
  v_candidatos integer := 0;
  v_orden integer := 0;
  v_intento integer;
  v_destino uuid;
  v_fila record;
  v_flag boolean;
  v_veredicto jsonb;
  v_bloqueo jsonb;
  v_previo_reab text;
begin
  if p_episodios is null
     or pg_catalog.array_length(p_episodios, 1) is null
     or pg_catalog.array_length(p_episodios, 1) = 0
     or pg_catalog.array_length(p_episodios, 1) > 100
     or pg_catalog.array_position(p_episodios, null) is not null then
    raise exception 'Selecciona entre 1 y 100 descartes válidos'
      using errcode = '22023';
  end if;

  if (select pg_catalog.count(*) from (
    select distinct id from pg_catalog.unnest(p_episodios) as u(id)
  ) episodios_unicos) <> pg_catalog.array_length(p_episodios, 1) then
    raise exception 'Un descarte no se puede enviar dos veces en el mismo reparto'
      using errcode = '22023';
  end if;

  if p_analistas_destino is null
     or pg_catalog.array_length(p_analistas_destino, 1) is null
     or pg_catalog.array_length(p_analistas_destino, 1) = 0
     or pg_catalog.array_length(p_analistas_destino, 1) > 30
     or pg_catalog.array_position(p_analistas_destino, null) is not null then
    raise exception 'Selecciona al menos un asesor destino'
      using errcode = '22023';
  end if;

  if (select pg_catalog.count(*) from (
    select distinct id from pg_catalog.unnest(p_analistas_destino) as u(id)
  ) destinos_unicos) <> pg_catalog.array_length(p_analistas_destino, 1) then
    raise exception 'No repitas un asesor destino'
      using errcode = '22023';
  end if;

  select e.rol_crm
    into v_rol
  from crm.equipo e
  join public.perfiles p on p.id = e.perfil_id
  where e.perfil_id = v_actor
    and e.activo = true
    and p.activo = true
    and e.rol_crm in ('supervisor', 'gerencia');

  if v_actor is null or v_rol is null then
    raise exception 'Solo supervisión puede rescatar descartes'
      using errcode = '42501';
  end if;
  -- F2.b [D-5] (auditor v4 #1): la bandera se lee bajo el candado COMPARTIDO crm_flag_resolver_en_puertas (el cambio de
  -- bandera toma el exclusivo): esta llamada termina con la bandera que leyó, aunque espere por una fila.
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  v_flag := coalesce((select activo from crm.multiempresa_flags where nombre='resolver_en_puertas'), false);

  select pg_catalog.array_agg(destino.id order by destino.orden)
    into v_destinos_validos
  from (
    select u.id, u.orden
    from pg_catalog.unnest(p_analistas_destino) with ordinality as u(id, orden)
    join crm.equipo e on e.perfil_id = u.id
    join public.perfiles p on p.id = e.perfil_id
    where e.activo = true
      and p.activo = true
      and e.rol_crm = 'vendedor'
      and (
        v_rol = 'gerencia'
        or e.perfil_id in (
          select private.vendedor_ids_visibles(v_actor)
        )
      )
  ) destino;

  v_total_destinos := coalesce(pg_catalog.array_length(v_destinos_validos, 1), 0);  -- F2.b (b2): pg_catalog.coalesce no existe (bug desde 20/08)
  if v_total_destinos <> pg_catalog.array_length(p_analistas_destino, 1) then
    raise exception 'Uno de los asesores destino no está activo o no pertenece a tu equipo'
      using errcode = '22023';
  end if;

  -- F2.b [D-13]: candados de PERSONA antes de las filas (documento -> persona -> lead): documentos y personas de todos los
  -- leads del lote, en orden; luego las filas. Si tras tomarlas la persona de un lead no está entre las bloqueadas -> 40001.
  v_bloqueo := private.bloquear_personas_de_leads(
    (select pg_catalog.array_agg(la.lead_id) from crm.lead_asignaciones la where la.id = any(p_episodios)), null);
  -- Se bloquean los leads antes de modificar alguno. Si una carrera ya los
  -- reabrió, toda la operación falla y no deja un reparto parcial.
  for v_fila in
    select
      la.id as episodio_id,
      la.lead_id,
      la.analista_id as asesor_origen_id,
      (l.no_contactar or (v_flag and coalesce(inv.no_contactar, false))) as no_contactar,  -- veto de la PERSONA
      l.telefono, l.dni, l.inversionista_id
    from crm.lead_asignaciones la
    join crm.leads l on l.id = la.lead_id
  left join crm.inversionistas inv0 on inv0.id = l.inversionista_id
    left join crm.inversionistas inv  on inv.id  = coalesce(inv0.inversionista_canonico_id, inv0.id)  -- sigue a la canónica si está fusionada
    where la.id = any(p_episodios)
      and la.resultado = 'descartado'
      and la.resultado_en is not null
      and l.activo = true
      and l.etapa = 'descartado'
      and l.descartado_en is not distinct from la.resultado_en
      and la.motivo_descarte_cierre <> 'datos_invalidos'
      and (
        v_rol = 'gerencia'
        or la.analista_id in (
          select private.vendedor_ids_visibles(v_actor)
        )
      )
    order by la.resultado_en, la.id
    for update of l
  loop
    v_candidatos := v_candidatos + 1;
    if v_fila.no_contactar then
      raise exception 'Uno de los leads tiene la restricción «No insistir» y no puede reactivarse'
        using errcode = 'P0429';
    end if;
    -- F2.b (b2): también por documento exacto (lead suelto de una persona vetada).
    if private.persona_vetada(v_fila.lead_id) then
      raise exception 'Uno de los leads pertenece a una persona con la restricción «No insistir» y no puede reactivarse'
        using errcode = 'P0429';
    end if;
    -- F2.b [D-13] (auditor M1 / Codex #6): con la identidad encendida, el JUICIO único de reapertura por lead; todo el lote
    -- falla, como con el veto. La persona debe ser una de las bloqueadas antes de las filas (si no, 40001).
    if v_flag then
      if not private.lead_dentro_de_bloqueo(v_fila.lead_id, v_bloqueo) then
        raise exception 'El documento o la persona de uno de los leads cambió mientras se bloqueaba; vuelve a intentarlo' using errcode = '40001';
      end if;
      v_veredicto := private.juicio_reapertura(v_fila.lead_id, v_fila.telefono, null);
      if v_veredicto->>'estado' = 'no_contactar' then
        raise exception 'Uno de los leads pertenece a una persona con la restricción «No insistir» y no puede reactivarse'
          using errcode = 'P0429';
      end if;
      if v_veredicto is not null then
        raise exception 'Uno de los leads pertenece a una persona que ya es cliente o ya tiene su lead y no puede reactivarse'
          using errcode = 'P0409', detail = pg_catalog.jsonb_build_object('estado', 'ya_es_cliente', 'via', 'identidad', 'lead_id', v_fila.lead_id)::text;
      end if;
    end if;
  end loop;

  v_total_episodios := pg_catalog.array_length(p_episodios, 1);
  if v_candidatos <> v_total_episodios then
    raise exception 'Uno de los descartes ya no está disponible para rescate'
      using errcode = 'P0002';
  end if;

  -- F2.b [D-13]: la reapertura pasa por la puerta (trigger «solo por RPC»).
  v_previo_reab := coalesce(pg_catalog.current_setting('crm.reapertura_identidad', true), 'off');
  perform pg_catalog.set_config('crm.reapertura_identidad', 'on', true);
  -- Una segunda pasada usa los mismos locks. La vuelta redonda conserva el
  -- orden seleccionado y, si se pidió, salta al asesor que lo descartó.
  for v_fila in
    select
      la.id as episodio_id,
      la.lead_id,
      la.analista_id as asesor_origen_id
    from crm.lead_asignaciones la
    join crm.leads l on l.id = la.lead_id
    where la.id = any(p_episodios)
      and la.resultado = 'descartado'
      and l.activo = true
      and l.etapa = 'descartado'
      and l.descartado_en is not distinct from la.resultado_en
    order by la.resultado_en, la.id
  loop
    v_destino := null;
    for v_intento in 0..(v_total_destinos - 1) loop
      v_destino := v_destinos_validos[((v_orden + v_intento) % v_total_destinos) + 1];
      exit when not p_evitar_asesor_origen or v_destino is distinct from v_fila.asesor_origen_id;
    end loop;

    if v_destino is null
       or (p_evitar_asesor_origen and v_destino = v_fila.asesor_origen_id) then
      raise exception 'No hay otro asesor destino para uno de los descartes seleccionados'
        using errcode = '22023';
    end if;

    update crm.leads
       set etapa = 'nuevo',
           motivo_descarte = null,
           vendedor_id = v_destino,
           asignado_supervisor_id = null
     where id = v_fila.lead_id;
    -- F2.b [D-13] (auditor M1 / Codex #6): el lead reabierto queda ENLAZADO a su persona (como al nacer), ya bloqueada FOR SHARE.
    if v_flag then
      perform private.enlazar_lead_reabierto(v_fila.lead_id, private.lead_persona_reabrir(v_fila.lead_id));
    end if;

    v_orden := v_orden + 1;
  end loop;
  perform pg_catalog.set_config('crm.reapertura_identidad', v_previo_reab, true);

  return pg_catalog.jsonb_build_object(
    'rescatados', v_candidatos,
    'asesores_destino', v_total_destinos
  );
end;

declare
  v_uid      uuid := (select auth.uid());
  v_rol      text := private.rol_crm((select auth.uid()));
  v_lead     crm.leads%rowtype;
  v_expira   timestamptz;
  v_ahora    timestamptz := now();
  v_ventana  interval := interval '5 minutes';
  v_tope     interval := interval '30 minutes';
  v_tipo     text := coalesce(nullif(pg_catalog.upper(pg_catalog.btrim(p_tipo_documento)), ''), 'DNI');
  v_doc      text := nullif(pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p_documento, ''), '[^A-Za-z0-9]', '', 'g')), '');
  v_inv      uuid; v_veto boolean; v_otro uuid; v_perfil uuid; v_perfil_activo boolean;
  v_hash     text; v_hash_payload jsonb; v_saga jsonb; v_claim uuid;
begin
  if not private.puede_gestionar_contratos_crm() then
    raise exception 'No autorizado para convertir leads'
      using errcode = '42501';
  end if;
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada: usa la reserva por lead' using errcode = 'P0409';
  end if;
  if v_doc is null then
    raise exception 'El documento es obligatorio para reservar la conversión' using errcode = '22023';
  end if;
  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Payload inválido' using errcode = '22023';
  end if;

  -- documento -> identidad -> lead (ámbito, VERBATIM de la viva) -> revalidaciones de la persona.
  -- El ámbito va ANTES de cualquier lectura sobre la persona: un vendedor no puede sondear
  -- documentos ajenos con un lead que no es suyo (auditor b4 A1).
  perform private.identidad_bloquear_documento(v_tipo, v_doc);
  v_inv := private.inversionista_resolver(v_tipo, v_doc, true, 'reserva_conversion');
  select i.no_contactar, i.perfil_id into v_veto, v_perfil from crm.inversionistas i where i.id = v_inv for update;
  select *
    into v_lead
  from crm.leads
  where id = p_lead_id
    and activo = true
    and (
      v_rol = 'gerencia'
      or vendedor_id in (
        select private.vendedor_ids_visibles((select auth.uid()))
      )
      or (
        vendedor_id is null
        and asignado_supervisor_id in (
          select private.vendedor_ids_visibles((select auth.uid()))
        )
      )
    )
  for update;
  if not found then
    raise exception 'Lead no encontrado o fuera de tu ambito';
  end if;


  -- El documento tecleado debe ser el de la persona de ESTE lead (misma regla que convertir_lead, adelantada a antes de Auth).
  if v_lead.inversionista_id is not null and v_lead.inversionista_id <> v_inv then
    raise exception 'El documento no es el de la persona de este lead' using errcode = 'P0409';
  end if;
  -- F2.b [D-10] (Codex #2): el PUENTE de ESTE lead también manda. Un lead que solo está en el puente (sin enlace vivo
  -- ni DNI) pertenece a la persona de su puente; con un documento que resuelve a otra persona no se reserva
  -- (la Gerencia lo corrige o fusiona), igual que ya exige crm.enlazar_lead_inversionista_fn (b5). Por la canónica.
  if exists (select 1 from crm.inversionista_leads il
              where il.lead_id = p_lead_id and private.inversionista_canonica(il.inversionista_id) is distinct from v_inv) then
    raise exception 'La persona de este lead (según su puente) no es la del documento: corrección o fusión de Gerencia'
      using errcode = 'P0409';
  end if;
  if v_tipo = 'DNI' and v_lead.dni is not null and v_lead.dni <> v_doc then
    raise exception 'El documento no coincide con el del lead' using errcode = 'P0409';
  end if;
  if coalesce(v_veto, false) then
    raise exception 'La persona tiene la restricción «No insistir»: no se convierte' using errcode = 'P0429';
  end if;
  -- un solo lead TOTAL (invariante #6): la persona no puede tener OTRO lead.
  select l.id into v_otro from crm.leads l where l.inversionista_id = v_inv and l.id <> p_lead_id limit 1;
  -- F2.b [D-10] (Codex B2): si no hay OTRO enlace vivo, «un solo lead» cuenta también el PUENTE (crm.inversionista_leads,
  -- históricos del backfill sin enlace vivo), como ya hacen las dos conversiones desde b5; el propio lead no cuenta.
  -- Espejo de b5 (auditor D-10 M1): el enlace vivo se comprueba PRIMERO (el detalle señala el lead canónico cuando existe)
  -- y un lead ya cerrado conserva las respuestas de hoy (enlazado / «ya esta cerrado», más abajo). Mismo error y mismo
  -- detalle que hoy (el front no cambia).
  if v_otro is null and v_lead.etapa not in ('convertido', 'descartado') then
    -- F2.b [D-13] (Codex #1): también los SUELTOS vivos con un documento vigente de la persona (private.leads_de_personas).
    select x into v_otro from private.leads_de_personas(array[v_inv]) x where x <> p_lead_id order by x limit 1;
  end if;
  if v_otro is not null then
    raise exception 'Esta persona ya tiene su lead: la nueva inversión sobre un cliente existente no es una conversión'
      using errcode = 'P0409', detail = pg_catalog.jsonb_build_object('estado', 'ya_es_cliente', 'via', 'identidad', 'lead_id', v_otro)::text;
  end if;
  if v_perfil is null then
    -- Perfil cliente con ese documento creado antes de la identidad: se reutiliza (dedup de hoy, por identidad).
    select p.id into v_perfil from public.perfiles p
     where p.rol = 'cliente' and p.dni = v_doc and coalesce(nullif(pg_catalog.btrim(p.tipo_documento), ''), 'DNI') = v_tipo
     limit 1;
  end if;
  if v_perfil is not null then
    select p.activo into v_perfil_activo from public.perfiles p where p.id = v_perfil;
    if v_perfil_activo is distinct from true then
      raise exception 'Ese cliente existe pero está inactivo en el portal' using errcode = 'P0409';
    end if;
  end if;

  -- Conversión ya consumada cuya respuesta se perdió (Codex E2 #4): la saga manda.
  if v_lead.etapa = 'convertido' and v_lead.perfil_id is not null and v_lead.inversionista_id = v_inv
     and exists (select 1 from crm.multiempresa_idempotencia i where i.clave = 'auth_persona:' || v_inv::text
                 and i.resultado->>'estado' <> 'enlazado' and i.resultado->>'tipo' = 'conversion'
                 and (i.resultado->>'lead_id')::uuid = p_lead_id
                 and coalesce((i.resultado->>'auth_user_id')::uuid, v_lead.perfil_id) = v_lead.perfil_id) then
    update crm.multiempresa_idempotencia
       set resultado = resultado || pg_catalog.jsonb_build_object('estado', 'enlazado', 'perfil_id', v_lead.perfil_id, 'actualizado_en', pg_catalog.now()),
           version = version + 1
     where clave = 'auth_persona:' || v_inv::text;
  end if;
  if v_lead.etapa in ('convertido', 'descartado') then
    if v_lead.etapa = 'convertido' and v_lead.perfil_id is not null then
      return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'estado', 'enlazado', 'reanudar', true,
        'inversionista_id', v_inv, 'perfil_id', v_lead.perfil_id, 'ya_existia', true);
    end if;
    raise exception 'El lead ya esta cerrado';
  end if;
  -- Reserva viva o sellada de OTRO lead de la misma persona (Avance en curso en otro lead).
  if exists (select 1 from crm.conversion_reservas r
              where r.inversionista_id = v_inv and r.lead_id <> p_lead_id
                and (r.efectos_iniciados_en is not null or r.expira_en > v_ahora)) then
    raise exception using errcode = 'P0409',
      message = 'Esta persona tiene una conversion a cliente de Avance en curso en otro lead',
      hint    = 'Quien la empezo tiene que terminarla o dejar que caduque.';
  end if;

  -- Una reserva viva o sellada de este lead pertenece a UNA persona: no se cambia de identidad
  -- sin compensar (Codex E2 #5).
  if exists (select 1 from crm.conversion_reservas r
              where r.lead_id = p_lead_id and r.inversionista_id is not null and r.inversionista_id <> v_inv
                and (r.efectos_iniciados_en is not null or r.expira_en > v_ahora)) then
    raise exception 'Este lead ya está reservado para otra persona; espera a que caduque o pide a Gerencia que lo retome'
      using errcode = 'P0409';
  end if;
  -- Huella canónica SIN documento (Codex E2 #10).
  v_hash_payload := pg_catalog.jsonb_build_object('v', 1, 'inv', v_inv,
    'correo', pg_catalog.lower(coalesce(p_payload->>'correo','')), 'nombre', coalesce(p_payload->>'nombre_completo',''),
    'apellidos', coalesce(p_payload->>'apellidos',''), 'nombres', coalesce(p_payload->>'nombres',''),
    'telefono', coalesce(p_payload->>'telefono',''), 'domicilio', coalesce(p_payload->'domicilio', 'null'::jsonb),
    'bancarios', coalesce(p_payload->'bancarios', 'null'::jsonb));
  v_hash := private.idem_hash(v_hash_payload);

  insert into crm.conversion_reservas as r
    (lead_id, reservado_por, expira_en, vence_absoluto_en, inversionista_id, hash_payload)
  values (p_lead_id, v_uid,
          v_ahora + v_ventana, v_ahora + v_tope, v_inv, v_hash)
  on conflict (lead_id) do update
     set reservado_por = excluded.reservado_por,
         reservado_en  = v_ahora,
         inversionista_id = v_inv,
         hash_payload  = v_hash,
         -- El tope absoluto MANDA sobre la ventana: sin este `least`, renovar a
         -- los 29 minutos daba 5 más y el tope no era un tope.
         expira_en     = least(excluded.expira_en,
                               case when r.reservado_por = v_uid
                                    then r.vence_absoluto_en
                                    else excluded.vence_absoluto_en end),
         vence_absoluto_en = case
           -- Retomar la propia reserva NO reinicia el tope.
           when r.reservado_por = v_uid then r.vence_absoluto_en
           else excluded.vence_absoluto_en
         end
   where (r.reservado_por = v_uid and r.vence_absoluto_en > v_ahora)
      or (r.efectos_iniciados_en is null and r.expira_en <= v_ahora)
  returning r.expira_en into v_expira;

  if v_expira is null then
    -- Distinguir los motivos importa: uno se resuelve esperando y el otro no.
    if exists (select 1 from crm.conversion_reservas r2
               where r2.lead_id = p_lead_id and r2.efectos_iniciados_en is not null) then
      raise exception using
        errcode = 'P0409',
        message = 'Este lead ya tiene una conversion a cliente de Avance empezada por otra persona',
        hint    = 'Ya existe una cuenta de portal a su nombre: quien la empezo tiene que terminarla.';
    end if;
    raise exception using
      errcode = 'P0409',
      message = 'Otra persona esta convirtiendo este lead en este momento',
      hint    = 'Espera unos minutos y vuelve a intentarlo.';
  end if;


  -- Persona YA cliente del portal (identidad enlazada o perfil con el documento exacto): sin Auth y
  -- sin saga; el edge convierte con convertir_lead_con_domicilio como hoy (auditor b4 A2).
  if v_perfil is not null then
    update crm.conversion_reservas r set claim_id = null where r.lead_id = p_lead_id;
    return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'expira_en', v_expira,
      'inversionista_id', v_inv, 'perfil_id', v_perfil, 'ya_existia', true, 'estado', 'ya_existia', 'reanudar', false);
  end if;
  -- Claim de la saga (o reanudación con token / lease vencido).
  v_saga := private.saga_auth_reclamar(v_inv, 'conversion', v_hash_payload, p_lead_id, p_payload->>'token');
  v_claim := (v_saga->>'claim_id')::uuid;
  update crm.conversion_reservas r set claim_id = v_claim where r.lead_id = p_lead_id;

  return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'expira_en', v_expira,
    'inversionista_id', v_inv, 'perfil_id', (v_saga->>'perfil_id')::uuid, 'ya_existia', false)
    || (v_saga - 'inversionista_id' - 'perfil_id');
end;

declare
  v_uid uuid := (select auth.uid());
  v_s crm.solicitudes_tasa;
  v_estado text; v_tope numeric;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_previo text := coalesce(current_setting('crm.solicitud_tasa_por_puerta', true), 'off');
begin
  if v_uid is null or private.rol_crm(v_uid) is distinct from 'gerencia' then
    raise exception 'Solo Gerencia resuelve una solicitud de tasa' using errcode = '42501';
  end if;
  if p_solicitud_id is null then
    raise exception 'La solicitud es obligatoria' using errcode = '22023';
  end if;
  if p_decision is null or p_decision not in ('aprobar', 'rechazar', 'aprobar_hasta') then
    raise exception 'Decisión inválida: aprobar, rechazar o aprobar_hasta' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) > 500 then
    raise exception 'El motivo no puede superar 500 caracteres' using errcode = '22023';
  end if;
  perform private.vencer_solicitudes_tasa(p_solicitud_id);
  select * into v_s from crm.solicitudes_tasa s where s.id = p_solicitud_id for update;
  if v_s.id is null then
    raise exception 'Solicitud no encontrada' using errcode = 'P0002';
  end if;
  if v_s.solicitada_por = v_uid then
    raise exception 'Quien solicita no resuelve su propia solicitud' using errcode = '42501';
  end if;
  -- Una viva con vence_en pasado ES vencida aunque la fila aún diga otra cosa: el sello «vencida» lo escribe
  -- private.vencer_solicitudes_tasa en la siguiente llamada que COMMITEA (esta lanza y revierte). Quien lea la tabla
  -- debe mirar también vence_en.
  if v_s.estado <> 'pendiente' or v_s.vence_en < statement_timestamp() then
    raise exception 'La solicitud ya no está pendiente (estado «%»)',
      case when v_s.estado = 'pendiente' then 'vencida' else v_s.estado end using errcode = 'P0409';
  end if;

  if p_decision = 'rechazar' then
    v_estado := 'rechazada'; v_tope := null;
  elsif p_decision = 'aprobar' then
    v_estado := 'aprobada'; v_tope := v_s.tasa_solicitada;
  else
    if p_tasa_maxima is null then
      raise exception 'Indica hasta qué tasa apruebas' using errcode = '22023';
    end if;
    p_tasa_maxima := round(p_tasa_maxima, 2);   -- misma escala que contratos.tasa_anual (auditor m5)
    if p_tasa_maxima <= v_s.tasa_base then
      raise exception 'El tope debe superar la tasa base de % %% (la excepción solo eleva)', rtrim(rtrim(to_char(v_s.tasa_base, 'FM999990.99'), '0'), '.') using errcode = '22023';
    end if;
    if p_tasa_maxima > v_s.tasa_solicitada then
      raise exception 'El tope no puede superar la tasa pedida de % %%', rtrim(rtrim(to_char(v_s.tasa_solicitada, 'FM999990.99'), '0'), '.') using errcode = '22023';
    end if;
    if p_tasa_maxima = v_s.tasa_solicitada then
      v_estado := 'aprobada'; v_tope := v_s.tasa_solicitada;      -- «hasta lo pedido» es aprobar tal cual
    else
      v_estado := 'aprobada_con_tope'; v_tope := p_tasa_maxima;
    end if;
  end if;

  perform set_config('crm.solicitud_tasa_por_puerta', 'on', true);
  update crm.solicitudes_tasa s
     set estado = v_estado, tasa_maxima_autorizada = v_tope, motivo_resolucion = v_motivo,
         resuelta_por = v_uid, resuelta_en = statement_timestamp()
   where s.id = p_solicitud_id
   returning * into v_s;
  perform set_config('crm.solicitud_tasa_por_puerta', v_previo, true);
  return to_jsonb(v_s) || jsonb_build_object('ok', true);
end;

begin
  if not private.puede_operar_tasa_cliente(p_cliente_id) then
    raise exception 'Cliente no encontrado o fuera de tu cartera' using errcode = '42501';
  end if;
  return private.resolver_tasa(p_cliente_id, p_categoria, p_contrato_origen_id, statement_timestamp());
end;

declare
  v_uid uuid := (select auth.uid());
  v_s crm.solicitudes_tasa;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_previo text := coalesce(current_setting('crm.solicitud_tasa_por_puerta', true), 'off');
begin
  if v_uid is null or not private.puede_registrar_ventas() then
    raise exception 'Solicitud no encontrada o fuera de tu ámbito' using errcode = '42501';
  end if;
  if p_solicitud_id is null or p_acepta is null then
    raise exception 'La solicitud y la respuesta son obligatorias' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) > 500 then
    raise exception 'El motivo no puede superar 500 caracteres' using errcode = '22023';
  end if;
  perform private.vencer_solicitudes_tasa(p_solicitud_id);
  select * into v_s from crm.solicitudes_tasa s where s.id = p_solicitud_id for update;
  if v_s.id is null or v_s.solicitada_por <> v_uid then
    -- Solo quien pidió responde (ni Gerencia en su nombre); ajena o inexistente responden igual.
    raise exception 'Solicitud no encontrada o fuera de tu ámbito' using errcode = '42501';
  end if;
  if v_s.estado <> 'aprobada_con_tope' or v_s.vence_en < statement_timestamp() then
    raise exception 'Solo se responde a una autorización con tope vigente (estado «%»)',
      case when v_s.estado = 'aprobada_con_tope' then 'vencida' else v_s.estado end using errcode = 'P0409';
  end if;
  perform set_config('crm.solicitud_tasa_por_puerta', 'on', true);
  update crm.solicitudes_tasa s
     set estado = case when p_acepta then 'aceptada_por_analista' else 'declinada_por_analista' end,
         respondida_por_analista_en = statement_timestamp(), motivo_analista = v_motivo
   where s.id = p_solicitud_id
   returning * into v_s;
  perform set_config('crm.solicitud_tasa_por_puerta', v_previo, true);
  return to_jsonb(v_s) || jsonb_build_object('ok', true);
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text;
  v_lector boolean;
  v_visibles uuid[];
  v_ahora timestamptz := now();
  v_hoy_lima date;
  v_payload jsonb;
begin
  v_rol := private.rol_crm(v_uid);
  v_lector := private.es_lector_global();
  if v_uid is null or (v_rol is null and not v_lector) then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  v_visibles := array(select private.vendedor_ids_visibles(v_uid));
  v_hoy_lima := (v_ahora at time zone 'America/Lima')::date;

  with clientes_ambito as materialized (
    select p.id, p.activo, p.asesor_perfil_id
    from public.perfiles p
    where p.rol = 'cliente'
      and (
        v_lector
        or v_rol = 'gerencia'
        or p.asesor_perfil_id = any(v_visibles)
      )
  ),
  contratos_ambito as materialized (
    -- Los hechos, del NUCLEO; el ambito por cliente, de esta pantalla.
    select e.contrato_id as id, e.estado, e.moneda, coalesce(e.monto, 0) as capital,
           e.fecha_vencimiento, cli.activo as cliente_activo, cli.id as cliente_id
    from private.capital_episodios(
           '-infinity'::timestamptz,
           'infinity'::timestamptz,
           true, '{}'::uuid[]) e
    join clientes_ambito cli on cli.id = e.cliente_id
    where e.tipo like 'contrato_%'
  ),
  con_capital as (
    select count(distinct ca.cliente_id)::int as n
    from contratos_ambito ca
    where ca.estado = 'activo' and ca.cliente_activo
  ),
  por_estado as (
    select coalesce(jsonb_object_agg(x.estado, x.n), '{}'::jsonb) as j
    from (select ca.estado, count(*)::int as n
          from contratos_ambito ca group by ca.estado) x
  )
  select jsonb_build_object(
    'version', 1,
    'generado_en', v_ahora,
    'zona', 'America/Lima',
    'dias_alarma_renovacion', 30,
    'clientes', jsonb_build_object(
      'en_gestion', count(*) filter (where cl.activo),
      'de_baja', count(*) filter (where not cl.activo),
      'con_capital', (select n from con_capital),
      'sin_asesor', count(*) filter (where cl.activo and cl.asesor_perfil_id is null)
    ),
    'capital_activo', jsonb_build_object(
      'pen', coalesce((select round(sum(ca.capital), 2) from contratos_ambito ca
                       where ca.estado = 'activo' and ca.cliente_activo
                         and ca.moneda is distinct from 'USD'), 0),
      'usd', coalesce((select round(sum(ca.capital), 2) from contratos_ambito ca
                       where ca.estado = 'activo' and ca.cliente_activo
                         and ca.moneda = 'USD'), 0)
    ),
    'contratos', jsonb_build_object(
      'por_estado', (select j from por_estado),
      'por_vencer_30', coalesce((select count(*)::int from contratos_ambito ca
                                 where ca.estado = 'activo'
                                   and ca.fecha_vencimiento is not null
                                   and ca.fecha_vencimiento >= v_hoy_lima
                                   and ca.fecha_vencimiento <= v_hoy_lima + 30), 0),
      'por_vencer_30_de_baja', coalesce((select count(*)::int from contratos_ambito ca
                                         where ca.estado = 'activo'
                                           and not ca.cliente_activo
                                           and ca.fecha_vencimiento is not null
                                           and ca.fecha_vencimiento >= v_hoy_lima
                                           and ca.fecha_vencimiento <= v_hoy_lima + 30), 0)
    )
  )
  into v_payload
  from clientes_ambito cl;

  return v_payload;
end;

declare
  v_uid uuid := (select auth.uid());
  v_rol text;
  v_lector boolean;
  v_reparto boolean;
  v_visibles uuid[];
  v_ahora timestamptz := now();
  v_corte timestamptz;
  v_mes date;
  v_mes_ini timestamptz;
  v_mes_fin timestamptz;
  v_payload jsonb;
begin
  v_rol := private.rol_crm(v_uid);
  v_lector := private.es_lector_global();
  if v_uid is null or (v_rol is null and not v_lector) then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  v_reparto := private.puede_operar_reparto_crm();
  v_visibles := array(select private.vendedor_ids_visibles(v_uid));
  v_corte := v_ahora - interval '45 days'; -- ventana de la VISTA, no de la metrica
  v_mes := date_trunc('month', v_ahora at time zone 'America/Lima')::date;
  v_mes_ini := (v_mes::timestamp at time zone 'America/Lima');
  v_mes_fin := ((v_mes + interval '1 month')::timestamp at time zone 'America/Lima');

  with ambito as materialized (
    select l.id, l.etapa, l.moneda,
           coalesce(l.monto_estimado, 0) as monto,
           l.vendedor_id, l.motivo_descarte,
           (l.etapa not in ('convertido', 'descartado')) as abierto
    from crm.leads l
    where l.activo is true
      and (l.etapa <> 'convertido' or l.convertido_en >= v_corte)
      and (
        l.vendedor_id = any(v_visibles)
        or (l.vendedor_id is null
            and (l.asignado_supervisor_id = any(v_visibles) or v_reparto))
        or v_rol = 'gerencia'
        or v_lector
      )
  ),
  -- F2.4 (decision D1): la METRICA pasa al mes calendario del NUCLEO. La
  -- ventana de 45 dias sigue siendo la de la VISTA (que leads se ven en
  -- cartera). Va GLOBAL y se recorta al unir con el ambito ya recortado.
  nucleo_mes as materialized (
    select e.analista_id,
      count(distinct e.lead_id) filter (
        where e.tipo = 'cierre' and not e.anulado and not e.fue_referido)::int as cierres_no_referidos,
      count(distinct e.lead_id) filter (
        where e.tipo = 'cierre' and not e.anulado and e.fue_referido)::int as cierres_referidos,
      count(*) filter (where e.tipo = 'operacion')::int as operaciones
    from private.conversion_episodios(
      v_mes_ini, v_mes_fin, v_mes, true, '{}'::uuid[],
      private.peso_referido_conversion(v_mes)
    ) e
    where e.analista_id = any(v_visibles) or v_rol = 'gerencia' or v_lector
    group by e.analista_id
  ),
  -- Abiertos ASIGNADOS que nadie ha CONTACTADO jamás (los 5 tipos de
  -- TIPOS_CONTACTO, espejo del índice parcial actividades_contacto_episodio_idx;
  -- una `reasignacion` del sistema no cuenta como trabajo comercial).
  sin_contacto as (
    select count(*)::int as n
    from ambito a
    where a.abierto
      and a.vendedor_id is not null
      and not exists (
        select 1 from crm.actividades act
        where act.lead_id = a.id
          and act.tipo in ('llamada_realizada', 'llamada_no_contestada',
                           'whatsapp_enviado', 'whatsapp_recibido', 'reunion_realizada')
      )
  ),
  embudo as (
    select jsonb_agg(
             jsonb_build_object('etapa', e.etapa, 'n', coalesce(c.n, 0))
             order by e.orden
           ) as j
    from unnest(array['nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada',
                      'convertido', 'descartado']) with ordinality as e(etapa, orden)
    left join (
      select a.etapa, count(*)::int as n from ambito a group by a.etapa
    ) c on c.etapa = e.etapa
  ),
  descartes_motivo as (
    select coalesce(
             jsonb_agg(jsonb_build_object('motivo', d.motivo_descarte, 'n', d.n)
                       order by d.n desc, d.motivo_descarte),
             '[]'::jsonb
           ) as j
    from (
      select a.motivo_descarte, count(*)::int as n
      from ambito a
      where a.etapa = 'descartado' and a.motivo_descarte is not null
      group by a.motivo_descarte
    ) d
  )
  select jsonb_build_object(
    'version', 1,
    'generado_en', v_ahora,
    'ventana_convertidos_dias', 45,
    'ventana_metrica', 'mes_calendario',
    'mes_metrica', v_mes,
    'totales', jsonb_build_object(
      'vivos', count(*),
      'abiertos', count(*) filter (where a.abierto),
      'asignados', count(*) filter (where a.abierto and a.vendedor_id is not null),
      'parkeados', count(*) filter (where a.abierto and a.vendedor_id is null),
      -- F2.4/D1: los cierres del MES del ledger, no los leads con etapa
      -- convertido dentro de la ventana de la VISTA (que incluia anulados).
      -- CIERRES DE LEAD, sin las operaciones de cartera: el mismo criterio que
      -- la serie comercial y que Gestion de equipo. Las renovaciones no son
      -- «convertidos» de este tile; el % del nucleo si las cuenta.
      'convertidos', (select coalesce(sum(
           nm.cierres_no_referidos + nm.cierres_referidos), 0)
         from nucleo_mes nm),
      'operaciones_cartera', (select coalesce(sum(nm.operaciones), 0) from nucleo_mes nm),
      'descartados', count(*) filter (where a.etapa = 'descartado'),
      -- El donut de directorio cuenta sobre ASIGNADOS (los parkeados no
      -- cuentan como activos ni suman capital) — el nombre no debe mentir.
      'asignados_pen', count(*) filter (where a.abierto and a.vendedor_id is not null and a.moneda is distinct from 'USD'),
      'asignados_usd', count(*) filter (where a.abierto and a.vendedor_id is not null and a.moneda = 'USD')
    ),
    'capital', jsonb_build_object(
      'asignado', jsonb_build_object(
        'pen', coalesce(sum(a.monto) filter (where a.abierto and a.vendedor_id is not null and a.moneda is distinct from 'USD'), 0),
        'usd', coalesce(sum(a.monto) filter (where a.abierto and a.vendedor_id is not null and a.moneda = 'USD'), 0)
      ),
      'parkeado', jsonb_build_object(
        'pen', coalesce(sum(a.monto) filter (where a.abierto and a.vendedor_id is null and a.moneda is distinct from 'USD'), 0),
        'usd', coalesce(sum(a.monto) filter (where a.abierto and a.vendedor_id is null and a.moneda = 'USD'), 0)
      ),
      'ganado', jsonb_build_object(
        'pen', coalesce(sum(a.monto) filter (where a.etapa = 'convertido' and a.moneda is distinct from 'USD'), 0),
        'usd', coalesce(sum(a.monto) filter (where a.etapa = 'convertido' and a.moneda = 'USD'), 0)
      )
    ),
    -- Espejo de conversionGlobal: base = vivos CON vendedor (terminales
    -- incluidos; los parkeados no cuentan porque nadie los trabaja).
    'conversion', jsonb_build_object(
      'convertidos', count(*) filter (where a.etapa = 'convertido' and a.vendedor_id is not null),
      'base', count(*) filter (where a.vendedor_id is not null),
      'pct', case
        when count(*) filter (where a.vendedor_id is not null) > 0
        then round(100.0 * (count(*) filter (where a.etapa = 'convertido' and a.vendedor_id is not null))
                   / (count(*) filter (where a.vendedor_id is not null)))::int
        else 0
      end
    ),
    'descartes', jsonb_build_object(
      'total', count(*) filter (where a.etapa = 'descartado'),
      'sin_motivo', count(*) filter (where a.etapa = 'descartado' and a.motivo_descarte is null),
      'por_motivo', (select j from descartes_motivo)
    ),
    'embudo', (select j from embudo),
    'sin_tocar', (select n from sin_contacto)
  )
  into v_payload
  from ambito a;

  return v_payload;
end;

declare
  v_uid uuid := (select auth.uid()); v_inv uuid; v_r crm.conversion_reservas%rowtype; v_est jsonb; v_token text; v_clave text;
begin
  if not private.es_gerencia_crm_activa() then
    raise exception 'Solo Gerencia retoma una conversión' using errcode = '42501';
  end if;
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then   -- F2.b [D-5]
    raise exception 'Retomar requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  if not coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false) then
    raise exception 'Identidad unificada apagada' using errcode = 'P0409';
  end if;
  select r.inversionista_id into v_inv from crm.conversion_reservas r where r.lead_id = p_lead_id;
  if v_inv is null then
    raise exception 'Este lead no tiene una reserva por persona' using errcode = 'P0002';
  end if;
  perform 1 from crm.inversionistas i where i.id = v_inv for update;
  select * into v_r from crm.conversion_reservas r where r.lead_id = p_lead_id for update;
  if v_r.efectos_iniciados_en is null then
    raise exception 'La reserva no está sellada: basta con volver a reservar' using errcode = 'P0409';
  end if;
  v_clave := 'auth_persona:' || v_inv::text;
  select i.resultado into v_est from crm.multiempresa_idempotencia i where i.clave = v_clave for update;
  if v_est is null or v_est->>'estado' = 'enlazado' then
    raise exception 'No hay una conversión a medias que retomar' using errcode = 'P0409';
  end if;
  if (v_est->>'lead_id')::uuid is distinct from p_lead_id or v_r.claim_id is distinct from (v_est->>'claim_id')::uuid then
    raise exception 'La reserva y el claim de esta persona no corresponden a este lead' using errcode = 'P0409';
  end if;
  -- Nunca expulsa a una ejecución viva: solo pasado el tope de la reserva o con el lease del claim vencido (Codex E2 #10).
  if v_est->>'lease_hasta' is null then
    raise exception 'El claim de esta conversión no tiene lease (anomalía de datos): revisar antes de retomar' using errcode = 'P0409';
  end if;
  -- F2.b [D-5] (Codex v5 #2): mismo criterio que abandonar. Retomar rota el token del claim: nunca expulsa a una ejecución
  -- viva. Exige el tope de la reserva Y el lease del claim vencidos (un reintento del dueño renueva el lease aunque el tope pase).
  if v_r.vence_absoluto_en > pg_catalog.now() or (v_est->>'lease_hasta')::timestamptz > pg_catalog.now() then
    raise exception 'La conversión sigue viva (reserva y claim vigentes): no hay nada que retomar todavía' using errcode = 'P0409';
  end if;
  v_token := pg_catalog.encode(extensions.gen_random_bytes(24), 'hex');
  v_est := v_est || pg_catalog.jsonb_build_object('token_hash', private.saga_token_hash(v_token), 'owner', v_uid,
    'lease_hasta', pg_catalog.now() + interval '10 minutes', 'actualizado_en', pg_catalog.now(), 'retomado_por_gerencia', true);
  update crm.multiempresa_idempotencia set resultado = v_est, version = version + 1 where clave = v_clave;
  update crm.conversion_reservas r
     set reservado_por = v_uid, reservado_en = pg_catalog.now(),
         expira_en = pg_catalog.now() + interval '5 minutes', vence_absoluto_en = pg_catalog.now() + interval '30 minutes'
   where r.lead_id = p_lead_id;
  return pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'inversionista_id', v_inv,
    'claim_id', (v_est->>'claim_id')::uuid, 'token', v_token, 'estado', v_est->>'estado',
    'version', (select i.version from crm.multiempresa_idempotencia i where i.clave = v_clave),
    'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid, 'reanudar', true);
end;

declare
  v_actor uuid := (select auth.uid());
  v_hoy date := (pg_catalog.now() at time zone 'America/Lima')::date;
  v_inicio_hoy timestamptz := v_hoy::timestamp at time zone 'America/Lima';
  v_fin_hoy timestamptz := (v_hoy + 1)::timestamp at time zone 'America/Lima';
  v_lead crm.leads%rowtype;
  v_episodio crm.lead_asignaciones%rowtype;
  v_asesor_bloqueado uuid;
begin
  if p_lead_id is null then
    raise exception 'Indica el lead que deseas devolver'
      using errcode = '22023';
  end if;

  if v_actor is null or not exists (
    select 1
    from crm.equipo actor_equipo
    join public.perfiles actor_perfil on actor_perfil.id = actor_equipo.perfil_id
    where actor_equipo.perfil_id = v_actor
      and actor_equipo.rol_crm = 'supervisor'
      and actor_equipo.activo = true
      and actor_perfil.activo = true
  ) then
    raise exception 'Solo un supervisor activo puede devolver derivaciones de su equipo'
      using errcode = '42501';
  end if;

  -- Interlock compartido con la jerarquía: offboarding usa la misma clave en
  -- exclusivo antes de tocar equipo/leads. Debe ocurrir antes del row lock.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0)
  );

  select l.*
    into v_lead
  from crm.leads l
  where l.id = p_lead_id
  for update;
  if not found then
    raise exception 'El lead ya no está disponible'
      using errcode = 'P0001';
  end if;
  -- F2.b (b2): con la bandera encendida, ni el lead vetado ni el de una persona
  -- vetada se devuelven a la bandeja (coherente con reparto/derivación).
  if private.persona_vetada(v_lead.id) then
    raise exception '%: no se devuelve a la bandeja', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;

  -- Revalida bajo lock el rol que pasó el precheck. Esto impide completar la
  -- devolución si Gerencia desactivó al supervisor mientras esperaba el lead.
  perform 1
  from crm.equipo actor_equipo
  join public.perfiles actor_perfil on actor_perfil.id = actor_equipo.perfil_id
  where actor_equipo.perfil_id = v_actor
    and actor_equipo.rol_crm = 'supervisor'
    and actor_equipo.activo = true
    and actor_perfil.activo = true
  for no key update of actor_equipo, actor_perfil;
  if not found then
    raise exception 'Tu acceso de supervisor cambió; recarga antes de devolver'
      using errcode = '42501';
  end if;

  -- Mismo orden que el guardado masivo: lead → supervisor → asesor. La
  -- membresía y los perfiles quedan estables hasta terminar la devolución.
  select asesor_equipo.perfil_id
    into v_asesor_bloqueado
  from crm.equipo asesor_equipo
  join public.perfiles asesor_perfil on asesor_perfil.id = asesor_equipo.perfil_id
  where asesor_equipo.perfil_id = v_lead.vendedor_id
    and asesor_equipo.rol_crm = 'vendedor'
    and asesor_equipo.supervisor_id = v_actor
    and asesor_equipo.activo = true
    and asesor_perfil.activo = true
  for no key update of asesor_equipo, asesor_perfil;

  if not found then
    raise exception 'Solo puedes devolver una derivación vigente de hoy hecha a un asesor de tu equipo'
      using errcode = 'P0001';
  end if;

  select la.*
    into v_episodio
  from crm.lead_asignaciones la
  where la.lead_id = p_lead_id
    and la.analista_id = v_lead.vendedor_id
    and la.asignado_por = v_actor
    and la.supervisor_origen_id = v_actor
    and la.asignado_en >= v_inicio_hoy
    and la.asignado_en < v_fin_hoy
    and la.finalizado_en is null
  order by la.asignado_en desc
  limit 1
  for update of la;

  if not found
     or v_lead.activo is not true
     or v_lead.etapa not in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada') then
    raise exception 'Solo puedes devolver una derivación vigente de hoy hecha a un asesor de tu equipo'
      using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from crm.actividades actividad
    where actividad.lead_id = p_lead_id
      and actividad.creado_por = v_episodio.analista_id
      and actividad.creado_en >= v_episodio.asignado_en
  ) or exists (
    select 1
    from crm.tareas tarea
    where tarea.lead_id = p_lead_id
      and tarea.creado_por = v_episodio.analista_id
      and tarea.creado_en >= v_episodio.asignado_en
  ) then
    raise exception 'No puedes devolver este lead porque el asesor ya registró gestión; su historial se conserva'
      using errcode = 'P0001';
  end if;

  perform pg_catalog.set_config('crm.reversion_derivacion_equipo', 'on', true);
  update crm.leads
  set vendedor_id = null,
      asignado_supervisor_id = v_actor
  where id = p_lead_id;
  perform pg_catalog.set_config('crm.reversion_derivacion_equipo', 'off', true);

  return pg_catalog.jsonb_build_object(
    'version', 1,
    'lead_id', p_lead_id,
    'devuelto_a_bandeja', true
  );
end;

declare
  v_claim uuid; v_loc record; v_res jsonb; v_perfil uuid; v_lead uuid; v_inv_conv uuid; v_tipo text; v_doc text;
begin
  if not private.puede_gestionar_contratos_crm() then
    raise exception 'No autorizado para convertir leads' using errcode = '42501';
  end if;
  if not private.resolver_en_puertas_bajo_candado() then
    raise exception 'Identidad unificada apagada' using errcode = 'P0409';
  end if;
  if p_payload is null or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Payload inválido' using errcode = '22023';
  end if;
  v_claim := (p_payload->>'claim_id')::uuid;
  if v_claim is null then raise exception 'Falta claim_id' using errcode = '22023'; end if;
  if (p_payload->>'version') is null then raise exception 'Falta version (CAS)' using errcode = '22023'; end if;

  if p_paso = 'registrar_auth' then
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'auth_creado', (p_payload->>'auth_user_id')::uuid, null, (p_payload->>'version')::integer);
  elsif p_paso = 'compensar_auth' then
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'reclamado', null, null, (p_payload->>'version')::integer);
  elsif p_paso = 'perfil_creado' then
    return private.saga_auth_avanzar(v_claim, p_payload->>'token', 'perfil_creado', null, (p_payload->>'perfil_id')::uuid, (p_payload->>'version')::integer);
  elsif p_paso = 'cerrar' then
    -- CIERRE TRANSACCIONAL (Codex E2 #7): convertir y comprobar que la identidad convertida es la
    -- reservada, o revertir todo. Orden: (convertir_lead) documento -> identidad -> lead -> reserva -> claim.
    select * into v_loc from private.saga_auth_localizar(v_claim);
    if not found then raise exception 'Saga: claim inexistente' using errcode = 'P0002'; end if;
    if v_loc.estado->>'token_hash' is distinct from private.saga_token_hash(p_payload->>'token') then
      raise exception 'Saga: token inválido' using errcode = '42501';
    end if;
    v_lead   := coalesce((p_payload->>'lead_id')::uuid, (v_loc.estado->>'lead_id')::uuid);
    v_perfil := coalesce((p_payload->>'perfil_id')::uuid, (v_loc.estado->>'perfil_id')::uuid, (v_loc.estado->>'auth_user_id')::uuid);
    if v_lead is null or v_perfil is null then
      raise exception 'Saga: faltan lead o perfil para cerrar' using errcode = 'P0409';
    end if;
    if (v_loc.estado->>'lead_id')::uuid is distinct from v_lead then
      raise exception 'Saga: el lead no es el reservado en este claim' using errcode = 'P0409';
    end if;
    -- El perfil de un claim con Auth es ese Auth: no se cierra con otro perfil (auditor b4 M1).
    if (v_loc.estado->>'auth_user_id') is not null and v_perfil is distinct from (v_loc.estado->>'auth_user_id')::uuid then
      raise exception 'Saga: el perfil no corresponde al usuario de Auth de este claim' using errcode = 'P0409';
    end if;
    -- F2.b (b5) [E3-1]: documento ANTES de identidad (la fusión toma documento -> identidad;
    -- convertir_lead resolverá este mismo documento, reentrante).
    select coalesce(nullif(pg_catalog.btrim(p.tipo_documento), ''), 'DNI'), p.dni into v_tipo, v_doc
      from public.perfiles p where p.id = v_perfil;
    if v_doc is null then
      raise exception 'Saga: el perfil del claim no existe o no tiene documento' using errcode = 'P0409';
    end if;
    perform private.identidad_bloquear_documento(v_tipo, v_doc);
    -- Veto revalidado también al cerrar (Codex E2 #11): con veto, la conversión no se consuma.
    perform 1 from crm.inversionistas i where i.id = v_loc.inversionista_id for update;
    if exists (select 1 from crm.inversionistas i where i.id = v_loc.inversionista_id and i.no_contactar) then
      raise exception 'La persona tiene la restricción «No insistir»: no se convierte' using errcode = 'P0429';
    end if;
    v_res := crm.convertir_lead_con_domicilio(v_lead, v_perfil, p_payload->>'domicilio');
    v_inv_conv := (v_res->>'inversionista_id')::uuid;
    -- F2.b (b5) [E3-12]: comparación por la CANÓNICA (una fusión posterior no invalida el reintento de un cierre ya consumado).
    if private.inversionista_canonica(v_inv_conv) is distinct from private.inversionista_canonica(v_loc.inversionista_id) then
      raise exception 'La persona convertida no es la persona reservada (el documento cambió): se revierte la conversión'
        using errcode = 'P0409';
    end if;
    return v_res || private.saga_auth_avanzar(v_claim, p_payload->>'token', 'enlazado', null, v_perfil, (p_payload->>'version')::integer)
           || pg_catalog.jsonb_build_object('inversionista_id', private.inversionista_canonica(v_inv_conv));
  end if;
  raise exception 'Paso desconocido: %', p_paso using errcode = '22023';
end;

declare
  v_uid uuid := (select auth.uid());
  v_cliente uuid; v_cat text; v_origen uuid; v_pc uuid;
  v_capital numeric; v_moneda text; v_mod text; v_ti text; v_fi date; v_fv date;
  v_tasa numeric; v_motivo text;
  v_res jsonb; v_base numeric; v_tope numeric; v_dias integer; v_pol_id uuid;
  v_huella text; v_viva record; v_fila crm.solicitudes_tasa;
  v_previo text := coalesce(current_setting('crm.solicitud_tasa_por_puerta', true), 'off');
begin
  -- La AUTORIDAD se pregunta antes de mirar el JSON (auditor n2): un no autorizado muere en el 42501 uniforme sin
  -- distinguir «formato inválido»; el cliente (activo, rol cliente) se comprueba justo después de leerlo.
  if v_uid is null or not private.puede_registrar_ventas() then
    raise exception 'Cliente no encontrado o fuera de tu cartera' using errcode = '42501';
  end if;
  if p_solicitud is null or jsonb_typeof(p_solicitud) <> 'object' then
    raise exception 'Faltan los datos de la solicitud' using errcode = '22023';
  end if;
  begin
    v_cliente := (p_solicitud ->> 'cliente_id')::uuid;
    v_cat     := p_solicitud ->> 'categoria';
    v_origen  := (p_solicitud ->> 'contrato_origen_id')::uuid;
    v_pc      := (p_solicitud ->> 'producto_condicion_id')::uuid;
    v_capital := (p_solicitud ->> 'capital')::numeric;
    v_moneda  := p_solicitud ->> 'moneda';
    v_mod     := p_solicitud ->> 'modalidad';
    v_ti      := p_solicitud ->> 'tipo_interes';
    v_fi      := (p_solicitud ->> 'fecha_inicio')::date;
    v_fv      := (p_solicitud ->> 'fecha_vencimiento')::date;
    v_tasa    := round((p_solicitud ->> 'tasa_solicitada')::numeric, 2);   -- misma escala que contratos.tasa_anual (auditor m5)
    v_motivo  := btrim(p_solicitud ->> 'motivo');
  exception when others then
    raise exception 'Datos de la solicitud inválidos' using errcode = '22023';
  end;
  if not private.puede_operar_tasa_cliente(v_cliente) then
    raise exception 'Cliente no encontrado o fuera de tu cartera' using errcode = '42501';
  end if;
  if v_capital is null or v_capital < 100 or v_capital > 100000000 then
    raise exception 'El capital debe estar entre 100 y 100,000,000' using errcode = '22023';
  end if;
  if v_moneda is null or v_moneda not in ('PEN', 'USD') then
    raise exception 'Moneda inválida' using errcode = '22023';
  end if;
  if v_mod is null or v_mod not in ('mensual', 'trimestral', 'semestral', 'anual')
     or v_ti is null or v_ti not in ('simple', 'compuesto') then
    raise exception 'Modalidad o tipo de interés inválidos' using errcode = '22023';
  end if;
  if v_fi is null or v_fv is null or v_fv <= v_fi then
    raise exception 'El plazo del contrato es inválido' using errcode = '22023';
  end if;
  if v_motivo is null or length(v_motivo) < 5 or length(v_motivo) > 500 then
    raise exception 'Escribe el motivo comercial (entre 5 y 500 caracteres)' using errcode = '22023';
  end if;
  if v_tasa is null or v_tasa <= 0 then
    raise exception 'La tasa solicitada es inválida' using errcode = '22023';
  end if;

  perform private.vencer_solicitudes_tasa();
  -- EL NÚCLEO decide la base y la regla; esta puerta no calcula tasa.
  v_res := private.resolver_tasa(v_cliente, v_cat, v_origen, statement_timestamp());
  v_base := (v_res ->> 'tasa_base')::numeric;
  v_tope := (v_res #>> '{politica,tope_tecnico}')::numeric;
  v_dias := (v_res #>> '{politica,vigencia_solicitud_dias}')::integer;
  v_pol_id := (v_res #>> '{politica,id}')::uuid;
  if v_tasa <= v_base then
    raise exception 'La excepción debe ser superior a la tasa base de % %%', rtrim(rtrim(to_char(v_base, 'FM999990.99'), '0'), '.') using errcode = '22023';
  end if;
  if v_tasa > v_tope then
    raise exception 'La tasa solicitada supera el tope técnico de % %%', rtrim(rtrim(to_char(v_tope, 'FM999990.99'), '0'), '.') using errcode = '22023';
  end if;

  v_huella := private.huella_solicitud_tasa(v_cliente, v_cat, v_origen, v_pc, v_capital, v_moneda, v_mod, v_ti, v_fi, v_fv);
  perform pg_advisory_xact_lock(hashtext('crm.solicitudes_tasa'), hashtext(v_huella));
  select s.id, s.estado, s.solicitada_por into v_viva from crm.solicitudes_tasa s
   where s.huella = v_huella
     and s.estado in ('pendiente', 'aprobada', 'aprobada_con_tope', 'aceptada_por_analista')
   limit 1;
  if v_viva.id is not null then
    raise exception 'Ya hay una solicitud viva para este contrato (estado «%»)', v_viva.estado
      using errcode = 'P0409',
            detail = jsonb_build_object('solicitud_id', v_viva.id, 'estado', v_viva.estado, 'solicitada_por', v_viva.solicitada_por,
                                        'propia', v_viva.solicitada_por = v_uid)::text;
  end if;

  perform set_config('crm.solicitud_tasa_por_puerta', 'on', true);
  insert into crm.solicitudes_tasa (
    politica_id, cliente_id, categoria, contrato_origen_id, contrato_origen_numero, producto_condicion_id,
    capital, moneda, modalidad, tipo_interes, fecha_inicio, fecha_vencimiento, huella,
    tasa_base, regla_base, contratos_previos, prioridad_bandeja, tasa_solicitada, motivo,
    estado, solicitada_por, solicitada_en, vence_en
  ) values (
    v_pol_id, v_cliente, v_cat, v_origen, v_res #>> '{contrato_origen,numero_contrato}', v_pc,
    v_capital, v_moneda, v_mod, v_ti, v_fi, v_fv, v_huella,
    v_base, v_res ->> 'regla', (v_res ->> 'contratos_previos')::integer, (v_res ->> 'prioridad_bandeja')::boolean, v_tasa, v_motivo,
    'pendiente', v_uid, statement_timestamp(), statement_timestamp() + make_interval(days => v_dias)
  ) returning * into v_fila;
  perform set_config('crm.solicitud_tasa_por_puerta', v_previo, true);
  return to_jsonb(v_fila) || jsonb_build_object('ok', true, 'resolucion', v_res);
end;

begin
  if not private.puede_operar_reparto_crm() then
    raise insufficient_privilege using message = 'Solo Coordinacion o Gerencia puede ver los supervisores de reparto';
  end if;
  return query
  select s.*
  from private.supervisores_para_reparto_implementacion() s
  where private.es_destino_crm_activo(s.perfil_id, array['supervisor']);
end;

declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_tel text := private.normalizar_telefono(p_telefono);
  v_dni text := nullif(pg_catalog.btrim(p_dni), '');
  v_veredicto_identidad jsonb;
  v_flag_d13 boolean;
  v_candidato uuid;
  v_bloqueo jsonb;
  v_previo_reab text;
  v_lead crm.leads%rowtype;
  v_dias integer;
  v_disponible_desde timestamptz;
  v_quedo_libre_en timestamptz;
  v_ultima_conv timestamptz;
  v_propietario_anterior uuid;
  v_modo text;
  v_previo text;
begin
  v_rol := private.rol_crm(v_actor);
  if v_actor is null or v_rol is null
     or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception using errcode = '42501', message = 'Acceso CRM revocado';
  end if;

  -- La toma directa es del VENDEDOR para sí mismo (spec §7). Supervisor y
  -- gerencia ya tienen su puerta con destino elegible: el reparto.
  if v_rol <> 'vendedor' then
    raise exception using
      errcode = '42501',
      message = 'La toma directa es solo para vendedores; supervisión asigna por el reparto';
  end if;
  -- F2.b [D-5] (auditor v4 #1): la bandera se lee bajo el candado COMPARTIDO crm_flag_resolver_en_puertas (el cambio de
  -- bandera toma el exclusivo): esta llamada termina con la bandera que leyó, aunque espere por una fila.
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  v_flag_d13 := coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false);

  if v_tel is null or v_tel !~ '^\+519[0-9]{8}$' then
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      pg_catalog.jsonb_build_object(
        'estado', 'error',
        'detalle', 'telefono_invalido'
      ));
  end if;
  if v_dni is not null and v_dni !~ '^[0-9]{8}$' then
    raise exception using errcode = '22023', message = 'El DNI debe tener exactamente 8 digitos';
  end if;
  -- F2.b [D-13]: los candados de PERSONA van ANTES de la fila (orden total documento -> persona -> lead, el de la reserva,
  -- el sellado y la fusión). El blanco se localiza SIN lock con el mismo criterio de abajo (teléfono manda; si no, DNI),
  -- se bloquean sus documentos y su persona (y los del DNI tecleado), y después se toma la fila; si la fila ya no es la
  -- misma o su persona cambió, manda el veredicto fresco. Inerte con la bandera apagada.
  if v_flag_d13 then
    select l.id into v_candidato
    from crm.leads l
    where l.telefono = v_tel
      and l.no_contactar = false
      and not private.persona_vetada(l.id)
      and (
        (l.activo = true
          and l.etapa not in ('convertido', 'descartado')
          and l.vendedor_id is null
          and l.asignado_supervisor_id is null)
        or (l.etapa = 'descartado' and l.descartado_en is not null)
      )
    order by (l.etapa = 'descartado'), l.descartado_en desc, l.id
    limit 1;
    if v_candidato is null and v_dni is not null then
      select l.id into v_candidato
      from crm.leads l
      where l.dni = v_dni
        and l.no_contactar = false
        and not private.persona_vetada(l.id)
        and (
          (l.activo = true
            and l.etapa not in ('convertido', 'descartado')
            and l.vendedor_id is null
            and l.asignado_supervisor_id is null)
          or (l.etapa = 'descartado' and l.descartado_en is not null)
        )
      order by (l.etapa = 'descartado'), l.descartado_en desc nulls last, l.id
      limit 1;
    end if;
    v_bloqueo := private.bloquear_personas_de_leads(case when v_candidato is null then '{}'::uuid[] else array[v_candidato] end, v_dni);
  end if;

  -- Vetos de contacto ANTES de bloquear filas: baratos, y el veredicto que
  -- devuelven es el mismo que daría la verificación.
  if exists (
    select 1
    from crm.leads l
    where (l.no_contactar = true or private.persona_vetada(l.id))  -- F2.b (b2): veto de la persona
      and (l.telefono = v_tel or (v_dni is not null and l.dni = v_dni))
  ) then
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      pg_catalog.jsonb_build_object('estado', 'no_contactar'));
  end if;

  if exists (
    select 1
    from public.perfiles per
    where per.rol = 'cliente'
      and per.activo = true
      and (
        private.normalizar_telefono(per.telefono) = v_tel
        or (v_dni is not null and per.dni = v_dni)
      )
  ) then
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
  end if;

  -- El blanco, POR CONTACTO y el TELÉFONO manda (adenda 16/08-b del ledger):
  -- solo si el número no casa con nada se cae al DNI. FILA primero — el orden
  -- advisory→fila se abraza con «Deshacer descarte» (refutador del plan); las
  -- llaves advisory las toman los triggers del propio UPDATE, en el orden de
  -- los caminos vivos. ORDER BY determinista: la bolsa viva antes que los
  -- descartes, el descarte más reciente primero, id como desempate.
  select l.* into v_lead
  from crm.leads l
  where l.telefono = v_tel
    -- Codex R4: el veto DENTRO del predicado — EvalPlanQual lo re-evalúa
    -- sobre la versión nueva tras esperar la fila; el pre-chequeo solo no
    -- veía un no_contactar en vuelo.
    and l.no_contactar = false
    and not private.persona_vetada(l.id)  -- F2.b (b2): snapshot de la sentencia (no EvalPlanQual); el enlazado lo cubre la propagación de marcar
    and (
      (l.activo = true
        and l.etapa not in ('convertido', 'descartado')
        and l.vendedor_id is null
        and l.asignado_supervisor_id is null)
      -- Espejo del impl: un descarte sin fecha es anomalía y no se toma.
      or (l.etapa = 'descartado' and l.descartado_en is not null)
    )
  order by (l.etapa = 'descartado'), l.descartado_en desc, l.id
  limit 1
  for update;

  if not found and v_dni is not null then
    select l.* into v_lead
    from crm.leads l
    where l.dni = v_dni
      and l.no_contactar = false
      and not private.persona_vetada(l.id)  -- F2.b (b2): snapshot de la sentencia (no EvalPlanQual); el enlazado lo cubre la propagación de marcar
      and (
        (l.activo = true
          and l.etapa not in ('convertido', 'descartado')
          and l.vendedor_id is null
          and l.asignado_supervisor_id is null)
        -- Espejo EXACTO del brazo telefónico (auditor M1): sin este filtro un
        -- descarte-anomalía sin fecha entraba por el DNI saltándose
        -- enfriamiento y carencia.
        or (l.etapa = 'descartado' and l.descartado_en is not null)
      )
    order by (l.etapa = 'descartado'), l.descartado_en desc nulls last, l.id
    limit 1
    for update;
  end if;

  if not found then
    -- Nada tomable con ese contacto: el veredicto fresco explica qué pasa
    -- (tomado por otro, libre → alta nueva, etc.).
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
  end if;

  -- P-048: el permiso se re-consulta DESPUÉS del lock — una membresía
  -- revocada mientras esperaba la fila no alcanza a tomar al despertar. El
  -- FOR SHARE ancla la fila de equipo (Codex, carrera de offboarding): la
  -- desactivación la toma FOR UPDATE, así que o ella terminó (y aquí se ve
  -- inactivo) o espera a que esta toma termine (y su chequeo de dependencias
  -- verá el lead nuevo). Sin ciclo: la desactivación no bloquea crm.leads.
  perform 1
  from crm.equipo e
  where e.perfil_id = v_actor
  for share;
  if private.rol_crm(v_actor) is distinct from 'vendedor'
     or not private.es_destino_crm_activo(v_actor, array['vendedor']::text[]) then
    raise exception using errcode = '42501', message = 'Acceso CRM revocado';
  end if;

  -- F2.b [D-13]: la fila tomada debe ser el candidato bloqueado y seguir DENTRO de lo bloqueado: su documento actual entre las
  -- claves y su persona entre las personas (Codex v4.1/v4.2: un cambio de DNI en medio, incluso A->B->A, dejaría obsoleto el
  -- candado); si no, veredicto fresco.
  if v_flag_d13 and (v_lead.id is distinct from v_candidato or not private.lead_dentro_de_bloqueo(v_lead.id, v_bloqueo)) then
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, coalesce(v_dni, v_lead.dni)));
  end if;
  -- F2.b [D-13]: el JUICIO único de reapertura/toma (documento tecleado, documento del blanco, puente, enlace; otro lead de la
  -- persona, conversión en curso, ya cliente): con veredicto asentado y sin escribir nada.
  if v_flag_d13 then
    v_veredicto_identidad := private.juicio_reapertura(v_lead.id, v_tel, v_dni);
    if v_veredicto_identidad is not null then
      return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni, v_veredicto_identidad);
    end if;
  end if;

  -- Si OTRO lead vivo del mismo contacto tiene DUEÑO, el contacto está tomado
  -- aunque nuestro blanco sea un descarte viejo: manda el veredicto fresco.
  -- El filtro de dueño es deliberado: una bolsa viva que casa solo por el OTRO
  -- dato no estorba (el teléfono manda) — sin él, el veredicto diría «en
  -- bolsa» y la toma rebotaría en bucle contra su propio blanco telefónico.
  if exists (
    select 1
    from crm.leads l
    where l.id <> v_lead.id
      and l.activo = true
      and l.etapa not in ('convertido', 'descartado')
      and (l.vendedor_id is not null or l.asignado_supervisor_id is not null)
      and (l.telefono = v_tel or (v_dni is not null and l.dni = v_dni))
  ) then
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
  end if;

  v_propietario_anterior := coalesce(v_lead.vendedor_id, v_lead.asignado_supervisor_id);
  v_ultima_conv := (
    select pg_catalog.max(a.creado_en)
    from crm.actividades a
    where a.lead_id = v_lead.id
      and a.tipo in ('llamada_realizada', 'whatsapp_recibido', 'reunion_realizada')
  );

  if v_lead.activo = true
     and v_lead.etapa not in ('convertido', 'descartado')
     and v_lead.vendedor_id is null
     and v_lead.asignado_supervisor_id is null then
    v_modo := 'bolsa';
    v_quedo_libre_en := null;
  elsif v_lead.etapa = 'descartado' then
    if v_lead.activo = false then
      -- Un soft-borrado no se revive por esta puerta (regla del plan).
      return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
    end if;
    select ep.dias into v_dias
    from crm.enfriamiento_politica ep
    where ep.motivo = v_lead.motivo_descarte;
    v_dias := coalesce(v_dias, 0);
    v_disponible_desde := v_lead.descartado_en
      + pg_catalog.make_interval(days => v_dias);
    if v_dias > 0 and v_disponible_desde > pg_catalog.now() then
      return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
    end if;
    if v_dias = 0
       and v_lead.descartado_en + pg_catalog.make_interval(hours => 24) > pg_catalog.now() then
      -- Carencia de Miguel: un descarte de 0 días espera 24 h para TOMARSE.
      return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
    end if;
    v_modo := 'reutilizable';
    v_quedo_libre_en := case
      when v_dias > 0 then v_disponible_desde
      else v_lead.descartado_en + pg_catalog.make_interval(hours => 24)
    end;
  else
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
  end if;

  -- La válvula, SOLO alrededor del UPDATE, y quien la enciende la apaga.
  v_previo := coalesce(pg_catalog.current_setting('crm.toma_directa', true), 'off');
  perform pg_catalog.set_config('crm.toma_directa', 'on', true);
  v_previo_reab := coalesce(pg_catalog.current_setting('crm.reapertura_identidad', true), 'off');
  perform pg_catalog.set_config('crm.reapertura_identidad', 'on', true);

  if v_modo = 'bolsa' then
    update crm.leads l
       set vendedor_id = v_actor
     where l.id = v_lead.id
       and l.activo = true
       and l.no_contactar = false
       and not private.persona_vetada(l.id)  -- F2.b (b2): snapshot de la sentencia (no EvalPlanQual); el enlazado lo cubre la propagación de marcar
       and l.etapa not in ('convertido', 'descartado')
       and l.vendedor_id is null
       and l.asignado_supervisor_id is null;
  else
    begin
      update crm.leads l
         set etapa = 'nuevo',
             vendedor_id = v_actor,
             asignado_supervisor_id = null,
             motivo_descarte = null
       where l.id = v_lead.id
         and l.activo = true
         and l.no_contactar = false
         and not private.persona_vetada(l.id)  -- F2.b (b2): snapshot de la sentencia (no EvalPlanQual); el enlazado lo cubre la propagación de marcar
         and l.etapa = 'descartado';
    exception
      when unique_violation then
        -- Los índices de dedup (solo vivos) cazaron un vivo del mismo
        -- contacto: nadie roba, se responde la verdad fresca. El DNI del
        -- BLANCO entra en la consulta a propósito: el choque pudo venir por
        -- un dato que el vendedor no tecleó, y sin él el veredicto repetiría
        -- 'reutilizable' e invitaría a un bucle de reintentos.
        perform pg_catalog.set_config('crm.toma_directa', v_previo, true);
        perform pg_catalog.set_config('crm.reapertura_identidad', v_previo_reab, true);
        return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
          private.verificar_disponibilidad_lead_impl(v_tel, coalesce(v_dni, v_lead.dni)));
    end;
  end if;

  perform pg_catalog.set_config('crm.toma_directa', v_previo, true);
  perform pg_catalog.set_config('crm.reapertura_identidad', v_previo_reab, true);

  if not found then
    -- CAS en 0 filas: el estado cambió entre el veredicto y la escritura.
    return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
      private.verificar_disponibilidad_lead_impl(v_tel, v_dni));
  end if;
  -- F2.b [D-13] (Codex #5): un lead con DNI (o puente) de una persona reconocida queda ENLAZADO al tomarse, como al nacer:
  -- así la reserva, el sellado y las conversiones lo ven por identidad. La persona ya está bloqueada FOR SHARE (arriba).
  if v_flag_d13 and v_lead.inversionista_id is null then
    perform private.enlazar_lead_reabierto(v_lead.id, private.lead_persona_reabrir(v_lead.id));
  end if;

  -- Traza §9 (además de la cascada, que ya asentó 'reasignacion' + ledger):
  -- la nota rica del evento, firmada por quien tomó.
  insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por, creado_en)
  values (
    v_lead.id,
    'nota',
    case v_modo
      when 'bolsa' then 'Lead tomado desde la bolsa tras verificación de disponibilidad'
      else 'Lead tomado después de liberación por enfriamiento vencido'
    end,
    pg_catalog.jsonb_build_object(
      'evento', 'toma_directa',
      'modo', v_modo,
      'propietario_anterior', v_propietario_anterior,
      'ultima_conversacion', v_ultima_conv,
      'quedo_libre_en', v_quedo_libre_en,
      'motivo', case v_modo when 'bolsa' then 'toma_de_bolsa' else 'enfriamiento_vencido' end
    ),
    v_actor,
    pg_catalog.statement_timestamp()
  );

  -- La fila FINAL (los BEFORE ya subieron ciclo y renacieron tenencia).
  select l.* into v_lead from crm.leads l where l.id = v_lead.id;

  return private.toma_asienta_y_devuelve(v_actor, p_telefono, v_tel, v_dni,
    pg_catalog.jsonb_build_object(
      'estado', 'tomado_ok',
      'lead_id', v_lead.id,
      'modo', v_modo,
      'etapa', v_lead.etapa,
      'ciclo_actual', v_lead.ciclo_actual,
      'tenencia_desde', v_lead.tenencia_desde
    ));
end;

declare
  v_rol text := private.rol_crm((select auth.uid()));
  v_resultado jsonb;
begin
  if v_rol is null or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception using
      errcode = '42501',
      message = 'Acceso CRM revocado';
  end if;

  v_resultado := private.verificar_disponibilidad_lead_impl(p_telefono, p_dni);

  -- Registro anti-pesca (F1 lead libre): la búsqueda por identidad deja
  -- rastro legible por gerencia. Se asienta TODO intento, también el teléfono
  -- inválido — iterar identidades es exactamente lo que se vigila. Si el
  -- normalizado no existe se guarda lo tecleado, acotado.
  insert into crm.verificaciones_lead (verificado_por, telefono_consultado, dni_consultado, veredicto)
  values (
    (select auth.uid()),
    pg_catalog.left(coalesce(private.normalizar_telefono(p_telefono), p_telefono, ''), 32),
    pg_catalog.left(p_dni, 16),
    v_resultado ->> 'estado'
  );

  return v_resultado;
end;

declare
  v_actor uuid := (select auth.uid());
begin
  if v_actor is null or not exists (
    select 1
    from crm.equipo actor_equipo
    join public.perfiles actor_perfil
      on actor_perfil.id = actor_equipo.perfil_id
    where actor_equipo.perfil_id = v_actor
      and actor_equipo.rol_crm = 'gerencia'
      and actor_equipo.activo = true
      and actor_perfil.activo = true
  ) then
    raise exception 'Solo Gerencia puede configurar la capacidad de los analistas'
      using errcode = '42501';
  end if;

  if p_capacidad_leads_objetivo is not null
     and p_capacidad_leads_objetivo not between 1 and 1000 then
    raise exception 'La capacidad debe estar entre 1 y 1000 leads, o quedar sin configurar'
      using errcode = '22023';
  end if;

  return query
  update crm.equipo e
     set capacidad_leads_objetivo = p_capacidad_leads_objetivo,
         actualizado_en = statement_timestamp()
   where e.perfil_id = p_analista_id
     and e.activo = true
     and e.rol_crm in ('vendedor', 'supervisor')
     and exists (
       select 1
       from public.perfiles perfil_objetivo
       where perfil_objetivo.id = e.perfil_id
         and perfil_objetivo.activo = true
     )
  returning e.perfil_id, e.capacidad_leads_objetivo;

  if not found then
    raise exception 'Analista activo no encontrado'
      using errcode = 'P0002';
  end if;
end;

declare
  v_p record; v_inv uuid; v_otro uuid; v_enlazado boolean := false;
  v_tramo boolean := false; v_revision boolean := false; v_asesor uuid; v_tipo text; v_doc text;
begin
  select p.tipo_documento, p.dni, p.rol, p.activo, p.asesor_perfil_id
    into v_p from public.perfiles p where p.id = p_perfil_id;
  if not found or v_p.rol <> 'cliente' then
    raise exception 'El perfil no es un cliente' using errcode = 'P0409';
  end if;
  v_tipo := coalesce(nullif(pg_catalog.btrim(v_p.tipo_documento), ''), 'DNI');
  v_doc  := nullif(pg_catalog.upper(pg_catalog.regexp_replace(coalesce(v_p.dni, ''), '[^A-Za-z0-9]', '', 'g')), '');
  if v_doc is null then
    raise exception 'El cliente no tiene documento: no se puede reconocer a la persona (identidad unificada)'
      using errcode = 'P0409';
  end if;
  -- jerarquía (compartida, como derivar) -> documento -> identidad -> perfil. La jerarquía va
  -- PRIMERO: el offboarding la toma exclusiva y luego actualiza perfiles (Codex E2 #9).
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0));
  perform private.identidad_bloquear_documento(v_tipo, v_doc);
  v_inv := private.inversionista_resolver(v_tipo, v_doc, true, p_fuente);
  perform 1 from crm.inversionistas i where i.id = v_inv for update;
  perform 1 from public.perfiles p where p.id = p_perfil_id
     and coalesce(nullif(pg_catalog.btrim(p.tipo_documento), ''), 'DNI') = v_tipo
     and pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p.dni, ''), '[^A-Za-z0-9]', '', 'g')) = v_doc
   for share;
  if not found then
    raise exception 'El documento del cliente cambió mientras se enlazaba; vuelve a intentarlo' using errcode = '40001';
  end if;
  select i.perfil_id into v_otro from crm.inversionistas i where i.id = v_inv;
  if v_otro is null then
    if exists (select 1 from crm.inversionistas i where i.perfil_id = p_perfil_id and i.estado <> 'fusionado' and i.id <> v_inv) then
      raise exception 'Este perfil ya pertenece a otra persona reconocida (fusión o corrección de Gerencia)' using errcode = 'P0409';
    end if;
    update crm.inversionistas set perfil_id = p_perfil_id where id = v_inv;
    v_enlazado := true;
  elsif v_otro <> p_perfil_id then
    raise exception 'La persona de este documento ya tiene otro perfil de cliente (revisión de Gerencia)' using errcode = 'P0409';
  end if;
  -- Responsable de relación (contrato §6): solo si no hay tramo abierto y el asesor está activo.
  if not exists (select 1 from crm.inversionista_responsables r where r.inversionista_id = v_inv and r.hasta is null) then
    -- Asesor releído bajo el perfil FOR SHARE (el offboarding no pudo cambiarlo: sostiene la jerarquía exclusiva).
    select p.asesor_perfil_id into v_asesor from public.perfiles p where p.id = p_perfil_id;
    if v_asesor is not null
       and exists (select 1 from crm.equipo e join public.perfiles pp on pp.id = e.perfil_id
                   where e.perfil_id = v_asesor and e.activo and pp.activo) then
      insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo, por)
      values (v_inv, v_asesor, p_fuente, (select auth.uid()));
      update crm.inversionistas set responsable_relacion_id = v_asesor where id = v_inv;
      v_tramo := true;
    else
      v_revision := true;
    end if;
  end if;
  return pg_catalog.jsonb_build_object('inversionista_id', v_inv, 'enlazado_ahora', v_enlazado,
    'tramo_abierto', v_tramo, 'revision_responsable', v_revision);
end;

declare
  v_sin_declarar text;
  v_caducadas text;
  v_declaradas integer;
  v_tope integer;
  v_nucleo text;
  v_nucleo_esperado text;
  v_src text;
begin
  select string_agg(tipo || ' ' || objeto, ', ' order by objeto)
    into v_sin_declarar
    from private.puertas_analista_sin_vigencia() where not declarada;
  if v_sin_declarar is not null then
    raise exception 'Puertas que preguntan por el rol del Portal a secas y NO estan declaradas: %. O preguntan por private.es_analista_vigente(), o se declaran con su razon.', v_sin_declarar;
  end if;

  select string_agg(tipo || ' ' || objeto, ', ' order by objeto)
    into v_caducadas
    from private.puertas_analista_sin_vigencia() where declarada and not huella_ok;
  if v_caducadas is not null then
    raise exception 'Puertas exentas cuyo cuerpo CAMBIO desde que se declararon (la razon ya no se puede dar por buena): %', v_caducadas;
  end if;

  select count(*) into v_declaradas from private.puertas_analista_sin_vigencia();
  select tope, nucleo_huella into v_tope, v_nucleo_esperado from private.analista_vigencia_tope where id;
  if v_tope is null then
    raise exception 'No hay tope fijado para las puertas sin vigencia';
  end if;
  if v_declaradas > v_tope then
    raise exception 'Las puertas sin vigencia subieron de % a %: el trinquete solo deja bajar.', v_tope, v_declaradas;
  end if;

  -- La pregunta unica, por HUELLA exacta y por atributos: no basta con que
  -- "contenga" las dos palabras.
  select md5(p.prosrc), p.prosrc into v_nucleo, v_src
    from pg_proc p where p.oid = 'private.es_analista_vigente()'::regprocedure;
  if v_nucleo_esperado is not null and v_nucleo is distinct from v_nucleo_esperado then
    raise exception 'private.es_analista_vigente() cambio de cuerpo (huella % en vez de %)', v_nucleo, v_nucleo_esperado;
  end if;
  if v_src !~ '\mes_analista\s*\(' or v_src !~ '\mmembresia_crm_revocada\s*\(' then
    raise exception 'private.es_analista_vigente() dejo de preguntar por las dos mitades';
  end if;
  if not exists (
    select 1 from pg_proc p
     where p.oid = 'private.es_analista_vigente()'::regprocedure
       and p.prosecdef and p.provolatile = 's'
       -- 🔴 El search_path vacio se guarda CON COMILLAS (`search_path=""`).
       --    Comprobar `array['search_path=']` falla SIEMPRE (trampa ya pagada
       --    dos veces en este proyecto). Se aceptan las dos formas.
       and exists (select 1 from unnest(p.proconfig) c where c ~ '^search_path=(""|)$')
  ) then
    raise exception 'private.es_analista_vigente() perdio security definer, stable o el search_path vacio';
  end if;

  return 'OK: ' || v_declaradas || ' puertas declaradas y con su huella intacta, tope ' || v_tope || ', 0 sin declarar';
end;

declare
  v_sin text; v_cad text; v_n integer; v_tope integer;
begin
  select string_agg(tipo || ' ' || objeto, ', ' order by objeto)
    into v_sin from private.contadores_crudos_leads_citas() where not declarada;
  if v_sin is not null then
    raise exception 'Contadores crudos de leads/citas SIN declarar: %. O beben del nucleo, o se declaran con su razon.', v_sin;
  end if;

  select string_agg(tipo || ' ' || objeto, ', ' order by objeto)
    into v_cad from private.contadores_crudos_leads_citas() where declarada and not huella_ok;
  if v_cad is not null then
    raise exception 'Contadores exentos cuyo cuerpo CAMBIO desde que se declararon (la razon caduco): %', v_cad;
  end if;

  select count(*) into v_n from private.contadores_crudos_leads_citas();
  -- Anti-vacuidad: el tope es techo, no suelo. Un censo que devuelve 0 filas es
  -- una regresion del propio censo, no un exito.
  if v_n = 0 then
    raise exception 'El censo devolvio 0 contadores: eso es una regresion del censo, no la meta';
  end if;
  select tope into v_tope from private.analitica_leads_citas_tope where id;
  if v_tope is null then raise exception 'No hay tope fijado'; end if;
  if v_n > v_tope then
    raise exception 'Los contadores crudos subieron de % a %: el trinquete solo deja bajar.', v_tope, v_n;
  end if;

  -- El sello de la lista: si alguien la relavo sin re-sellar, rojo.
  if (select sello from private.analitica_lc_sello where id)
     is distinct from private.huella_exenciones_analitica_lc() then
    raise exception 'La lista de exenciones cambio sin re-sellarse en una migracion';
  end if;

  -- Los candados del tope tienen que seguir puestos y ACTIVOS: sin esto, un
  -- despliegue privilegiado podria deshabilitar el trigger, subir el tope y
  -- dejar el gate verde.
  if (select count(*) from pg_trigger t
       where t.tgrelid = 'private.analitica_leads_citas_tope'::regclass
         and t.tgname in ('trg_analitica_lc_tope_solo_baja','trg_analitica_lc_tope_no_truncar')
         and t.tgenabled in ('O','A')) <> 2 then
    raise exception 'Los candados del tope no estan puestos o no estan activos';
  end if;

  -- Los dos nucleos tienen que seguir vivos y con su forma.
  if to_regprocedure('private.citas_episodios(timestamptz,timestamptz,timestamptz)') is null then
    raise exception 'El nucleo de citas desaparecio';
  end if;
  if to_regprocedure('private.conversion_episodios(timestamptz,timestamptz,date,boolean,uuid[],numeric)') is null then
    raise exception 'El nucleo de leads desaparecio';
  end if;
  -- Y la pantalla de reuniones tiene que seguir bebiendo del de citas - mirado
  -- SIN comentarios (un `-- citas_episodios` de senuelo no vale).
  if not exists (
    select 1 from pg_proc p
     where p.oid = 'private.metricas_reuniones_implementacion(date,date)'::regprocedure
       and regexp_replace(regexp_replace(p.prosrc,'--[^\n]*',' ','g'),'/\*.*?\*/',' ','g')
           ~ '\mcitas_episodios\s*\('
  ) then
    raise exception 'La pantalla de reuniones dejo de beber del nucleo de citas';
  end if;

  -- El nucleo devuelve FILAS de toda la empresa (DEFINER): cada llamador tiene
  -- que estar DECLARADO en las exenciones (su declaracion es su puerta escrita).
  if exists (
    select 1 from pg_proc p
     where p.prokind in ('f','p')
       and p.oid <> coalesce(to_regprocedure('private.citas_episodios(timestamptz,timestamptz,timestamptz)'),0)
       and p.oid <> coalesce(to_regprocedure('private.assert_analitica_leads_citas()'),0)
       and p.oid <> coalesce(to_regprocedure('private.contadores_crudos_leads_citas()'),0)
       and regexp_replace(regexp_replace(coalesce(p.prosrc,''),'--[^\n]*',' ','g'),'/\*.*?\*/',' ','g')
           ~ '\mcitas_episodios\s*\('
       and not exists (select 1 from private.analitica_leads_citas_exenciones e
                        where e.objeto = p.oid::regprocedure::text)
  ) then
    raise exception 'Hay un consumidor de citas_episodios SIN declarar: el nucleo sirve filas de toda la empresa y cada llamador declara su puerta';
  end if;

  -- El ACL del nucleo, exacto: solo postgres (el mismo patron que
  -- conversion_episodios y capital_episodios). Un grant posterior es rojo.
  if exists (
    select 1 from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     where p.oid = 'private.citas_episodios(timestamptz,timestamptz,timestamptz)'::regprocedure
       and a.grantee <> 'postgres'::regrole::oid
  ) then
    raise exception 'citas_episodios tiene EXECUTE para alguien mas que postgres';
  end if;

  return 'OK: ' || v_n || ' contadores declarados y con su huella intacta, tope ' || v_tope || ', 0 sin declarar';
end;

declare
  v_sin_rastro text;
  v_cuantas int;
  v_alertas text;
  v_cron int;
begin
  select pg_catalog.count(*), pg_catalog.string_agg(s.tabla, ', ')
    into v_cuantas, v_sin_rastro
  from private.tablas_sin_rastro() s;

  if v_cuantas > 0 then
    raise exception using errcode = 'P0001',
      message = 'AUDITORÍA ROTA: ' || v_cuantas || ' tabla(s) sin rastro completo [' ||
        v_sin_rastro || ']. Cuélgale un auditor AFTER por fila para los tres ' ||
        'verbos, o declárala en private.auditoria_exenciones con su razón.';
  end if;

  if not exists (select 1 from private.auditoria_sello
                 where huella = private.huella_exenciones()) then
    raise exception using errcode = 'P0001',
      message = 'SELLO ROTO: las listas de exenciones o de auditoría condicionada cambiaron sin re-sellar.';
  end if;

  select pg_catalog.count(*) into v_cron
  from cron.job
  where jobname = 'crm-auditoria-vigia'
    and command = 'select private.vigia_auditoria()'
    and schedule = '29 6 * * *'
    and database = pg_catalog.current_database()
    and active;
  if v_cron <> 1 then
    raise exception using errcode = 'P0001',
      message = 'VIGÍA MAL PROGRAMADO: se esperaba exactamente 1 job activo con su horario, comando y base; hay ' || v_cron || '.';
  end if;

  select pg_catalog.string_agg(a.tabla, ', ') into v_alertas
  from private.auditoria_alertas a where a.resuelta_en is null;
  if v_alertas is not null then
    raise exception using errcode = 'P0001',
      message = 'EL VIGÍA TIENE ALERTAS ABIERTAS: ' || v_alertas;
  end if;
end;

declare
  r record; v_h text; v_acl text; v_n integer; v_p text;
  v_excluidos oid[]; v_permitidos oid[];
  v_obs integer := 0; v_perm integer := 0; v_dem integer := 0; v_lib integer := 0;
begin
  if not exists (select 1 from private.f7_piezas_en_observacion) then
    raise exception 'F7: la tabla de observacion esta VACIA (fail-closed)';
  end if;

  -- El conjunto vigilado entero se excluye de todo censo: las gemelas se
  -- nombran entre si y todas estan congeladas por huella de todos modos.
  select coalesce(array_agg((to_regprocedure(o.firma))::oid), '{}'::oid[]) into v_excluidos
    from private.f7_piezas_en_observacion o
   where to_regprocedure(o.firma) is not null;

  for r in select * from private.f7_piezas_en_observacion order by firma loop
    if r.estado = 'liberada' then
      -- Llegar aqui SOLO es posible por una migracion que bajo el candado
      -- (la maquina de estados lo prohibe por UPDATE): la pieza volvio al
      -- servicio deliberadamente y deja de vigilarse.
      v_lib := v_lib + 1; continue;
    end if;

    if r.estado = 'demolida' then
      if to_regprocedure(r.firma) is not null then
        raise exception 'F7: % RENACIO despues de su demolicion', r.firma;
      end if;
      if r.drop_no_antes_de is not null and current_date < r.drop_no_antes_de then
        raise exception 'F7: % fue demolida ANTES de su ventana (no antes de %)', r.firma, r.drop_no_antes_de;
      end if;
      v_dem := v_dem + 1; continue;
    end if;

    -- observacion / cerrada_permanente: existe, congelada, cerrada.
    if to_regprocedure(r.firma) is null then
      raise exception 'F7: % desaparecio SIN pasar por la demolicion', r.firma;
    end if;
    select md5(p.prosrc) into v_h from pg_proc p where p.oid = r.firma::regprocedure;
    if v_h is distinct from r.huella_md5 then
      raise exception 'F7: el cuerpo de % cambio estando cerrada (huella %)', r.firma, v_h;
    end if;
    select p.proacl::text into v_acl from pg_proc p where p.oid = r.firma::regprocedure;
    if v_acl is distinct from r.acl_esperada then
      raise exception 'F7: % SE REABRIO (ACL %, se esperaba %)', r.firma, v_acl, r.acl_esperada;
    end if;

    v_permitidos := '{}'::oid[];
    foreach v_p in array r.llamadores_permitidos loop
      if to_regprocedure(v_p) is null then
        raise exception 'F7: el llamador permitido % de % ya no resuelve', v_p, r.firma;
      end if;
      v_permitidos := v_permitidos || (to_regprocedure(v_p))::oid;
    end loop;

    -- Codex P0-1: el cuerpo de una funcion SQL-standard vive en prosqlbody
    -- (prosrc queda vacio) — se censan AMBOS textos.
    select count(*) into v_n
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname not in ('pg_catalog', 'information_schema')
       and p.oid <> all (v_excluidos || v_permitidos)
       and lower(replace(
             regexp_replace(regexp_replace(
               coalesce(p.prosrc, '') || ' ' || coalesce(pg_get_function_sqlbody(p.oid), ''),
               '--[^\n]*', ' ', 'g'),
               '/\*.*?\*/', ' ', 'g'), '"', '')) ~ r.patron_censo;
    if v_n <> 0 then
      raise exception 'F7: % funciones NUEVAS nombran a % — alguien empezo a usarla', v_n, r.firma;
    end if;

    -- Codex P0-1: las VISTAS y REGLAS tambien pueden llamarla — se censan.
    select count(*) into v_n
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname not in ('pg_catalog', 'information_schema')
       and c.relkind in ('v', 'm')
       and lower(replace(pg_get_viewdef(c.oid), '"', '')) ~ r.patron_censo;
    if v_n <> 0 then
      raise exception 'F7: % VISTAS nombran a % — alguien la cableo por una vista', v_n, r.firma;
    end if;

    -- Auditoria F7.0 (P1): el parser resuelve MAYUSCULAS y comillas — el censo
    -- tambien: todo texto se normaliza con lower() y sin comillas dobles.
    select (select count(*) from pg_policy pol
             where lower(replace(coalesce(pg_get_expr(pol.polqual, pol.polrelid), ''), '"', '')) ~ r.patron_censo
                or lower(replace(coalesce(pg_get_expr(pol.polwithcheck, pol.polrelid), ''), '"', '')) ~ r.patron_censo)
         + (select count(*) from pg_attrdef ad
             where lower(replace(pg_get_expr(ad.adbin, ad.adrelid), '"', '')) ~ r.patron_censo)
         + (select count(*) from pg_constraint c
             where c.contype = 'c' and lower(replace(pg_get_constraintdef(c.oid), '"', '')) ~ r.patron_censo)
         + (select count(*) from cron.job j where lower(replace(j.command, '"', '')) ~ r.patron_censo)
      into v_n;
    if v_n <> 0 then
      raise exception 'F7: % aparece en % superficies (policies/defaults/checks/cron)', r.firma, v_n;
    end if;

    if r.estado = 'observacion' then v_obs := v_obs + 1; else v_perm := v_perm + 1; end if;
  end loop;

  -- Codex P0-4: un GRANT de MEMBRESIA (rol puente hacia el dueño) transmite
  -- los privilegios del owner SIN tocar proacl. Cierre transversal AMPLIADO
  -- en F7.1 (2 hallazgos Codex 30/08): ni authenticated, ni anon, NI
  -- service_role (esta ola le quita dos EXECUTE directos) pueden alcanzar por
  -- la cadena de roles a postgres NI a NINGUN rol dueño de una pieza vigilada
  -- (crm_metricas_bridge posee las puertas v1/v2: una membresia heredable
  -- hacia el las reabriria con el proacl intacto y el vigia verde).
  if exists (
    with recursive alcance as (
      select pr.oid from pg_roles pr where pr.rolname in ('authenticated', 'anon', 'service_role')
      union
      select m.roleid from pg_auth_members m join alcance al on al.oid = m.member
    )
    select 1 from alcance al2
     where al2.oid = 'postgres'::regrole
        or al2.oid in (
          select p.proowner from pg_proc p
           where p.oid in (
             select to_regprocedure(o.firma) from private.f7_piezas_en_observacion o
              where o.estado in ('observacion', 'cerrada_permanente')
                and to_regprocedure(o.firma) is not null
           )
        )
  ) then
    raise exception 'F7: un rol de API ALCANZA a postgres o a un dueño de pieza vigilada por membresia de roles — puerta trasera de herencia';
  end if;

  return format('OK: %s piezas vigiladas (observacion %s, permanentes %s, demolidas %s, liberadas %s)',
                v_obs + v_perm + v_dem + v_lib, v_obs, v_perm, v_dem, v_lib);
end;

declare
  r record; v_inv uuid; v_valido boolean;
  v_old_priv text := pg_catalog.current_setting('crm.op_privilegiada', true);
  v_demo_cierre constant uuid := 'a112aead-184a-4979-9041-943978fadae4';
  v_a int:=0; v_b int:=0; v_c int:=0; v_e int:=0; v_resp int:=0; v_noc int:=0;
begin
  perform pg_catalog.set_config('crm.op_privilegiada','on', true);

  -- ── Clase A / E: perfiles cliente ──
  for r in
    select p.id, p.tipo_documento as tipo, p.asesor_perfil_id,
           pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p.dni,''),'[^A-Za-z0-9]','','g')) as dnorm
    from public.perfiles p where p.rol='cliente'
    order by p.id
  loop
    if r.dnorm = '' then
      perform private.f2_mapear('perfil', r.id, null, 'E', 'cliente sin documento', 'revision');
      v_e := v_e+1; continue;
    end if;
    v_valido := coalesce(case r.tipo
      when 'DNI' then r.dnorm ~ '^[0-9]{8}$'
      when 'CE' then r.dnorm ~ '^[0-9]{9,12}$'
      when 'PASAPORTE' then r.dnorm ~ '^[A-Z0-9]{6,12}$' else false end, false);
    if not v_valido then
      perform private.f2_mapear('perfil', r.id, null, 'E', 'documento con formato invalido para '||r.tipo, 'revision');
      v_e := v_e+1; continue;
    end if;
    if exists (
      select 1 from public.perfiles p2
      where p2.id <> r.id
        and pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p2.dni,''),'[^A-Za-z0-9]','','g')) = r.dnorm
    ) then
      perform private.f2_mapear('perfil', r.id, null, 'E', 'documento compartido con otro perfil (multirrol/colision)', 'revision');
      v_e := v_e+1; continue;
    end if;
    v_inv := private.inversionista_resolver(r.tipo, r.dnorm, true, 'backfill-A');
    update crm.inversionistas set perfil_id = r.id
      where id = v_inv and perfil_id is null
        and not exists (select 1 from crm.inversionistas i2 where i2.perfil_id = r.id and i2.id <> v_inv);
    perform private.f2_mapear('perfil', r.id, v_inv, 'A', 'perfil cliente con documento valido y unico', 'alta');
    v_a := v_a+1;
    if r.asesor_perfil_id is not null
       and exists (select 1 from crm.equipo e where e.perfil_id=r.asesor_perfil_id and e.activo)
       and not exists (select 1 from crm.inversionista_responsables ir where ir.inversionista_id=v_inv and ir.hasta is null) then
      insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo)
      values (v_inv, r.asesor_perfil_id, 'backfill: asesor del perfil cliente');
      update crm.inversionistas set responsable_relacion_id = r.asesor_perfil_id where id=v_inv and responsable_relacion_id is null;
      v_resp := v_resp+1;
    end if;
  end loop;

  -- ── Clase B / E: cierres coop (EXCLUYE el demo por id) ──
  for r in
    select ce.id, ce.documento_tipo as tipo, ce.cooperativa, ce.vendedor_id, ce.creado_por, ce.creado_en,
           pg_catalog.upper(pg_catalog.regexp_replace(ce.documento,'[^A-Za-z0-9]','','g')) as dnorm
    from crm.cierres_externos ce where ce.id <> v_demo_cierre
    order by ce.creado_en, ce.id
  loop
    v_valido := coalesce(case r.tipo
      when 'DNI' then r.dnorm ~ '^[0-9]{8}$'
      when 'CE' then r.dnorm ~ '^[0-9]{9,12}$'
      when 'PASAPORTE' then r.dnorm ~ '^[A-Z0-9]{6,12}$' else false end, false);
    if not v_valido then
      perform private.f2_mapear('cierre', r.id, null, 'E', 'documento de cierre invalido', 'revision');
      v_e := v_e+1; continue;
    end if;
    v_inv := private.inversionista_resolver(r.tipo, r.dnorm, true, 'backfill-B');
    update crm.cierres_externos set inversionista_id = v_inv where id = r.id and inversionista_id is null;
    insert into crm.inversiones (inversionista_id, empresa_id, cierre_externo_id, estado, fecha_comercial, es_primera_conversion, creado_por)
    select v_inv, e.id, r.id, 'vigente',
           least((r.creado_en at time zone 'America/Lima')::date, (pg_catalog.now() at time zone 'America/Lima')::date),
           true, r.creado_por
    from crm.empresas e
    where e.clave = r.cooperativa
      and not exists (select 1 from crm.inversiones inv where inv.cierre_externo_id = r.id);
    insert into crm.inversion_titulares (inversion_id, inversionista_id, rol)
    select inv.id, v_inv, 'principal' from crm.inversiones inv
    where inv.cierre_externo_id = r.id
      and not exists (select 1 from crm.inversion_titulares it where it.inversion_id=inv.id and it.rol='principal');
    perform private.f2_mapear('cierre', r.id, v_inv, 'B', 'cierre coop con documento valido; inversion externa inicial', 'alta');
    v_b := v_b+1;
    if r.vendedor_id is not null
       and not exists (select 1 from crm.inversionista_responsables ir where ir.inversionista_id=v_inv and ir.hasta is null) then
      insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo)
      values (v_inv, r.vendedor_id, 'backfill: vendedor del cierre coop');
      update crm.inversionistas set responsable_relacion_id = r.vendedor_id where id=v_inv and responsable_relacion_id is null;
      v_resp := v_resp+1;
    end if;
  end loop;

  -- ── Clase C / E: leads convertidos ──
  for r in
    select l.id as lead_id, l.no_contactar,
           pg_catalog.upper(pg_catalog.regexp_replace(coalesce(l.dni,''),'[^A-Za-z0-9]','','g')) as ldni,
           (select i.id from crm.inversionistas i where i.perfil_id = l.perfil_id and i.estado <> 'fusionado' limit 1) as inv_perfil,
           (select ce.inversionista_id from crm.cierres_externos ce where ce.lead_id = l.id) as inv_cierre
    from crm.leads l where l.etapa='convertido'
    order by l.creado_en, l.id
  loop
    if r.inv_perfil is not null and r.inv_cierre is not null and r.inv_perfil <> r.inv_cierre then
      perform private.f2_mapear('lead', r.lead_id, null, 'E', 'convertido con perfil y cierre en identidades distintas', 'revision');
      v_e := v_e+1; continue;
    end if;
    v_inv := coalesce(r.inv_perfil, r.inv_cierre);
    if v_inv is null then
      perform private.f2_mapear('lead', r.lead_id, null, 'E', 'lead convertido sin identidad inequivoca de perfil ni cierre', 'revision');
      v_e := v_e+1; continue;
    end if;
    if r.ldni <> '' and not exists (
      select 1 from crm.inversionista_identificadores d
      where d.inversionista_id = v_inv and d.documento_normalizado = r.ldni and d.estado='vigente'
    ) then
      perform private.f2_mapear('lead', r.lead_id, null, 'E', 'discrepancia documental del lead convertido', 'revision');
      v_e := v_e+1; continue;
    end if;
    if exists (select 1 from crm.leads l2 where l2.inversionista_id = v_inv) then
      insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
      select v_inv, r.lead_id, 'historico'
      where not exists (select 1 from crm.inversionista_leads il where il.lead_id = r.lead_id);
    else
      update crm.leads set inversionista_id = v_inv where id = r.lead_id and inversionista_id is null;
      insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
      select v_inv, r.lead_id, 'canonico'
      where not exists (select 1 from crm.inversionista_leads il where il.lead_id = r.lead_id);
    end if;
    perform private.f2_mapear('lead', r.lead_id, v_inv, 'C', 'lead convertido hereda identidad de perfil/cierre', 'alta');
    v_c := v_c+1;
    if r.no_contactar then
      update crm.inversionistas set no_contactar = true, no_contactar_en = coalesce(no_contactar_en, pg_catalog.now())
      where id = v_inv and no_contactar = false;
      v_noc := v_noc+1;
    end if;
  end loop;

  perform pg_catalog.set_config('crm.op_privilegiada', coalesce(v_old_priv, 'off'), true);
  return jsonb_build_object('A',v_a,'B',v_b,'C',v_c,'E',v_e,'responsables',v_resp,'no_contactar',v_noc);
end

