declare v_personas uuid[]; v_claves text[]; v_k text;
begin
  if not private.resolver_en_puertas_bajo_candado() then
    return pg_catalog.jsonb_build_object('personas', '[]'::jsonb, 'claves', '[]'::jsonb);
  end if;
  -- Codex v4.3 [2]: la comprobación «sigue dentro de lo bloqueado» relee tras esperar y eso solo vale en READ COMMITTED
  -- (en REPEATABLE READ el snapshot viejo esconde a una persona confirmada por otra transacción).
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  select pg_catalog.array_agg(distinct p order by p) into v_personas
  from (select private.lead_persona_reabrir(l.id) as p from crm.leads l where l.id = any(coalesce(p_leads, '{}'::uuid[]))
        union select private.inversionista_por_documento('DNI', p_dni_extra) where p_dni_extra is not null) s
  where p is not null;
  select pg_catalog.array_agg(distinct k order by k) into v_claves
  from (select 'DNI:' || l.dni as k from crm.leads l where l.id = any(coalesce(p_leads, '{}'::uuid[])) and l.dni is not null
        union select 'DNI:' || p_dni_extra where p_dni_extra is not null
        union select d.tipo_documento || ':' || d.documento_normalizado
                from crm.inversionista_identificadores d
               where d.inversionista_id = any(coalesce(v_personas, '{}'::uuid[])) and d.estado = 'vigente') s;
  if v_claves is not null then
    foreach v_k in array v_claves loop
      perform private.identidad_bloquear_documento(split_part(v_k, ':', 1), split_part(v_k, ':', 2));
    end loop;
  end if;
  if v_personas is not null then
    perform 1 from crm.inversionistas i where i.id = any(v_personas) order by i.id for share;
  end if;
  -- Codex v4.3 [1]: identidad_bloquear_documento es un no-op si la bandera está APAGADA; si alguien la apagó entre la primera
  -- lectura y los candados, no hay candados reales → no se declara nada bloqueado (el llamador da veredicto fresco / 40001).
  if not private.resolver_en_puertas_bajo_candado() then
    return pg_catalog.jsonb_build_object('personas', '[]'::jsonb, 'claves', '[]'::jsonb);
  end if;
  -- Devuelve lo que REALMENTE bloqueó (Codex v4.2, ABA): el llamador, tras tomar la fila, exige que el documento actual
  -- del lead esté entre las claves bloqueadas y su persona entre las bloqueadas; si no, veredicto fresco / 40001.
  return pg_catalog.jsonb_build_object('personas', pg_catalog.to_jsonb(coalesce(v_personas, '{}'::uuid[])),
                                       'claves', pg_catalog.to_jsonb(coalesce(v_claves, '{}'::text[])));
end;

declare
  v_borrados integer;
begin
  -- A los 90 días el asiento ya no gobierna ninguna alerta viva (los grupos
  -- se rehacen a diario); la trazabilidad de largo plazo vive en audit_log.
  delete from crm.alertas_reconocimientos
  where creado_en < pg_catalog.now() - make_interval(days => 90);
  get diagnostics v_borrados = row_count;
  return v_borrados;
end;

declare
  v_borrados integer;
begin
  -- 7 días de gracia tras vencer: si en una semana no atendió la campana,
  -- el recordatorio ya no recuerda nada — se va (y su PII con él).
  delete from crm.recordatorios_disponibilidad
  where recordar_en < pg_catalog.now() - make_interval(days => 7);
  get diagnostics v_borrados = row_count;
  return v_borrados;
end;

declare v_n integer;
begin
  perform pg_catalog.set_config('crm.cancela_sistema', 'on', true);
  update crm.tareas t set estado = 'cancelada' where t.lead_id = p_lead_id and t.estado = 'pendiente';
  get diagnostics v_n = row_count;
  perform pg_catalog.set_config('crm.cancela_sistema', 'off', true);
  return v_n;
end;

declare
  v_bruto text := pg_catalog.btrim(coalesce(p, ''));
  v_digitos text;
  v_internacional boolean;
  v_sin_salida text;
  v_nacional text;
  v_declara_peru boolean;
  v_n text;
  v_sin_cero text;
begin
  if v_bruto = '' then return; end if;
  -- Un correo metido en la casilla del telefono es otro dato en el sitio
  -- equivocado, no un numero roto.
  if pg_catalog.strpos(v_bruto, '@') > 0 then return; end if;

  v_digitos := pg_catalog.regexp_replace(v_bruto, '[^0-9]', '', 'g');
  if v_digitos = '' then return; end if;

  v_internacional := pg_catalog.left(v_bruto, 1) = '+'
                     or pg_catalog.left(v_digitos, 2) = '00';
  v_sin_salida := pg_catalog.regexp_replace(v_digitos, '^00', '');

  v_nacional := case when pg_catalog.left(v_sin_salida, 2) = '51'
                     then pg_catalog.substr(v_sin_salida, 3)
                     else v_sin_salida end;
  -- Todo lo que dice ser peruano se juzga con la vara peruana: si no tiene la
  -- forma exacta NO se cuela por la puerta internacional. Sin esto,
  -- '+51123456789' entraria como numero valido y nadie podria llamarlo nunca.
  v_declara_peru := pg_catalog.left(v_sin_salida, 2) = '51'
                    and pg_catalog.length(v_nacional) >= 8;

  if v_declara_peru or not v_internacional then
    v_n := case when v_declara_peru then v_nacional else v_sin_salida end;

    if v_n ~ '^9[0-9]{8}$' then
      return query select '+51' || v_n, 'celular_pe'::text, true;
      return;
    end if;

    -- ⚠️ UN FIJO EXIGE MARCA. El nacional de un fijo peruano tiene ocho digitos
    -- (Lima 1+siete, provincias 84+seis)… y el DNI peruano TAMBIEN tiene ocho.
    -- Aceptar ocho digitos pelados convertiria todo DNI en un telefono.
    v_sin_cero := case when pg_catalog.left(v_n, 1) = '0'
                       then pg_catalog.substr(v_n, 2) else v_n end;
    if (v_declara_peru or pg_catalog.left(v_n, 1) = '0')
       and v_sin_cero ~ '^[1-8][0-9]{7}$' then
      return query select '+51' || v_sin_cero, 'fijo_pe'::text, false;
      return;
    end if;

    -- Dijo ser peruano y no lo es: se acaba aqui. Y sin `+` no hay pais que
    -- suponer: no se inventa uno.
    if v_declara_peru or not v_internacional then return; end if;
  end if;

  -- E.164 puro. No se valida el codigo de pais contra una lista: mantenerla al
  -- dia en seis capas es peor deuda que aceptar un numero raro.
  if pg_catalog.length(v_sin_salida) between 8 and 15
     and v_sin_salida ~ '^[1-9][0-9]*$' then
    -- Movil o fijo es indecidible fuera de Peru sin libphonenumber. Se asume
    -- MOVIL: esconder el unico canal que hay seria peor que ofrecer uno que
    -- quiza no conteste.
    return query select '+' || v_sin_salida, 'internacional'::text, true;
  end if;
  return;
end;

declare
  v_uid      uuid := (select auth.uid());
  v_rol      text := private.rol_crm((select auth.uid()));
  v_global   boolean;
  v_visibles uuid[] := '{}'::uuid[];
begin
  if v_uid is null then
    raise exception 'No autorizado' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'Periodo invalido' using errcode = '22023';
  end if;
  if p_medida is null or p_medida not in ('stock','desglose','nula') then
    raise exception 'Elige la medida: stock (el capital existe una vez), desglose (como se compone) o nula (anuladas)'
      using errcode = '22023';
  end if;
  v_global := coalesce(v_rol = 'gerencia', false) or (select private.es_lector_global());
  if not v_global then
    v_visibles := array(select private.vendedor_ids_visibles(v_uid));
    if coalesce(array_length(v_visibles, 1), 0) = 0 then
      raise exception 'No autorizado' using errcode = '42501';
    end if;
  end if;
  return query select * from private.capital_episodios(
    (p_desde::timestamp at time zone 'America/Lima'),
    ((p_hasta + 1)::timestamp at time zone 'America/Lima'),
    v_global, v_visibles) e
  where e.medida = p_medida;
end;

select position(
  ' ' || private.normalizar_texto_ayuda(p_termino) || ' '
  in ' ' || coalesce(p_consulta_normalizada, '') || ' '
) > 0;

