declare
  v_job_id uuid;
  v_snapshot jsonb;
  v_nombre text;
  v_revision integer;
begin
  if not private.puede_leer_contrato_pdf_como(p_contrato_id, p_actor_id) then
    raise insufficient_privilege using
      message = 'Contrato no encontrado o fuera de tu cartera';
  end if;

  perform private.bloquear_fila_contrato_pdf(p_contrato_id);

  if private.contrato_en_eliminacion(p_contrato_id) then
    raise exception 'El contrato está en proceso de eliminación'
      using errcode = '55000';
  end if;
  if not private.puede_leer_contrato_pdf_como(p_contrato_id, p_actor_id) then
    raise insufficient_privilege using
      message = 'Contrato no encontrado o fuera de tu cartera';
  end if;

  if exists (
    select 1 from private.contrato_pdfs p
    where p.contrato_id = p_contrato_id
  ) or exists (
    select 1 from private.contrato_pdf_jobs j
    where j.contrato_id = p_contrato_id
  ) then
    return private.contrato_pdf_estado_base(p_contrato_id);
  end if;

  if private.contrato_documental_regimen(p_contrato_id) = 'anterior' then
    return private.contrato_pdf_estado_base(p_contrato_id);
  end if;

  v_job_id := gen_random_uuid();
  v_revision := 1;
  v_snapshot := private.contrato_pdf_snapshot_v2_base(p_contrato_id);
  v_nombre := private.nombre_archivo_contrato_pdf(p_contrato_id);
  if v_nombre is null then
    raise exception 'Contrato no encontrado' using errcode = 'P0002';
  end if;

  insert into private.contrato_pdf_jobs (
    id, contrato_id, revision, estado, storage_path, nombre_archivo,
    template_version, snapshot, solicitado_por
  ) values (
    v_job_id,
    p_contrato_id,
    v_revision,
    'pendiente',
    p_contrato_id::text || '/v2/' || v_job_id::text || '/contrato.pdf',
    v_nombre,
    'contrato-aep-17-v7',
    v_snapshot,
    p_actor_id
  );

  return private.contrato_pdf_estado_base(p_contrato_id);
end;

declare
  v_job_id uuid := gen_random_uuid();
  v_revision integer;
  v_snapshot jsonb;
  v_nombre text;
begin
  perform private.bloquear_fila_contrato_pdf(p_contrato_id);
  if private.contrato_en_eliminacion(p_contrato_id) then
    raise exception 'El contrato está en proceso de eliminación'
      using errcode = '55000';
  end if;
  if not private.puede_leer_contrato_pdf_como(p_contrato_id, p_actor_id) then
    raise insufficient_privilege using
      message = 'Contrato no encontrado o fuera de tu cartera';
  end if;

  if private.contrato_documental_regimen(p_contrato_id) = 'anterior' then
    return private.contrato_pdf_estado_base(p_contrato_id);
  end if;

  select greatest(
    coalesce((select max(j.revision) from private.contrato_pdf_jobs j
              where j.contrato_id = p_contrato_id), 0),
    coalesce((select max(p.revision) from private.contrato_pdfs p
              where p.contrato_id = p_contrato_id), 0)
  ) + 1 into v_revision;

  v_snapshot := private.contrato_pdf_snapshot_v2_base(p_contrato_id);
  v_nombre := private.nombre_archivo_contrato_pdf(p_contrato_id);
  if v_nombre is null then
    raise exception 'Contrato no encontrado' using errcode = 'P0002';
  end if;

  insert into private.contrato_pdf_jobs (
    id, contrato_id, revision, estado, storage_path, nombre_archivo,
    template_version, snapshot, solicitado_por
  ) values (
    v_job_id,
    p_contrato_id,
    v_revision,
    'pendiente',
    p_contrato_id::text || '/v2/' || v_job_id::text || '/contrato.pdf',
    v_nombre,
    'contrato-aep-17-v7',
    v_snapshot,
    p_actor_id
  );

  return private.contrato_pdf_estado_base(p_contrato_id);
end;

declare
  v_id uuid;
  v_tipo text;
  v_titulo text;
  v_vence timestamptz;
  v_duracion smallint;
  v_modalidad text;
begin
  if p_siguiente is null then return null; end if;
  v_tipo := p_siguiente->>'tipo';
  v_titulo := btrim(coalesce(p_siguiente->>'titulo',''));
  begin
    v_vence := (p_siguiente->>'vence_en')::timestamptz;
    v_id := nullif(p_siguiente->>'id','')::uuid;
  exception when others then
    raise exception 'Fecha o identificador invalido en la tarea siguiente';
  end;
  if p_siguiente->>'duracion_min' is not null then
    v_duracion := (p_siguiente->>'duracion_min')::smallint;
  end if;
  if v_tipo is null or v_tipo not in ('llamada','whatsapp','reunion','tarea')
     or v_titulo = '' or v_vence is null then
    raise exception 'La tarea siguiente exige tipo, titulo y vence_en validos';
  end if;
  if v_tipo = 'reunion' then
    v_modalidad := coalesce(nullif(p_siguiente->>'modalidad_reunion',''), 'sin_clasificar');
  end if;

  insert into crm.tareas (
    id, lead_id, perfil_id, tipo, titulo, nota, vence_en, duracion_min,
    modalidad_reunion, ubicacion_reunion, enlace_reunion,
    reagendada_de, creado_por
  ) values (
    coalesce(v_id, gen_random_uuid()), p_anterior.lead_id, p_anterior.perfil_id,
    v_tipo, v_titulo, nullif(btrim(coalesce(p_siguiente->>'nota','')), ''),
    v_vence, v_duracion, v_modalidad,
    case when v_tipo = 'reunion' then nullif(btrim(coalesce(p_siguiente->>'ubicacion_reunion','')), '') end,
    case when v_tipo = 'reunion' then nullif(btrim(coalesce(p_siguiente->>'enlace_reunion','')), '') end,
    p_reagendada_de, p_uid
  ) returning id into v_id;
  return v_id;
end;

declare
  v_producto_id uuid;
  v_permite_legacy boolean;
  v_numero_version integer;
  v_version_id uuid;
  v_condicion_id uuid;
  v_actor uuid := (select auth.uid());
begin
  if p_contrato_id is null
     or p_moneda not in ('PEN', 'USD')
     or p_modalidad not in ('mensual', 'trimestral', 'semestral', 'anual')
     or p_tipo_interes not in ('simple', 'compuesto')
     or p_capital not between 100 and 100000000
     or p_tasa_anual <= 0 or p_tasa_anual > 50
     or p_fecha_inicio is null or p_fecha_vencimiento is null
     or p_fecha_vencimiento < p_fecha_inicio
     or (p_categoria is not null
       and p_categoria not in ('nuevo', 'renovacion', 'upgrade')) then
    raise exception 'No se puede fotografiar un contrato con términos inválidos'
      using errcode = '23514';
  end if;

  select p.id, p.permite_altas_legacy
    into v_producto_id, v_permite_legacy
  from crm.productos_inversion p
  where p.codigo = 'HISTORICO-SIN-CATALOGO'
    and p.es_legacy
  for update;
  if not found then
    raise exception 'Falta el producto técnico de contratos históricos'
      using errcode = 'P0001';
  end if;
  if not v_permite_legacy then
    raise exception
      'La compatibilidad legacy está cerrada; selecciona un producto publicado para cambiar términos'
      using errcode = '23514';
  end if;

  select coalesce(max(v.numero_version), 0) + 1
    into v_numero_version
  from crm.producto_versiones v
  where v.producto_id = v_producto_id;

  insert into crm.producto_versiones (
    producto_id, numero_version, estado, nombre, descripcion,
    vigente_desde, vigente_hasta, creado_por, actualizado_por
  ) values (
    v_producto_id, v_numero_version, 'borrador',
    'Histórico sin catálogo',
    'Snapshot técnico del contrato ' || p_contrato_id::text,
    p_fecha_inicio, p_fecha_vencimiento, v_actor, v_actor
  ) returning id into v_version_id;

  insert into crm.producto_condiciones (
    version_id, orden, categoria, moneda, plazo_meses, modalidad,
    tipo_interes, capital_minimo, capital_maximo, tasa_referencia,
    tasa_minima, tasa_maxima, es_legacy, legacy_contrato_id,
    fecha_inicio_legacy, fecha_vencimiento_legacy, creado_por
  ) values (
    v_version_id, 1, p_categoria, p_moneda, null, p_modalidad,
    p_tipo_interes, p_capital, p_capital, p_tasa_anual,
    p_tasa_anual, p_tasa_anual, true, p_contrato_id,
    p_fecha_inicio, p_fecha_vencimiento, v_actor
  ) returning id into v_condicion_id;

  update crm.producto_versiones
     set estado = 'retirada',
         revision = revision + 1,
         actualizado_por = v_actor,
         actualizado_en = now(),
         retirada_por = v_actor,
         retirada_en = now()
   where id = v_version_id;

  return v_condicion_id;
end;

