declare
  v_dia_registro date := (
    coalesce(new.creado_en, statement_timestamp())
      at time zone 'America/Lima'
  )::date;
  v_periodo date;
begin
  if tg_op = 'UPDATE' then
    if (
      new.fecha_cierre_comercial is distinct from old.fecha_cierre_comercial
      or new.fuente_cierre_comercial is distinct from old.fuente_cierre_comercial
    ) and coalesce(
      current_setting('crm.correccion_periodo_comercial', true), ''
    ) <> 'on' then
      raise exception 'La fecha de cierre comercial solo se corrige mediante su RPC auditada'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.fecha_cierre_comercial is not null then
    raise exception 'La fecha de cierre comercial no se envia en el alta'
      using errcode = '42501',
            hint = 'El servidor la infiere; Gerencia puede corregirla despues mediante la RPC auditada.';
  end if;

  new.fecha_cierre_comercial := least(new.fecha_inicio, v_dia_registro);
  new.fuente_cierre_comercial := case
    when new.fecha_inicio < v_dia_registro then 'fecha_inicio_inferida'
    else 'registro'
  end;

  v_periodo := date_trunc('month', new.fecha_cierre_comercial)::date;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.periodos_cerrados'),
    (v_periodo - date '2000-01-01')::integer
  );
  if exists (
    select 1
    from crm.periodos_cerrados pc
    where pc.periodo = v_periodo
  ) then
    raise exception 'No se puede registrar un contrato en un mes comercial sellado'
      using errcode = 'P0409',
            hint = 'Registra o corrige el cierre comercial antes del sello mensual.';
  end if;

  return new;
end;

declare
  v_actor uuid := (select auth.uid());
  v_lead  crm.leads%rowtype;
  v_nota  text := nullif(btrim(coalesce(p_nota, '')), '');
begin
  -- 1) Gate: coordinador|gerencia activos, con perfil de portal activo.
  if v_actor is null or not exists (
    select 1 from crm.equipo ae
    join public.perfiles ap on ap.id = ae.perfil_id
    where ae.perfil_id = v_actor
      and ae.rol_crm in ('coordinador','gerencia')
      and ae.activo = true and ap.activo = true
  ) then
    raise exception 'Solo el coordinador puede descartar leads de la cola'
      using errcode = '42501';
  end if;

  -- 2) Argumentos. La lista es el ESPEJO de leads_motivo_descarte_check: el
  --    CHECK sigue siendo la autoridad, esto solo da un mensaje humano antes
  --    de tocar la fila (un 23514 crudo no se puede traducir al usuario).
  if p_lead is null then
    raise exception 'El lead es obligatorio' using errcode = '22023';
  end if;
  if p_motivo is null or p_motivo not in (
    'sin_interes','sin_fondos','competencia','no_responde',
    'datos_invalidos','pide_credito','otro'
  ) then
    raise exception 'Motivo de descarte inválido' using errcode = '22023';
  end if;
  if v_nota is not null and length(v_nota) > 500 then
    raise exception 'La nota del descarte no puede pasar de 500 caracteres'
      using errcode = '22023';
  end if;

  -- 3) Toma el lead de la COLA GLOBAL y bloquéalo en la MISMA tx. El filtro NO
  --    incluye `etapa`: hace falta leer la etapa ya bloqueada para resolver la
  --    idempotencia del paso 4 (si se filtrara por etapa abierta, un reintento
  --    legítimo caería en P0002 y la UI mostraría un error falso).
  select * into v_lead
  from crm.leads l
  where l.id = p_lead and l.activo = true
    and l.vendedor_id is null and l.asignado_supervisor_id is null
  for update;
  if not found then
    raise exception 'El lead no está en la cola por repartir (tiene dueño, está inactivo o no existe)'
      using errcode = 'P0002';
  end if;

  -- 4) IDEMPOTENCIA: el mismo actor repitiendo el mismo descarte (doble clic,
  --    reintento de red, perdedor de una carrera consigo mismo) recibe el mismo
  --    resultado con 'ya_estaba', sin segunda actividad ni segunda fila de
  --    auditoría. Con OTRO motivo o de OTRO actor NO es idempotente: eso es un
  --    conflicto real y debe verse.
  if v_lead.etapa = 'descartado' then
    if v_lead.motivo_descarte = p_motivo
       and v_lead.descartado_por is not distinct from v_actor then
      return jsonb_build_object(
        'lead_id', p_lead,
        'motivo_descarte', v_lead.motivo_descarte,
        'clasificacion_auto', v_lead.clasificacion_auto,
        'descartado_por', v_lead.descartado_por,
        'descartado_en', v_lead.descartado_en,
        'ya_estaba', true);
    end if;
    raise exception 'El lead ya fue descartado con otro motivo o por otra persona'
      using errcode = 'P0002';
  end if;

  if v_lead.etapa = 'convertido' then
    raise exception 'Un lead convertido no se descarta' using errcode = 'P0002';
  end if;

  -- 5) UPDATE con CANDADO CAS: el predicado de tenencia y de etapa va TAMBIÉN
  --    aquí (no solo en el SELECT del paso 3) → la mutación se auto-defiende de
  --    la carrera aunque un refactor futuro debilite el FOR UPDATE.
  --    La nota se APPENDEA, jamás se pisa: el comentario del cliente no se
  --    pierde (regla dura de Miguel).
  update crm.leads
     set etapa = 'descartado',
         motivo_descarte = p_motivo,
         nota = case
                  when v_nota is null then nota
                  else coalesce(nullif(nota, '') || ' · ', '') || 'DESCARTE: ' || v_nota
                end
   where id = p_lead and activo = true
     and vendedor_id is null and asignado_supervisor_id is null
     and etapa not in ('descartado','convertido');
  if not found then
    raise exception 'El lead ya no está en la cola por repartir (carrera de descarte)'
      using errcode = 'P0002';
  end if;

  select * into v_lead from crm.leads where id = p_lead;

  return jsonb_build_object(
    'lead_id', p_lead,
    'motivo_descarte', v_lead.motivo_descarte,
    'clasificacion_auto', v_lead.clasificacion_auto,
    'descartado_por', v_lead.descartado_por,
    'descartado_en', v_lead.descartado_en,
    'ya_estaba', false);
end;

declare
  v_actor   uuid := (select auth.uid());
  v_ventana interval := interval '24 hours';
  v_lead    crm.leads%rowtype;
  v_veredicto jsonb;
  v_bloqueo jsonb;
  v_previo_reab text;
  v_flag_d13 boolean;
begin
  if v_actor is null or not exists (
    select 1 from crm.equipo ae
    join public.perfiles ap on ap.id = ae.perfil_id
    where ae.perfil_id = v_actor
      and ae.rol_crm in ('coordinador','gerencia')
      and ae.activo = true and ap.activo = true
  ) then
    raise exception 'Solo el coordinador puede deshacer un descarte'
      using errcode = '42501';
  end if;

  if p_lead is null then
    raise exception 'El lead es obligatorio' using errcode = '22023';
  end if;
  -- F2.b [D-5] (auditor v4 #1): la bandera se lee bajo el candado COMPARTIDO crm_flag_resolver_en_puertas (el cambio de
  -- bandera toma el exclusivo): esta llamada termina con la bandera que leyó, aunque espere por una fila.
  if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', pg_catalog.current_setting('transaction_isolation') using errcode = '0A000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  v_flag_d13 := coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false);

  -- F2.b [D-13]: candados de PERSONA antes de la fila (documento -> persona -> lead); inerte con la bandera apagada.
  v_bloqueo := private.bloquear_personas_de_leads(array[p_lead], null);
  select * into v_lead
  from crm.leads l
  where l.id = p_lead and l.activo = true
    and l.vendedor_id is null and l.asignado_supervisor_id is null
    and l.etapa = 'descartado'
    and l.descartado_por = v_actor
    and l.descartado_en > (statement_timestamp() - v_ventana)
  for update;
  if not found then
    raise exception 'Solo puedes deshacer tus propios descartes de las últimas 24 horas, y solo si el lead sigue sin dueño'
      using errcode = 'P0002';
  end if;
  -- F2.b (b2): gemela de rescatar_descartes: una persona vetada no se reabre.
  if private.persona_vetada(v_lead.id) then
    raise exception '%: no se puede reabrir', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;
  -- F2.b [D-13] (auditor M1 / Codex #6): gemela de rescatar_descartes: el JUICIO único de reapertura con la identidad encendida.
  if v_flag_d13 then
    if not private.lead_dentro_de_bloqueo(v_lead.id, v_bloqueo) then
      raise exception 'El documento o la persona de este lead cambió mientras se bloqueaba; vuelve a intentarlo' using errcode = '40001';
    end if;
    v_veredicto := private.juicio_reapertura(v_lead.id, v_lead.telefono, null);
    if v_veredicto->>'estado' = 'no_contactar' then
      raise exception '%: no se puede reabrir', 'La persona tiene la restricción «No insistir»' using errcode = 'P0429';
    end if;
    if v_veredicto is not null then
      raise exception 'La persona ya es cliente o ya tiene su lead: no se puede reabrir'
        using errcode = 'P0409', detail = pg_catalog.jsonb_build_object('estado', 'ya_es_cliente', 'via', 'identidad', 'lead_id', v_lead.id)::text;
    end if;
  end if;

  v_previo_reab := coalesce(pg_catalog.current_setting('crm.reapertura_identidad', true), 'off');
  perform pg_catalog.set_config('crm.reapertura_identidad', 'on', true);
  begin
    update crm.leads
       set etapa = 'nuevo', motivo_descarte = null
     where id = p_lead and activo = true and etapa = 'descartado'
       and vendedor_id is null and asignado_supervisor_id is null;
    if not found then
      raise exception 'El descarte ya no se puede deshacer (carrera)'
        using errcode = 'P0002';
    end if;
  exception
    when unique_violation then
      raise exception 'Ya existe otro lead vivo con ese mismo teléfono o documento: no se puede reabrir'
        using errcode = '22023';
  end;

  perform pg_catalog.set_config('crm.reapertura_identidad', v_previo_reab, true);
  -- F2.b [D-13]: el lead reabierto queda ENLAZADO a su persona (como al nacer), ya bloqueada FOR SHARE.
  if v_flag_d13 and v_lead.inversionista_id is null then
    perform private.enlazar_lead_reabierto(p_lead, private.lead_persona_reabrir(p_lead));
  end if;
  select * into v_lead from crm.leads where id = p_lead;

  return jsonb_build_object(
    'lead_id', p_lead,
    'etapa', v_lead.etapa,
    'ciclo_actual', v_lead.ciclo_actual,
    'reabierto_por', v_actor,
    'reabierto_en', statement_timestamp());
end;

declare v_previo text;
begin
  if p_inv is null or not private.resolver_en_puertas_bajo_candado() then
    return;
  end if;
  v_previo := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true), 'off');
  perform pg_catalog.set_config('crm.op_privilegiada', 'on', true);
  update crm.leads set inversionista_id = p_inv where id = p_lead_id and inversionista_id is null;
  update crm.inversionista_leads il set rol = 'canonico'
   where il.lead_id = p_lead_id and il.rol = 'historico'
     and not exists (select 1 from crm.inversionista_leads il2 where il2.inversionista_id = il.inversionista_id and il2.rol = 'canonico');
  perform pg_catalog.set_config('crm.op_privilegiada', v_previo, true);
end;

