declare
  v_texto text := coalesce(p_texto, '');
  v_normalizado text;
  v_resultado text;
  v_permitidos constant text[] := array[
    'a','accion','actividad','actualizar','agenda','agendar','algo','anular',
    'archivo','asistio','borrar','busco','buscar','cambiar','cancelar','capital',
    'cartera','celular','cerrar','cierre','cita','cliente','como','completar',
    'confirmar','confirmada','contactar','contacto','contrato','convertir','corregir',
    'crear','datos','descargar','descartar','dni','documento','donde','duplicado',
    'editar','el','eliminar','en','encontrar','error','es','esta','etapa','existe',
    'fallo','fecha','gestion','guardar','hacer','hice','historial','la','lead','llamada',
    'llamar','llego','lo','marcar','mover','no','nombre','nuevo','numero','ocupado',
    'pdf','pendiente','persona','plantado','por','programar','prospecto','propuesta',
    'proxima','quitar','que','recordatorio','registrar','reintentar','reprogramar',
    'resultado','reunion','sacar','siguiente','tarea','telefono','trabajar','venta',
    'whatsapp','ya','quiero','piicorreo','piinumero'
  ];
begin
  v_texto := regexp_replace(
    v_texto,
    '[[:alnum:]._%+\-]+@[[:alnum:].\-]+\.[[:alpha:]]{2,}',
    ' piicorreo ',
    'gi'
  );
  v_texto := regexp_replace(
    v_texto,
    '([0-9][[:space:].()\-]*){8,}',
    ' piinumero ',
    'g'
  );
  v_normalizado := private.normalizar_consulta_ayuda(v_texto);

  select string_agg(
    case
      when token = 'piicorreo' then '[correo]'
      when token = 'piinumero' then '[numero]'
      when token = any(v_permitidos) then token
      else '[otro]'
    end,
    ' ' order by orden
  )
  into v_resultado
  from unnest(regexp_split_to_array(v_normalizado, '[[:space:]]+'))
       with ordinality as t(token, orden)
  where token <> '';

  return coalesce(v_resultado, '');
end;

declare
  v_lead        crm.leads%rowtype;
  v_periodo     date;
  v_acreditado  uuid;
  v_referido    boolean;
  v_peso        numeric;
  v_numerador   numeric;
  v_n_episodios integer;
  v_periodo_episodio date;
  v_pen         numeric := 0;
  v_usd         numeric := 0;
  v_detalle     jsonb := '[]'::jsonb;
  v_id          uuid;
begin
  select * into v_lead from crm.leads where id = p_lead_id;
  if not found or v_lead.convertido_en is null then
    return null;
  end if;

  v_periodo := date_trunc('month', v_lead.convertido_en at time zone 'America/Lima')::date;

  -- ⚠️ EL CERROJO, antes de mirar si el mes esta cerrado. Sin el, una anulacion
  -- concurrente con el sellado de ESE mes lee «abierto» —porque el sello aun no
  -- ha commiteado—, devuelve NULL, y el cierre anulado se queda pagado para
  -- siempre. Misma clave que en `crm.cerrar_periodo`.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.periodos_cerrados'),
    (v_periodo - date '2000-01-01')::integer
  );

  -- Mes ABIERTO: no hay deuda que registrar. El mes se recalcula y el cierre
  -- desaparece de el, que es el comportamiento de siempre.
  if not exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_periodo) then
    return null;
  end if;

  -- A quien se le descuenta: el mismo acreditado que usa la cuota.
  v_acreditado := coalesce(
    (select ca.acreditado_a from crm.cierres_avance_anulados ca where ca.lead_id = p_lead_id),
    private.vendedor_acreditado_del_cierre(p_lead_id));
  if v_acreditado is null then
    -- Sin acreditado no hay a quien descontarle. No se inventa un deudor.
    return null;
  end if;

  -- Lo que valia el cierre en la conversion. El origen sale del LEDGER (la foto
  -- del episodio), no de `crm.leads.origen`, que es una columna viva.
  -- F6.c (v2, tras el P1 de Codex): EL EPISODIO MANDA. El cierre puede caer a
  -- caballo del mes (convertido_en usa now() de transaccion y el ledger
  -- statement_timestamp(), caso documentado): se localiza el episodio canonico
  -- del lead SIN depender del mes de leads.convertido_en, y de el salen el
  -- PERIODO real, el referido y el peso. Cero episodios => la sancion de
  -- conversion vale CERO (nunca 1 en silencio) y queda alerta; mas de uno =>
  -- excepcion de integridad (el ledger solo permite una conversion por lead).
  select count(*),
         coalesce(bool_or(e.fue_referido), false),
         min(date_trunc('month', (e.fecha_numerador at time zone 'America/Lima'))::date)
    into v_n_episodios, v_referido, v_periodo_episodio
  from private.conversion_episodios(
         '1900-01-01'::timestamptz, '2100-01-01'::timestamptz,
         null::date, true, '{}'::uuid[], 1) e
  where e.lead_id = p_lead_id and e.tipo = 'cierre';

  if v_n_episodios > 1 then
    raise exception 'Integridad: el lead % tiene % episodios de cierre en el ledger', p_lead_id, v_n_episodios;
  end if;
  if v_n_episodios = 1 and v_periodo_episodio is distinct from v_periodo then
    -- El mes REAL del cierre es el del episodio: el cerrojo y la foto del mes
    -- sellado se toman sobre ese periodo (se re-toma el candado por si acaso).
    v_periodo := v_periodo_episodio;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtext('crm.periodos_cerrados'),
      (v_periodo - date '2000-01-01')::integer);
    if not exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_periodo) then
      return null;
    end if;
  end if;
  if v_n_episodios = 0 then
    insert into private.vigia_alertas (fase, motivo)
    values ('f6c_ajuste_sin_episodio',
            format('lead %s: sin episodio de cierre en el ledger; la sancion de conversion vale 0', p_lead_id));
  end if;

  v_peso := private.peso_referido_conversion(v_periodo);
  v_numerador := case when v_n_episodios = 0 then 0
                       when v_referido then v_peso else 1 end;

  -- ATR-4 (Miguel 31/08): «solo la conversion, siempre». La deuda de un mes
  -- sellado ya NO carga capital: el capital del analista se queda en su
  -- produccion y el de la empresa en el AUM. Solo se descuenta la conversion.
  v_pen := 0; v_usd := 0; v_detalle := '[]'::jsonb;

  -- Con capital siempre 0, la deuda existe SOLO si la conversion valia algo.
  -- numerador 0 (cierre sin episodio) => NULL POR DISENO declarado: el rastro
  -- queda en la alerta del vigia (f6c_ajuste_sin_episodio) y en la anulacion
  -- misma; no se fabrica una deuda vacia.
  if v_numerador <= 0 and v_pen = 0 and v_usd = 0 then
    return null;
  end if;

  insert into crm.ajustes_mes_cerrado (
    vendedor_id, periodo_origen, lead_id, motivo, creado_por,
    numerador, capital_pen, capital_usd, detalle,
    pendiente_numerador, pendiente_pen, pendiente_usd, pendiente_detalle
  ) values (
    v_acreditado, v_periodo, p_lead_id, p_motivo, p_por,
    v_numerador, v_pen, v_usd, v_detalle,
    v_numerador, v_pen, v_usd, v_detalle
  )
  on conflict (lead_id) do nothing
  returning id into v_id;

  return v_id;
end;

declare
  v_detalle jsonb := coalesce(p_detalle, '{}'::jsonb);
begin
  if (select auth.uid()) is null or p_idempotencia is null then
    raise insufficient_privilege using message = 'Actor e idempotencia requeridos';
  end if;

  if pg_catalog.jsonb_typeof(v_detalle) <> 'object'
     or pg_catalog.octet_length(v_detalle::text) > 4096
     or lower(v_detalle::text) ~ '(password|contrase|token|secret|clave)' then
    raise exception 'Detalle de auditoria no permitido';
  end if;

  insert into crm.usuario_eventos (
    actor_id, objetivo_id, accion, detalle, idempotencia
  ) values (
    (select auth.uid()), p_objetivo_id, p_accion, v_detalle, p_idempotencia
  )
  on conflict (actor_id, accion, idempotencia) do nothing;
end;

declare
  v_actor      uuid := (select auth.uid());
  v_lead       crm.leads%rowtype;
  v_sup_nombre text;
begin
  if v_actor is null or not exists (
    select 1 from crm.equipo ae
    join public.perfiles ap on ap.id = ae.perfil_id
    where ae.perfil_id = v_actor
      and ae.rol_crm in ('coordinador','gerencia')
      and ae.activo = true and ap.activo = true
  ) then
    raise exception 'Solo el coordinador puede repartir leads' using errcode = '42501';
  end if;

  if p_lead is null or p_supervisor is null then
    raise exception 'Lead y supervisor destino son obligatorios' using errcode = '22023';
  end if;

  select p.nombre_completo into v_sup_nombre
  from crm.equipo e join public.perfiles p on p.id = e.perfil_id
  where e.perfil_id = p_supervisor
    and e.rol_crm = 'supervisor' and e.activo = true and p.activo = true;
  if not found then
    raise exception 'La bandeja destino no pertenece a un supervisor activo'
      using errcode = '22023';
  end if;

  select * into v_lead
  from crm.leads l
  where l.id = p_lead and l.activo = true
    and l.vendedor_id is null and l.asignado_supervisor_id is null
    and l.etapa in ('nuevo','contactado','reunion_agendada','propuesta_enviada')
  for update;
  if not found then
    raise exception 'El lead ya no está en la cola por repartir (tiene dueño, está cerrado o no existe)'
      using errcode = 'P0002';
  end if;

  if v_lead.no_contactar then
    raise exception 'Lead marcado No Insista (Ley 29571): no se puede repartir'
      using errcode = 'P0429';
  end if;
  -- F2.b (b2): el veto es de la PERSONA (contrato §7.3). Lectura sin lock tras el
  -- FOR UPDATE del lead: no altera el orden de locks.
  if private.persona_vetada(v_lead.id) then
    raise exception '%: no se puede repartir', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;

  update crm.leads
     set asignado_supervisor_id = p_supervisor
   where id = p_lead and activo = true
     and vendedor_id is null and asignado_supervisor_id is null;
  if not found then
    raise exception 'El lead ya no está en la cola por repartir (carrera de reparto)'
      using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'lead_id', p_lead,
    'asignado_supervisor_id', p_supervisor,
    'supervisor', v_sup_nombre,
    'repartido_por', v_actor,
    'repartido_en', statement_timestamp());
end;

declare
  v_aisl text := pg_catalog.current_setting('transaction_isolation');
begin
  -- F2.b [D-19]. Un solo sitio para el invariante «leer la bandera implica tener su candado».
  -- 1) READ COMMITTED obligatorio: bajo REPEATABLE READ o SERIALIZABLE la transacción vería una foto anterior al
  --    encendido aunque el candado la hubiese hecho esperar, que es justo el error que esto viene a impedir.
  if v_aisl <> 'read committed' then
    raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', v_aisl
      using errcode = '0A000';
  end if;
  -- 2) El COMPARTIDO del encendido. Es de transacción: una vez tomado, el valor no puede cambiar hasta el commit, y
  --    el UPDATE de la bandera (que toma el EXCLUSIVO por el trigger de D-5) espera a que esta llamada termine.
  --    Reentrante: tomarlo dos veces en la misma transacción no cuesta nada.
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
  -- 3) Y ahora sí, el valor.
  return coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false);
end;

declare
  v_pol      crm.politica_rentabilidad;
  v_cli      record;
  v_origen   public.contratos%rowtype;
  v_previos  integer;
  v_activos  integer;
  v_base     numeric;
  v_regla    text;
begin
  if p_cliente_id is null then
    raise exception 'El cliente es obligatorio' using errcode = '22023';
  end if;
  if p_categoria is null or p_categoria not in ('nuevo', 'renovacion', 'upgrade') then
    raise exception 'Selecciona la categoría del contrato (nuevo, renovacion o upgrade)' using errcode = '22023';
  end if;
  v_pol := private.politica_rentabilidad_vigente(p_instante);
  if v_pol.id is null then
    raise exception 'No hay política de rentabilidad vigente' using errcode = 'P0002';
  end if;
  select p.id, p.activo, p.asesor_perfil_id into v_cli
  from public.perfiles p where p.id = p_cliente_id and p.rol = 'cliente';
  if v_cli.id is null then
    raise exception 'Cliente no encontrado' using errcode = 'P0002';
  end if;
  if v_cli.activo is not true then
    raise exception 'El cliente está inactivo' using errcode = 'P0409';
  end if;
  -- «Previos» = los contratos del cliente sin contar el que se está observando (al commit, el nuevo ya existe).
  select count(*), count(*) filter (where c.estado = 'activo')
    into v_previos, v_activos
  from public.contratos c
  where c.cliente_id = p_cliente_id and not c.es_demo and c.id is distinct from p_contrato_nuevo_id;

  if p_categoria = 'nuevo' then
    if p_contrato_origen_id is not null then
      raise exception 'Una primera inversión no lleva contrato origen' using errcode = '22023';
    end if;
    v_base := v_pol.tasa_base_nueva;
    v_regla := 'primera_inversion';
  else
    if p_contrato_origen_id is null then
      raise exception 'Selecciona el contrato que se % (contrato origen)', case when p_categoria = 'renovacion' then 'renueva' else 'amplía' end
        using errcode = '22023';
    end if;
    select * into v_origen from public.contratos c where c.id = p_contrato_origen_id;
    if v_origen.id is null then
      raise exception 'El contrato origen no existe' using errcode = 'P0002';
    end if;
    if v_origen.cliente_id is distinct from p_cliente_id then
      raise exception 'El contrato origen pertenece a otro cliente' using errcode = 'P0409';
    end if;
    if p_categoria = 'renovacion' then
      -- Mismo criterio que public.crear_contrato: se renueva un contrato activo o vencido que aún no fue renovado…
      -- …salvo que ya haya quedado renovado POR ESTE contrato (observación al commit): sigue siendo su origen.
      -- IS NOT TRUE (no «NOT»): con renovado_a_id NULL la segunda alternativa es NULL y un «NOT NULL» dejaría pasar un
      -- origen retirado (Codex R2 #3). La segunda alternativa exige además estado 'renovado'.
      if (
           (v_origen.estado in ('activo', 'vencido') and v_origen.renovado_a_id is null)
        or (p_contrato_nuevo_id is not null and v_origen.estado = 'renovado' and v_origen.renovado_a_id = p_contrato_nuevo_id)
      ) is not true then
        raise exception 'El contrato origen ya fue cerrado o renovado (estado «%»)', v_origen.estado using errcode = 'P0409';
      end if;
      v_regla := 'heredada_renovacion';
    else
      -- D2: el upgrade amplía un contrato ACTIVO concreto que el analista selecciona.
      if v_origen.estado <> 'activo' or v_origen.renovado_a_id is not null then
        raise exception 'El upgrade solo amplía un contrato activo (este está «%»)', v_origen.estado using errcode = 'P0409';
      end if;
      v_regla := 'heredada_upgrade';
    end if;
    v_base := v_origen.tasa_anual;
  end if;

  return jsonb_build_object(
    'tasa_base', v_base,
    'regla', v_regla,
    'categoria', p_categoria,
    'cliente_id', p_cliente_id,
    'contrato_origen', case when v_origen.id is null then null else jsonb_build_object(
        'id', v_origen.id, 'numero_contrato', v_origen.numero_contrato, 'tasa_anual', v_origen.tasa_anual,
        'estado', v_origen.estado, 'moneda', v_origen.moneda, 'capital', v_origen.capital,
        'fecha_vencimiento', v_origen.fecha_vencimiento) end,
    'contratos_previos', v_previos,
    'contratos_activos', v_activos,
    'prioridad_bandeja', (p_categoria = 'nuevo' and v_previos > 0),
    'politica', jsonb_build_object('id', v_pol.id, 'version', v_pol.version, 'modo', v_pol.modo,
        'tasa_base_nueva', v_pol.tasa_base_nueva, 'tope_tecnico', v_pol.tope_tecnico,
        'vigencia_solicitud_dias', v_pol.vigencia_solicitud_dias),
    'resuelto_en', coalesce(p_instante, statement_timestamp())
  );
end;

declare
  v_loc record;
  v_row crm.multiempresa_idempotencia%rowtype;
  v_est jsonb;
  v_prev text;
begin
  select * into v_loc from private.saga_auth_localizar(p_claim_id);
  if not found then
    raise exception 'Saga: claim inexistente' using errcode = 'P0002';
  end if;
  select * into v_row from crm.multiempresa_idempotencia where clave = v_loc.clave for update;
  v_est := v_row.resultado;
  if v_est->>'token_hash' is distinct from private.saga_token_hash(p_token) then
    raise exception 'Saga: token inválido' using errcode = '42501';
  end if;
  if p_version is null then
    raise exception 'Saga: falta la versión del claim (CAS)' using errcode = '22023';
  end if;
  if v_row.version is distinct from p_version then
    raise exception 'Saga: el claim cambió (versión % ≠ %); vuelve a reclamar', v_row.version, p_version
      using errcode = '40001';
  end if;
  v_prev := v_est->>'estado';
  if not ((v_prev = 'reclamado' and p_estado = 'auth_creado' and p_auth_user_id is not null)
       or (v_prev = 'auth_creado' and p_estado = 'perfil_creado' and p_perfil_id is not null and p_perfil_id = (v_est->>'auth_user_id')::uuid)
       or (v_prev in ('auth_creado','perfil_creado') and p_estado = 'enlazado')
       or (v_prev = 'auth_creado' and p_estado = 'reclamado')   -- compensación: el Auth se borró tras fallar el perfil
       or (v_prev = p_estado                                      -- repetición idempotente: NUNCA reescribe auth/perfil (auditor b3 A1)
           and coalesce(p_auth_user_id, (v_est->>'auth_user_id')::uuid) is not distinct from (v_est->>'auth_user_id')::uuid
           and coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid) is not distinct from (v_est->>'perfil_id')::uuid)) then
    raise exception 'Saga: transición inválida % -> %', v_prev, p_estado using errcode = 'P0409';
  end if;
  -- Procedencia verificada EN SERVIDOR (Codex E2 #2): el Auth declarado debe existir y llevar la
  -- marca de ESTE claim en app_metadata; el perfil debe existir con id = auth_user_id.
  if p_estado = 'auth_creado' and v_prev = 'reclamado' then
    if not exists (select 1 from auth.users u where u.id = p_auth_user_id
                    and u.raw_app_meta_data->>'claim_id' = p_claim_id::text) then
      raise exception 'Saga: el usuario de Auth no existe o no lleva la marca de este claim' using errcode = 'P0409';
    end if;
  end if;
  if p_estado = 'perfil_creado' then
    if not exists (select 1 from public.perfiles p where p.id = p_perfil_id and p.rol = 'cliente') then
      raise exception 'Saga: el perfil declarado no existe' using errcode = 'P0409';
    end if;
  end if;
  if p_estado = 'enlazado' and (v_est->>'auth_user_id') is not null
     and coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid) is distinct from (v_est->>'auth_user_id')::uuid then
    raise exception 'Saga: el perfil enlazado debe ser el usuario de Auth de este claim' using errcode = 'P0409';
  end if;
  if p_estado = 'reclamado' then
    if exists (select 1 from auth.users u where u.id = (v_est->>'auth_user_id')::uuid) then
      raise exception 'Saga: no se puede compensar: el usuario de Auth sigue existiendo' using errcode = 'P0409';
    end if;
    v_est := v_est - 'auth_user_id' || pg_catalog.jsonb_build_object('auth_user_id', null);
    p_auth_user_id := null;
  end if;
  v_est := v_est || pg_catalog.jsonb_build_object('estado', p_estado,
    'auth_user_id', case when p_estado = 'reclamado' then null else coalesce(p_auth_user_id, (v_est->>'auth_user_id')::uuid) end,
    'perfil_id', coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid),
    'lease_hasta', pg_catalog.now() + interval '10 minutes', 'actualizado_en', pg_catalog.now());
  update crm.multiempresa_idempotencia set resultado = v_est, version = version + 1 where clave = v_loc.clave;
  return pg_catalog.jsonb_build_object('claim_id', p_claim_id, 'estado', p_estado, 'version', v_row.version + 1,
    'inversionista_id', v_loc.inversionista_id, 'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
end;

declare
  v_uid   uuid := (select auth.uid());
  v_clave text := 'auth_persona:' || p_inv::text;
  v_hash  text := private.idem_hash(coalesce(p_payload, '{}'::jsonb));
  v_token text := pg_catalog.encode(extensions.gen_random_bytes(24), 'hex');
  v_row   crm.multiempresa_idempotencia%rowtype;
  v_est   jsonb;
  v_claim uuid;
begin
  if p_inv is null or p_tipo not in ('alta_cliente','conversion') then
    raise exception 'Saga: identidad o tipo inválidos' using errcode = '22023';
  end if;
  select * into v_row from crm.multiempresa_idempotencia where clave = v_clave for update;
  if not found then
    v_claim := gen_random_uuid();
    v_est := pg_catalog.jsonb_build_object(
      'claim_id', v_claim, 'token_hash', private.saga_token_hash(v_token), 'tipo', p_tipo,
      'owner', v_uid, 'estado', 'reclamado', 'auth_user_id', null, 'perfil_id', null,
      'lead_id', p_lead_id, 'lease_hasta', pg_catalog.now() + interval '10 minutes',
      'creado_en', pg_catalog.now(), 'actualizado_en', pg_catalog.now());
    insert into crm.multiempresa_idempotencia (clave, tipo, hash_payload, resultado, creado_por)
    values (v_clave, p_tipo, v_hash, v_est, v_uid);
    return pg_catalog.jsonb_build_object('claim_id', v_claim, 'token', v_token, 'estado', 'reclamado',
      'version', 1, 'reanudar', false, 'inversionista_id', p_inv, 'auth_user_id', null, 'perfil_id', null);
  end if;
  v_est := v_row.resultado;
  if v_est->>'estado' = 'enlazado' then
    return pg_catalog.jsonb_build_object('claim_id', (v_est->>'claim_id')::uuid, 'token', null, 'estado', 'enlazado',
      'version', v_row.version, 'reanudar', true, 'inversionista_id', p_inv,
      'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
  end if;
  -- Reanudar SOLO con el token vigente (misma ejecución) o con el lease vencido. Compartir
  -- actor no basta: una segunda petición del mismo usuario no puede expulsar a la primera
  -- (Codex E2 #1). service_role (owner null) tampoco identifica un proceso.
  if (v_est->>'lease_hasta')::timestamptz > pg_catalog.now()
     and (p_token is null or v_est->>'token_hash' is distinct from private.saga_token_hash(p_token)) then
    raise exception 'Esta persona tiene un alta en curso; espera unos minutos'
      using errcode = 'P0409';
  end if;
  -- En 'reclamado' aún no existe nada externo: un payload distinto (correo corregido, etc.)
  -- REEMPLAZA la huella en vez de varar a la persona (auditor b3 A2). Desde 'auth_creado' el
  -- Auth y el perfil ya llevan los datos: un payload distinto es otra intención → P0409.
  if v_est->>'estado' <> 'reclamado' and v_row.hash_payload <> v_hash then
    raise exception 'La misma persona llegó con datos distintos; no se puede reintentar así'
      using errcode = 'P0409';
  end if;
  v_est := v_est || pg_catalog.jsonb_build_object('token_hash', private.saga_token_hash(v_token), 'owner', v_uid,
    'tipo', p_tipo, 'lead_id', coalesce(p_lead_id, (v_est->>'lead_id')::uuid),
    'lease_hasta', pg_catalog.now() + interval '10 minutes', 'actualizado_en', pg_catalog.now());
  update crm.multiempresa_idempotencia
     set resultado = v_est, version = version + 1,
         hash_payload = case when v_est->>'estado' = 'reclamado' then v_hash else hash_payload end,
         tipo = p_tipo
   where clave = v_clave;
  return pg_catalog.jsonb_build_object('claim_id', (v_est->>'claim_id')::uuid, 'token', v_token, 'estado', v_est->>'estado',
    'version', v_row.version + 1, 'reanudar', true, 'inversionista_id', p_inv,
    'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
end;

declare
  v_num numeric := greatest(coalesce(p_numerador_disponible, 0), 0);
  v_disp jsonb := jsonb_build_object('PEN', greatest(coalesce(p_pen_disponible, 0), 0),
                                     'USD', greatest(coalesce(p_usd_disponible, 0), 0));
  v_ap_num numeric := 0;
  v_ap jsonb := '{}'::jsonb;          -- clave "categoria|moneda" -> {capital, contratos}
  r record;
  b record;
  v_toma_num numeric;
  v_toma_cap numeric;
  v_toma_con integer;
  v_resto jsonb;
  v_clave text;
  v_prev jsonb;
  v_pen numeric;
  v_usd numeric;
begin
  -- Las deudas MAS VIEJAS primero: una de agosto no espera a que se salde una de
  -- octubre.
  for r in
    select * from crm.ajustes_mes_cerrado
    where vendedor_id = p_vendedor and saldado_en is null
    order by periodo_origen, creado_en
    for update
  loop
    v_toma_num := least(r.pendiente_numerador, v_num);
    v_num := v_num - v_toma_num;
    v_ap_num := v_ap_num + v_toma_num;

    -- El capital se descuenta CASILLA A CASILLA (categoria x moneda). Descontarlo
    -- de un total dejaria la cuota por categoria sin cuadrar con su propia suma,
    -- y —peor— antes ni siquiera se restaba: la deuda se daba por cobrada y el
    -- dinero se perdonaba en silencio.
    v_resto := '[]'::jsonb;
    for b in
      select (e->>'categoria') as categoria, (e->>'moneda') as moneda,
             coalesce((e->>'capital')::numeric, 0) as capital,
             coalesce((e->>'contratos')::int, 0) as contratos
      from jsonb_array_elements(coalesce(r.pendiente_detalle, '[]'::jsonb)) e
    loop
      v_toma_cap := least(b.capital, coalesce((v_disp->>b.moneda)::numeric, 0));
      -- Los contratos se descuentan en proporcion a lo que se pudo pagar: si se
      -- salda entero, se descuentan todos; si no, ninguno (un contrato no se
      -- parte por la mitad).
      v_toma_con := case when v_toma_cap >= b.capital then b.contratos else 0 end;

      if v_toma_cap > 0 then
        v_disp := jsonb_set(v_disp, array[b.moneda],
          to_jsonb(coalesce((v_disp->>b.moneda)::numeric, 0) - v_toma_cap));
        v_clave := b.categoria || '|' || b.moneda;
        v_prev := coalesce(v_ap->v_clave, jsonb_build_object('capital', 0, 'contratos', 0));
        v_ap := jsonb_set(v_ap, array[v_clave], jsonb_build_object(
          'capital', coalesce((v_prev->>'capital')::numeric, 0) + v_toma_cap,
          'contratos', coalesce((v_prev->>'contratos')::int, 0) + v_toma_con));
      end if;

      if b.capital - v_toma_cap > 0 then
        v_resto := v_resto || jsonb_build_array(jsonb_build_object(
          'categoria', b.categoria, 'moneda', b.moneda,
          'capital', b.capital - v_toma_cap,
          'contratos', b.contratos - v_toma_con));
      end if;
    end loop;

    select
      coalesce(sum((e->>'capital')::numeric) filter (where e->>'moneda' = 'PEN'), 0),
      coalesce(sum((e->>'capital')::numeric) filter (where e->>'moneda' = 'USD'), 0)
      into v_pen, v_usd
    from jsonb_array_elements(v_resto) e;

    update crm.ajustes_mes_cerrado
    set pendiente_numerador = r.pendiente_numerador - v_toma_num,
        pendiente_pen = v_pen,
        pendiente_usd = v_usd,
        pendiente_detalle = v_resto,
        saldado_en = case
          when (r.pendiente_numerador - v_toma_num) = 0 and v_pen = 0 and v_usd = 0
          then now() end
    where id = r.id;
  end loop;

  aplicado_numerador := v_ap_num;
  select
    coalesce(sum((v->>'capital')::numeric) filter (where split_part(k, '|', 2) = 'PEN'), 0),
    coalesce(sum((v->>'capital')::numeric) filter (where split_part(k, '|', 2) = 'USD'), 0)
    into aplicado_pen, aplicado_usd
  from jsonb_each(v_ap) as t(k, v);
  aplicado_pen := coalesce(aplicado_pen, 0);
  aplicado_usd := coalesce(aplicado_usd, 0);
  aplicado_detalle := coalesce((
    select jsonb_agg(jsonb_build_object(
      'categoria', split_part(k, '|', 1),
      'moneda', split_part(k, '|', 2),
      'capital', (v->>'capital')::numeric,
      'contratos', (v->>'contratos')::int))
    from jsonb_each(v_ap) as t(k, v)), '[]'::jsonb);
  return next;
end;

declare
  v_elemento jsonb;
  v_id uuid;
  v_analistas jsonb := '[]'::jsonb;
  v_bandejas jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_payload) <> 'object'
     or jsonb_typeof(p_payload->'analistas') <> 'array'
     or jsonb_typeof(p_payload#>'{por_repartir,bandejas}') <> 'array' then
    raise exception 'Contrato interno de distribucion inesperado'
      using errcode='55000';
  end if;

  for v_elemento in
    select elemento.value from jsonb_array_elements(p_payload->'analistas') elemento
  loop
    begin
      v_id := (v_elemento->>'analista_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'Identidad interna de distribucion invalida'
        using errcode='55000';
    end;
    if not coalesce(
      private.rol_crm(v_id) in ('vendedor','supervisor'),
      false
    ) then
      v_elemento := v_elemento || jsonb_build_object(
        'activo',false,
        'disponible_para_recibir',false
      );
    end if;
    v_analistas := v_analistas || jsonb_build_array(v_elemento);
  end loop;

  for v_elemento in
    select elemento.value
    from jsonb_array_elements(p_payload#>'{por_repartir,bandejas}') elemento
  loop
    begin
      v_id := (v_elemento->>'supervisor_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'Bandeja interna de distribucion invalida'
        using errcode='55000';
    end;
    if private.rol_crm(v_id) is distinct from 'supervisor' then
      v_elemento := v_elemento || jsonb_build_object('supervisor_activo',false);
    end if;
    v_bandejas := v_bandejas || jsonb_build_array(v_elemento);
  end loop;

  p_payload := jsonb_set(p_payload,'{analistas}',v_analistas,false);
  return jsonb_set(p_payload,'{por_repartir,bandejas}',v_bandejas,false);
end;

begin
  new.actualizado_en := now();
  return new;
end;

declare
  v_seq integer;
begin
  if p_anio is null or p_anio < 2000 or p_anio > 9999 then
    raise exception 'Año de contrato inválido' using errcode = '22023';
  end if;

  -- La pareja (namespace, año) permite concurrencia entre años y serializa
  -- solamente a quienes calculan el siguiente número del mismo año.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('public.contratos.numero_contrato'),
    p_anio
  );

  -- Solo el namespace automático AC-AAAA-(1..4 dígitos) participa del
  -- contador. Un número explícito malformado o con miles de dígitos jamás
  -- puede provocar overflow al convertir ni bloquear futuras altas.
  select coalesce(pg_catalog.max(
           pg_catalog.split_part(c.numero_contrato, '-', 3)::integer
         ), 0) + 1
    into v_seq
  from public.contratos c
  where c.numero_contrato ~ (
    '^AC-' || p_anio::text || '-[0-9]{1,4}$'
  );

  if v_seq > 9999 then
    raise exception 'Se agotó la numeración automática AC-% para el año %',
      p_anio, p_anio
      using errcode = '22003';
  end if;

  return 'AC-' || p_anio || '-' || pg_catalog.lpad(v_seq::text, 4, '0');
end;

declare v_actor uuid := (select auth.uid());
begin
  if v_actor is null or not exists (
    select 1 from crm.equipo ae
    join public.perfiles ap on ap.id = ae.perfil_id
    where ae.perfil_id = v_actor
      and ae.rol_crm in ('coordinador','gerencia')
      and ae.activo = true and ap.activo = true
  ) then
    raise exception 'Solo el coordinador puede ver los supervisores de reparto'
      using errcode = '42501';
  end if;

  return query
  select e.perfil_id, p.nombre_completo, e.activo,
         (select count(*)::int from crm.leads l
           where l.asignado_supervisor_id = e.perfil_id
             and l.vendedor_id is null and l.activo = true
             and l.etapa in ('nuevo','contactado','reunion_agendada','propuesta_enviada')
         ) as bandeja_pendiente
  from crm.equipo e
  join public.perfiles p on p.id = e.perfil_id
  where e.rol_crm = 'supervisor' and e.activo = true and p.activo = true
  order by p.nombre_completo;
end;

begin
  insert into crm.verificaciones_lead (verificado_por, telefono_consultado, dni_consultado, veredicto)
  values (
    p_actor,
    pg_catalog.left(coalesce(p_telefono_norm, p_telefono_tecleado, ''), 32),
    pg_catalog.left(p_dni, 16),
    p_veredicto ->> 'estado'
  );
  return p_veredicto;
end;

begin
  -- F2.b [D-3]: el veto de la persona bloquea el SEGUIMIENTO también en la ficha del cliente (contrato §7.3): los tipos
  -- de CONTACTO. Notas y reasignaciones entran. Writers internos (auth.uid NULL) y la válvula quedan fuera, como en leads.
  if (select auth.uid()) is null
     or coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false)
     or new.tipo not in ('llamada_realizada', 'llamada_no_contestada', 'whatsapp_enviado', 'whatsapp_recibido', 'reunion_realizada') then
    return new;
  end if;
  if private.persona_vetada_perfil(new.cliente_id) then
    raise exception '%: no se registra seguimiento', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;
  return new;
end;

declare
  v_contacto boolean;
  v_evento_en timestamptz:=statement_timestamp();
begin
  if new.lead_id is null or new.tipo not in (
    'llamada_realizada','llamada_no_contestada','whatsapp_enviado','whatsapp_recibido','reunion_realizada'
  ) then return null; end if;
  v_contacto:=new.tipo in ('llamada_realizada','whatsapp_recibido','reunion_realizada');
  perform set_config('crm.sla_writer','on',true);
  update crm.lead_sla_ciclos c set
    primera_gestion_en=coalesce(c.primera_gestion_en,v_evento_en),
    primer_contacto_en=case when v_contacto then coalesce(c.primer_contacto_en,v_evento_en)
      else c.primer_contacto_en end
  from crm.leads l
  where l.id=new.lead_id and c.lead_id=l.id and c.ciclo_n=l.ciclo_actual
    and (c.primera_gestion_en is null or (v_contacto and c.primer_contacto_en is null));

  -- El ledger de responsabilidad conserva sus propios hitos: una transferencia
  -- posterior no reasigna el trabajo del analista anterior ni obliga a releer
  -- timestamps de actividades controlables por el payload.
  update crm.lead_asignacion_sla_hitos h set
    primera_gestion_en=coalesce(h.primera_gestion_en,v_evento_en),
    primer_contacto_en=case when v_contacto
      then coalesce(h.primer_contacto_en,v_evento_en) else h.primer_contacto_en end
  from crm.lead_asignaciones a
  where a.id=h.lead_asignacion_id and a.lead_id=new.lead_id
    and a.analista_id=new.creado_por and a.finalizado_en is null
    and v_evento_en>=a.asignado_en
    and (h.primera_gestion_en is null or (v_contacto and h.primer_contacto_en is null));
  perform set_config('crm.sla_writer','off',true);
  return null;
end;

begin
  raise exception 'La tabla del tope no se vacia.' using errcode = '42501';
end;

begin
  -- El trinquete no se burla borrando y volviendo a insertar la fila.
  if tg_op = 'DELETE' then
    raise exception 'La fila del tope no se borra: borrarla y reinsertarla reiniciaria el trinquete.'
      using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.tope > old.tope then
    raise exception 'El tope de puertas sin vigencia solo puede BAJAR (% -> %). Subirlo es una decision de negocio, no un ajuste.', old.tope, new.tope
      using errcode = '42501';
  end if;
  new.actualizado_en := now();
  return new;
end;

begin
  raise exception 'Una exencion no se borra por fuera: se retira en una migracion que re-selle la lista.' using errcode = '42501';
  return null;
end;

begin
  raise exception 'La tabla del tope no se vacia.' using errcode = '42501';
end;

begin
  if tg_op = 'DELETE' then
    raise exception 'La fila del tope no se borra: borrarla y reinsertarla reiniciaria el trinquete.' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.tope > old.tope then
    raise exception 'El tope de contadores crudos solo puede BAJAR (% -> %).', old.tope, new.tope using errcode = '42501';
  end if;
  new.actualizado_en := now();
  return new;
end;

begin
  raise exception 'El archivo legacy de metas es inmutable' using errcode='55000';
end;

begin
  raise exception using
    errcode = 'P0409',
    message = 'Un mes cerrado no se edita ni se borra',
    hint    = 'Por diseno: lo que haya que corregir de un mes pagado se descuenta en el mes vivo, no se reescribe el mes.';
end;

begin
  raise exception using
    errcode = 'P0409',
    message = 'Una anulacion de cierre no se edita ni se borra',
    hint    = 'Es de una sola direccion por diseno: si se pudiera deshacer, el cierre anulado volveria a acreditar sin rastro.';
end;

declare
  v_priv boolean := coalesce(current_setting('crm.op_privilegiada', true) = 'on', false);
begin
  if tg_op = 'DELETE' then
    raise exception using
      errcode = 'P0409',
      message = 'Un cierre externo no se elimina: gerencia lo corrige via crm.corregir_cierre_externo',
      hint    = 'El cierre respalda una conversion ya contada; borrar la fila dejaria un convertido sin perfil ni cierre (invariante P4).';
  end if;

  if not v_priv then
    raise exception using
      errcode = 'P0409',
      message = 'Un cierre externo solo se corrige via crm.corregir_cierre_externo',
      detail  = pg_catalog.format('cierre %s (lead %s)', old.id, old.lead_id);
  end if;

  -- Con la válvula encendida, las columnas de identidad se restauran en
  -- silencio (no con excepción): la RPC de corrección no las manda, así que
  -- esto es un cinturón contra bugs futuros de rutas DEFINER, no una rama que
  -- un usuario pueda pisar.
  new.id := old.id;
  new.lead_id := old.lead_id;
  new.vendedor_id := old.vendedor_id;
  new.documento_tipo := old.documento_tipo;
  new.documento := old.documento;
  new.nombre_completo := old.nombre_completo;
  new.creado_por := old.creado_por;
  new.creado_en := old.creado_en;

  -- La anulación es de UNA SOLA DIRECCIÓN. Des-anular sería volver a pagar un
  -- cierre que ya se declaró falso, y eso no se hace en silencio desde una ruta
  -- DEFINER: aquí se restaura y punto. (Aquí SÍ con excepción y no en silencio:
  -- si una RPC futura intentara resucitar un cierre anulado, el error tiene que
  -- salir a la superficie, no perderse en un 200 mudo.)
  if old.anulado_en is not null
     and (new.anulado_en is null
          or new.anulado_por is distinct from old.anulado_por
          or new.anulado_en is distinct from old.anulado_en) then
    raise exception using
      errcode = 'P0409',
      message = 'Un cierre externo anulado no se restablece',
      detail  = pg_catalog.format('cierre %s (lead %s), anulado el %s',
                                  old.id, old.lead_id, old.anulado_en);
  end if;
  return new;
end;

declare
  v_responsable uuid := coalesce(new.asesor_perfil_id, old.asesor_perfil_id);
  v_anterior text;
  v_nuevo text;
  v_detalle text;
begin
  if new.rol <> 'cliente'
     or new.asesor_perfil_id is not distinct from old.asesor_perfil_id then
    return new;
  end if;

  select p.nombre_completo
    into v_anterior
  from public.perfiles p
  where p.id = old.asesor_perfil_id;

  select p.nombre_completo
    into v_nuevo
  from public.perfiles p
  where p.id = new.asesor_perfil_id;

  if v_responsable is not null
     and not exists (
       select 1
       from crm.equipo e
       where e.perfil_id = v_responsable
     ) then
    v_responsable := null;
  end if;

  v_detalle := case
    when old.asesor_perfil_id is null then
      format('Cliente asignado a Analista: %s.', coalesce(v_nuevo, 'no disponible'))
    when new.asesor_perfil_id is null then
      format('Cliente quedó sin Analista. Analista anterior: %s.', coalesce(v_anterior, 'no disponible'))
    else
      format(
        'Asignación actualizada. Analista anterior: %s. Analista actual: %s.',
        coalesce(v_anterior, 'no disponible'),
        coalesce(v_nuevo, 'no disponible')
      )
  end;

  insert into crm.actividades_cliente (
    cliente_id,
    vendedor_id,
    tarea_id,
    tipo,
    detalle,
    creado_por
  ) values (
    new.id,
    v_responsable,
    null,
    'reasignacion',
    v_detalle,
    (select auth.uid())
  );

  return new;
end;

declare
  v_equipo crm.equipo%rowtype;
begin
  if new.rol <> 'cliente'
     or new.asesor_perfil_id is not distinct from old.asesor_perfil_id then
    return new;
  end if;
  if new.asesor_perfil_id is null then
    perform set_config('crm.cancela_sistema', 'on', true);
    update crm.tareas t set estado = 'cancelada'
    where t.perfil_id = new.id and t.activo and t.estado = 'pendiente';
    perform set_config('crm.cancela_sistema', 'off', true);
    return new;
  end if;
  select * into v_equipo from crm.equipo e
  where e.perfil_id = new.asesor_perfil_id and e.activo
    and e.rol_crm in ('vendedor','supervisor');
  if not found then
    raise exception 'El nuevo asesor no está activo en el CRM' using errcode = '22023';
  end if;
  update crm.tareas t
     set vendedor_id = new.asesor_perfil_id,
         asignado_supervisor_id = case
           when v_equipo.rol_crm = 'vendedor' then v_equipo.supervisor_id else null
         end
   where t.perfil_id = new.id and t.activo and t.estado = 'pendiente';
  return new;
end;

begin
  if tg_op in ('UPDATE', 'DELETE') then
    raise exception 'La configuracion publicada es inmutable; publica una nueva revision'
      using errcode = '55000';
  end if;
  return new;
end;

begin
  if not exists (
    select 1
    from public.contratos ct
    join crm.cuentas_bancarias cb
      on cb.id = new.cuenta_bancaria_id
     and cb.cliente_id = ct.cliente_id
     and cb.moneda = ct.moneda
    where ct.id = new.contrato_id
  ) then
    raise exception using
      errcode = '23514',
      message = 'La cuenta bancaria no pertenece al cliente o a la moneda del contrato';
  end if;
  return new;
end;

begin
  if row(new.id, new.contrato_id, new.cuenta_bancaria_id, new.creado_en)
     is distinct from
     row(old.id, old.contrato_id, old.cuenta_bancaria_id, old.creado_en) then
    raise exception using
      errcode = '22023',
      message = 'La cuenta de pago del contrato es historica y no se reemplaza';
  end if;
  if new.creado_por is distinct from old.creado_por
     and not (
       new.creado_por is null
       and old.creado_por is not null
       and not exists (select 1 from public.perfiles p where p.id = old.creado_por)
     ) then
    raise exception using errcode = '22023', message = 'La autoria del enlace bancario es inmutable';
  end if;
  return new;
end;

begin
  if new.categoria in ('renovacion', 'upgrade') and not exists (
    select 1 from crm.operaciones_cartera o where o.contrato_nuevo_id = new.id
  ) then
    raise exception using
      errcode = '23514',
      message = 'Una renovación o upgrade debe registrarse por el flujo de cartera';
  end if;
  return null;
end;

declare
  v_por_la_puerta boolean :=
    coalesce(current_setting('crm.reasignando_analista', true) = 'on', false);
begin
  if new.analista_cierre_id is distinct from old.analista_cierre_id
     and not v_por_la_puerta then
    raise exception using
      errcode = 'P0409',
      message = 'La atribucion de una venta solo se cambia con public.reasignar_analista_contrato',
      hint    = 'Hace falta un motivo escrito: mover el merito de una persona a otra no se hace en silencio.';
  end if;
  return new;
end;

begin
  if new.es_demo
     and not coalesce(current_setting('crm.marcando_demo', true) = 'on', false) then
    raise exception using
      errcode = 'P0409',
      message = 'Un contrato no nace marcado como prueba: se marca despues con public.marcar_contrato_demo';
  end if;
  return new;
end;

declare
  v_por_la_puerta boolean :=
    coalesce(current_setting('crm.marcando_demo', true) = 'on', false);
begin
  if new.es_demo is distinct from old.es_demo and not v_por_la_puerta then
    raise exception using
      errcode = 'P0409',
      message = 'La marca de prueba solo se cambia con public.marcar_contrato_demo',
      hint    = 'Marcar un contrato como prueba lo saca de todas las metricas y del sello mensual: eso exige motivo escrito y autoridad de gerencia.';
  end if;
  return new;
end;

declare
  v_c          public.contratos%rowtype;   -- el estado FINAL de la fila al commit (no la imagen del evento; Codex R2 #4)
  v_xid        text := pg_current_xact_id()::text;
  v_marca      text := 'crm.r2_obs_' || replace(new.id::text, '-', '');   -- GUC transaccional: «este contrato ya se procesó en esta tx»
  v_pol        crm.politica_rentabilidad;
  v_prev       record;
  v_prev_id    uuid;
  v_conservada boolean := false;
  v_pol_id     uuid;
  v_origen     uuid;
  v_candidatos integer := 0;
  v_cand_id    uuid;
  v_cand_num   text;
  v_cand_tasa  numeric;
  v_res        jsonb;
  v_base       numeric;
  v_regla      text;
  v_motivo     text;
  v_cambios    jsonb;
  v_detalle    jsonb;
begin
 -- TODO el cuerpo va bajo una excepción externa: el observador no puede abortar un alta ni una corrección. lock_timeout=2s
 -- convierte una espera de candado en 55P03 (atrapable). Lo único que WHEN OTHERS no atrapa es query_canceled (57014):
 -- en PostgreSQL 17 statement_timeout se desactiva antes del commit, y aquí no hay más esperas que las de candado.
 begin
  select * into v_c from public.contratos c where c.id = new.id;
  if v_c.id is null then
    return null;   -- borrado en la misma transacción: nada que observar
  end if;
  -- UNA observación por contrato y transacción: varios eventos (alta + correcciones en la misma tx) → una sola foto FINAL.
  -- El marcador es un GUC transaccional (se fija también cuando el cambio neto es vacío: 15→18→15 no es una corrección; Codex R2 #25).
  -- Límite declarado: si un cliente ejecutara SET CONSTRAINTS … IMMEDIATE a mitad de transacción, la foto sería la de ese
  -- momento (nadie lo hace en el proyecto; Codex R2 #19).
  if coalesce(current_setting(v_marca, true), '') = '1' then
    return null;
  end if;
  perform set_config(v_marca, '1', true);
  if tg_op = 'UPDATE' then
    -- Solo si cambió algo que determine la regla o el margen (Codex R2 #5), comparando la imagen previa con el estado final.
    v_cambios := jsonb_strip_nulls(jsonb_build_object(
      'tasa_anual',        case when old.tasa_anual        is distinct from v_c.tasa_anual        then jsonb_build_array(old.tasa_anual, v_c.tasa_anual) end,
      'categoria',         case when old.categoria         is distinct from v_c.categoria         then jsonb_build_array(old.categoria, v_c.categoria) end,
      'cliente_id',        case when old.cliente_id        is distinct from v_c.cliente_id        then jsonb_build_array(old.cliente_id, v_c.cliente_id) end,
      'capital',           case when old.capital           is distinct from v_c.capital           then jsonb_build_array(old.capital, v_c.capital) end,
      'moneda',            case when old.moneda            is distinct from v_c.moneda            then jsonb_build_array(old.moneda, v_c.moneda) end,
      'fecha_inicio',      case when old.fecha_inicio      is distinct from v_c.fecha_inicio      then jsonb_build_array(old.fecha_inicio, v_c.fecha_inicio) end,
      'fecha_vencimiento', case when old.fecha_vencimiento is distinct from v_c.fecha_vencimiento then jsonb_build_array(old.fecha_vencimiento, v_c.fecha_vencimiento) end));
    if v_cambios = '{}'::jsonb then
      return null;
    end if;
  end if;
  v_pol := private.politica_rentabilidad_vigente(statement_timestamp());
  if v_pol.id is null then
    return null;   -- sin política publicada no se observa (R1 garantiza la v1)
  end if;

  -- En una CORRECCIÓN que no cambia cliente ni categoría, la base de comparación es la RESOLUCIÓN ORIGINAL del alta
  -- (base, regla, origen), no una reevaluación con el estado de hoy (Codex R2 #8). Si cambió cliente o categoría, se resuelve de nuevo.
  v_pol_id := v_pol.id;
  if tg_op = 'UPDATE' and not (v_cambios ? 'categoria' or v_cambios ? 'cliente_id') then
    -- Solo se conserva una resolución del MISMO cliente y la MISMA categoría (Codex R2 #20), con la política que la produjo (#21).
    select l.tasa_base, l.regla, l.contrato_origen_id, l.politica_id, l.id, l.detalle ->> 'motivo' as motivo into v_prev
    from crm.ledger_rentabilidad l
    where l.contrato_id = v_c.id and l.origen = 'observacion'
      and l.categoria = v_c.categoria and l.cliente_id = v_c.cliente_id
    order by l.secuencia asc limit 1;
    if v_prev.regla is not null then
      -- Se conserva la resolución original… y también su INCERTIDUMBRE (Codex #8): un sin_regla no se «resuelve» al corregir.
      v_regla := v_prev.regla; v_origen := v_prev.contrato_origen_id; v_pol_id := v_prev.politica_id; v_prev_id := v_prev.id; v_conservada := true;
      if v_prev.regla = 'sin_regla' then
        v_base := v_c.tasa_anual; v_motivo := coalesce(v_prev.motivo, 'sin_motivo');
      else
        v_base := v_prev.tasa_base;
      end if;
    end if;
  end if;

  if not v_conservada then
    begin
      if v_c.categoria is null then
        v_regla := 'sin_regla'; v_base := v_c.tasa_anual; v_motivo := 'categoria_nula';
      elsif v_c.categoria = 'renovacion' then
        select o.contrato_origen_id into v_origen from crm.operaciones_cartera o where o.contrato_nuevo_id = v_c.id;
        if v_origen is null then
          v_regla := 'sin_regla'; v_base := v_c.tasa_anual; v_motivo := 'renovacion_sin_origen_registrado';
        else
          v_res := private.resolver_tasa(v_c.cliente_id, v_c.categoria, v_origen, statement_timestamp(), v_c.id);
          v_base := (v_res ->> 'tasa_base')::numeric; v_regla := v_res ->> 'regla';
        end if;
      elsif v_c.categoria = 'upgrade' then
        -- D2 exige que el analista SELECCIONE el origen (R3). Hoy la puerta no lo registra: el observador solo apunta el
        -- candidato cuando es único —contrato activo del cliente que ya EXISTÍA antes y seguía vigente al inicio del
        -- nuevo— y lo deja como sin_regla (una inferencia es una hipótesis, no una regla; Codex R2 #7).
        select count(*), min(c.id::text)::uuid into v_candidatos, v_origen
        from public.contratos c
        where c.cliente_id = v_c.cliente_id and c.id <> v_c.id and c.estado = 'activo' and c.renovado_a_id is null
          and not c.es_demo and c.creado_en < v_c.creado_en and c.fecha_vencimiento >= v_c.fecha_inicio;
        if v_candidatos = 1 then
          select c.id, c.numero_contrato, c.tasa_anual into v_cand_id, v_cand_num, v_cand_tasa from public.contratos c where c.id = v_origen;
          v_regla := 'sin_regla'; v_base := v_c.tasa_anual; v_motivo := 'upgrade_origen_inferido';
        else
          v_origen := null; v_regla := 'sin_regla'; v_base := v_c.tasa_anual;
          v_motivo := case when v_candidatos = 0 then 'upgrade_sin_contrato_activo_previo' else 'upgrade_origen_ambiguo' end;
        end if;
        v_origen := null;   -- sin origen DEMOSTRADO no se anota como origen; el candidato va en detalle
      else
        v_res := private.resolver_tasa(v_c.cliente_id, v_c.categoria, null, statement_timestamp(), v_c.id);
        v_base := (v_res ->> 'tasa_base')::numeric; v_regla := v_res ->> 'regla';
      end if;
    exception when others then
      -- El núcleo no pudo decidir (cliente inactivo, origen raro…): se anota, no se bloquea.
      v_regla := 'sin_regla'; v_base := v_c.tasa_anual;
      v_motivo := 'resolver:' || sqlstate || ':' || left(sqlerrm, 160);
      v_res := null; v_origen := null;
    end;
  end if;

  v_detalle := jsonb_strip_nulls(jsonb_build_object(
    'xid', v_xid, 'evento', tg_op,
    'capital', v_c.capital, 'moneda', v_c.moneda,
    'fecha_inicio', v_c.fecha_inicio, 'fecha_vencimiento', v_c.fecha_vencimiento,
    'plazo_dias', (v_c.fecha_vencimiento - v_c.fecha_inicio),
    'analista_cierre_id', v_c.analista_cierre_id, 'creado_por', v_c.creado_por,
    'es_demo', v_c.es_demo, 'estado', v_c.estado, 'operacion', tg_op,
    'tasa_anterior', case when tg_op = 'UPDATE' then old.tasa_anual end,
    'cambios', case when tg_op = 'UPDATE' then v_cambios end,
    'base_conservada', case when v_conservada then true end,
    'observacion_base_id', v_prev_id,
    'politica_vigente_al_observar', v_pol.version,
    'motivo', v_motivo,
    'candidato_origen', case when v_cand_id is null then null else jsonb_build_object('id', v_cand_id, 'numero_contrato', v_cand_num, 'tasa_anual', v_cand_tasa) end,
    'politica_version', (select pp.version from crm.politica_rentabilidad pp where pp.id = v_pol_id),
    'resolucion', case when v_res is null then null else v_res - 'politica' - 'cliente_id' - 'categoria' end
  ));
  begin
    insert into crm.ledger_rentabilidad (
      contrato_id, numero_contrato, cliente_id, categoria, contrato_origen_id, politica_id, solicitud_id,
      tasa_base, tasa_final, tasa_recibida, regla, origen, actor_id, detalle
    ) values (
      v_c.id, v_c.numero_contrato, v_c.cliente_id, v_c.categoria, v_origen, v_pol_id, null,
      v_base, v_c.tasa_anual, v_c.tasa_anual, v_regla, 'observacion', (select auth.uid()), v_detalle
    );
  exception when others then
    raise warning 'RENTABILIDAD R2: no se pudo observar el contrato % (% %)', v_c.id, sqlstate, sqlerrm;
  end;
  return null;
 exception when others then
  raise warning 'RENTABILIDAD R2: el observador falló y se ignora (% %) en el contrato %', sqlstate, sqlerrm, new.id;
  return null;
 end;
end;

declare
  v_solicitada_text text := nullif(
    current_setting('crm.producto_condicion_id', true), ''
  );
  v_producto_id uuid;
  v_producto_estado text;
  v_version_estado text;
  v_vigente_desde date;
  v_vigente_hasta date;
  v_condicion_activa boolean;
  v_es_legacy boolean;
  v_legacy_contrato_id uuid;
  v_categoria text;
  v_moneda text;
  v_plazo integer;
  v_modalidad text;
  v_tipo_interes text;
  v_capital_min numeric;
  v_capital_max numeric;
  v_tasa_min numeric;
  v_tasa_max numeric;
  v_fecha_inicio_legacy date;
  v_fecha_vencimiento_legacy date;
  v_old_es_legacy boolean;
  v_terminos_legacy_coinciden boolean;
  v_terminos_cambiaron boolean := false;
begin
  if v_solicitada_text is not null then
    begin
      new.producto_condicion_id := v_solicitada_text::uuid;
    exception when invalid_text_representation then
      raise exception 'Condición de producto inválida'
        using errcode = '22023';
    end;
  end if;

  if tg_op = 'UPDATE'
     and new.producto_condicion_id is null
     and old.producto_condicion_id is not null then
    select c.es_legacy into v_old_es_legacy
    from crm.producto_condiciones c
    where c.id = old.producto_condicion_id;
    if not coalesce(v_old_es_legacy, false) then
      raise exception 'Un contrato catalogado no puede perder su producto'
        using errcode = '23514';
    end if;
  end if;

  if new.producto_condicion_id is null then
    if tg_op = 'INSERT' and not exists (
      select 1
      from crm.productos_inversion p
      where p.es_legacy and p.permite_altas_legacy
    ) then
      raise exception 'Selecciona un producto de inversión publicado'
        using errcode = '23514';
    end if;
    new.producto_condicion_id := private.crear_snapshot_producto_legacy(
      new.id, new.categoria, new.moneda, new.modalidad, new.tipo_interes,
      new.capital, new.tasa_anual, new.fecha_inicio, new.fecha_vencimiento
    );
  end if;

  select v.producto_id, c.es_legacy into v_producto_id, v_es_legacy
  from crm.producto_condiciones c
  join crm.producto_versiones v on v.id = c.version_id
  where c.id = new.producto_condicion_id;
  if not found then
    raise exception 'Condición de producto no encontrada'
      using errcode = '23503';
  end if;

  -- Mismo orden de locks que publicar/archivar: producto -> versión. Las
  -- correcciones legacy toman el lock exclusivo desde el inicio porque crear
  -- su nueva versión serializa numero_version sobre el producto técnico.
  if v_es_legacy then
    perform 1
    from crm.productos_inversion p
    where p.id = v_producto_id
    for update;
  else
    perform 1
    from crm.productos_inversion p
    where p.id = v_producto_id
    for share;
  end if;

  select
    p.estado, v.estado, v.vigente_desde, v.vigente_hasta,
    c.activa, c.es_legacy, c.legacy_contrato_id,
    c.categoria, c.moneda, c.plazo_meses, c.modalidad, c.tipo_interes,
    c.capital_minimo, c.capital_maximo, c.tasa_minima, c.tasa_maxima,
    c.fecha_inicio_legacy, c.fecha_vencimiento_legacy
  into
    v_producto_estado, v_version_estado, v_vigente_desde, v_vigente_hasta,
    v_condicion_activa, v_es_legacy, v_legacy_contrato_id,
    v_categoria, v_moneda, v_plazo, v_modalidad, v_tipo_interes,
    v_capital_min, v_capital_max, v_tasa_min, v_tasa_max,
    v_fecha_inicio_legacy, v_fecha_vencimiento_legacy
  from crm.producto_condiciones c
  join crm.producto_versiones v on v.id = c.version_id
  join crm.productos_inversion p on p.id = v.producto_id
  where c.id = new.producto_condicion_id
  for share of v, c;

  if v_es_legacy then
    if v_legacy_contrato_id is distinct from new.id then
      raise exception 'Un snapshot histórico no puede reutilizarse en otro contrato'
        using errcode = '23514';
    end if;

    if tg_op = 'UPDATE'
       and old.producto_condicion_id is not null
       and new.producto_condicion_id is distinct from old.producto_condicion_id then
      raise exception 'Una corrección histórica debe partir del snapshot vigente del contrato'
        using errcode = '23514';
    end if;

    v_terminos_legacy_coinciden :=
      v_categoria is not distinct from new.categoria
      and v_moneda is not distinct from new.moneda
      and v_modalidad is not distinct from new.modalidad
      and v_tipo_interes is not distinct from new.tipo_interes
      and v_capital_min is not distinct from new.capital
      and v_capital_max is not distinct from new.capital
      and v_tasa_min is not distinct from new.tasa_anual
      and v_tasa_max is not distinct from new.tasa_anual
      and v_fecha_inicio_legacy is not distinct from new.fecha_inicio
      and v_fecha_vencimiento_legacy is not distinct from new.fecha_vencimiento;

    if not v_terminos_legacy_coinciden then
      if tg_op = 'UPDATE'
         and new.producto_condicion_id is not distinct from old.producto_condicion_id then
        -- Tanto el caller legacy como los wrappers vigentes conservan el
        -- snapshot actual durante el UPDATE. Si cambian los términos, se crea
        -- otro snapshot retirado en vez de reescribir o reutilizar historia.
        new.producto_condicion_id := private.crear_snapshot_producto_legacy(
          new.id, new.categoria, new.moneda, new.modalidad, new.tipo_interes,
          new.capital, new.tasa_anual, new.fecha_inicio, new.fecha_vencimiento
        );
      else
        raise exception 'El snapshot histórico no coincide con los términos del contrato'
          using errcode = '23514';
      end if;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_terminos_cambiaron :=
      new.categoria is distinct from old.categoria
      or new.moneda is distinct from old.moneda
      or new.modalidad is distinct from old.modalidad
      or new.tipo_interes is distinct from old.tipo_interes
      or new.capital is distinct from old.capital
      or new.tasa_anual is distinct from old.tasa_anual
      or new.fecha_inicio is distinct from old.fecha_inicio
      or new.fecha_vencimiento is distinct from old.fecha_vencimiento;
  end if;

  -- Una selección nueva exige catálogo vigente. Un contrato ya vinculado puede
  -- conservar/corregir su snapshot aunque después se publique v2 o se archive.
  if tg_op = 'INSERT'
     or new.producto_condicion_id is distinct from old.producto_condicion_id
     or v_terminos_cambiaron then
    if not v_condicion_activa
       or v_producto_estado <> 'activo'
       or v_version_estado <> 'publicada'
       or v_vigente_desde > current_date
       or (v_vigente_hasta is not null and v_vigente_hasta < current_date) then
      raise exception 'La condición no está publicada y vigente para contratos nuevos'
        using errcode = '23514';
    end if;
  end if;

  if new.categoria is distinct from v_categoria
     or new.moneda is distinct from v_moneda
     or new.modalidad is distinct from v_modalidad
     or new.tipo_interes is distinct from v_tipo_interes
     or new.capital < v_capital_min or new.capital > v_capital_max
     or new.tasa_anual < v_tasa_min or new.tasa_anual > v_tasa_max
     or new.fecha_vencimiento is distinct from
       (new.fecha_inicio + make_interval(months => v_plazo))::date then
    raise exception 'Los términos del contrato no cumplen la condición seleccionada'
      using errcode = '23514';
  end if;

  return new;
end;

begin
  if row(
    new.id, new.cliente_id, new.moneda, new.banco, new.tipo_cuenta,
    new.numero_cuenta, new.cci, new.titular_distinto,
    new.beneficiario_nombre, new.beneficiario_dni,
    new.origen, new.creado_en
  ) is distinct from row(
    old.id, old.cliente_id, old.moneda, old.banco, old.tipo_cuenta,
    old.numero_cuenta, old.cci, old.titular_distinto,
    old.beneficiario_nombre, old.beneficiario_dni,
    old.origen, old.creado_en
  ) then
    raise exception using
      errcode = '22023',
      message = 'Los datos de una cuenta bancaria son historicos; registra una cuenta nueva';
  end if;

  -- La unica excepcion de autoria es el SET NULL de su FK cuando el perfil
  -- autor fue eliminado. No es una correccion de negocio y evita que el trigger
  -- convierta el ON DELETE SET NULL declarado arriba en una promesa falsa.
  if new.creado_por is distinct from old.creado_por
     and not (
       new.creado_por is null
       and old.creado_por is not null
       and not exists (select 1 from public.perfiles p where p.id = old.creado_por)
     ) then
    raise exception using errcode = '22023', message = 'La autoria de la cuenta es inmutable';
  end if;

  if old.activa = false and new.activa = true then
    raise exception using
      errcode = '22023',
      message = 'Una version bancaria historica no se reactiva; registra una cuenta nueva';
  end if;

  if old.activa = true and new.activa = false then
    if new.desactivada_en is null then
      raise exception using errcode = '22023', message = 'Falta el sello de desactivacion de la cuenta';
    end if;
  elsif new.activa is distinct from old.activa
     or new.desactivada_en is distinct from old.desactivada_en then
    raise exception using errcode = '22023', message = 'Cambio de estado bancario invalido';
  elsif new.desactivada_por is distinct from old.desactivada_por
     and not (
       new.desactivada_por is null
       and old.desactivada_por is not null
       and not exists (select 1 from public.perfiles p where p.id = old.desactivada_por)
     ) then
    raise exception using errcode = '22023', message = 'La autoria de desactivacion es inmutable';
  end if;

  return new;
end;

begin
  raise exception using
    errcode = 'P0409',
    message = 'Un numero de operacion reclamado no se edita ni se borra',
    hint    = 'Esta tabla existe para no olvidar: si se pudiera limpiar, el mismo deposito se podria cobrar dos veces.';
end;

declare
  v_actor uuid := (select auth.uid());
  v_hoy date := (pg_catalog.now() at time zone 'America/Lima')::date;
  v_inicio_hoy timestamptz := v_hoy::timestamp at time zone 'America/Lima';
  v_fin_hoy timestamptz := (v_hoy + 1)::timestamp at time zone 'America/Lima';
begin
  if v_actor is null
     or new.vendedor_id is not null
     or old.vendedor_id is null
     or new.asignado_supervisor_id is distinct from v_actor
     or private.rol_crm(v_actor) is distinct from 'supervisor'
     or coalesce(
       pg_catalog.current_setting('crm.reversion_derivacion_equipo', true),
       'off'
     ) = 'on' then
    return new;
  end if;

  if exists (
    select 1
    from crm.lead_asignaciones la
    where la.lead_id = old.id
      and la.analista_id = old.vendedor_id
      and la.asignado_por = v_actor
      and la.supervisor_origen_id = v_actor
      and la.asignado_en >= v_inicio_hoy
      and la.asignado_en < v_fin_hoy
      and la.finalizado_en is null
  ) then
    raise exception 'Usa la acción Devolver: la derivación debe validar primero que el asesor no tenga gestión'
      using errcode = '42501';
  end if;

  return new;
end;

begin
  -- UNICA salida: la puerta declarada del punto 5.1, que deja rastro y lapida.
  -- La valvula usa el mismo idioma que `crm.op_privilegiada` de la Fase 3.
  if coalesce(current_setting('crm.purgando_membresia', true), '') = 'on' then
    return old;
  end if;
  raise exception
    'Una fila de crm.equipo no se borra: el offboarding es activo=false. Borrarla convertiria a una persona REVOCADA en AJENA al CRM y le devolveria los accesos del Portal (perfil_id=%). Si de verdad hace falta purgarla, usa crm.purgar_membresia_crm(perfil_id, motivo).', old.perfil_id
    using errcode = '42501';
  return null;
end;

declare v_rol_portal text;
begin
  -- El guardian vive donde hay una PERSONA detras (panel: RPC DEFINER con
  -- auth.uid presente). service_role (edges, seed), la consola postgres
  -- (migraciones, guiones tipo Carlos Valles) y el replay del seed operan con
  -- auth.uid()=NULL y son deliberados: exentos, como proteger_campos_inmutables.
  if (select auth.uid()) is null
     or coalesce(current_setting('crm.cambiando_par', true), '') = 'on' then
    return new;
  end if;
  select p.rol into v_rol_portal from public.perfiles p where p.id = new.perfil_id;
  if v_rol_portal is null then
    raise exception 'La ficha del equipo necesita un perfil del Portal (%).', new.perfil_id;
  end if;
  if not private.par_autoridad_valido(v_rol_portal, new.rol_crm) then
    raise exception 'El par %/% no esta declarado en private.pares_autoridad. Si es legitimo, se declara en una migracion; si es una transicion, usa la valvula crm.cambiando_par con el guion ordenado.',
      v_rol_portal, new.rol_crm using errcode = '42501';
  end if;
  return new;
end;

begin
  raise exception 'F7: una pieza en observacion no se borra (la salida es estado=liberada)'
    using errcode = '42501';
end;

begin
  if new.cerrada_en is distinct from old.cerrada_en then
    raise exception 'F7: cerrada_en es inmutable (%)', old.firma using errcode = '42501';
  end if;
  -- Auditoria F7.0 (P1): las columnas que definen el VEREDICTO y la AUTORIDAD
  -- tambien se congelan. El cambio legitimo baja este candado NOMBRADO en un
  -- DO de migracion (doctrina limpieza-leads) y lo re-activa.
  if new.huella_md5 is distinct from old.huella_md5
     or new.acl_esperada is distinct from old.acl_esperada
     or new.patron_censo is distinct from old.patron_censo
     or new.llamadores_permitidos is distinct from old.llamadores_permitidos
     or new.ok_miguel is distinct from old.ok_miguel
     or new.ola is distinct from old.ola then
    raise exception 'F7: la declaracion de % no se reescribe; una pieza que cambia se re-declara por migracion', old.firma
      using errcode = '42501';
  end if;
  if new.firma is distinct from old.firma then
    raise exception 'F7: la firma es la identidad de la fila y no se reescribe' using errcode = '42501';
  end if;
  -- Codex P0-3: la ventana ni encoge NI se resetea via NULL — una vez NULL
  -- (permanente), no se re-adquiere por UPDATE; eso es re-declaracion por
  -- migracion con el candado bajado.
  if old.drop_no_antes_de is not null
     and (new.drop_no_antes_de is null and new.estado <> 'cerrada_permanente'
          or new.drop_no_antes_de < old.drop_no_antes_de) then
    raise exception 'F7: la ventana de % solo puede CRECER', old.firma using errcode = '42501';
  end if;
  if old.drop_no_antes_de is null and new.drop_no_antes_de is not null then
    raise exception 'F7: % no re-adquiere ventana por UPDATE; se re-declara por migracion', old.firma
      using errcode = '42501';
  end if;
  -- Codex P0-2: MAQUINA DE ESTADOS cerrada. Solo observacion->demolida y
  -- observacion->cerrada_permanente. 'liberada' (devolver una pieza al
  -- servicio) y cualquier salida de demolida/cerrada_permanente EXIGEN una
  -- migracion que baje este candado nombrado (doctrina limpieza-leads):
  -- jamas un UPDATE de consola.
  if new.estado is distinct from old.estado then
    if not (old.estado = 'observacion' and new.estado in ('demolida', 'cerrada_permanente')) then
      raise exception 'F7: la transicion %->% de % SOLO por migracion con el candado bajado',
        old.estado, new.estado, old.firma using errcode = '42501';
    end if;
    if new.nota is not distinct from old.nota then
      raise exception 'F7: cambiar el estado de % exige dejar RASTRO en nota (quien y por que)', old.firma
        using errcode = '42501';
    end if;
  end if;
  return new;
end;

declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_autorizado boolean := false;
begin
  -- Los writers internos (auth.uid NULL) y los eventos de sistema ya tienen
  -- sus propios gates. No deben quedar atrapados al dispararse desde un UPDATE
  -- del lead que ya posee el lock.
  if v_actor is null
     or (
       tg_table_name = 'actividades'
       and new.tipo in ('cambio_etapa', 'reasignacion', 'conversion')
     ) then
    return new;
  end if;

  -- `crm.tareas` también admite tareas de perfil sin lead; no participan en
  -- una devolución y conservan su policy existente.
  if new.lead_id is null then
    return new;
  end if;

  -- `creado_en` no es inmutable durante INSERT en las tablas heredadas. Un
  -- asesor podría enviar una fecha anterior a la asignación y hacer invisible
  -- su gestión para el candado de devolución. Los inserts manuales reciben un
  -- sello del servidor; writers internos con auth.uid NULL conservan backfill.
  -- Se preservan antes los contratos heredados de NOT NULL/fecha finita: el
  -- sello no debe convertir un payload imposible en una escritura válida.
  if new.creado_en is null then
    raise exception 'La fecha de creación de la gestión es obligatoria'
      using errcode = '23502';
  end if;
  if not pg_catalog.isfinite(new.creado_en) then
    raise exception 'La fecha de creación de la gestión debe ser finita'
      using errcode = '23514';
  end if;

  if new.creado_por is distinct from v_actor then
    raise exception 'La gestión debe quedar atribuida al usuario autenticado'
      using errcode = '42501';
  end if;

  v_rol := private.rol_crm(v_actor);
  select true
    into v_autorizado
  from crm.leads lead
  where lead.id = new.lead_id
    and lead.activo = true
    and (
      v_rol = 'gerencia'
      or lead.vendedor_id = v_actor
      or (
        v_rol = 'supervisor'
        and (
          lead.vendedor_id in (
            select private.vendedor_ids_visibles(v_actor)
          )
          or (
            lead.vendedor_id is null
            and lead.asignado_supervisor_id in (
              select private.vendedor_ids_visibles(v_actor)
            )
          )
        )
      )
    )
  for update;

  if v_autorizado is distinct from true then
    raise exception 'El lead cambió de responsable; recarga antes de registrar la gestión'
      using errcode = '42501';
  end if;
  -- F2.b (b2): el veto de la PERSONA bloquea el SEGUIMIENTO (contrato §7.3): los tipos
  -- de CONTACTO y las tareas. Las notas administrativas (corrección/anulación de un
  -- cierre, fusión, reingreso) no son contacto y siguen entrando; la nota de las RPC
  -- de veto entra además bajo la válvula op_privilegiada.
  if not coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false)
     and (tg_table_name = 'tareas'
          or new.tipo in ('llamada_realizada','llamada_no_contestada','whatsapp_enviado','whatsapp_recibido','reunion_realizada'))
     and private.persona_vetada(new.lead_id) then
    raise exception '%: no se registra seguimiento', 'La persona tiene la restricción «No insistir»'
      using errcode = 'P0429';
  end if;

  -- El sello se toma DESPUÉS del lock y de la revalidación. `statement_timestamp`
  -- conservaría la hora previa a una espera: si una derivación ganara durante
  -- esa espera, la gestión podría quedar fechada antes del episodio y el
  -- supervisor aún la vería como reversible. `clock_timestamp` registra el
  -- orden causal ya serializado por el lock.
  new.creado_en := pg_catalog.clock_timestamp();

  return new;
end;

declare
  v_asignado_en timestamptz;
  v_finalizado_en timestamptz;
begin
  if tg_op='DELETE' then
    raise exception 'Los hitos SLA de asignacion no se eliminan' using errcode='55000';
  end if;
  if coalesce(current_setting('crm.sla_writer',true),'off')<>'on'
    or pg_trigger_depth()<2 then
    raise exception 'Los hitos SLA solo se sellan desde eventos CRM' using errcode='42501';
  end if;
  select a.asignado_en,a.finalizado_en into v_asignado_en,v_finalizado_en
  from crm.lead_asignaciones a where a.id=new.lead_asignacion_id;
  if not found then raise exception 'Asignacion SLA inexistente' using errcode='23503'; end if;
  if tg_op='UPDATE' and (
    old.id is distinct from new.id
    or old.lead_asignacion_id is distinct from new.lead_asignacion_id
    or old.creado_en is distinct from new.creado_en
    or (old.primera_gestion_en is not null
      and old.primera_gestion_en is distinct from new.primera_gestion_en)
    or (old.primer_contacto_en is not null
      and old.primer_contacto_en is distinct from new.primer_contacto_en)
  ) then
    raise exception 'Los hitos SLA de asignacion son inmutables' using errcode='55000';
  end if;
  if (new.primera_gestion_en is not null and (
      new.primera_gestion_en<v_asignado_en
      or (v_finalizado_en is not null and new.primera_gestion_en>v_finalizado_en)
    )) or (new.primer_contacto_en is not null and (
      new.primera_gestion_en is null
      or new.primer_contacto_en<new.primera_gestion_en
      or (v_finalizado_en is not null and new.primer_contacto_en>v_finalizado_en)
    )) then
    raise exception 'Hito SLA fuera del episodio de asignacion' using errcode='23514';
  end if;
  return new;
end;

declare
  v_inicio timestamptz;
  v_aproximado boolean;
  v_ciclo integer;
begin
  if tg_op <> 'INSERT' then
    return new;
  end if;

  select
    l.sla_global_iniciado_en,
    l.sla_global_aproximado,
    l.ciclo_actual
  into v_inicio, v_aproximado, v_ciclo
  from crm.leads l
  where l.id = new.lead_id;

  if not found or v_inicio is null then
    raise exception 'El lead no tiene un inicio de SLA global valido';
  end if;
  if new.ciclo_n is distinct from v_ciclo then
    raise exception 'El episodio no pertenece al ciclo actual del lead';
  end if;
  if v_inicio > new.asignado_en then
    raise exception 'El SLA global no puede iniciar despues de la asignacion';
  end if;

  new.sla_global_iniciado_en := v_inicio;
  new.sla_global_aproximado := v_aproximado;
  return new;
end;

begin
  perform set_config('crm.sla_writer','on',true);
  insert into crm.lead_asignacion_sla_hitos(lead_asignacion_id) values(new.id);
  perform set_config('crm.sla_writer','off',true);
  return null;
end;

begin
  if tg_op = 'DELETE' then
    raise exception 'Los episodios de asignacion no se eliminan';
  end if;

  if coalesce(current_setting('crm.ledger_writer', true), 'off') <> 'on'
     or pg_trigger_depth() < 2 then
    raise exception 'El ledger solo se escribe desde el movimiento del lead';
  end if;

  if tg_op = 'INSERT' then
    return new;
  end if;

  if old.finalizado_en is not null then
    raise exception 'Un episodio cerrado es inmutable';
  end if;

  if old.id is distinct from new.id
     or old.lead_id is distinct from new.lead_id
     or old.ciclo_n is distinct from new.ciclo_n
     or old.episodio_n is distinct from new.episodio_n
     or old.analista_id is distinct from new.analista_id
     or old.motivo_apertura is distinct from new.motivo_apertura
     or old.asignado_en is distinct from new.asignado_en
     or old.asignado_por is distinct from new.asignado_por
     or old.supervisor_origen_id is distinct from new.supervisor_origen_id
     or old.monto_estimado is distinct from new.monto_estimado
     or old.moneda is distinct from new.moneda
     or old.origen is distinct from new.origen
     or old.categoria_interes is distinct from new.categoria_interes
     or old.aproximado is distinct from new.aproximado
     or old.creado_en is distinct from new.creado_en then
    raise exception 'La fotografia de un episodio es inmutable';
  end if;

  if new.finalizado_en is null or new.motivo_cierre is null then
    raise exception 'La unica actualizacion valida del ledger es su cierre completo';
  end if;

  return new;
end;

begin
  if tg_op = 'UPDATE'
     and (
       old.sla_global_iniciado_en is distinct from new.sla_global_iniciado_en
       or old.sla_global_aproximado is distinct from new.sla_global_aproximado
     ) then
    raise exception 'El inicio del SLA global de un episodio es inmutable';
  end if;
  return new;
end;

declare v_p crm.sla_politicas%rowtype;
begin
  if tg_op='INSERT' then
    select p.* into v_p from crm.sla_politicas p
    where p.id=private.sla_politica_vigente(new.asignado_en);
    if not found then raise exception 'No existe politica SLA para la asignacion'; end if;
    new.sla_politica_asignacion_id:=v_p.id;
    new.primera_gestion_limite_en:=new.asignado_en+v_p.primera_gestion_minutos*interval '1 minute';
    new.primer_contacto_limite_en:=new.asignado_en+v_p.primer_contacto_minutos*interval '1 minute';
  elsif old.sla_politica_asignacion_id is distinct from new.sla_politica_asignacion_id
    or old.primera_gestion_limite_en is distinct from new.primera_gestion_limite_en
    or old.primer_contacto_limite_en is distinct from new.primer_contacto_limite_en then
    raise exception 'Snapshot SLA de asignacion inmutable' using errcode='55000';
  end if;
  return new;
end;

begin
  if tg_op='DELETE' then raise exception 'Los ciclos SLA no se eliminan' using errcode='55000'; end if;
  if coalesce(current_setting('crm.sla_writer',true),'off')<>'on' or pg_trigger_depth()<2 then
    raise exception 'Los ciclos SLA solo se escriben desde eventos CRM' using errcode='42501';
  end if;
  if tg_op='INSERT' then return new; end if;
  if old.id is distinct from new.id or old.lead_id is distinct from new.lead_id
    or old.ciclo_n is distinct from new.ciclo_n or old.politica_id is distinct from new.politica_id
    or old.iniciado_en is distinct from new.iniciado_en
    or old.primera_gestion_limite_en is distinct from new.primera_gestion_limite_en
    or old.primer_contacto_limite_en is distinct from new.primer_contacto_limite_en
    or old.aproximado is distinct from new.aproximado or old.creado_en is distinct from new.creado_en
    or (old.primera_gestion_en is not null and old.primera_gestion_en is distinct from new.primera_gestion_en)
    or (old.primer_contacto_en is not null and old.primer_contacto_en is distinct from new.primer_contacto_en) then
    raise exception 'Snapshot/eventos SLA inmutables' using errcode='55000';
  end if;
  return new;
end;

begin
  if tg_op='DELETE' then raise exception 'Las etapas SLA no se eliminan' using errcode='55000'; end if;
  if coalesce(current_setting('crm.sla_writer',true),'off')<>'on' or pg_trigger_depth()<2 then
    raise exception 'Las etapas SLA solo se escriben desde crm.leads' using errcode='42501';
  end if;
  if tg_op='INSERT' then return new; end if;
  if old.finalizado_en is not null or new.finalizado_en is null or new.motivo_cierre is null
    or old.id is distinct from new.id or old.lead_id is distinct from new.lead_id
    or old.ciclo_n is distinct from new.ciclo_n or old.episodio_n is distinct from new.episodio_n
    or old.etapa is distinct from new.etapa or old.politica_id is distinct from new.politica_id
    or old.iniciado_en is distinct from new.iniciado_en or old.limite_en is distinct from new.limite_en
    or old.aproximado is distinct from new.aproximado or old.creado_en is distinct from new.creado_en then
    raise exception 'Solo se permite cerrar una etapa SLA abierta' using errcode='55000';
  end if;
  return new;
end;

declare
  v_evento_en timestamptz;
  v_actor uuid;
  v_movimiento text := 'sin_cambio';
  v_abierto crm.lead_asignaciones%rowtype;
  v_hay_abierto boolean := false;
  v_old_debe_tener boolean := false;
  v_new_debe_tener boolean;
  v_entra_terminal boolean := false;
  v_reabierto boolean := false;
  v_reactivado boolean := false;
  v_motivo_apertura text;
  v_motivo_cierre text;
  v_episodio_n integer;
  v_abiertos integer;
  v_analista_abierto uuid;
begin
  v_new_debe_tener := new.activo = true
    and new.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
    and new.vendedor_id is not null;

  if tg_op = 'INSERT' then
    v_evento_en := new.creado_en;
    v_actor := coalesce(auth.uid(), new.creado_por);

    if v_new_debe_tener then
      perform set_config('crm.ledger_writer', 'on', true);
      insert into crm.lead_asignaciones (
        lead_id,
        ciclo_n,
        episodio_n,
        analista_id,
        motivo_apertura,
        asignado_en,
        asignado_por,
        monto_estimado,
        moneda,
        origen,
        categoria_interes
      )
      values (
        new.id,
        new.ciclo_actual,
        1,
        new.vendedor_id,
        'ingreso',
        v_evento_en,
        v_actor,
        new.monto_estimado,
        new.moneda,
        new.origen,
        new.categoria_interes
      );
      perform set_config('crm.ledger_writer', 'off', true);
    end if;
  else
    v_evento_en := statement_timestamp();
    v_actor := auth.uid();
    v_movimiento := private.clasificar_movimiento_tenencia(
      old.vendedor_id,
      new.vendedor_id,
      old.asignado_supervisor_id,
      new.asignado_supervisor_id
    );
    v_old_debe_tener := old.activo = true
      and old.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
      and old.vendedor_id is not null;
    v_entra_terminal := old.etapa not in ('convertido', 'descartado')
      and new.etapa in ('convertido', 'descartado');
    v_reabierto := old.etapa = 'descartado' and new.etapa = 'nuevo';
    v_reactivado := old.activo = false and new.activo = true;

    select la.*
      into v_abierto
    from crm.lead_asignaciones la
    where la.lead_id = new.id
      and la.finalizado_en is null
    for update;
    v_hay_abierto := found;

    if v_old_debe_tener and not v_hay_abierto then
      raise exception 'Invariante rota: falta el episodio abierto del lead %', new.id;
    end if;
    if v_old_debe_tener and v_abierto.analista_id is distinct from old.vendedor_id then
      raise exception 'Invariante rota: el episodio abierto no coincide con el analista del lead %', new.id;
    end if;
    if not v_old_debe_tener and v_hay_abierto then
      raise exception 'Invariante rota: existe un episodio abierto fuera de tenencia operativa para %', new.id;
    end if;

    if v_hay_abierto
       and (
         new.vendedor_id is distinct from old.vendedor_id
         or not v_new_debe_tener
       ) then
      v_motivo_cierre := case
        when v_entra_terminal then new.etapa
        when old.activo = true and new.activo = false then 'desactivado'
        when v_movimiento = 'transferido' then 'transferido'
        when v_movimiento in ('parqueado', 'sin_asignar') then 'parqueado'
        else null
      end;

      if v_motivo_cierre is null then
        raise exception 'No se pudo clasificar el cierre del episodio del lead %', new.id;
      end if;

      perform set_config('crm.ledger_writer', 'on', true);
      update crm.lead_asignaciones
      set finalizado_en = v_evento_en,
          finalizado_por = v_actor,
          motivo_cierre = v_motivo_cierre,
          analista_destino_id = case
            when v_motivo_cierre = 'transferido' then new.vendedor_id
            else null
          end,
          supervisor_destino_id = case
            when v_motivo_cierre = 'parqueado' then new.asignado_supervisor_id
            else null
          end,
          resultado = case
            when v_motivo_cierre in ('convertido', 'descartado') then v_motivo_cierre
            else null
          end,
          resultado_en = case
            when v_motivo_cierre in ('convertido', 'descartado') then v_evento_en
            else null
          end,
          motivo_descarte_cierre = case
            when v_motivo_cierre = 'descartado' then new.motivo_descarte
            else null
          end
      where id = v_abierto.id;
      perform set_config('crm.ledger_writer', 'off', true);
      v_hay_abierto := false;
    end if;

    if v_new_debe_tener
       and (
         not v_old_debe_tener
         or new.vendedor_id is distinct from old.vendedor_id
       ) then
      v_motivo_apertura := case
        when v_reabierto then 'reabierto'
        when v_reactivado then 'reactivado'
        when v_movimiento = 'transferido' then 'reasignado'
        else 'asignado'
      end;

      select coalesce(max(la.episodio_n), 0) + 1
        into v_episodio_n
      from crm.lead_asignaciones la
      where la.lead_id = new.id
        and la.ciclo_n = new.ciclo_actual;

      perform set_config('crm.ledger_writer', 'on', true);
      insert into crm.lead_asignaciones (
        lead_id,
        ciclo_n,
        episodio_n,
        analista_id,
        motivo_apertura,
        asignado_en,
        asignado_por,
        supervisor_origen_id,
        monto_estimado,
        moneda,
        origen,
        categoria_interes
      )
      values (
        new.id,
        new.ciclo_actual,
        v_episodio_n,
        new.vendedor_id,
        v_motivo_apertura,
        v_evento_en,
        v_actor,
        old.asignado_supervisor_id,
        new.monto_estimado,
        new.moneda,
        new.origen,
        new.categoria_interes
      );
      perform set_config('crm.ledger_writer', 'off', true);
    end if;
  end if;

  select count(*), (array_agg(la.analista_id))[1]
    into v_abiertos, v_analista_abierto
  from crm.lead_asignaciones la
  where la.lead_id = new.id
    and la.finalizado_en is null;

  if v_new_debe_tener
     and (v_abiertos <> 1 or v_analista_abierto is distinct from new.vendedor_id) then
    raise exception 'Invariante rota: el lead % debe terminar con un episodio abierto', new.id;
  end if;
  if not v_new_debe_tener and v_abiertos <> 0 then
    raise exception 'Invariante rota: el lead % no debe terminar con episodio abierto', new.id;
  end if;

  return new;
end;

begin
  if new.vendedor_id is distinct from old.vendedor_id
     and private.rol_crm((select auth.uid())) = 'vendedor'
     and not (
       coalesce(pg_catalog.current_setting('crm.toma_directa', true), 'off') = 'on'
       and new.vendedor_id = (select auth.uid())
     ) then
    raise exception 'Un vendedor no puede reasignar leads';
  end if;
  return new;
end;

begin
  if new.etapa is distinct from old.etapa then
    insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por)
    values (
      new.id, 'cambio_etapa', old.etapa || ' → ' || new.etapa,
      jsonb_build_object(
        'etapa_anterior', old.etapa,
        'etapa_nueva', new.etapa,
        'automatico', coalesce(current_setting('crm.avance_auto', true), 'off') = 'on'
      ),
      coalesce((select auth.uid()), new.creado_por)
    );
    if new.etapa = 'convertido' and new.convertido_en is null then
      new.convertido_en := now();
    end if;
  end if;
  return new;
end;

declare
  v_actor uuid := (select auth.uid());
  v_rol text;
  v_disponibilidad jsonb;
  v_cambio_identidad boolean;
  v_dias integer;
  v_disponible_desde timestamptz;
  v_descartado_por text;
  v_priv boolean := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false);
begin
  if tg_op = 'UPDATE' then
    if new.telefono is distinct from old.telefono then
      new.telefono := private.normalizar_telefono(new.telefono);
      if new.telefono is null or new.telefono !~ '^\+519[0-9]{8}$' then
        raise exception using errcode = '22023', message = 'Telefono invalido';
      end if;
    end if;

    if new.dni is distinct from old.dni then
      new.dni := nullif(pg_catalog.btrim(new.dni), '');
      if new.dni is not null and new.dni !~ '^[0-9]{8}$' then
        raise exception using errcode = '22023', message = 'DNI invalido';
      end if;
    end if;

    v_cambio_identidad := new.telefono is distinct from old.telefono
      or new.dni is distinct from old.dni;

    perform private.bloquear_contactos_lead(
      array[old.telefono, new.telefono],
      array[old.dni, new.dni]
    );

    -- F2.b (b5) [E3-6]: la corrección de documento de Gerencia (RPC definer bajo válvula Y con su
    -- GUC propia crm.correccion_documento) cambia SOLO el DNI de un lead que conserva su persona; los terceros (otra identidad,
    -- otro cliente del Portal, otro lead vivo) ya los comprobó la RPC bajo sus locks. Ningún
    -- otro escritor bajo válvula cambia el DNI; fuera de esta forma exacta nada cambia.
    if v_priv and coalesce(pg_catalog.current_setting('crm.correccion_documento', true) = 'on', false)
       and private.resolver_en_puertas_bajo_candado()
       and new.dni is distinct from old.dni and new.telefono is not distinct from old.telefono
       and new.no_contactar = old.no_contactar and new.etapa = old.etapa and new.activo = old.activo
       and new.motivo_descarte is not distinct from old.motivo_descarte
       and old.inversionista_id is not null and new.inversionista_id = old.inversionista_id then
      return new;
    end if;
    if not v_cambio_identidad or v_actor is null then
      return new;
    end if;

    v_rol := private.rol_crm(v_actor);
    if v_rol is null or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
      raise exception using errcode = '42501', message = 'Acceso CRM revocado';
    end if;

    -- Excluir OLD al validar el destino es correcto para un lead operativo,
    -- pero no debe permitir «mover» un No contactar o un enfriamiento y dejar
    -- libre la identidad anterior. Ambos vetos propios congelan teléfono y DNI
    -- mientras sigan vigentes; levantarlos es una operación separada y auditable.
    if old.no_contactar = true then
      raise exception using
        errcode = 'P0481',
        message = 'Contacto no disponible',
        detail = pg_catalog.jsonb_build_object('estado', 'no_contactar')::text;
    end if;

    if old.etapa = 'descartado'
       and old.descartado_en is not null
       and old.motivo_descarte is not null then
      select
        ep.dias,
        old.descartado_en + pg_catalog.make_interval(days => ep.dias),
        p.nombre_completo
      into v_dias, v_disponible_desde, v_descartado_por
      from crm.enfriamiento_politica ep
      left join public.perfiles p on p.id = old.descartado_por
      where ep.motivo = old.motivo_descarte;

      if coalesce(v_dias, 0) > 0
         and v_disponible_desde > pg_catalog.now() then
        raise exception using
          errcode = 'P0481',
          message = 'Contacto no disponible',
          detail = pg_catalog.jsonb_build_object(
            'estado', 'enfriamiento',
            'motivo_descarte', old.motivo_descarte,
            'disponible_desde', v_disponible_desde,
            'descartado_por', v_descartado_por
          )::text;
      end if;
    end if;

    v_disponibilidad := private.verificar_disponibilidad_lead_impl(
      new.telefono,
      new.dni,
      old.id
    );
    if v_disponibilidad ->> 'estado' is distinct from 'libre' then
      raise exception using
        errcode = 'P0481',
        message = 'Contacto no disponible',
        detail = v_disponibilidad::text;
    end if;
    return new;
  end if;

  new.telefono := private.normalizar_telefono(new.telefono);
  new.dni := nullif(pg_catalog.btrim(new.dni), '');

  if new.telefono is null or new.telefono !~ '^\+519[0-9]{8}$' then
    raise exception using errcode = '22023', message = 'Telefono invalido';
  end if;
  if new.dni is not null and new.dni !~ '^[0-9]{8}$' then
    raise exception using errcode = '22023', message = 'DNI invalido';
  end if;

  perform private.bloquear_contactos_lead(array[new.telefono], array[new.dni]);

  -- Un escritor interno sin sesion humana se serializa, pero conserva su
  -- contrato especializado (por ejemplo crm-importar-leads con service_role).
  if v_actor is null then
    return new;
  end if;

  v_rol := private.rol_crm(v_actor);
  if v_rol is null or v_rol not in ('vendedor', 'supervisor', 'gerencia') then
    raise exception using errcode = '42501', message = 'Acceso CRM revocado';
  end if;

  -- La compatibilidad temporal es solo para el alta que ya hacía el bundle
  -- anterior. No abre una vía para fabricar leads terminales o inactivos.
  if new.activo is distinct from true
     or new.etapa not in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada') then
    raise exception using errcode = '22023', message = 'Un lead debe nacer activo y en etapa operativa';
  end if;

  v_disponibilidad := private.verificar_disponibilidad_lead_impl(new.telefono, new.dni);
  if v_disponibilidad ->> 'estado' is distinct from 'libre' then
    raise exception using
      errcode = 'P0481',
      message = 'Contacto no disponible',
      detail = v_disponibilidad::text;
  end if;

  return new;
end;

declare
  v_rol_actor text;
  v_entra_terminal boolean;
begin
  if new.vendedor_id is not null and new.asignado_supervisor_id is not null then
    raise exception 'Un lead no puede tener analista y bandeja al mismo tiempo';
  end if;

  -- Solo un miembro plenamente activo puede recibir responsabilidad nueva.
  if new.vendedor_id is not null
     and (
       tg_op = 'INSERT'
       or new.vendedor_id is distinct from old.vendedor_id
       or (old.activo = false and new.activo = true)
       or (
         old.etapa in ('convertido', 'descartado')
         and new.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
       )
     )
     and not private.es_destino_crm_activo(
       new.vendedor_id,
       array['vendedor', 'supervisor']::text[]
     ) then
    raise exception 'El analista destino no existe, no esta activo o no puede recibir leads';
  end if;

  -- Una bandeja pertenece exclusivamente a un supervisor plenamente activo.
  if new.asignado_supervisor_id is not null
     and (
       tg_op = 'INSERT'
       or new.asignado_supervisor_id is distinct from old.asignado_supervisor_id
       or (old.activo = false and new.activo = true)
       or (
         old.etapa in ('convertido', 'descartado')
         and new.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
       )
     )
     and not private.es_destino_crm_activo(
       new.asignado_supervisor_id,
       array['supervisor']::text[]
     ) then
    raise exception 'La bandeja destino no pertenece a un supervisor activo';
  end if;

  -- Un usuario CRM no gerencial no puede liberar un lead a la cola global.
  if new.vendedor_id is null
     and new.asignado_supervisor_id is null
     and (
       tg_op = 'INSERT'
       or old.vendedor_id is not null
       or old.asignado_supervisor_id is not null
     )
     and auth.uid() is not null then
    v_rol_actor := private.rol_crm(auth.uid());
    if v_rol_actor is distinct from 'gerencia' then
      raise exception 'Solo Gerencia puede dejar un lead en la cola global';
    end if;
  end if;

  if tg_op = 'INSERT' then
    new.creado_en := statement_timestamp();
    new.actualizado_en := new.creado_en;
    new.ciclo_actual := 1;
    return new;
  end if;

  new.ciclo_actual := old.ciclo_actual;

  if old.etapa = 'convertido' and new.etapa is distinct from old.etapa then
    raise exception 'Un lead convertido no se puede reabrir';
  end if;

  if old.etapa = 'descartado' and new.etapa is distinct from old.etapa then
    if new.etapa <> 'nuevo' then
      raise exception 'Un lead descartado solo se puede reabrir en etapa nuevo';
    end if;
    new.ciclo_actual := old.ciclo_actual + 1;
  end if;

  v_entra_terminal := old.etapa not in ('convertido', 'descartado')
    and new.etapa in ('convertido', 'descartado');

  if v_entra_terminal
     and (
       new.vendedor_id is distinct from old.vendedor_id
       or new.asignado_supervisor_id is distinct from old.asignado_supervisor_id
     ) then
    raise exception 'Asigna al responsable antes de cerrar el lead';
  end if;

  if v_entra_terminal and old.activo = false then
    raise exception 'Reactiva el lead antes de cerrarlo';
  end if;

  if v_entra_terminal and old.activo = true and new.activo = false then
    raise exception 'Cierra o desactiva el lead en operaciones separadas';
  end if;

  if old.etapa <> 'convertido' and new.etapa = 'convertido'
     and old.vendedor_id is null then
    raise exception 'Asigna un analista antes de convertir el lead';
  end if;

  if old.activo = true and new.activo = false
     and (
       new.vendedor_id is distinct from old.vendedor_id
       or new.asignado_supervisor_id is distinct from old.asignado_supervisor_id
     ) then
    raise exception 'Reasigna o desactiva el lead en operaciones separadas';
  end if;

  return new;
end;

declare
  v_inv uuid;
  v_veto boolean;
begin
  if not private.resolver_en_puertas_bajo_candado() then
    return new;
  end if;
  -- Solo DNI: crm.leads.dni es siempre DNI de 8 dígitos (contrato §18). Se
  -- normaliza igual que el resolver (este trigger corre ANTES del btrim de 00).
  if nullif(pg_catalog.btrim(coalesce(new.dni,'')), '') is null then
    return new;
  end if;
  -- Orden total: documento -> identidad -> (contactos los toma 00 después).
  perform private.identidad_bloquear_documento('DNI', new.dni);
  v_inv := private.inversionista_por_documento('DNI', new.dni);
  if v_inv is null then
    return new;
  end if;
  -- Serializa contra marcar/levantar_no_contactar (identidad FOR UPDATE) y relee.
  select i.no_contactar into v_veto
  from crm.inversionistas i
  where i.id = v_inv
  for update;
  if coalesce(v_veto, false) then
    raise exception 'La persona tiene la restricción «No insistir»: no se abre una oportunidad nueva'
      using errcode = 'P0429',
            detail = pg_catalog.jsonb_build_object('estado', 'no_contactar', 'via', 'identidad')::text;
  end if;
  return new;
end;

begin
  if not private.resolver_en_puertas_bajo_candado() then
    return new;  -- bandera apagada: comportamiento de hoy
  end if;
  if new.no_contactar is distinct from old.no_contactar
     and coalesce(pg_catalog.current_setting('crm.op_privilegiada', true), 'off') <> 'on' then
    raise exception 'No contactar se cambia solo por su puerta (marcar_no_contactar / levantar_no_contactar)'
      using errcode = '42501';
  end if;
  return new;
end;

begin
  new.telefono := private.normalizar_telefono(new.telefono);
  return new;
end;

declare
  v_movimiento text;
  v_anterior text;
  v_nuevo text;
begin
  v_movimiento := private.clasificar_movimiento_tenencia(
    old.vendedor_id,
    new.vendedor_id,
    old.asignado_supervisor_id,
    new.asignado_supervisor_id
  );

  if v_movimiento = 'sin_cambio' then
    return new;
  end if;

  if old.vendedor_id is not null then
    select p.nombre_completo into v_anterior
    from public.perfiles p
    where p.id = old.vendedor_id;
  elsif old.asignado_supervisor_id is not null then
    select 'Bandeja de ' || p.nombre_completo into v_anterior
    from public.perfiles p
    where p.id = old.asignado_supervisor_id;
  else
    v_anterior := 'Sin asignar';
  end if;

  if new.vendedor_id is not null then
    select p.nombre_completo into v_nuevo
    from public.perfiles p
    where p.id = new.vendedor_id;
  elsif new.asignado_supervisor_id is not null then
    select 'Bandeja de ' || p.nombre_completo into v_nuevo
    from public.perfiles p
    where p.id = new.asignado_supervisor_id;
  else
    v_nuevo := 'Sin asignar';
  end if;

  insert into crm.actividades (
    lead_id,
    tipo,
    detalle,
    metadata,
    creado_por,
    creado_en
  )
  values (
    new.id,
    'reasignacion',
    coalesce(v_anterior, 'Responsable desconocido') || ' → '
      || coalesce(v_nuevo, 'Responsable desconocido'),
    jsonb_build_object(
      'movimiento', v_movimiento,
      'vendedor_anterior', old.vendedor_id,
      'vendedor_nuevo', new.vendedor_id,
      'supervisor_anterior', old.asignado_supervisor_id,
      'supervisor_nuevo', new.asignado_supervisor_id
    ),
    coalesce(auth.uid(), new.creado_por),
    statement_timestamp()
  );

  return new;
end;

begin
  if tg_op = 'INSERT' then
    if new.creado_en is null then
      raise exception 'No existe timestamp de ingreso para iniciar el SLA global';
    end if;
    new.sla_global_iniciado_en := new.creado_en;
    new.sla_global_aproximado := false;
    return new;
  end if;

  if new.ciclo_actual is distinct from old.ciclo_actual then
    if new.ciclo_actual <> old.ciclo_actual + 1 then
      raise exception 'Transicion de ciclo invalida para el SLA global';
    end if;
    new.sla_global_iniciado_en := statement_timestamp();
    new.sla_global_aproximado := false;
  else
    new.sla_global_iniciado_en := old.sla_global_iniciado_en;
    new.sla_global_aproximado := old.sla_global_aproximado;
  end if;

  return new;
end;

declare
  v_en timestamptz;
  v_p crm.sla_politicas%rowtype;
  v_maximo integer;
  v_n integer;
  v_motivo text;
begin
  v_en:=case when tg_op='INSERT' then new.sla_global_iniciado_en else statement_timestamp() end;
  perform set_config('crm.sla_writer','on',true);

  if tg_op='INSERT' or new.ciclo_actual is distinct from old.ciclo_actual then
    select p.* into v_p from crm.sla_politicas p
    where p.id=private.sla_politica_vigente(new.sla_global_iniciado_en);
    if not found then raise exception 'No existe politica SLA para el ciclo'; end if;
    insert into crm.lead_sla_ciclos(
      lead_id,ciclo_n,politica_id,iniciado_en,primera_gestion_limite_en,primer_contacto_limite_en
    ) values(new.id,new.ciclo_actual,v_p.id,new.sla_global_iniciado_en,
      new.sla_global_iniciado_en+v_p.primera_gestion_minutos*interval '1 minute',
      new.sla_global_iniciado_en+v_p.primer_contacto_minutos*interval '1 minute');
  end if;

  if tg_op='UPDATE' and (
    new.ciclo_actual is distinct from old.ciclo_actual or new.etapa is distinct from old.etapa
    or (old.activo and not new.activo)
  ) then
    v_motivo:=case
      when new.ciclo_actual is distinct from old.ciclo_actual then 'reapertura'
      when old.activo and not new.activo then 'desactivacion'
      when new.etapa in ('convertido','descartado') then 'cierre_terminal'
      else 'cambio_etapa' end;
    update crm.lead_sla_etapas set finalizado_en=v_en,motivo_cierre=v_motivo
    where lead_id=new.id and finalizado_en is null;
  end if;

  if new.activo and new.etapa in ('nuevo','contactado','reunion_agendada','propuesta_enviada')
    and (tg_op='INSERT' or new.ciclo_actual is distinct from old.ciclo_actual
      or new.etapa is distinct from old.etapa or (not old.activo and new.activo)) then
    select p.* into v_p
    from crm.sla_politicas p
    where p.id=private.sla_politica_vigente(v_en);
    if not found then raise exception 'No existe politica SLA vigente'; end if;
    select pe.maximo_minutos into v_maximo
    from crm.sla_politica_etapas pe
    where pe.politica_id=v_p.id and pe.etapa=new.etapa;
    if not found then raise exception 'No existe SLA para etapa %',new.etapa; end if;
    select coalesce(max(e.episodio_n),0)+1 into v_n from crm.lead_sla_etapas e
    where e.lead_id=new.id and e.ciclo_n=new.ciclo_actual;
    insert into crm.lead_sla_etapas(
      lead_id,ciclo_n,episodio_n,etapa,politica_id,iniciado_en,limite_en
    ) values(new.id,new.ciclo_actual,v_n,new.etapa,v_p.id,v_en,
      v_en+v_maximo*interval '1 minute');
  end if;
  perform set_config('crm.sla_writer','off',true);
  return new;
end;

declare
  v_new_debe boolean;
  v_old_debe boolean;
begin
  v_new_debe := new.activo = true
    and new.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
    and new.vendedor_id is not null;

  if tg_op = 'INSERT' then
    new.tenencia_desde := case when v_new_debe then new.creado_en else null end;
    return new;
  end if;

  v_old_debe := old.activo = true
    and old.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
    and old.vendedor_id is not null;

  if not v_new_debe then
    new.tenencia_desde := null;
  elsif not v_old_debe then
    new.tenencia_desde := statement_timestamp();
  elsif new.vendedor_id is distinct from old.vendedor_id then
    new.tenencia_desde := statement_timestamp();
  elsif new.ciclo_actual is distinct from old.ciclo_actual then
    new.tenencia_desde := statement_timestamp();
  else
    new.tenencia_desde := old.tenencia_desde;
  end if;

  return new;
end;

declare
  v_priv boolean := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false);
  v_inv uuid;
  v_otro record;
begin
  if not private.resolver_en_puertas_bajo_candado() then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.dni is not distinct from old.dni or v_priv then
      return new;
    end if;
    -- En UPDATE la fila del lead YA está bloqueada: aquí no se toma ningún lock de
    -- identidad (evitaría el orden documento->identidad->lead y podría abrazarse con
    -- marcar/levantar y la conversión). Se RECHAZA, no se enlaza: el documento de una
    -- persona enlazada, o un documento que resuelve a una persona reconocida, solo
    -- cambia por la corrección de Gerencia (bajo válvula, b5). Un DNI que no resuelve
    -- a nadie sigue editándose como hoy.
    if old.inversionista_id is not null
       or exists (select 1 from crm.inversionista_leads il where il.lead_id = new.id) then
      raise exception 'El documento pertenece a una persona reconocida: solo Gerencia lo corrige (corrección de documento)'
        using errcode = 'P0409';
    end if;
    -- F2.b [D-13] (Codex v3 B1, auditor v4 A1): con la identidad encendida, el DNI de un lead se FIJA por su puerta
    -- (crm.fijar_dni_lead_fn), que toma el candado del documento y a la persona ANTES de la fila (orden documento ->
    -- persona -> lead), juzga a la persona y enlaza si procede: por la puerta, el trigger deja pasar. El UPDATE directo
    -- (fila ya bloqueada, sin serialización posible con una reserva en vuelo) se rechaza: hacia una persona reconocida
    -- con el mensaje de siempre; hacia un documento sin dueño, «por su puerta».
    if coalesce(pg_catalog.current_setting('crm.dni_por_puerta', true), 'off') = 'on' then
      return new;
    end if;
    if nullif(pg_catalog.btrim(coalesce(new.dni,'')), '') is not null
       and private.inversionista_por_documento('DNI', new.dni) is not null then
      raise exception 'El documento pertenece a una persona reconocida: solo Gerencia lo corrige (corrección de documento)'
        using errcode = 'P0409';
    end if;
    raise exception 'Con la identidad unificada encendida, el DNI de un lead se fija por su puerta (fijar_dni_lead_fn) o lo corrige Gerencia'
      using errcode = 'P0409';
  elsif v_priv and new.inversionista_id is not null then
    -- Una RPC bajo válvula que ya trae el enlace (p. ej. una fusión futura) manda.
    return new;
  end if;

  if nullif(pg_catalog.btrim(coalesce(new.dni,'')), '') is null then
    new.inversionista_id := null;
    return new;
  end if;
  -- El advisory documental ya lo tomó el trigger 000 en esta misma sentencia.
  v_inv := private.inversionista_por_documento('DNI', new.dni);
  if v_inv is null then
    new.inversionista_id := null;
    return new;
  end if;
  -- Un solo lead TOTAL por persona (invariante #6): vivos, convertidos y descartados.
  -- F2.b [D-13]: enlace vivo ∪ PUENTE ∪ sueltos vivos con su documento (private.leads_de_personas; el enlace vivo primero en
  -- el detalle) y persona EN CONVERSIÓN (reserva por persona viva o sellada de otro lead). Serializado con la reserva por el
  -- candado documental que ya tomó el trigger 000 (inv_resolver:DNI:<doc>, la misma clave que toma la reserva; b1).
  select x as id, coalesce(resp.nombre_completo, 'sin asesor asignado') as asesor
    into v_otro
  from private.leads_de_personas(array[v_inv]) x
  join crm.inversionistas i on i.id = v_inv
  left join public.perfiles resp on resp.id = i.responsable_relacion_id
  where x is distinct from new.id
  order by (exists (select 1 from crm.leads l where l.id = x and l.inversionista_id = v_inv)) desc, x
  limit 1;
  if found then
    raise exception 'Contacto no disponible'
      using errcode = 'P0481',
            detail = pg_catalog.jsonb_build_object(
              'estado', 'ya_es_cliente', 'asesor', v_otro.asesor, 'via', 'identidad', 'lead_id', v_otro.id)::text;
  end if;
  if private.persona_en_conversion(v_inv, new.id)
     or exists (select 1 from crm.inversionistas i where i.id = v_inv and i.perfil_id is not null) then   -- ya cliente (Codex v3 M2)
    raise exception 'Contacto no disponible'
      using errcode = 'P0481',
            detail = pg_catalog.jsonb_build_object(
              'estado', 'ya_es_cliente',
              'asesor', coalesce((select p.nombre_completo
                                    from crm.conversion_reservas r
                                    join public.perfiles p on p.id = r.reservado_por
                                    left join crm.leads lr on lr.id = r.lead_id
                                   where r.inversionista_id = v_inv and r.lead_id is distinct from new.id
                                     and (r.expira_en > pg_catalog.now() or (r.efectos_iniciados_en is not null and coalesce(lr.etapa, '') <> 'convertido'))
                                   order by r.reservado_en desc limit 1), 'sin asesor asignado'),
              'via', 'identidad',
              'lead_id', (select r.lead_id from crm.conversion_reservas r
                           left join crm.leads lr on lr.id = r.lead_id
                           where r.inversionista_id = v_inv and r.lead_id is distinct from new.id
                             and (r.expira_en > pg_catalog.now() or (r.efectos_iniciados_en is not null and coalesce(lr.etapa, '') <> 'convertido'))
                           order by r.reservado_en desc limit 1))::text;
  end if;
  new.inversionista_id := v_inv;
  return new;
end;

declare
  v_priv boolean := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false);
begin
  -- «UPDATE OF columna» mira la lista SET de la sentencia, no el valor: un BEFORE
  -- que fija inversionista_id no lo dispararía. Por eso AFTER INSERT OR UPDATE
  -- con comparación de valor.
  if tg_op = 'UPDATE' and new.inversionista_id is not distinct from old.inversionista_id then
    return null;
  end if;
  if new.inversionista_id is null then
    return null;
  end if;
  if not private.resolver_en_puertas_bajo_candado() then
    return null;
  end if;
  if exists (select 1 from crm.inversionista_leads il where il.lead_id = new.id) then
    -- Reapuntes de puente (fusión) los gestiona su propia puerta bajo válvula.
    if v_priv then
      return null;
    end if;
    if exists (select 1 from crm.inversionista_leads il
               where il.lead_id = new.id and il.inversionista_id <> new.inversionista_id) then
      raise exception 'El puente persona<->lead no coincide con el enlace del lead' using errcode = 'P0409';
    end if;
    return null;
  end if;
  if exists (select 1 from crm.inversionista_leads il
             where il.inversionista_id = new.inversionista_id and il.rol = 'canonico' and il.lead_id <> new.id) then
    raise exception 'La persona ya tiene un lead canónico' using errcode = 'P0409';
  end if;
  insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
  values (new.inversionista_id, new.id, 'canonico');
  return null;
end;

declare v_priv boolean := coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false);
begin
  if v_priv or not private.resolver_en_puertas_bajo_candado() then
    return new;
  end if;
  if ((old.etapa = 'descartado' and new.etapa is distinct from 'descartado') or (old.activo = false and new.activo = true))
     and coalesce(pg_catalog.current_setting('crm.reapertura_identidad', true), 'off') <> 'on' then
    raise exception 'Con la identidad unificada encendida, un descarte se reabre solo por sus puertas (tomar, rescatar o deshacer): juzgan a la persona y enlazan el lead'
      using errcode = 'P0409';
  end if;
  return new;
end;

declare
  v_txt text;
begin
  if tg_op = 'INSERT' then
    -- El cliente API NO decide su propia clasificación ni su sello de cierre.
    -- translate() quita tildes sin depender de la extensión unaccent.
    v_txt := lower(translate(coalesce(new.nota, ''),
                             'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'));
    -- Prefijos con frontera de palabra a la izquierda: 'prestam*' (préstamo,
    -- préstamos, prestamista) y 'financiamient*'. Regla ESTRECHA a propósito
    -- (auditoría 2026-07-23): 'credit*' marcaba "¿son cooperativa de ahorro y
    -- CRÉDITO?" — la identidad de la propia empresa y la pregunta MÁS común de
    -- un buen cliente — y 'prestar' marcaba "prestar información". Con tasa
    -- base 0.5%, un falso positivo cuesta más que un falso negativo: lo que
    -- esta regla no atrape lo atrapa Rosa leyendo el comentario redactado.
    if v_txt ~ '\m(prestam|financiamient)' then
      new.clasificacion_auto := 'posible_credito';
    else
      new.clasificacion_auto := null;
    end if;
    new.descartado_en := null;
    new.descartado_por := null;
    return new;
  end if;

  -- El veredicto del código es un DATO DE MEDICIÓN: si un humano pudiera
  -- reescribirlo, la matriz de confusión (falsos positivos vs negativos)
  -- dejaría de ser calculable. Inmutable, como id/creado_por/creado_en.
  new.clasificacion_auto := old.clasificacion_auto;

  if new.etapa = 'descartado' and old.etapa is distinct from 'descartado' then
    new.descartado_en := statement_timestamp();
    new.descartado_por := auth.uid();
  elsif new.etapa is distinct from 'descartado' then
    -- Reapertura: el sello describe el cierre VIGENTE, no uno viejo. Dejarlo
    -- rancio corrompería en silencio cualquier informe de "descartes del mes".
    -- El histórico completo queda en public.audit_log y en crm.actividades.
    new.descartado_en := null;
    new.descartado_por := null;
  else
    new.descartado_en := old.descartado_en;
    new.descartado_por := old.descartado_por;
  end if;

  return new;
end;

begin
  raise exception 'El ledger de rentabilidad es append-only: no se edita ni se borra' using errcode = 'P0409';
end;

declare
  v_ultimo date;
begin
  -- GLOBAL primero: serializa esta publicación con CUALQUIER sellado en vuelo
  -- (también el de OTRO mes — la carrera del residuo de 20260815223000).
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.periodos_cerrados')::bigint
  );
  -- Y el por-mes de siempre: mismo recurso que cerrar_periodo y que las
  -- anulaciones (que NO toman el global) para el mes concreto.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.periodos_cerrados'),
    (new.periodo - date '2000-01-01')::integer
  );

  select max(pc.periodo) into v_ultimo from crm.periodos_cerrados pc;

  if v_ultimo is not null and new.periodo <= v_ultimo then
    raise exception using
      errcode = '22023',
      message = format('No se publican metas de %s: %s ya esta cerrado',
                       to_char(new.periodo, 'YYYY-MM'), to_char(v_ultimo, 'YYYY-MM')),
      hint    = 'Un mes cerrado no se reescribe, y uno anterior ya no se puede sellar. Lo que haya que corregir se descuenta en el mes vivo.';
  end if;

  return new;
end;

begin
  -- F2.b [D-5] (Codex v3 #3/#4): encender o apagar una bandera espera a que terminen las puertas que la leyeron bajo el
  -- candado compartido (pg_advisory_xact_lock_shared('crm_flag_<nombre>')) y bloquea a las que lleguen hasta que el cambio
  -- se confirme. Así ninguna llamada termina con una bandera distinta de la que leyó. Candado por bandera, transaccional.
  if new.activo is distinct from old.activo then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm_flag_' || new.nombre));
  end if;
  return new;
end;

begin
  if coalesce(current_setting('crm.elimina_operacion_cartera', true), 'off') = 'on'
     and tg_op = 'DELETE' then
    return old;
  end if;
  raise exception using
    errcode = 'P0409',
    message = 'Una operación de cartera confirmada no se edita ni se borra directamente';
end;

begin
  if (select auth.uid()) is not null then
    raise exception 'Un par de autoridad no se borra desde una sesion de persona.' using errcode = '42501';
  end if;
  if tg_op = 'TRUNCATE' then
    raise exception 'La tabla de pares no se vacia.' using errcode = '42501';
  end if;
  raise exception 'Un par de autoridad no se borra desde una migracion sin justificarlo.' using errcode = '42501';
end;

declare
  v_old text := pg_catalog.upper(pg_catalog.regexp_replace(coalesce(old.dni, ''), '[^A-Za-z0-9]', '', 'g'));
  v_new text := pg_catalog.upper(pg_catalog.regexp_replace(coalesce(new.dni, ''), '[^A-Za-z0-9]', '', 'g'));
  v_told text := coalesce(nullif(pg_catalog.btrim(old.tipo_documento), ''), 'DNI');
  v_tnew text := coalesce(nullif(pg_catalog.btrim(new.tipo_documento), ''), 'DNI');
begin
  if not private.resolver_en_puertas_bajo_candado() then
    return new;
  end if;
  -- La corrección de Gerencia (crm.corregir_documento_inversionista_fn, b5) fija AMBAS marcas alrededor de sus hechos
  -- (válvula + GUC propia, como el candado de leads) [auditor N2]. SECURITY DEFINER porque los roles del Portal no leen crm.* [N1].
  if coalesce(pg_catalog.current_setting('crm.op_privilegiada', true) = 'on', false)
     and coalesce(pg_catalog.current_setting('crm.correccion_documento', true) = 'on', false) then
    return new;
  end if;
  if v_old = v_new and v_told = v_tnew then
    return new;   -- mismo documento con otro formato: no es un cambio
  end if;
  -- [Codex B-1] por OLD.id: un UPDATE que envía id+dni no puede esquivar el candado (proteger_campos_inmutables restaura el id DESPUÉS).
  if exists (select 1 from crm.inversionistas i where i.perfil_id = old.id and i.estado <> 'fusionado') then
    raise exception 'El documento de un cliente reconocido como persona solo se corrige desde el CRM (corrección de documento de Gerencia)'
      using errcode = 'P0409';
  end if;
  return new;
end;

declare
  v_rol_crm text;
begin
  -- Suspender siempre queda permitido: el corte P04 debe ser inmediato. La
  -- pareja se valida al cambiar el rol o al reactivar el perfil.
  if new.activo is not true then
    return new;
  end if;

  select e.rol_crm into v_rol_crm
  from crm.equipo e
  where e.perfil_id = new.id and e.activo is true;

  if not found then
    return new;
  end if;

  if new.rol = 'superadmin' and v_rol_crm <> 'gerencia' then
    raise exception 'Superadmin Portal solo puede tener una membresía CRM activa como Gerencia';
  end if;
  if new.rol = 'directorio' and v_rol_crm <> 'directorio' then
    raise exception 'Directorio Portal solo puede tener una membresía CRM activa como Directorio';
  end if;
  if v_rol_crm = 'directorio' and new.rol is distinct from 'directorio' then
    raise exception 'Directorio CRM requiere el rol Directorio en el Portal';
  end if;
  return new;
end;

declare v_rol_crm text; v_tiene boolean;
begin
  if (select auth.uid()) is null
     or coalesce(current_setting('crm.cambiando_par', true), '') = 'on' then
    return new;
  end if;
  select true, e.rol_crm into v_tiene, v_rol_crm from crm.equipo e where e.perfil_id = new.id;
  if coalesce(v_tiene, false) and not private.par_autoridad_valido(new.rol, v_rol_crm) then
    raise exception 'El par %/% no esta declarado en private.pares_autoridad (la persona tiene ficha en el CRM). Transiciones: valvula crm.cambiando_par + guion ordenado.',
      new.rol, v_rol_crm using errcode = '42501';
  end if;
  return new;
end;

declare
  v_op crm.operaciones_cartera%rowtype;
begin
  select * into v_op from crm.operaciones_cartera o
  where o.contrato_nuevo_id = new.contrato_id
     or o.contrato_origen_id = new.contrato_id
  order by (o.contrato_nuevo_id = new.contrato_id) desc
  limit 1;
  if not found then return new; end if;
  if v_op.contrato_origen_id = new.contrato_id then
    raise exception 'Primero elimina el contrato nuevo que renovó este contrato'
      using errcode = 'P0409';
  end if;
  if exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_op.periodo) then
    raise exception 'El contrato pertenece a un mes comercial cerrado y no se puede eliminar'
      using errcode = 'P0409';
  end if;
  return new;
end;

declare
  v_producto_estado text;
  v_producto_legacy boolean;
begin
  if tg_op = 'INSERT' then
    if new.estado <> 'borrador' then
      raise exception 'Toda versión nace como borrador'
        using errcode = '23514';
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    raise exception 'Las versiones se retiran; no se eliminan'
      using errcode = '23514';
  end if;

  if new.id is distinct from old.id
     or new.producto_id is distinct from old.producto_id
     or new.numero_version is distinct from old.numero_version
     or new.creado_por is distinct from old.creado_por
     or new.creado_en is distinct from old.creado_en
     or new.revision <> old.revision + 1 then
    raise exception 'Identidad, autoría o revisión de versión inválida'
      using errcode = '23514';
  end if;

  if old.estado = 'retirada' then
    raise exception 'Una versión retirada es inmutable'
      using errcode = '23514';
  elsif old.estado = 'publicada' then
    if new.estado <> 'retirada'
       or new.nombre is distinct from old.nombre
       or new.descripcion is distinct from old.descripcion
       or new.vigente_desde is distinct from old.vigente_desde
       or new.vigente_hasta is distinct from old.vigente_hasta
       or new.publicada_por is distinct from old.publicada_por
       or new.publicada_en is distinct from old.publicada_en then
      raise exception 'Una versión publicada solo puede retirarse sin cambiar contenido'
        using errcode = '23514';
    end if;
  elsif new.estado not in ('borrador', 'publicada', 'retirada') then
    raise exception 'Transición de versión inválida'
      using errcode = '23514';
  elsif new.estado <> 'borrador' and (
    new.nombre is distinct from old.nombre
    or new.descripcion is distinct from old.descripcion
    or new.vigente_desde is distinct from old.vigente_desde
    or new.vigente_hasta is distinct from old.vigente_hasta
  ) then
    raise exception 'Publicar o retirar no puede cambiar el contenido del borrador'
      using errcode = '23514';
  end if;

  if new.estado = 'publicada' then
    select p.estado, p.es_legacy
      into v_producto_estado, v_producto_legacy
    from crm.productos_inversion p
    where p.id = new.producto_id;

    if v_producto_estado <> 'activo' or v_producto_legacy then
      raise exception 'Solo un producto comercial activo puede publicar versiones'
        using errcode = '23514';
    end if;
    if not exists (
      select 1
      from crm.producto_condiciones c
      where c.version_id = new.id
        and c.activa
        and not c.es_legacy
    ) then
      raise exception 'Una versión publicada requiere condiciones activas'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;

begin
  if tg_op = 'DELETE' then
    raise exception 'Los productos se archivan; no se eliminan'
      using errcode = '23514';
  end if;

  if new.id is distinct from old.id
     or new.codigo is distinct from old.codigo
     or new.es_legacy is distinct from old.es_legacy
     or new.creado_por is distinct from old.creado_por
     or new.creado_en is distinct from old.creado_en then
    raise exception 'La identidad y autoría del producto son inmutables'
      using errcode = '23514';
  end if;
  if old.estado = 'archivado' then
    if old.es_legacy
       and old.permite_altas_legacy
       and not new.permite_altas_legacy
       and new.estado = old.estado
       and new.revision = old.revision + 1
       and new.archivado_por is not distinct from old.archivado_por
       and new.archivado_en is not distinct from old.archivado_en then
      return new;
    end if;
    raise exception 'Un producto archivado es inmutable'
      using errcode = '23514';
  end if;
  if new.estado not in ('activo', 'archivado')
     or new.revision <> old.revision + 1 then
    raise exception 'Transición o revisión de producto inválida'
      using errcode = '23514';
  end if;
  return new;
end;

begin
  raise exception using
    errcode = 'P0409',
    message = 'El rastro de reasignaciones no se edita ni se borra';
end;

declare
  v_op crm.operaciones_cartera%rowtype;
begin
  select * into v_op from crm.operaciones_cartera o
  where o.contrato_nuevo_id = old.id for update;
  if not found then return old; end if;
  if exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_op.periodo) then
    raise exception 'El contrato pertenece a un mes comercial cerrado y no se puede eliminar'
      using errcode = 'P0409';
  end if;

  perform set_config('crm.elimina_operacion_cartera', 'on', true);
  delete from crm.operaciones_cartera o where o.id = v_op.id;
  perform set_config('crm.elimina_operacion_cartera', 'off', true);

  if v_op.tipo = 'renovacion' and v_op.contrato_origen_id is not null then
    update public.cronograma_pagos cp
       set estado = case
         when cp.fecha_programada < (now() at time zone 'America/Lima')::date
           then 'vencido'
         else 'pendiente'
       end
     where cp.contrato_id = v_op.contrato_origen_id and cp.estado = 'trasladado';
    update public.contratos c
       set estado = case
         when c.fecha_vencimiento < (now() at time zone 'America/Lima')::date
           then 'vencido'
         else 'activo'
       end,
       renovado_a_id = null, cerrado_en = null, cerrado_por = null
     where c.id = v_op.contrato_origen_id and c.renovado_a_id = old.id;
  end if;
  return old;
end;

begin
  update crm.agenda_ics
  set token = pg_catalog.gen_random_uuid(),
      rotado_en = pg_catalog.clock_timestamp()
  where perfil_id = new.perfil_id;

