begin
  if tg_op = 'DELETE' then
    raise exception 'Una solicitud de tasa no se borra: queda como historia' using errcode = 'P0409';
  end if;
  if coalesce(current_setting('crm.solicitud_tasa_por_puerta', true), 'off') <> 'on' then
