  perform private.validar_equipo_usuario_crm(new.perfil_id);
  return new;
end;

begin
  if length(btrim(coalesce(p_nombre, ''))) not between 3 and 160
     or (p_descripcion is not null and length(p_descripcion) > 2000)
     or p_vigente_desde is null
     or (p_vigente_hasta is not null and p_vigente_hasta < p_vigente_desde) then
    raise exception 'Nombre o vigencia del producto inválidos'
      using errcode = '22023';
  end if;
end;

declare
  v_tipo text := upper(pg_catalog.btrim(coalesce(p_tipo_documento, '')));
  v_documento text := upper(pg_catalog.btrim(coalesce(p_documento, '')));
begin
  if length(pg_catalog.btrim(coalesce(p_nombre_completo, ''))) not between 2 and 160 then
    raise exception 'Nombre completo invalido';
  end if;

  if v_tipo = 'DNI' and v_documento !~ '^[0-9]{8}$' then
    raise exception 'DNI invalido';
  elsif v_tipo = 'CE' and v_documento !~ '^[0-9]{9,12}$' then
    raise exception 'CE invalido';
  elsif v_tipo = 'PASAPORTE' and v_documento !~ '^[A-Z0-9]{6,12}$' then
    raise exception 'Pasaporte invalido';
  elsif v_tipo not in ('DNI','CE','PASAPORTE') then
    raise exception 'Tipo de documento invalido';
  end if;

  if p_telefono is not null
     and length(pg_catalog.btrim(p_telefono)) not between 7 and 30 then
    raise exception 'Telefono invalido';
  end if;
  if p_whatsapp is not null
     and length(pg_catalog.btrim(p_whatsapp)) not between 7 and 30 then
    raise exception 'WhatsApp invalido';
  end if;
  if p_cargo is not null
     and length(pg_catalog.btrim(p_cargo)) not between 1 and 120 then
    raise exception 'Cargo invalido';
  end if;
end;

declare
  v_fila crm.equipo%rowtype;
  v_perfil_activo boolean;
  v_rol_portal text;
begin
  select e.* into v_fila
  from crm.equipo e
  where e.perfil_id = p_perfil_id;

  if not found then
    return;
  end if;

  perform private.validar_supervisor_usuario_crm(
    v_fila.perfil_id, v_fila.rol_crm, v_fila.supervisor_id
  );

  select p.activo, p.rol into v_perfil_activo, v_rol_portal
  from public.perfiles p where p.id = v_fila.perfil_id;

  if v_fila.activo and v_perfil_activo is not true then
    raise exception 'Una membresía CRM activa requiere perfil Portal activo';
  end if;

  if v_fila.activo
     and v_rol_portal = 'superadmin'
     and v_fila.rol_crm <> 'gerencia' then
    raise exception 'Superadmin Portal solo puede tener una membresía CRM activa como Gerencia';
  end if;

  if v_fila.activo
     and v_rol_portal = 'directorio'
     and v_fila.rol_crm <> 'directorio' then
    raise exception 'Directorio Portal solo puede tener una membresía CRM activa como Directorio';
  end if;

  if v_fila.activo
     and v_fila.rol_crm = 'directorio'
     and v_rol_portal is distinct from 'directorio' then
    raise exception 'Directorio CRM requiere el rol Directorio en el Portal';
  end if;

  if v_fila.rol_crm not in ('supervisor','gerencia') and exists (
    select 1 from crm.equipo h
    where h.supervisor_id = v_fila.perfil_id and h.activo is true
  ) then
    raise exception 'El rol propuesto no puede conservar subordinados activos';
  end if;

  if v_fila.rol_crm not in ('vendedor','supervisor') and exists (
    select 1 from crm.leads l
    where l.vendedor_id = v_fila.perfil_id
      and l.activo is true and l.etapa not in ('convertido','descartado')
  ) then
    raise exception 'El rol propuesto no puede conservar leads asignados';
  end if;

  if v_fila.rol_crm <> 'supervisor' and exists (
    select 1 from crm.leads l
    where l.asignado_supervisor_id = v_fila.perfil_id
      and l.activo is true and l.etapa not in ('convertido','descartado')
  ) then
    raise exception 'El rol propuesto no puede conservar una bandeja de supervisor';
  end if;

  if v_fila.rol_crm not in ('vendedor','supervisor') and exists (
    select 1 from public.perfiles p
    where p.rol = 'cliente' and p.activo is true
      and p.asesor_perfil_id = v_fila.perfil_id
  ) then
    raise exception 'El rol propuesto no puede conservar clientes asignados';
  end if;

  if v_fila.rol_crm not in ('vendedor','supervisor') and exists (
    select 1 from crm.tareas t
    where t.vendedor_id = v_fila.perfil_id
      and t.activo is true and t.estado = 'pendiente'
  ) then
    raise exception 'El rol propuesto no puede conservar tareas comerciales pendientes';
  end if;

  if v_fila.rol_crm <> 'supervisor' and exists (
    select 1 from crm.tareas t
    where t.asignado_supervisor_id = v_fila.perfil_id
      and t.activo is true and t.estado = 'pendiente'
  ) then
    raise exception 'El rol propuesto no puede conservar tareas de bandeja de supervisor';
  end if;

  if v_fila.activo is not true and (
    exists (
      select 1 from crm.equipo h
      where h.supervisor_id = v_fila.perfil_id and h.activo is true
    )
    or exists (
      select 1 from crm.leads l
      where (l.vendedor_id = v_fila.perfil_id
          or l.asignado_supervisor_id = v_fila.perfil_id)
        and l.activo is true and l.etapa not in ('convertido','descartado')
    )
    or exists (
      select 1 from crm.tareas t
      where (t.vendedor_id = v_fila.perfil_id
          or t.asignado_supervisor_id = v_fila.perfil_id)
        and t.activo is true and t.estado = 'pendiente'
    )
    or exists (
      select 1 from public.perfiles p
      where p.rol = 'cliente' and p.activo is true
        and p.asesor_perfil_id = v_fila.perfil_id
    )
  ) then
    raise exception 'La membresía conserva dependencias activas; reasigna antes de desactivar';
  end if;
end;

declare
  v_rol_supervisor text;
  v_supervisor_activo boolean;
  v_perfil_supervisor_activo boolean;
  v_membresia_activa boolean;
begin
  if p_rol_crm not in ('vendedor','supervisor','gerencia','coordinador','directorio') then
    raise exception 'Rol CRM no permitido';
  end if;

  select e.activo into v_membresia_activa
  from crm.equipo e
  where e.perfil_id = p_perfil_id;

  if p_supervisor_id is null then
    if p_rol_crm = 'vendedor' and v_membresia_activa is true then
      raise exception 'Un vendedor CRM activo requiere un Supervisor activo';
    end if;
    return;
  end if;

  if p_supervisor_id = p_perfil_id then
    raise exception 'Un usuario no puede supervisarse a si mismo';
  end if;

  if p_rol_crm in ('gerencia','coordinador','directorio') then
    raise exception 'Gerencia, Coordinacion y Directorio no admiten supervisor';
  end if;

  select e.rol_crm, e.activo, p.activo
    into v_rol_supervisor, v_supervisor_activo, v_perfil_supervisor_activo
  from crm.equipo e
  join public.perfiles p on p.id = e.perfil_id
  where e.perfil_id = p_supervisor_id;

  if not found
     or v_supervisor_activo is not true
     or v_perfil_supervisor_activo is not true
     or (p_rol_crm = 'vendedor' and v_rol_supervisor <> 'supervisor')
     or (p_rol_crm = 'supervisor' and v_rol_supervisor not in ('supervisor','gerencia')) then
    raise exception 'El supervisor destino no existe, no esta activo o no tiene rol compatible';
  end if;

  if exists (
    with recursive ancestros as (
      select e.perfil_id, e.supervisor_id
      from crm.equipo e
      where e.perfil_id = p_supervisor_id
      union
      select e.perfil_id, e.supervisor_id
      from crm.equipo e
      join ancestros a on e.perfil_id = a.supervisor_id
    )
    select 1 from ancestros where perfil_id = p_perfil_id
  ) then
    raise exception 'La jerarquia propuesta forma un ciclo';
  end if;
end;

declare
  v_previo text := coalesce(current_setting('crm.solicitud_tasa_por_puerta', true), 'off');
  v_n integer;
begin
  perform set_config('crm.solicitud_tasa_por_puerta', 'on', true);
  update crm.solicitudes_tasa s
     set estado = 'vencida'
   where s.estado in ('pendiente', 'aprobada', 'aprobada_con_tope', 'aceptada_por_analista')
     and s.vence_en < statement_timestamp()
     and (p_solicitud_id is null or s.id = p_solicitud_id);
  get diagnostics v_n = row_count;
  perform set_config('crm.solicitud_tasa_por_puerta', v_previo, true);
  return v_n;
end;

declare
  v_rol text;
begin
  if p_perfil_id is distinct from (select auth.uid())
     and not private.es_lector_global() then
    return; -- defensa en profundidad: no enumerar equipos ajenos
  end if;

  v_rol := private.rol_crm(p_perfil_id);

  if v_rol is null then
    return;
  elsif v_rol = 'gerencia' then
    return query select e.perfil_id from crm.equipo e; -- incluye históricos
  elsif v_rol = 'supervisor' then
    return query
      with recursive subarbol as (
        select e.perfil_id
        from crm.equipo e
        where e.perfil_id = p_perfil_id
        union -- corta ciclos accidentales A↔B
        select e.perfil_id
        from crm.equipo e
        join subarbol s on e.supervisor_id = s.perfil_id
      )
      select s.perfil_id from subarbol s;
  elsif v_rol = 'vendedor' then
    return next p_perfil_id;
  else
    return; -- coordinador/rol futuro: deny-by-default
  end if;
end;

declare v_n integer; v_txt text;
begin
  select count(*) into v_n from private.vigia_alertas va where va.resuelta_en is null;
  if v_n > 0 then
    select 'ALERTAS ABIERTAS: ' || string_agg(format('[%s] %s', va.fase, left(va.motivo, 80)), ' · ' order by va.creado_en)
      into v_txt from private.vigia_alertas va where va.resuelta_en is null;
    return v_txt;
  end if;
  if (select count(*) from cron.job j
       where j.jobname = 'crm-f7-piezas-vigia' and j.schedule = '59 6 * * *'
         and j.command = 'select private.vigia_f7_piezas()'
         and j.database = current_database() and j.username = 'postgres' and j.active) <> 1 then
    return 'VIGIA APAGADO O ALTERADO: crm-f7-piezas-vigia no esta exactamente como se declaro';
  end if;
  if exists (
    select 1 from cron.job_run_details d
    join cron.job j on j.jobid = d.jobid and j.jobname = 'crm-f7-piezas-vigia'
    where d.start_time = (select max(d2.start_time) from cron.job_run_details d2 where d2.jobid = j.jobid)
      and d.status = 'failed'
  ) then
    return 'VIGIA CAIDO: la ultima corrida del cron FALLO';
  end if;
  return private.assert_f7_piezas_cerradas();
end;

