DECLARE
  v_uid           uuid := auth.uid();
  v_asesor_perfil uuid;
  v_asesor_legacy uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  SELECT p.asesor_perfil_id, p.asesor_id
    INTO v_asesor_perfil, v_asesor_legacy
    FROM public.perfiles p WHERE p.id = v_uid;

